--
-- Name: match_lead_knowledge(bigint, public.vector, integer, double precision); Type: FUNCTION; Schema: emp_garbo; Owner: -
--

CREATE FUNCTION emp_garbo.match_lead_knowledge(p_lead_id bigint, query_embedding public.vector, match_count integer DEFAULT 10, match_threshold double precision DEFAULT 0.5) RETURNS TABLE(id uuid, content text, source_type text, metadata jsonb, similarity double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'emp_garbo', 'public'
    AS $$
        SELECT
          c.id,
          c.content,
          c.source_type,
          c.metadata,
          1 - (c.embedding <=> query_embedding) AS similarity
        FROM emp_garbo.lead_ai_knowledge_chunks c
        WHERE c.lead_id = p_lead_id
          AND c.embedding IS NOT NULL
          AND 1 - (c.embedding <=> query_embedding) >= match_threshold
        ORDER BY c.embedding <=> query_embedding
        LIMIT GREATEST(match_count, 1);
      $$;


