--
-- Name: trg_pontua_comissao_cria_conta_pagar(); Type: FUNCTION; Schema: emp_garbo; Owner: -
--

CREATE FUNCTION emp_garbo.trg_pontua_comissao_cria_conta_pagar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
DECLARE
  v_conta_id UUID;
BEGIN
  IF NEW.status IS DISTINCT FROM 'aguardando_liberacao' THEN
    RETURN NEW;
  END IF;

  IF NEW.conta_pagar_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_conta_id := public.movelaria_criar_conta_pagar_pontua_garbo(
    NEW.id,
    NEW.prestador_id,
    NEW.lead_id,
    NEW.valor_comissao
  );

  IF v_conta_id IS NOT NULL THEN
    NEW.conta_pagar_id := v_conta_id;
  END IF;

  RETURN NEW;
END;
$$;


