--
-- Name: agenda_public_attach_uploads_to_lead(text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agenda_public_attach_uploads_to_lead(p_schema text, p_lead_id bigint, p_resposta_formulario text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_parsed jsonb;
  v_entry record;
  v_item jsonb;
  v_url text;
  v_name text;
  v_mime text;
  v_size bigint;
  v_tipo text;
  v_folder_id uuid;
  v_folders_table text;
  v_medias_table text;
BEGIN
  IF p_lead_id IS NULL OR p_resposta_formulario IS NULL OR trim(p_resposta_formulario) = '' THEN
    RETURN;
  END IF;

  BEGIN
    v_parsed := p_resposta_formulario::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RETURN;
  END;

  IF p_schema IS NOT NULL AND p_schema <> '' THEN
    v_folders_table := format('%I.marketing_media_folders', p_schema);
    v_medias_table := format('%I.marketing_medias', p_schema);
  ELSE
    v_folders_table := 'public.crm_multiempresas_marketing_media_folders';
    v_medias_table := 'public.crm_multiempresas_marketing_medias';
  END IF;

  EXECUTE format(
    'SELECT id FROM %s WHERE nome = $1 LIMIT 1',
    v_folders_table
  )
    INTO v_folder_id
    USING 'orçamentos';

  IF v_folder_id IS NULL THEN
    EXECUTE format(
      'INSERT INTO %s (nome, descricao) VALUES ($1, $2) RETURNING id',
      v_folders_table
    )
      INTO v_folder_id
      USING 'orçamentos', 'Orçamentos de leads';
  END IF;

  FOR v_entry IN SELECT key, value FROM jsonb_each(v_parsed)
  LOOP
    IF jsonb_typeof(v_entry.value) = 'array' THEN
      FOR v_item IN SELECT value FROM jsonb_array_elements(v_entry.value)
      LOOP
        IF jsonb_typeof(v_item) <> 'object' THEN
          CONTINUE;
        END IF;

        v_url := nullif(trim(both '"' from v_item->>'url'), '');
        IF v_url IS NULL OR v_url NOT LIKE 'http%' THEN
          CONTINUE;
        END IF;

        v_name := coalesce(nullif(trim(v_item->>'name'), ''), 'Anexo');
        v_mime := lower(coalesce(nullif(trim(v_item->>'mime_type'), ''), 'application/octet-stream'));
        v_size := coalesce((v_item->>'size')::bigint, 0);

        IF v_mime = 'application/pdf' THEN
          v_tipo := 'pdf';
        ELSIF v_mime LIKE 'image/%' THEN
          v_tipo := 'imagem';
        ELSIF v_mime LIKE 'video/%' THEN
          v_tipo := 'video';
        ELSE
          CONTINUE;
        END IF;

        EXECUTE format(
          'INSERT INTO %s (titulo, tipo, file_url, file_name, file_size, mime_type, folder_id, lead_id)
           VALUES ($1, $2, $3, $4, $5, $6, $7, $8)',
          v_medias_table
        )
        USING
          regexp_replace(v_name, '\.[^.]+$', ''),
          v_tipo,
          v_url,
          v_name,
          v_size,
          v_mime,
          v_folder_id,
          p_lead_id;
      END LOOP;
    ELSIF jsonb_typeof(v_entry.value) = 'object' THEN
      v_item := v_entry.value;
      v_url := nullif(trim(v_item->>'url'), '');
      IF v_url IS NULL OR v_url NOT LIKE 'http%' THEN
        CONTINUE;
      END IF;

      v_name := coalesce(nullif(trim(v_item->>'name'), ''), 'Anexo');
      v_mime := lower(coalesce(nullif(trim(v_item->>'mime_type'), ''), 'application/octet-stream'));
      v_size := coalesce((v_item->>'size')::bigint, 0);

      IF v_mime = 'application/pdf' THEN
        v_tipo := 'pdf';
      ELSIF v_mime LIKE 'image/%' THEN
        v_tipo := 'imagem';
      ELSIF v_mime LIKE 'video/%' THEN
        v_tipo := 'video';
      ELSE
        CONTINUE;
      END IF;

      EXECUTE format(
        'INSERT INTO %s (titulo, tipo, file_url, file_name, file_size, mime_type, folder_id, lead_id)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)',
        v_medias_table
      )
      USING
        regexp_replace(v_name, '\.[^.]+$', ''),
        v_tipo,
        v_url,
        v_name,
        v_size,
        v_mime,
        v_folder_id,
        p_lead_id;
    END IF;
  END LOOP;
END;
$_$;


--
-- Name: agenda_public_create_booking(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agenda_public_create_booking(p_schema text, p_config_id uuid, p_agenda_slug text, p_dados jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_config record;
  v_lead_id bigint;
  v_reuniao_id uuid;
  v_data_inicio timestamptz;
  v_data_fim timestamptz;
  v_telefone text;
  v_nome text;
  v_email text;
  v_should_create_lead boolean;
  v_status_destino text;
  v_origem text;
  v_titulo text;
  v_resposta text;
  v_metadata jsonb;
  v_hoje date;
BEGIN
  v_nome := trim(coalesce(p_dados->>'convidado_nome', ''));
  v_telefone := regexp_replace(coalesce(p_dados->>'convidado_whatsapp', ''), '\D', '', 'g');
  v_email := nullif(trim(coalesce(p_dados->>'convidado_email', '')), '');
  v_resposta := p_dados->>'resposta_formulario';
  v_metadata := p_dados->'metadata_capturada';
  v_hoje := (timezone('America/Sao_Paulo', now()))::date;

  IF v_nome = '' OR length(v_telefone) < 10 OR p_dados->>'data_hora_inicio' IS NULL THEN
    RAISE EXCEPTION 'Dados incompletos para agendamento';
  END IF;

  v_data_inicio := (p_dados->>'data_hora_inicio')::timestamptz;

  IF p_schema IS NOT NULL AND p_schema <> '' THEN
    EXECUTE format(
      'SELECT id, duracao_minutos, link_video_conferencia, criar_lead_automatico, lead_status_destino, lead_origem
         FROM %I.agenda_config
        WHERE id = $1 AND slug = $2 AND ativo = true',
      p_schema
    )
      INTO v_config
      USING p_config_id, p_agenda_slug;
  ELSE
    SELECT id, duracao_minutos, link_video_conferencia, criar_lead_automatico, lead_status_destino, lead_origem
      INTO v_config
      FROM public."CRM-multi-empresas>agenda_config<"
     WHERE id = p_config_id
       AND slug = p_agenda_slug
       AND ativo = true;
  END IF;

  IF v_config IS NULL THEN
    RAISE EXCEPTION 'Configuração de agenda não encontrada';
  END IF;

  v_data_fim := v_data_inicio + make_interval(mins => v_config.duracao_minutos);
  v_should_create_lead := coalesce(v_config.criar_lead_automatico, true);
  v_lead_id := NULL;
  v_titulo := format('Reunião com %s', v_nome);

  IF v_should_create_lead THEN
    v_status_destino := coalesce(nullif(trim(v_config.lead_status_destino), ''), 'Novo Lead');
    v_origem := coalesce(nullif(trim(v_config.lead_origem), ''), 'Agendamento Público');

    IF p_schema IS NOT NULL AND p_schema <> '' THEN
      EXECUTE format(
        'INSERT INTO %I.leads (nome, telefone, email, status, origem, data_chegada, valor_negocio, observacoes)
         VALUES ($1, $2, $3, $4, $5, $6, 0, $7)
         RETURNING id',
        p_schema
      )
        INTO v_lead_id
        USING
          v_nome,
          v_telefone,
          v_email,
          v_status_destino,
          v_origem,
          v_hoje,
          format('Lead criado automaticamente via agendamento público (%s).', p_agenda_slug);

      PERFORM public.agenda_public_attach_uploads_to_lead(p_schema, v_lead_id, v_resposta);
    ELSE
      INSERT INTO public."CRM-multi-empresas>leads<" (
        nome, telefone, email, status, origem, data_chegada, valor_negocio, observacoes
      )
      VALUES (
        v_nome,
        v_telefone,
        v_email,
        v_status_destino,
        v_origem,
        v_hoje::text,
        0,
        format('Lead criado automaticamente via agendamento público (%s).', p_agenda_slug)
      )
      RETURNING id INTO v_lead_id;

      PERFORM public.agenda_public_attach_uploads_to_lead(NULL, v_lead_id, v_resposta);
    END IF;
  END IF;

  IF p_schema IS NOT NULL AND p_schema <> '' THEN
    EXECUTE format(
      'INSERT INTO %I.agenda_reunioes (
         titulo, data_hora_inicio, data_hora_fim, duracao_minutos,
         convidado_nome, convidado_whatsapp, convidado_email,
         resposta_formulario, tipo, status, link_video_conferencia,
         metadata_capturada, lead_id
       ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, ''publico'', ''pendente'', $9, $10, $11)
       RETURNING id',
      p_schema
    )
      INTO v_reuniao_id
      USING
        v_titulo,
        v_data_inicio,
        v_data_fim,
        v_config.duracao_minutos,
        v_nome,
        v_telefone,
        v_email,
        v_resposta,
        v_config.link_video_conferencia,
        v_metadata,
        v_lead_id;
  ELSE
    INSERT INTO public."CRM-multi-empresas>agenda_reunioes<" (
      titulo, data_hora_inicio, data_hora_fim, duracao_minutos,
      convidado_nome, convidado_whatsapp, convidado_email,
      resposta_formulario, tipo, status, link_video_conferencia,
      metadata_capturada, lead_id
    )
    VALUES (
      v_titulo,
      v_data_inicio,
      v_data_fim,
      v_config.duracao_minutos,
      v_nome,
      v_telefone,
      v_email,
      v_resposta,
      'publico',
      'pendente',
      v_config.link_video_conferencia,
      v_metadata,
      v_lead_id
    )
    RETURNING id INTO v_reuniao_id;
  END IF;

  RETURN jsonb_build_object(
    'reuniao_id', v_reuniao_id,
    'lead_id', v_lead_id
  );
END;
$_$;


--
-- Name: approve_user(uuid, public.selletos_crm_app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_user(_user_id uuid, _new_role public.selletos_crm_app_role) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Verificar se quem está chamando é admin
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Apenas administradores podem aprovar usuários';
  END IF;

  -- Atualizar status do usuário
  UPDATE public."CRM-Selletos>usuarios<"
  SET status_convite = 'ATIVO'
  WHERE id = _user_id;

  -- Inserir ou atualizar role
  INSERT INTO public."CRM-Selletos>user_roles<" (user_id, role)
  VALUES (_user_id, _new_role)
  ON CONFLICT (user_id) 
  DO UPDATE SET role = _new_role;
END;
$$;


--
-- Name: can_manage_lead(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_manage_lead(_user_id uuid, _lead_id bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public."CRM-Selletos>leads<" l
    INNER JOIN public."CRM-Selletos>user_roles<" ur ON ur.user_id = _user_id
    WHERE l.id = _lead_id
    AND (ur.role = 'admin' OR l.vendedor_responsavel_id = _user_id)
  );
$$;


--
-- Name: create_lead_notification(bigint, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_lead_notification(_lead_id bigint, _notification_type text, _vendor_id uuid, _vendor_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _message TEXT;
  _admin_record RECORD;
BEGIN
  -- Definir mensagem baseada no tipo
  CASE _notification_type
    WHEN 'aula_marcada' THEN
      _message := 'marcou uma aula experimental';
    WHEN 'venda_realizada' THEN
      _message := 'realizou uma venda';
    WHEN 'venda_perdida' THEN
      _message := 'perdeu uma venda';
    ELSE
      _message := 'atualizou um lead';
  END CASE;

  -- Criar notificação para o vendedor responsável
  INSERT INTO "CRM-Selletos>notifications<" (user_id, lead_id, vendor_name, notification_type, message)
  VALUES (_vendor_id, _lead_id, _vendor_name, _notification_type, 
          'O vendedor ' || _vendor_name || ' ' || _message);

  -- Criar notificações para todos os administradores (exceto se for o próprio admin)
  FOR _admin_record IN 
    SELECT ur.user_id, u.nome
    FROM "CRM-Selletos>user_roles<" ur
    INNER JOIN "CRM-Selletos>usuarios<" u ON u.id = ur.user_id
    WHERE ur.role = 'admin' 
      AND ur.user_id != _vendor_id
      AND u.status_convite = 'ATIVO'
  LOOP
    INSERT INTO "CRM-Selletos>notifications<" (user_id, lead_id, vendor_name, notification_type, message)
    VALUES (_admin_record.user_id, _lead_id, _vendor_name, _notification_type,
            'O vendedor ' || _vendor_name || ' ' || _message);
  END LOOP;
END;
$$;


--
-- Name: crm_lead_status_priority(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_lead_status_priority(p_status text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_status
    WHEN 'Venda Realizada (Matriculado)' THEN 1
    WHEN 'Negociação' THEN 2
    WHEN 'Aula Realizada' THEN 3
    WHEN 'Aula Experimental Marcada' THEN 4
    WHEN 'Interesse Futuro' THEN 5
    WHEN 'Novo Lead' THEN 6
    WHEN 'Clientes Já Cadastrados' THEN 7
    WHEN 'Não Entraram para Aula Experimental' THEN 8
    WHEN 'Venda Perdida (Não Matriculado)' THEN 9
    ELSE 10
  END;
$$;


--
-- Name: crm_normalize_lead_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_normalize_lead_phone(p_telefone text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_telefone IS NULL THEN NULL
    WHEN length(regexp_replace(p_telefone, '\D', '', 'g')) < 10 THEN NULL
    ELSE right(regexp_replace(p_telefone, '\D', '', 'g'), 11)
  END;
$$;


--
-- Name: FUNCTION crm_normalize_lead_phone(p_telefone text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.crm_normalize_lead_phone(p_telefone text) IS 'Últimos 11 dígitos do telefone; usado para deduplicar leads.';


--
-- Name: crm_prevent_duplicate_lead_phone(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_prevent_duplicate_lead_phone() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_existing_id bigint;
  v_norm text;
  v_new_status text;
BEGIN
  v_norm := public.crm_normalize_lead_phone(NEW.telefone);
  IF v_norm IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT l.id
  INTO v_existing_id
  FROM public."CRM-Selletos>leads<" l
  WHERE public.crm_normalize_lead_phone(l.telefone) = v_norm
    AND (
      (NEW.instancia_id IS NULL AND l.instancia_id IS NULL)
      OR (NEW.instancia_id IS NOT NULL AND l.instancia_id = NEW.instancia_id)
    )
    AND (TG_OP = 'INSERT' OR l.id <> NEW.id)
  ORDER BY
    public.crm_lead_status_priority(l.status),
    COALESCE(l.venda_realizada_em, l.atualizado_em, l.criado_em) DESC NULLS LAST,
    l.id DESC
  LIMIT 1;

  IF v_existing_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_new_status := CASE
      WHEN public.crm_lead_status_priority(NEW.status) < public.crm_lead_status_priority(
        (SELECT status FROM public."CRM-Selletos>leads<" WHERE id = v_existing_id)
      ) THEN NEW.status
      ELSE (SELECT status FROM public."CRM-Selletos>leads<" WHERE id = v_existing_id)
    END;

    UPDATE public."CRM-Selletos>leads<" l
    SET
      nome = COALESCE(NULLIF(trim(NEW.nome), ''), l.nome),
      email = COALESCE(NULLIF(trim(NEW.email), ''), l.email),
      empresa = COALESCE(NULLIF(trim(NEW.empresa), ''), l.empresa),
      origem = COALESCE(NULLIF(trim(NEW.origem), ''), l.origem),
      observacoes = CASE
        WHEN NEW.observacoes IS NULL OR trim(NEW.observacoes) = '' THEN l.observacoes
        WHEN l.observacoes IS NULL OR l.observacoes = '' THEN NEW.observacoes
        ELSE l.observacoes || E'\n' || NEW.observacoes
      END,
      status = v_new_status,
      valor_negocio = GREATEST(COALESCE(l.valor_negocio, 0), COALESCE(NEW.valor_negocio, 0)),
      venda_realizada_em = COALESCE(
        l.venda_realizada_em,
        NEW.venda_realizada_em,
        CASE
          WHEN v_new_status = 'Venda Realizada (Matriculado)' THEN now()
          ELSE NULL
        END
      ),
      vendedor_responsavel_id = COALESCE(l.vendedor_responsavel_id, NEW.vendedor_responsavel_id),
      regiao = COALESCE(l.regiao, NEW.regiao),
      regiao_tabela = COALESCE(l.regiao_tabela, NEW.regiao_tabela),
      instancia_id = COALESCE(l.instancia_id, NEW.instancia_id),
      atualizado_em = now()
    WHERE l.id = v_existing_id;

    RETURN NULL;
  END IF;

  RAISE EXCEPTION 'Já existe um lead com este telefone nesta instância (id %).', v_existing_id
    USING ERRCODE = 'unique_violation';
END;
$$;


--
-- Name: crm_selletos_last_messages_by_phones(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_selletos_last_messages_by_phones(p_phones text[]) RETURNS TABLE(telefone text, instancia_id uuid, conteudo text, criado_em timestamp with time zone, tipo_mensagem text, tipo_remetente text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT ON (m.telefone, m.instancia_id)
    m.telefone,
    m.instancia_id,
    m.conteudo,
    m.criado_em,
    m.tipo_mensagem,
    m.tipo_remetente
  FROM public.crm_selletos_chat_mensagens m
  WHERE p_phones IS NOT NULL
    AND cardinality(p_phones) > 0
    AND m.telefone = ANY (p_phones)
  ORDER BY m.telefone, m.instancia_id, m.criado_em DESC;
$$;


