--
-- Name: get_conversion_stats_filtered(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_conversion_stats_filtered(_cutoff_date date) RETURNS TABLE(total_leads bigint, marcaram_aula bigint, nao_entraram_aula bigint, realizaram_aula bigint, vendas_realizadas bigint, vendas_perdidas bigint, percentual_marcaram numeric, percentual_nao_entraram numeric, percentual_realizaram numeric, percentual_vendas numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    COUNT(*) as total_leads,
    COUNT(*) FILTER (WHERE status = 'Aula Experimental Marcada') as marcaram_aula,
    COUNT(*) FILTER (WHERE status = 'Não Entraram para Aula Experimental') as nao_entraram_aula,
    COUNT(*) FILTER (WHERE status = 'Aula Realizada') as realizaram_aula,
    COUNT(*) FILTER (WHERE status = 'Venda Realizada (Matriculado)') as vendas_realizadas,
    COUNT(*) FILTER (WHERE status = 'Venda Perdida (Não Matriculado)') as vendas_perdidas,
    ROUND(100.0 * COUNT(*) FILTER (WHERE status = 'Aula Experimental Marcada') / NULLIF(COUNT(*), 0), 2) as percentual_marcaram,
    ROUND(100.0 * COUNT(*) FILTER (WHERE status = 'Não Entraram para Aula Experimental') / NULLIF(COUNT(*) FILTER (WHERE status = 'Aula Experimental Marcada'), 0), 2) as percentual_nao_entraram,
    ROUND(100.0 * COUNT(*) FILTER (WHERE status = 'Aula Realizada') / NULLIF(COUNT(*) FILTER (WHERE status = 'Aula Experimental Marcada'), 0), 2) as percentual_realizaram,
    ROUND(100.0 * COUNT(*) FILTER (WHERE status = 'Venda Realizada (Matriculado)') / NULLIF(COUNT(*) FILTER (WHERE status = 'Aula Realizada'), 0), 2) as percentual_vendas
  FROM public."CRM-Selletos>leads<"
  WHERE data_chegada >= _cutoff_date
    AND (
      public.is_admin(auth.uid())
      OR (public.is_vendedor(auth.uid()) AND public.has_permission(auth.uid(), 'all_leads', 'view'))
      OR (public.is_vendedor(auth.uid()) AND vendedor_responsavel_id = auth.uid())
    );
$$;


--
-- Name: get_crm_multiempresas_marketing_ai_studio_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_crm_multiempresas_marketing_ai_studio_status() RETURNS TABLE(id uuid, ativo boolean, model_pesquisa text, model_copy text, openai_configured boolean, openai_key_hint text, serp_configured boolean, serp_key_hint text, atualizado_em timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_config public.crm_multiempresas_marketing_ai_studio_config%ROWTYPE;
  v_secrets public.crm_multiempresas_marketing_ai_studio_secrets%ROWTYPE;
  v_openai text; v_serp text;
BEGIN
  SELECT * INTO v_config FROM public.crm_multiempresas_marketing_ai_studio_config ORDER BY criado_em ASC LIMIT 1;
  IF v_config.id IS NULL THEN RETURN; END IF;
  SELECT * INTO v_secrets FROM public.crm_multiempresas_marketing_ai_studio_secrets WHERE config_id = v_config.id;
  v_openai := COALESCE(NULLIF(btrim(v_secrets.openai_api_key), ''), NULL);
  v_serp := COALESCE(NULLIF(btrim(v_secrets.serp_api_key), ''), NULL);
  id := v_config.id; ativo := v_config.ativo; model_pesquisa := v_config.model_pesquisa; model_copy := v_config.model_copy;
  openai_configured := v_openai IS NOT NULL;
  openai_key_hint := CASE WHEN v_openai IS NULL THEN NULL WHEN length(v_openai) <= 4 THEN '••••' ELSE '••••' || right(v_openai, 4) END;
  serp_configured := v_serp IS NOT NULL;
  serp_key_hint := CASE WHEN v_serp IS NULL THEN NULL WHEN length(v_serp) <= 4 THEN '••••' ELSE '••••' || right(v_serp, 4) END;
  atualizado_em := GREATEST(v_config.atualizado_em, COALESCE(v_secrets.atualizado_em, v_config.atualizado_em));
  RETURN NEXT;
END; $$;


--
-- Name: get_marketing_ai_studio_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_marketing_ai_studio_status() RETURNS TABLE(id uuid, ativo boolean, model_pesquisa text, model_copy text, criado_em timestamp with time zone, atualizado_em timestamp with time zone, openai_configured boolean, openai_key_hint text, serp_configured boolean, serp_key_hint text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    c.id,
    c.ativo,
    c.model_pesquisa,
    c.model_copy,
    c.criado_em,
    c.atualizado_em,
    (s.openai_api_key IS NOT NULL AND btrim(s.openai_api_key) <> '') AS openai_configured,
    CASE
      WHEN s.openai_api_key IS NOT NULL AND length(btrim(s.openai_api_key)) >= 4
        THEN '••••' || right(btrim(s.openai_api_key), 4)
      ELSE NULL
    END AS openai_key_hint,
    (s.serp_api_key IS NOT NULL AND btrim(s.serp_api_key) <> '') AS serp_configured,
    CASE
      WHEN s.serp_api_key IS NOT NULL AND length(btrim(s.serp_api_key)) >= 4
        THEN '••••' || right(btrim(s.serp_api_key), 4)
      ELSE NULL
    END AS serp_key_hint
  FROM public.marketing_ai_studio_config c
  LEFT JOIN public.marketing_ai_studio_secrets s ON s.config_id = c.id
  ORDER BY c.criado_em ASC
  LIMIT 1;
$$;


--
-- Name: get_marketing_ai_webhook_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_marketing_ai_webhook_status() RETURNS TABLE(id uuid, ativo boolean, topo_configured boolean, topo_url_hint text, fundo_configured boolean, fundo_url_hint text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    c.id,
    c.ativo,
    (s.webhook_topo_url IS NOT NULL AND btrim(s.webhook_topo_url) <> '') AS topo_configured,
    CASE
      WHEN s.webhook_topo_url IS NOT NULL AND length(btrim(s.webhook_topo_url)) >= 8
        THEN '••••' || right(btrim(s.webhook_topo_url), 8)
      WHEN s.webhook_topo_url IS NOT NULL AND btrim(s.webhook_topo_url) <> ''
        THEN '••••'
      ELSE NULL
    END AS topo_url_hint,
    (s.webhook_fundo_url IS NOT NULL AND btrim(s.webhook_fundo_url) <> '') AS fundo_configured,
    CASE
      WHEN s.webhook_fundo_url IS NOT NULL AND length(btrim(s.webhook_fundo_url)) >= 8
        THEN '••••' || right(btrim(s.webhook_fundo_url), 8)
      WHEN s.webhook_fundo_url IS NOT NULL AND btrim(s.webhook_fundo_url) <> ''
        THEN '••••'
      ELSE NULL
    END AS fundo_url_hint
  FROM public.marketing_ai_studio_config c
  LEFT JOIN public.marketing_ai_studio_secrets s ON s.config_id = c.id
  ORDER BY c.criado_em ASC
  LIMIT 1;
$$;


--
-- Name: FUNCTION get_marketing_ai_webhook_status(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_marketing_ai_webhook_status() IS 'Status mascarado dos webhooks de conteúdo (Topo/Fundo). URLs completas nunca saem desta RPC.';


