--
-- Name: get_session_metrics(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_session_metrics(p_data_inicio timestamp with time zone, p_data_fim timestamp with time zone) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  resultado JSON;
BEGIN
  WITH acessos_por_dia AS (
    SELECT 
      DATE(created_at AT TIME ZONE 'America/Sao_Paulo') as dia,
      COUNT(*) as total
    FROM auth.sessions
    WHERE created_at BETWEEN p_data_inicio AND p_data_fim
    GROUP BY DATE(created_at AT TIME ZONE 'America/Sao_Paulo')
    ORDER BY dia DESC
  ),
  totais AS (
    SELECT 
      COUNT(DISTINCT user_id) as total_usuarios_unicos
    FROM auth.sessions
    WHERE created_at BETWEEN p_data_inicio AND p_data_fim
  )
  SELECT json_build_object(
    'acessos_hoje', COALESCE(
      (SELECT total FROM acessos_por_dia WHERE dia = (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo')::date), 0
    ),
    'usuarios_unicos', (SELECT total_usuarios_unicos FROM totais),
    'media_sessoes_dia', COALESCE(
      (SELECT AVG(total)::numeric(10,1) FROM acessos_por_dia), 0
    ),
    'acessos_por_dia', COALESCE(
      (SELECT json_agg(json_build_object('dia', dia::text, 'total', total) ORDER BY dia DESC)
       FROM acessos_por_dia),
      '[]'::json
    )
  ) INTO resultado;
  
  RETURN resultado;
END;
$$;


--
-- Name: get_user_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_role(_user_id uuid) RETURNS public.selletos_crm_app_role
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT role
  FROM public."CRM-Selletos>user_roles<"
  WHERE user_id = _user_id
  ORDER BY CASE role
    WHEN 'admin'::public.selletos_crm_app_role THEN 1
    WHEN 'vendedor'::public.selletos_crm_app_role THEN 2
    WHEN 'marketing'::public.selletos_crm_app_role THEN 3
    ELSE 4
  END
  LIMIT 1;
$$;


--
-- Name: get_vendor_performance_filtered(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_vendor_performance_filtered(_cutoff_date date) RETURNS TABLE(vendedor_id uuid, vendedor_nome text, avatar_url text, total_leads bigint, vendas bigint, receita numeric, taxa_conversao numeric, ticket_medio numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    u.id AS vendedor_id,
    u.nome AS vendedor_nome,
    u.avatar_url,
    COUNT(l.id) AS total_leads,
    COUNT(*) FILTER (WHERE l.status = 'Venda Realizada (Matriculado)') AS vendas,
    COALESCE(SUM(l.valor_negocio) FILTER (WHERE l.status = 'Venda Realizada (Matriculado)'), 0) AS receita,
    ROUND(
      100.0 * COUNT(*) FILTER (WHERE l.status = 'Venda Realizada (Matriculado)')
      / NULLIF(COUNT(l.id), 0),
      2
    ) AS taxa_conversao,
    ROUND(AVG(l.valor_negocio) FILTER (WHERE l.status = 'Venda Realizada (Matriculado)'), 2) AS ticket_medio
  FROM public."CRM-Selletos>usuarios<" u
  LEFT JOIN public."CRM-Selletos>leads<" l
    ON l.vendedor_responsavel_id = u.id
    AND l.data_chegada >= _cutoff_date
    AND (
      public.is_admin(auth.uid())
      OR (public.is_vendedor(auth.uid()) AND public.has_permission(auth.uid(), 'all_leads', 'view'))
      OR (public.is_vendedor(auth.uid()) AND l.vendedor_responsavel_id = auth.uid())
    )
  WHERE u.status_convite = 'ATIVO'
  GROUP BY u.id, u.nome, u.avatar_url
  ORDER BY vendas DESC, receita DESC;
$$;


--
-- Name: handle_lead_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_lead_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _vendor_name TEXT;
  _notification_type TEXT;
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    SELECT nome INTO _vendor_name
    FROM "CRM-Selletos>usuarios<"
    WHERE id = NEW.vendedor_responsavel_id;

    IF _vendor_name IS NULL THEN
      _vendor_name := 'Vendedor desconhecido';
    END IF;

    CASE NEW.status
      WHEN 'Aula Experimental Marcada' THEN
        _notification_type := 'aula_marcada';
      WHEN 'Venda Realizada (Matriculado)' THEN
        _notification_type := 'venda_realizada';
      WHEN 'Venda Perdida (Não Matriculado)' THEN
        _notification_type := 'venda_perdida';
      ELSE
        RETURN NEW;
    END CASE;

    IF NEW.vendedor_responsavel_id IS NOT NULL THEN
      PERFORM create_lead_notification(
        NEW.id,
        _notification_type,
        NEW.vendedor_responsavel_id,
        _vendor_name
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


