--
-- Name: has_permission(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_permission(_user_id uuid, _resource text, _action text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    public.is_admin(_user_id)
    OR COALESCE(
      (
        SELECT bool_or(up.allowed)
        FROM public."CRM-Selletos>user_permissions<" up
        INNER JOIN public."CRM-Selletos>user_roles<" ur ON ur.role = up.role
        WHERE ur.user_id = _user_id
          AND up.resource = _resource
          AND up.action = _action
      ),
      false
    );
$$;


--
-- Name: FUNCTION has_permission(_user_id uuid, _resource text, _action text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_permission(_user_id uuid, _resource text, _action text) IS 'Admin tem tudo. Demais roles usam bool_or das permissões. Não usar COALESCE(is_admin, ...) porque FALSE curto-circuita.';


