--
-- Name: ler_form_inicio_orcamento(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ler_form_inicio_orcamento(p_schema text, p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_lead record;
  v_campos jsonb := '[]'::jsonb;
  v_empresa_nome text := NULL;
  v_row record;
  v_prefill text;
BEGIN
  IF p_token IS NULL OR trim(p_token) = '' THEN
    RAISE EXCEPTION 'Token inválido';
  END IF;

  IF public._form_orcamento_schema_ok(p_schema) THEN
    EXECUTE format(
      'SELECT id, nome, telefone, email, token_form_orcamento
         FROM %I.leads
        WHERE token_form_orcamento = $1
        LIMIT 1',
      p_schema
    )
      INTO v_lead
      USING trim(p_token);

    IF v_lead IS NULL OR v_lead.id IS NULL THEN
      RAISE EXCEPTION 'Link inválido ou expirado';
    END IF;

    BEGIN
      SELECT e.nome INTO v_empresa_nome
        FROM public."CRM-multi-empresas>empresas<" e
       WHERE e.schema_nome = p_schema
       LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
      v_empresa_nome := NULL;
    END;

    FOR v_row IN EXECUTE format(
      'SELECT nome, label, tipo, obrigatorio, ordem
         FROM %I.contratos_variaveis
        WHERE mostrar_no_link_publico = true
        ORDER BY ordem ASC',
      p_schema
    )
    LOOP
      v_prefill := NULL;
      IF lower(v_row.nome) IN ('nome', 'cliente_nome', 'nome_cliente', 'contratante') THEN
        v_prefill := v_lead.nome;
      ELSIF lower(v_row.nome) IN ('telefone', 'whatsapp', 'celular') THEN
        v_prefill := v_lead.telefone;
      ELSIF lower(v_row.nome) = 'email' THEN
        v_prefill := v_lead.email;
      END IF;

      v_campos := v_campos || jsonb_build_array(jsonb_build_object(
        'nome', v_row.nome,
        'label', v_row.label,
        'tipo', v_row.tipo,
        'obrigatorio', v_row.obrigatorio,
        'ordem', v_row.ordem,
        'valor_prefill', coalesce(v_prefill, '')
      ));
    END LOOP;
  ELSE
    SELECT id, nome, telefone, email, token_form_orcamento
      INTO v_lead
      FROM public."CRM-multi-empresas>leads<"
     WHERE token_form_orcamento = trim(p_token)
     LIMIT 1;

    IF v_lead IS NULL OR v_lead.id IS NULL THEN
      RAISE EXCEPTION 'Link inválido ou expirado';
    END IF;

    FOR v_row IN
      SELECT nome, label, tipo, obrigatorio, ordem
        FROM public."CRM-multi-empresas>contratos_variaveis<"
       WHERE mostrar_no_link_publico = true
         AND (schema_nome IS NULL OR schema_nome = coalesce(nullif(p_schema, ''), schema_nome))
       ORDER BY ordem ASC
    LOOP
      v_prefill := NULL;
      IF lower(v_row.nome) IN ('nome', 'cliente_nome', 'nome_cliente', 'contratante') THEN
        v_prefill := v_lead.nome;
      ELSIF lower(v_row.nome) IN ('telefone', 'whatsapp', 'celular') THEN
        v_prefill := v_lead.telefone;
      ELSIF lower(v_row.nome) = 'email' THEN
        v_prefill := v_lead.email;
      END IF;

      v_campos := v_campos || jsonb_build_array(jsonb_build_object(
        'nome', v_row.nome,
        'label', v_row.label,
        'tipo', v_row.tipo,
        'obrigatorio', v_row.obrigatorio,
        'ordem', v_row.ordem,
        'valor_prefill', coalesce(v_prefill, '')
      ));
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'lead_id', v_lead.id,
    'cliente_nome', coalesce(v_lead.nome, ''),
    'empresa_nome', v_empresa_nome,
    'campos', v_campos
  );
END;
$_$;


--
-- Name: log_lead_pipeline_movimento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_lead_pipeline_movimento() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status IS NOT NULL AND btrim(NEW.status) <> '' THEN
      IF TG_TABLE_SCHEMA = 'public' THEN
        INSERT INTO public."CRM-multi-empresas>lead_pipeline_movimentos<" (lead_id, status)
        VALUES (NEW.id, NEW.status);
      ELSE
        EXECUTE format(
          'INSERT INTO %I.lead_pipeline_movimentos (lead_id, status) VALUES ($1, $2)',
          TG_TABLE_SCHEMA
        ) USING NEW.id, NEW.status;
      END IF;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
    IF NEW.status IS NOT NULL AND btrim(NEW.status) <> '' THEN
      IF TG_TABLE_SCHEMA = 'public' THEN
        INSERT INTO public."CRM-multi-empresas>lead_pipeline_movimentos<" (lead_id, status)
        VALUES (NEW.id, NEW.status);
      ELSE
        EXECUTE format(
          'INSERT INTO %I.lead_pipeline_movimentos (lead_id, status) VALUES ($1, $2)',
          TG_TABLE_SCHEMA
        ) USING NEW.id, NEW.status;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: marketing_content_cards_lock_script_original(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_content_cards_lock_script_original() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.script_copy_original := COALESCE(NEW.script_copy_original, NEW.script_copy);
    RETURN NEW;
  END IF;

  IF OLD.script_copy_original IS NOT NULL THEN
    NEW.script_copy_original := OLD.script_copy_original;
  ELSIF NEW.script_copy_original IS NULL THEN
    NEW.script_copy_original := COALESCE(NEW.script_copy_original, NEW.script_copy, OLD.script_copy);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: marketing_p2p_grant_commission(uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_p2p_grant_commission(_seller_id uuid, _event_key text, _entity_type text, _entity_id text, _source_proof_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _rule RECORD;
  _work_date DATE := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  _file_count INT := 0;
BEGIN
  IF NOT (
    public.is_admin(auth.uid())
    OR auth.uid() = _seller_id
    OR public.is_vendedor(auth.uid())
    OR public.is_vendedor_p2p(auth.uid())
  ) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  IF _event_key IS DISTINCT FROM 'aula_experimental' THEN
    IF _source_proof_id IS NULL THEN
      RETURN;
    END IF;

    SELECT COUNT(*)::INT INTO _file_count
    FROM public."CRM-Selletos>marketing_p2p_contact_proof_files<"
    WHERE proof_id = _source_proof_id;

    IF _file_count < 1 THEN
      RETURN;
    END IF;
  END IF;

  SELECT * INTO _rule
  FROM public."CRM-Selletos>marketing_p2p_commission_rules<"
  WHERE event_key = _event_key AND active = true
  LIMIT 1;

  IF NOT FOUND OR _rule.amount_brl <= 0 THEN
    RETURN;
  END IF;

  INSERT INTO public."CRM-Selletos>marketing_p2p_commission_ledger<" (
    seller_id, event_key, entity_type, entity_id, amount_brl, rule_id, source_proof_id, work_date
  ) VALUES (
    _seller_id, _event_key, _entity_type, _entity_id, _rule.amount_brl, _rule.id, _source_proof_id, _work_date
  )
  ON CONFLICT (seller_id, event_key, entity_type, entity_id) DO NOTHING;
END;
$$;


--
-- Name: marketing_p2p_record_daily_move(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_p2p_record_daily_move(_seller_id uuid, _entity_type text, _entity_id text, _event_kind text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _work_date DATE := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
BEGIN
  IF NOT (public.is_admin(auth.uid()) OR auth.uid() = _seller_id OR public.is_vendedor(auth.uid())) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  INSERT INTO public."CRM-Selletos>marketing_p2p_daily_moves<" (work_date, seller_id, entity_type, entity_id, event_kinds)
  VALUES (_work_date, _seller_id, _entity_type, _entity_id, ARRAY[_event_kind])
  ON CONFLICT (work_date, seller_id, entity_type, entity_id)
  DO UPDATE SET
    last_event_at = now(),
    event_kinds = (
      SELECT array_agg(DISTINCT kind)
      FROM unnest(
        COALESCE(public."CRM-Selletos>marketing_p2p_daily_moves<".event_kinds, '{}'::text[]) || ARRAY[_event_kind]
      ) AS kind
    );
END;
$$;


--
-- Name: match_ai_memories(public.vector, uuid, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_ai_memories(query_embedding public.vector, filter_company_id uuid, match_threshold double precision DEFAULT 0.7, match_count integer DEFAULT 10) RETURNS TABLE(id uuid, category text, user_instruction text, similarity double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    ai_memories.id,
    ai_memories.category,
    ai_memories.user_instruction,
    (1 - (ai_memories.embedding <=> query_embedding))::float AS similarity
  FROM public.ai_memories
  WHERE ai_memories.company_id = filter_company_id
    AND 1 - (ai_memories.embedding <=> query_embedding) > match_threshold
  ORDER BY ai_memories.embedding <=> query_embedding
  LIMIT match_count;
$$;


--
-- Name: match_lead_knowledge_me(bigint, public.vector, integer, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_lead_knowledge_me(p_lead_id bigint, query_embedding public.vector, match_count integer DEFAULT 10, match_threshold double precision DEFAULT 0.5) RETURNS TABLE(id uuid, content text, source_type text, metadata jsonb, similarity double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    c.id,
    c.content,
    c.source_type,
    c.metadata,
    1 - (c.embedding <=> query_embedding) AS similarity
  FROM public."CRM-multi-empresas>lead_ai_knowledge_chunks<" c
  WHERE c.lead_id = p_lead_id
    AND c.embedding IS NOT NULL
    AND 1 - (c.embedding <=> query_embedding) >= match_threshold
  ORDER BY c.embedding <=> query_embedding
  LIMIT GREATEST(match_count, 1);
$$;


--
-- Name: me_criar_empresa(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_criar_empresa(p_nome text, p_slug text, p_cor_primaria text DEFAULT '#6366f1'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_schema TEXT;
  v_empresa_id UUID;
BEGIN
  IF NOT me_is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Acesso negado: apenas super admins podem criar empresas';
  END IF;

  IF p_slug !~ '^[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'Slug inválido: use apenas letras minúsculas, números e underscore';
  END IF;

  v_schema := 'emp_' || p_slug;
  v_empresa_id := gen_random_uuid();

  IF EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = v_schema) THEN
    IF EXISTS (
      SELECT 1 FROM public."CRM-multi-empresas>empresas<"
      WHERE schema_nome = v_schema
    ) THEN
      RAISE EXCEPTION 'Empresa com slug "%" já existe', p_slug;
    END IF;
    EXECUTE format('DROP SCHEMA %I CASCADE', v_schema);
  END IF;

  EXECUTE format('CREATE SCHEMA %I', v_schema);

  EXECUTE format('CREATE TABLE %I.usuarios (LIKE public."CRM-multi-empresas>usuarios<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.user_roles (LIKE public."CRM-multi-empresas>user_roles<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.lead_origins (LIKE public."CRM-multi-empresas>lead_origins<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.leads (LIKE public."CRM-multi-empresas>leads<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.user_permissions (LIKE public."CRM-multi-empresas>user_permissions<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.notifications (LIKE public."CRM-multi-empresas>notifications<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.kanban_pages (LIKE public."CRM-multi-empresas>kanban_pages<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.kanban_columns (LIKE public."CRM-multi-empresas>kanban_columns<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.kanban_column_sources (LIKE public."CRM-multi-empresas>kanban_column_sources<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.kanban_card_overrides (LIKE public."CRM-multi-empresas>kanban_card_overrides<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.agenda_reunioes (LIKE public."CRM-multi-empresas>agenda_reunioes<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.agenda_config (LIKE public."CRM-multi-empresas>agenda_config<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.agenda_form_fields (LIKE public."CRM-multi-empresas>agenda_form_fields<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.agenda_bloqueios (LIKE public."CRM-multi-empresas>agenda_bloqueios<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.lead_lembretes (LIKE public."CRM-multi-empresas>lead_lembretes<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.lead_custom_field_definitions (LIKE public."CRM-multi-empresas>lead_custom_field_definitions<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.lead_custom_field_values (LIKE public."CRM-multi-empresas>lead_custom_field_values<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.pipeline_custom_stages (LIKE public."CRM-multi-empresas>pipeline_custom_stages<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.pipeline_time_config (LIKE public."CRM-multi-empresas>pipeline_time_config<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.pipeline_daily_metrics (LIKE public."CRM-multi-empresas>pipeline_daily_metrics<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.relatorios_reunioes (LIKE public."CRM-multi-empresas>relatorios_reunioes<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.tabela_origem_config (LIKE public."CRM-multi-empresas>tabela_origem_config<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.webhooks_api (LIKE public."CRM-multi-empresas>webhooks_api<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.cadastro_alunos (LIKE public."CRM-multi-empresas>cadastro_alunos<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.cadastro_config (LIKE public."CRM-multi-empresas>cadastro_config<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.desmatriculados_kanban (LIKE public."CRM-multi-empresas>desmatriculados_kanban<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.desmatriculados_colunas (LIKE public."CRM-multi-empresas>desmatriculados_colunas<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.desmatriculados_movimentos (LIKE public."CRM-multi-empresas>desmatriculados_movimentos<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
