  EXECUTE format('CREATE TABLE %I.uso_config (LIKE public."CRM-multi-empresas>uso_config<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);

  EXECUTE format('CREATE TABLE %I.chat_contatos (LIKE public.crm_multiempresas_chat_contatos INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.chat_mensagens (LIKE public.crm_multiempresas_chat_mensagens INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.chat_logs (LIKE public.crm_multiempresas_chat_logs INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.ui_preferences (LIKE public.crm_multiempresas_ui_preferences INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.atalhos (LIKE public.crm_multiempresas_atalhos INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);

  EXECUTE format('CREATE TABLE %I.marketing_columns (LIKE public.crm_multiempresas_marketing_columns INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_tasks (LIKE public.crm_multiempresas_marketing_tasks INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
