  EXECUTE format('CREATE TABLE %I.marketing_medias (LIKE public.crm_multiempresas_marketing_medias INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_media_folders (LIKE public.crm_multiempresas_marketing_media_folders INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_funnel_stages (LIKE public.crm_multiempresas_marketing_funnel_stages INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_planning_nodes (LIKE public.crm_multiempresas_marketing_planning_nodes INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_planning_edges (LIKE public.crm_multiempresas_marketing_planning_edges INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_planning_drawings (LIKE public.crm_multiempresas_marketing_planning_drawings INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_planning_files (LIKE public.crm_multiempresas_marketing_planning_files INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_planning_shapes (LIKE public.crm_multiempresas_marketing_planning_shapes INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_board_templates (LIKE public.crm_multiempresas_marketing_board_templates INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_central_planning (LIKE public.crm_multiempresas_marketing_central_planning INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_ai_webhook_config (LIKE public.crm_multiempresas_marketing_ai_webhook_config INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_approval_notifications (LIKE public.crm_multiempresas_marketing_approval_notifications INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_products (LIKE public.crm_multiempresas_marketing_products INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_traffic_sources (LIKE public.crm_multiempresas_marketing_traffic_sources INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.marketing_ugc_webhook_config (LIKE public.crm_multiempresas_marketing_ugc_webhook_config INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);

  EXECUTE format('CREATE TABLE %I.mkt_fontes (LIKE public.crm_multiempresas_mkt_fontes INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.mkt_sub_fontes (LIKE public.crm_multiempresas_mkt_sub_fontes INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.mkt_lancamentos (LIKE public.crm_multiempresas_mkt_lancamentos INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.mkt_gastos_config (LIKE public.crm_multiempresas_mkt_gastos_config INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.mkt_config_colunas (LIKE public.crm_multiempresas_mkt_config_colunas INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);

  EXECUTE format('CREATE TABLE %I.agenda_pessoal_tarefas (LIKE public.crm_multiempresas_agenda_pessoal_tarefas INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.agenda_pessoal_admin_titular_filter (LIKE public.crm_multiempresas_agenda_pessoal_admin_titular_filter INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);

  EXECUTE format('CREATE TABLE %I.negativacao_webhook_config (LIKE public.crm_multiempresas_negativacao_webhook_config INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);
  EXECUTE format('CREATE TABLE %I.negativacao_numeros (LIKE public."CRM-multi-empresas>negativacao_numeros<" INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES INCLUDING GENERATED)', v_schema);

  PERFORM public.me_ensure_pk(v_schema, 'usuarios');
  PERFORM public.me_ensure_pk(v_schema, 'leads');
  PERFORM public.me_ensure_pk(v_schema, 'mkt_fontes');

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
    JOIN pg_class t ON t.oid = c.conrelid
    JOIN pg_namespace n ON n.oid = t.relnamespace
    WHERE n.nspname = v_schema AND t.relname = 'user_roles' AND c.conname = 'emp_user_roles_user_id_fkey'
  ) THEN
    EXECUTE format('ALTER TABLE %I.user_roles ADD CONSTRAINT emp_user_roles_user_id_fkey FOREIGN KEY (user_id) REFERENCES %I.usuarios(id) ON DELETE CASCADE', v_schema, v_schema);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
    JOIN pg_class t ON t.oid = c.conrelid
    JOIN pg_namespace n ON n.oid = t.relnamespace
    WHERE n.nspname = v_schema AND t.relname = 'leads' AND c.conname = 'emp_leads_vendedor_fkey'
  ) THEN
    EXECUTE format('ALTER TABLE %I.leads ADD CONSTRAINT emp_leads_vendedor_fkey FOREIGN KEY (vendedor_responsavel_id) REFERENCES %I.usuarios(id) ON DELETE SET NULL', v_schema, v_schema);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
    JOIN pg_class t ON t.oid = c.conrelid
    JOIN pg_namespace n ON n.oid = t.relnamespace
    WHERE n.nspname = v_schema AND t.relname = 'lead_lembretes' AND c.conname = 'emp_lead_lembretes_lead_fkey'
  ) THEN
    EXECUTE format('ALTER TABLE %I.lead_lembretes ADD CONSTRAINT emp_lead_lembretes_lead_fkey FOREIGN KEY (lead_id) REFERENCES %I.leads(id) ON DELETE CASCADE', v_schema, v_schema);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
    JOIN pg_class t ON t.oid = c.conrelid
    JOIN pg_namespace n ON n.oid = t.relnamespace
    WHERE n.nspname = v_schema AND t.relname = 'lead_custom_field_values' AND c.conname = 'emp_lead_custom_field_values_field_fkey'
  ) THEN
    EXECUTE format('ALTER TABLE %I.lead_custom_field_values ADD CONSTRAINT emp_lead_custom_field_values_field_fkey FOREIGN KEY (field_id) REFERENCES %I.lead_custom_field_definitions(id) ON DELETE CASCADE', v_schema, v_schema);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
    JOIN pg_class t ON t.oid = c.conrelid
    JOIN pg_namespace n ON n.oid = t.relnamespace
    WHERE n.nspname = v_schema AND t.relname = 'mkt_sub_fontes' AND c.conname = 'emp_mkt_sub_fontes_fonte_fkey'
  ) THEN
    EXECUTE format('ALTER TABLE %I.mkt_sub_fontes ADD CONSTRAINT emp_mkt_sub_fontes_fonte_fkey FOREIGN KEY (fonte_id) REFERENCES %I.mkt_fontes(id) ON DELETE CASCADE', v_schema, v_schema);
  END IF;

  EXECUTE format(
    'INSERT INTO %I.agenda_config (nome_agenda, slug, ativo)
     SELECT ''Agenda Principal'', ''agendamento'', true
     WHERE NOT EXISTS (SELECT 1 FROM %I.agenda_config WHERE ativo = true)',
    v_schema,
    v_schema
  );

  
  -- funil_projetos_clone
  PERFORM public.me_ensure_funil_projetos(v_schema);
  PERFORM public.me_grant_empresa_schema(v_schema);

  INSERT INTO public."CRM-multi-empresas>empresas<" (id, nome, slug, schema_nome, cor_primaria)
  VALUES (v_empresa_id, p_nome, p_slug, v_schema, p_cor_primaria);

  RETURN v_empresa_id;
END;
$_$;


--
-- Name: me_empresa_has_any_role(text, text[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_empresa_has_any_role(_schema text, _roles text[], _user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_found boolean := false;
BEGIN
  IF _user_id IS NULL OR _schema IS NULL OR _schema !~ '^emp_[a-z0-9_]+$' THEN
    RETURN false;
  END IF;
  EXECUTE format(
    'SELECT EXISTS (SELECT 1 FROM %I.user_roles WHERE user_id = $1 AND role::text = ANY($2))',
    _schema
  )
  INTO v_found
  USING _user_id, _roles;
  RETURN COALESCE(v_found, false);
END;
$_$;


--
-- Name: me_enable_lead_projetos_realtime(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_enable_lead_projetos_realtime(p_schema text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_schema IS NULL THEN
    RETURN;
  END IF;

  IF p_schema = 'public' THEN
    BEGIN
      ALTER PUBLICATION supabase_realtime ADD TABLE public."CRM-multi-empresas>lead_projetos<";
    EXCEPTION
      WHEN duplicate_object THEN NULL;
      WHEN undefined_object THEN NULL;
    END;
    RETURN;
  END IF;

  IF p_schema NOT LIKE 'emp\_%' ESCAPE '\' THEN
    RETURN;
  END IF;

  IF to_regclass(format('%I.lead_projetos', p_schema)) IS NULL THEN
    RETURN;
  END IF;

  BEGIN
    EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE %I.lead_projetos', p_schema);
  EXCEPTION
    WHEN duplicate_object THEN NULL;
    WHEN undefined_object THEN NULL;
  END;
END;
$$;


--
-- Name: me_ensure_evento_caderno(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_ensure_evento_caderno(p_schema text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_idx text;
BEGIN
  IF p_schema IS NULL OR p_schema NOT LIKE 'emp\_%' ESCAPE '\' THEN
    RETURN;
  END IF;

  IF to_regclass(format('%I.eventos', p_schema)) IS NULL THEN
    RETURN;
  END IF;

  v_idx := replace(p_schema, 'emp_', '');

  EXECUTE format(
    'ALTER TABLE %I.eventos ADD COLUMN IF NOT EXISTS fixado boolean NOT NULL DEFAULT false',
    p_schema
  );
  EXECUTE format(
    'ALTER TABLE %I.eventos ADD COLUMN IF NOT EXISTS ordem_topo integer',
    p_schema
  );
  EXECUTE format(
    'CREATE INDEX IF NOT EXISTS idx_%s_eventos_pin ON %I.eventos (fixado DESC, ordem_topo NULLS LAST, data_evento DESC)',
    v_idx, p_schema
  );

  EXECUTE format(
    'CREATE TABLE IF NOT EXISTS %I.evento_tarefas (
       id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
       evento_id uuid NOT NULL REFERENCES %I.eventos(id) ON DELETE CASCADE,
       titulo text NOT NULL,
       concluida boolean NOT NULL DEFAULT false,
       ordem integer NOT NULL DEFAULT 0,
       criado_em timestamptz NOT NULL DEFAULT now(),
       atualizado_em timestamptz NOT NULL DEFAULT now(),
       CONSTRAINT evento_tarefas_titulo_chk CHECK (char_length(btrim(titulo)) >= 1)
     )',
    p_schema, p_schema
  );
  EXECUTE format(
    'CREATE INDEX IF NOT EXISTS idx_%s_evento_tarefas_evento ON %I.evento_tarefas (evento_id, ordem)',
    v_idx, p_schema
  );

  EXECUTE format(
    'CREATE TABLE IF NOT EXISTS %I.evento_paginas (
       id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
       evento_id uuid NOT NULL REFERENCES %I.eventos(id) ON DELETE CASCADE,
       secao text NOT NULL DEFAULT ''detalhes''
         CHECK (secao IN (''detalhes'', ''discurso'', ''palestra'')),
       titulo text NOT NULL DEFAULT '''',
       corpo text NOT NULL DEFAULT '''',
       ordem integer NOT NULL DEFAULT 0,
       criado_em timestamptz NOT NULL DEFAULT now(),
       atualizado_em timestamptz NOT NULL DEFAULT now()
     )',
    p_schema, p_schema
  );
  EXECUTE format(
    'CREATE INDEX IF NOT EXISTS idx_%s_evento_paginas_evento ON %I.evento_paginas (evento_id, secao, ordem)',
    v_idx, p_schema
  );

  EXECUTE format('ALTER TABLE %I.evento_tarefas ENABLE ROW LEVEL SECURITY', p_schema);
  EXECUTE format('ALTER TABLE %I.evento_paginas ENABLE ROW LEVEL SECURITY', p_schema);

  EXECUTE format('DROP POLICY IF EXISTS me_evento_tarefas_all ON %I.evento_tarefas', p_schema);
  EXECUTE format(
    'CREATE POLICY me_evento_tarefas_all ON %I.evento_tarefas FOR ALL TO authenticated USING (true) WITH CHECK (true)',
    p_schema
  );
  EXECUTE format('DROP POLICY IF EXISTS me_evento_paginas_all ON %I.evento_paginas', p_schema);
  EXECUTE format(
    'CREATE POLICY me_evento_paginas_all ON %I.evento_paginas FOR ALL TO authenticated USING (true) WITH CHECK (true)',
    p_schema
  );

  EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON %I.evento_tarefas TO authenticated, service_role', p_schema);
  EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON %I.evento_paginas TO authenticated, service_role', p_schema);
END;
$$;


--
-- Name: me_ensure_funil_projetos(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_ensure_funil_projetos(p_schema text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_idx text := replace(p_schema, 'emp_', '');
BEGIN
  IF p_schema IS NULL OR p_schema NOT LIKE 'emp\_%' ESCAPE '\' THEN
    RETURN;
  END IF;

  EXECUTE format(
    'CREATE TABLE IF NOT EXISTS %I.projeto_stages (
       id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
       nome text NOT NULL,
       cor text,
       ordem integer NOT NULL DEFAULT 0,
       ativo boolean NOT NULL DEFAULT true,
       is_default boolean NOT NULL DEFAULT false,
       criado_em timestamptz NOT NULL DEFAULT now(),
       atualizado_em timestamptz NOT NULL DEFAULT now()
     )',
    p_schema
  );
  EXECUTE format(
    'CREATE INDEX IF NOT EXISTS idx_%s_projeto_stages_ordem ON %I.projeto_stages (ativo, ordem)',
    v_idx, p_schema
  );

  EXECUTE format(
    'CREATE TABLE IF NOT EXISTS %I.lead_projetos (
       id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
       lead_id bigint NOT NULL REFERENCES %I.leads(id) ON DELETE CASCADE,
       stage_id uuid NOT NULL REFERENCES %I.projeto_stages(id) ON DELETE RESTRICT,
       titular_id uuid,
       arquiteto_id uuid,
       enviado_por uuid,
       enviado_em timestamptz NOT NULL DEFAULT now(),
       aguardando_resposta boolean NOT NULL DEFAULT true,
       criado_em timestamptz NOT NULL DEFAULT now(),
       atualizado_em timestamptz NOT NULL DEFAULT now(),
       CONSTRAINT lead_projetos_lead_unique UNIQUE (lead_id)
     )',
    p_schema, p_schema, p_schema
  );
  EXECUTE format(
    'CREATE INDEX IF NOT EXISTS idx_%s_lead_projetos_stage ON %I.lead_projetos (stage_id)',
    v_idx, p_schema
  );
  EXECUTE format(
    'CREATE INDEX IF NOT EXISTS idx_%s_lead_projetos_arquiteto ON %I.lead_projetos (arquiteto_id)',
    v_idx, p_schema
  );

  EXECUTE format('DROP TRIGGER IF EXISTS trg_projeto_stages_updated ON %I.projeto_stages', p_schema);
  EXECUTE format(
    'CREATE TRIGGER trg_projeto_stages_updated
       BEFORE UPDATE ON %I.projeto_stages
       FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()',
    p_schema
  );
  EXECUTE format('DROP TRIGGER IF EXISTS trg_lead_projetos_updated ON %I.lead_projetos', p_schema);
  EXECUTE format(
    'CREATE TRIGGER trg_lead_projetos_updated
       BEFORE UPDATE ON %I.lead_projetos
       FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()',
    p_schema
  );

  EXECUTE format(
    'INSERT INTO %I.projeto_stages (nome, cor, ordem, ativo, is_default)
     SELECT v.nome, v.cor, v.ordem, true, true
     FROM (VALUES
       (''Projetos aguardando serem feitos'', ''warning'', 0),
       (''Visita agendada'', ''primary'', 1),
       (''Projetos feitos'', ''success'', 2)
     ) AS v(nome, cor, ordem)
     WHERE NOT EXISTS (SELECT 1 FROM %I.projeto_stages LIMIT 1)',
    p_schema, p_schema
  );

  PERFORM public.me_ensure_projeto_visita_column(p_schema);

  EXECUTE format('ALTER TABLE %I.projeto_stages ENABLE ROW LEVEL SECURITY', p_schema);
  EXECUTE format('ALTER TABLE %I.lead_projetos ENABLE ROW LEVEL SECURITY', p_schema);

  EXECUTE format('DROP POLICY IF EXISTS me_projeto_stages_select ON %I.projeto_stages', p_schema);
  EXECUTE format(
    'CREATE POLICY me_projeto_stages_select ON %I.projeto_stages
       FOR SELECT TO authenticated USING (true)',
    p_schema
  );
  EXECUTE format('DROP POLICY IF EXISTS me_projeto_stages_write ON %I.projeto_stages', p_schema);
  EXECUTE format(
    'CREATE POLICY me_projeto_stages_write ON %I.projeto_stages
       FOR ALL TO authenticated
       USING (public.me_is_crm_projetista_admin((SELECT auth.uid())))
       WITH CHECK (public.me_is_crm_projetista_admin((SELECT auth.uid())))',
    p_schema
  );

  EXECUTE format('DROP POLICY IF EXISTS me_lead_projetos_select ON %I.lead_projetos', p_schema);
  EXECUTE format(
    'CREATE POLICY me_lead_projetos_select ON %I.lead_projetos
       FOR SELECT TO authenticated
       USING (
         public.me_is_super_admin((SELECT auth.uid()))
         OR public.me_get_empresa_role(%L, (SELECT auth.uid())) = ''admin''
         OR public.me_empresa_has_any_role(%L, ARRAY[''vendedor''], (SELECT auth.uid()))
         OR public.me_empresa_has_any_role(%L, ARRAY[''projetista'', ''projetista_admin''], (SELECT auth.uid()))
       )',
    p_schema, p_schema, p_schema, p_schema
  );

  EXECUTE format('DROP POLICY IF EXISTS me_lead_projetos_insert ON %I.lead_projetos', p_schema);
  EXECUTE format(
    'CREATE POLICY me_lead_projetos_insert ON %I.lead_projetos
       FOR INSERT TO authenticated
       WITH CHECK (
         public.me_is_super_admin((SELECT auth.uid()))
         OR public.me_get_empresa_role(%L, (SELECT auth.uid())) = ''admin''
         OR public.me_empresa_has_any_role(%L, ARRAY[''vendedor''], (SELECT auth.uid()))
         OR public.me_empresa_has_any_role(%L, ARRAY[''projetista'', ''projetista_admin''], (SELECT auth.uid()))
       )',
    p_schema, p_schema, p_schema, p_schema
  );

  EXECUTE format('DROP POLICY IF EXISTS me_lead_projetos_update ON %I.lead_projetos', p_schema);
  EXECUTE format(
    'CREATE POLICY me_lead_projetos_update ON %I.lead_projetos
       FOR UPDATE TO authenticated
       USING (
         public.me_is_super_admin((SELECT auth.uid()))
         OR public.me_get_empresa_role(%L, (SELECT auth.uid())) = ''admin''
         OR public.me_empresa_has_any_role(%L, ARRAY[''vendedor''], (SELECT auth.uid()))
         OR public.me_empresa_has_any_role(%L, ARRAY[''projetista'', ''projetista_admin''], (SELECT auth.uid()))
       )
       WITH CHECK (
         public.me_is_super_admin((SELECT auth.uid()))
         OR public.me_get_empresa_role(%L, (SELECT auth.uid())) = ''admin''
         OR public.me_empresa_has_any_role(%L, ARRAY[''vendedor''], (SELECT auth.uid()))
         OR public.me_empresa_has_any_role(%L, ARRAY[''projetista'', ''projetista_admin''], (SELECT auth.uid()))
       )',
    p_schema, p_schema, p_schema, p_schema, p_schema, p_schema, p_schema
  );

  EXECUTE format('DROP POLICY IF EXISTS me_lead_projetos_delete ON %I.lead_projetos', p_schema);
  EXECUTE format(
    'CREATE POLICY me_lead_projetos_delete ON %I.lead_projetos
       FOR DELETE TO authenticated
       USING (public.me_is_crm_projetista_admin((SELECT auth.uid())))',
    p_schema
  );

  EXECUTE format(
    'GRANT SELECT, INSERT, UPDATE, DELETE ON %I.projeto_stages TO authenticated, service_role',
    p_schema
  );
  EXECUTE format(
    'GRANT SELECT, INSERT, UPDATE, DELETE ON %I.lead_projetos TO authenticated, service_role',
    p_schema
  );

  EXECUTE format('DROP POLICY IF EXISTS emp_leads_projetista_select ON %I.leads', p_schema);
  EXECUTE format(
    'CREATE POLICY emp_leads_projetista_select ON %I.leads
       FOR SELECT TO authenticated
       USING (
         public.me_empresa_has_any_role(%L, ARRAY[''projetista'', ''projetista_admin''], (SELECT auth.uid()))
         AND (
           EXISTS (SELECT 1 FROM %I.lead_projetos lp WHERE lp.lead_id = %I.leads.id)
           OR vendedor_responsavel_id = (SELECT auth.uid())
         )
       )',
    p_schema, p_schema, p_schema, p_schema
  );

  EXECUTE format('DROP POLICY IF EXISTS emp_leads_projetista_insert ON %I.leads', p_schema);
  EXECUTE format(
    'CREATE POLICY emp_leads_projetista_insert ON %I.leads
       FOR INSERT TO authenticated
       WITH CHECK (
         public.me_empresa_has_any_role(%L, ARRAY[''projetista'', ''projetista_admin''], (SELECT auth.uid()))
         AND vendedor_responsavel_id = (SELECT auth.uid())
       )',
    p_schema, p_schema
  );

  EXECUTE format('DROP POLICY IF EXISTS emp_leads_projetista_update ON %I.leads', p_schema);
  EXECUTE format(
    'CREATE POLICY emp_leads_projetista_update ON %I.leads
       FOR UPDATE TO authenticated
       USING (
         public.me_empresa_has_any_role(%L, ARRAY[''projetista'', ''projetista_admin''], (SELECT auth.uid()))
         AND (
           EXISTS (SELECT 1 FROM %I.lead_projetos lp WHERE lp.lead_id = %I.leads.id)
           OR vendedor_responsavel_id = (SELECT auth.uid())
         )
       )
       WITH CHECK (
         public.me_empresa_has_any_role(%L, ARRAY[''projetista'', ''projetista_admin''], (SELECT auth.uid()))
         AND (
           EXISTS (SELECT 1 FROM %I.lead_projetos lp WHERE lp.lead_id = %I.leads.id)
           OR vendedor_responsavel_id = (SELECT auth.uid())
         )
       )',
    p_schema, p_schema, p_schema, p_schema, p_schema, p_schema, p_schema
  );
  PERFORM public.me_ensure_lead_projeto_notas(p_schema);
  PERFORM public.me_ensure_projetista_leads_acesso(p_schema);
  PERFORM public.me_ensure_evento_caderno(p_schema);
END;
$$;


--
-- Name: me_ensure_lead_projeto_notas(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_ensure_lead_projeto_notas(p_schema text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_idx text;
BEGIN
  IF p_schema IS NULL OR p_schema NOT LIKE 'emp\_%' ESCAPE '\' THEN
    RETURN;
  END IF;

  v_idx := replace(p_schema, 'emp_', '');

  EXECUTE format(
    'CREATE TABLE IF NOT EXISTS %I.lead_projeto_notas (
       id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
       lead_id bigint NOT NULL REFERENCES %I.leads(id) ON DELETE CASCADE,
       autor_id uuid NOT NULL,
       mensagem text NOT NULL,
       tipo text NOT NULL DEFAULT ''conversa'',
       imagem_url text,
       file_name text,
       mime_type text,
       criado_em timestamptz NOT NULL DEFAULT now(),
       CONSTRAINT lead_projeto_notas_tipo_chk CHECK (tipo IN (''envio'', ''reenvio'', ''conversa'')),
       CONSTRAINT lead_projeto_notas_conteudo_chk CHECK (
         char_length(btrim(mensagem)) >= 1 OR imagem_url IS NOT NULL
       )
     )',
    p_schema, p_schema
  );

  EXECUTE format('ALTER TABLE %I.lead_projeto_notas ADD COLUMN IF NOT EXISTS imagem_url text', p_schema);
  EXECUTE format('ALTER TABLE %I.lead_projeto_notas ADD COLUMN IF NOT EXISTS file_name text', p_schema);
  EXECUTE format('ALTER TABLE %I.lead_projeto_notas ADD COLUMN IF NOT EXISTS mime_type text', p_schema);

  EXECUTE format(
    'ALTER TABLE %I.lead_projeto_notas DROP CONSTRAINT IF EXISTS lead_projeto_notas_mensagem_chk',
    p_schema
  );
  EXECUTE format(
    'ALTER TABLE %I.lead_projeto_notas DROP CONSTRAINT IF EXISTS lead_projeto_notas_conteudo_chk',
    p_schema
  );
  EXECUTE format(
    'ALTER TABLE %I.lead_projeto_notas
       ADD CONSTRAINT lead_projeto_notas_conteudo_chk CHECK (
         char_length(btrim(mensagem)) >= 1 OR imagem_url IS NOT NULL
       )',
    p_schema
  );

  EXECUTE format(
    'CREATE INDEX IF NOT EXISTS idx_%s_lead_projeto_notas_lead ON %I.lead_projeto_notas (lead_id, criado_em)',
    v_idx, p_schema
  );

  EXECUTE format('ALTER TABLE %I.lead_projeto_notas ENABLE ROW LEVEL SECURITY', p_schema);
  EXECUTE format('ALTER TABLE %I.lead_projeto_notas FORCE ROW LEVEL SECURITY', p_schema);

  EXECUTE format('DROP POLICY IF EXISTS me_lead_projeto_notas_select ON %I.lead_projeto_notas', p_schema);
  EXECUTE format(
    'CREATE POLICY me_lead_projeto_notas_select ON %I.lead_projeto_notas
       FOR SELECT TO authenticated
       USING (
         public.me_is_super_admin((SELECT auth.uid()))
         OR public.me_get_empresa_role(%L, (SELECT auth.uid())) = ''admin''
         OR public.me_empresa_has_any_role(%L, ARRAY[''vendedor''], (SELECT auth.uid()))
         OR public.me_empresa_has_any_role(%L, ARRAY[''projetista'', ''projetista_admin''], (SELECT auth.uid()))
       )',
    p_schema, p_schema, p_schema, p_schema
  );

  EXECUTE format('DROP POLICY IF EXISTS me_lead_projeto_notas_insert ON %I.lead_projeto_notas', p_schema);
  EXECUTE format(
    'CREATE POLICY me_lead_projeto_notas_insert ON %I.lead_projeto_notas
       FOR INSERT TO authenticated
       WITH CHECK (
         autor_id = (SELECT auth.uid())
         AND (
           public.me_is_super_admin((SELECT auth.uid()))
           OR public.me_get_empresa_role(%L, (SELECT auth.uid())) = ''admin''
           OR public.me_empresa_has_any_role(%L, ARRAY[''vendedor''], (SELECT auth.uid()))
           OR public.me_empresa_has_any_role(%L, ARRAY[''projetista'', ''projetista_admin''], (SELECT auth.uid()))
         )
       )',
    p_schema, p_schema, p_schema, p_schema
  );

  EXECUTE format(
    'GRANT SELECT, INSERT ON %I.lead_projeto_notas TO authenticated, service_role',
    p_schema
  );

  BEGIN
    EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE %I.lead_projeto_notas', p_schema);
  EXCEPTION
    WHEN duplicate_object THEN NULL;
    WHEN undefined_object THEN NULL;
  END;
END;
$$;


--
-- Name: me_ensure_pk(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_ensure_pk(_schema text, _table text, _cols text DEFAULT 'id'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint c
    JOIN pg_class t ON t.oid = c.conrelid
    JOIN pg_namespace n ON n.oid = t.relnamespace
    WHERE n.nspname = _schema
      AND t.relname = _table
      AND c.contype = 'p'
  ) THEN
    EXECUTE format(
      'ALTER TABLE %I.%I ADD PRIMARY KEY (%s)',
      _schema,
      _table,
      _cols
    );
  END IF;
END;
$$;


--
-- Name: me_ensure_projetista_leads_acesso(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_ensure_projetista_leads_acesso(p_schema text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF p_schema IS NULL OR p_schema NOT LIKE 'emp\_%' ESCAPE '\' THEN
    RETURN;
  END IF;

  IF to_regclass(format('%I.leads', p_schema)) IS NULL THEN
    RETURN;
  END IF;

  EXECUTE format('DROP POLICY IF EXISTS emp_leads_projetista_select ON %I.leads', p_schema);
  EXECUTE format(
    $sql$
      CREATE POLICY emp_leads_projetista_select ON %I.leads
        FOR SELECT TO authenticated
        USING (
          public.me_empresa_has_any_role(%L, ARRAY['projetista', 'projetista_admin'], (SELECT auth.uid()))
        )
    $sql$,
    p_schema,
    p_schema
  );

  EXECUTE format('DROP POLICY IF EXISTS emp_leads_projetista_update ON %I.leads', p_schema);
  EXECUTE format(
    $sql$
      CREATE POLICY emp_leads_projetista_update ON %I.leads
        FOR UPDATE TO authenticated
        USING (
          public.me_empresa_has_any_role(%L, ARRAY['projetista', 'projetista_admin'], (SELECT auth.uid()))
        )
        WITH CHECK (
          public.me_empresa_has_any_role(%L, ARRAY['projetista', 'projetista_admin'], (SELECT auth.uid()))
        )
    $sql$,
    p_schema,
    p_schema,
    p_schema
  );

  PERFORM public.me_enable_lead_projetos_realtime(p_schema);
END;
$_$;


--
-- Name: me_ensure_projeto_visita_column(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_ensure_projeto_visita_column(p_schema text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_waiting uuid;
  v_visita uuid;
  v_feito uuid;
BEGIN
  IF p_schema IS NULL OR p_schema NOT LIKE 'emp\_%' ESCAPE '\' THEN
    RETURN;
  END IF;
  IF to_regclass(format('%I.projeto_stages', p_schema)) IS NULL THEN
    RETURN;
  END IF;

  EXECUTE format(
    'INSERT INTO %I.projeto_stages (nome, cor, ordem, ativo, is_default)
     SELECT %L, %L, 1, true, true
     WHERE NOT EXISTS (
       SELECT 1 FROM %I.projeto_stages WHERE nome ILIKE %L
     )',
    p_schema,
    'Visita agendada',
    'primary',
    p_schema,
    '%visita%'
  );

  EXECUTE format(
    'SELECT id FROM %I.projeto_stages WHERE nome ILIKE %L AND ativo ORDER BY ordem, criado_em LIMIT 1',
    p_schema,
    '%aguardando%'
  ) INTO v_waiting;
  EXECUTE format(
    'SELECT id FROM %I.projeto_stages WHERE nome ILIKE %L AND ativo ORDER BY ordem, criado_em LIMIT 1',
    p_schema,
    '%visita%'
  ) INTO v_visita;
  EXECUTE format(
    'SELECT id FROM %I.projeto_stages WHERE nome ILIKE %L AND ativo ORDER BY ordem DESC, criado_em DESC LIMIT 1',
    p_schema,
    '%feito%'
  ) INTO v_feito;

  IF v_waiting IS NOT NULL THEN
    EXECUTE format('UPDATE %I.projeto_stages SET ordem = 0 WHERE id = $1', p_schema) USING v_waiting;
  END IF;
  IF v_visita IS NOT NULL THEN
    EXECUTE format(
      'UPDATE %I.projeto_stages SET ordem = 1, is_default = true, cor = COALESCE(NULLIF(cor, ''''), %L) WHERE id = $1',
      p_schema,
      'primary'
    ) USING v_visita;
  END IF;
  IF v_feito IS NOT NULL THEN
    EXECUTE format('UPDATE %I.projeto_stages SET ordem = 2 WHERE id = $1', p_schema) USING v_feito;
  END IF;
END;
$_$;


--
-- Name: me_ensure_super_admin_in_empresa(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_ensure_super_admin_in_empresa(_schema_nome text, _user_id uuid DEFAULT auth.uid()) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_nome TEXT;
  v_email TEXT;
  v_empresa_id UUID;
BEGIN
  IF NOT public.me_is_super_admin(_user_id) THEN
    RETURN;
  END IF;

  IF _schema_nome IS NULL OR _schema_nome !~ '^emp_[a-z0-9_]+$' THEN
    RETURN;
  END IF;

  SELECT nome, email
  INTO v_nome, v_email
  FROM public."CRM-multi-empresas>usuarios<"
  WHERE id = _user_id;

  IF v_nome IS NULL THEN
    SELECT
      COALESCE(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', split_part(email, '@', 1)),
      email
    INTO v_nome, v_email
    FROM auth.users
    WHERE id = _user_id;
  END IF;

  EXECUTE format(
    $sql$
      INSERT INTO %I.usuarios (id, nome, email, status_convite)
      VALUES ($1, $2, $3, 'ATIVO')
      ON CONFLICT (id) DO UPDATE SET
        nome = EXCLUDED.nome,
        email = EXCLUDED.email,
        status_convite = 'ATIVO',
        atualizado_em = now()
    $sql$,
    _schema_nome
  ) USING _user_id, v_nome, v_email;

  EXECUTE format(
    $sql$
      INSERT INTO %I.user_roles (user_id, role)
      VALUES ($1, 'admin'::public.selletos_crm_app_role)
      ON CONFLICT (user_id) DO UPDATE SET role = EXCLUDED.role
    $sql$,
    _schema_nome
  ) USING _user_id;

  SELECT id INTO v_empresa_id
  FROM public."CRM-multi-empresas>empresas<"
  WHERE schema_nome = _schema_nome
  LIMIT 1;

  IF v_empresa_id IS NOT NULL THEN
    INSERT INTO public."CRM-multi-empresas>usuario_empresa<" (user_id, empresa_id)
    VALUES (_user_id, v_empresa_id)
    ON CONFLICT (user_id, empresa_id) DO NOTHING;
  END IF;
END;
$_$;


--
-- Name: me_garantir_campo_pontua_garbo(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_garantir_campo_pontua_garbo(p_schema text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_table text;
  v_relname text;
BEGIN
  IF p_schema = 'public' THEN
    v_table := 'public."CRM-multi-empresas>lead_custom_field_definitions<"';
    v_relname := 'CRM-multi-empresas>lead_custom_field_definitions<';
  ELSE
    v_table := format('%I.lead_custom_field_definitions', p_schema);
    v_relname := 'lead_custom_field_definitions';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = p_schema
      AND c.relname = v_relname
      AND c.relkind = 'r'
  ) THEN
    RETURN;
  END IF;

  EXECUTE format(
    $sql$
    UPDATE %s
    SET
      ativo = true,
      tipo = 'usuario_sistema',
      config_pontua_garbo = COALESCE(
        config_pontua_garbo || jsonb_build_object('ativo', true),
        jsonb_build_object('ativo', true, 'percentual_padrao', 10)
      )
    WHERE public.me_is_campo_pontua_garbo(tipo, nome, config_pontua_garbo)
    $sql$,
    v_table
  );

  EXECUTE format(
    $sql$
    INSERT INTO %s (nome, tipo, opcoes, ordem, ativo, config_pontua_garbo)
    SELECT
      'Pontua Garbo',
      'usuario_sistema',
      NULL,
      0,
      true,
      jsonb_build_object('ativo', true, 'percentual_padrao', 10)
    WHERE NOT EXISTS (
      SELECT 1 FROM %s
      WHERE public.me_is_campo_pontua_garbo(tipo, nome, config_pontua_garbo)
    )
    $sql$,
    v_table,
    v_table
  );

  EXECUTE format('DROP TRIGGER IF EXISTS trg_proteger_campo_pontua_garbo ON %s', v_table);
  EXECUTE format(
    'CREATE TRIGGER trg_proteger_campo_pontua_garbo
       BEFORE UPDATE OR DELETE ON %s
       FOR EACH ROW EXECUTE FUNCTION public.me_proteger_campo_pontua_garbo()',
    v_table
  );
END;
$_$;


--
-- Name: me_get_empresa_do_usuario(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_get_empresa_do_usuario(_user_id uuid DEFAULT auth.uid()) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT empresa_id FROM public."CRM-multi-empresas>usuario_empresa<"
  WHERE user_id = _user_id
  LIMIT 1;
$$;


--
-- Name: me_get_empresa_role(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_get_empresa_role(_schema text, _user_id uuid DEFAULT auth.uid()) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_roles public.selletos_crm_app_role[];
BEGIN
  IF _schema IS NULL OR _schema !~ '^emp_[a-z0-9_]+$' THEN
    RETURN NULL;
  END IF;

  EXECUTE format(
    'SELECT COALESCE(ARRAY_AGG(role), ARRAY[]::public.selletos_crm_app_role[]) FROM %I.user_roles WHERE user_id = $1',
    _schema
  )
  INTO v_roles
  USING _user_id;

  RETURN public.me_pick_primary_role(v_roles)::text;
END;
$_$;


--
-- Name: me_get_schema_empresa(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_get_schema_empresa(_user_id uuid DEFAULT auth.uid()) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.schema_nome
  FROM public."CRM-multi-empresas>empresas<" e
  INNER JOIN public."CRM-multi-empresas>usuario_empresa<" ue ON ue.empresa_id = e.id
  WHERE ue.user_id = _user_id
  LIMIT 1;
$$;


--
-- Name: me_get_user_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_get_user_role(_user_id uuid) RETURNS public.selletos_crm_app_role
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.me_pick_primary_role(
    COALESCE(
      ARRAY(
        SELECT role
        FROM public."CRM-multi-empresas>user_roles<"
        WHERE user_id = _user_id
      ),
      ARRAY[]::public.selletos_crm_app_role[]
    )
  );
$$;


--
-- Name: me_get_user_roles(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_get_user_roles(_user_id uuid DEFAULT auth.uid()) RETURNS public.selletos_crm_app_role[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    ARRAY(
      SELECT role
      FROM public."CRM-multi-empresas>user_roles<"
      WHERE user_id = _user_id
      ORDER BY CASE role::text
        WHEN 'admin' THEN 1
        WHEN 'vendedor' THEN 2
        WHEN 'marketing' THEN 3
        ELSE 4
      END
    ),
    ARRAY[]::public.selletos_crm_app_role[]
  );
$$;


--
-- Name: me_grant_empresa_schema(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_grant_empresa_schema(p_schema text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  EXECUTE format('GRANT USAGE ON SCHEMA %I TO authenticated, anon, service_role', p_schema);
  EXECUTE format('GRANT ALL ON ALL TABLES IN SCHEMA %I TO authenticated, service_role', p_schema);
  EXECUTE format('GRANT ALL ON ALL SEQUENCES IN SCHEMA %I TO authenticated, service_role', p_schema);
  EXECUTE format('GRANT ALL ON ALL ROUTINES IN SCHEMA %I TO authenticated, service_role', p_schema);
  EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA %I GRANT ALL ON TABLES TO authenticated, service_role', p_schema);
  EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA %I GRANT ALL ON SEQUENCES TO authenticated, service_role', p_schema);
END;
$$;


--
-- Name: me_has_permission(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_has_permission(_user_id uuid, _resource text, _action text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (
      SELECT bool_or(up.allowed)
      FROM public."CRM-multi-empresas>user_permissions<" up
      INNER JOIN public."CRM-multi-empresas>user_roles<" ur ON ur.role = up.role
      WHERE ur.user_id = _user_id
        AND up.resource = _resource
        AND up.action = _action
    ),
    (SELECT public.me_is_admin(_user_id)),
    false
  );
$$;


--
-- Name: me_is_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_is_admin(_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.me_is_super_admin(_user_id)
    OR EXISTS (
      SELECT 1
      FROM public."CRM-multi-empresas>user_roles<"
      WHERE user_id = _user_id AND role = 'admin'
    );
$$;


--
-- Name: me_is_campo_pontua_garbo(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_is_campo_pontua_garbo(p_tipo text, p_nome text, p_config jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    (
      lower(trim(COALESCE(p_nome, ''))) LIKE '%pontua%'
      AND lower(trim(COALESCE(p_nome, ''))) LIKE '%garbo%'
    )
    OR (
      COALESCE(p_tipo, 'usuario_sistema') = 'usuario_sistema'
      AND p_config IS NOT NULL
      AND COALESCE((p_config->>'ativo')::boolean, false) = true
    )
    OR (
      COALESCE(p_tipo, 'usuario_sistema') = 'usuario_sistema'
      AND p_config IS NULL
      AND (
        lower(trim(COALESCE(p_nome, ''))) LIKE '%pontua%'
        OR lower(trim(COALESCE(p_nome, ''))) LIKE '%garbo%'
      )
    );
$$;


--
-- Name: FUNCTION me_is_campo_pontua_garbo(p_tipo text, p_nome text, p_config jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.me_is_campo_pontua_garbo(p_tipo text, p_nome text, p_config jsonb) IS 'Identifica o campo de sistema Pontua Garbo nos cards de lead.';


--
-- Name: me_is_crm_projetista(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_is_crm_projetista(_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_schema text;
BEGIN
  IF _user_id IS NULL THEN RETURN false; END IF;
  IF EXISTS (
    SELECT 1 FROM public."CRM-multi-empresas>user_roles<"
    WHERE user_id = _user_id
      AND role IN ('projetista'::public.selletos_crm_app_role, 'projetista_admin'::public.selletos_crm_app_role)
  ) THEN RETURN true; END IF;
  FOR v_schema IN
    SELECT schema_name FROM information_schema.schemata WHERE schema_name LIKE 'emp\_%' ESCAPE '\'
  LOOP
    IF public.me_empresa_has_any_role(v_schema, ARRAY['projetista', 'projetista_admin'], _user_id) THEN
      RETURN true;
    END IF;
  END LOOP;
  RETURN false;
END;
$$;


--
-- Name: me_is_crm_projetista_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_is_crm_projetista_admin(_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_schema text;
BEGIN
  IF _user_id IS NULL THEN RETURN false; END IF;
  IF public.me_is_admin(_user_id) OR public.me_is_super_admin(_user_id) THEN RETURN true; END IF;
  IF EXISTS (
    SELECT 1 FROM public."CRM-multi-empresas>user_roles<"
    WHERE user_id = _user_id AND role = 'projetista_admin'::public.selletos_crm_app_role
  ) THEN RETURN true; END IF;
  FOR v_schema IN
    SELECT schema_name FROM information_schema.schemata WHERE schema_name LIKE 'emp\_%' ESCAPE '\'
  LOOP
    IF public.me_empresa_has_any_role(v_schema, ARRAY['projetista_admin'], _user_id) THEN RETURN true; END IF;
  END LOOP;
  RETURN false;
END;
$$;


--
-- Name: me_is_crm_titular_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_is_crm_titular_admin(_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_schema text;
BEGIN
  IF _user_id IS NULL THEN
    RETURN false;
  END IF;

  IF public.me_is_admin(_user_id) THEN
    RETURN true;
  END IF;

  FOR v_schema IN
    SELECT schema_name
    FROM information_schema.schemata
    WHERE schema_name LIKE 'emp\_%' ESCAPE '\'
  LOOP
    IF public.me_get_empresa_role(v_schema, _user_id) = 'admin' THEN
      RETURN true;
    END IF;
  END LOOP;

  RETURN false;
END;
$$;


--
-- Name: FUNCTION me_is_crm_titular_admin(_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.me_is_crm_titular_admin(_user_id uuid) IS 'True para super/master admin ou admin em qualquer schema emp_* (gestão de titularidade).';


--
-- Name: me_is_crm_vendedor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_is_crm_vendedor(_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_schema text;
  v_role text;
BEGIN
  IF _user_id IS NULL THEN
    RETURN false;
  END IF;

  IF public.me_is_vendedor(_user_id) THEN
    RETURN true;
  END IF;

  FOR v_schema IN
    SELECT schema_name
    FROM information_schema.schemata
    WHERE schema_name LIKE 'emp\_%' ESCAPE '\'
  LOOP
    v_role := public.me_get_empresa_role(v_schema, _user_id);
    IF v_role IN ('admin', 'vendedor') THEN
      RETURN true;
    END IF;
  END LOOP;

  RETURN false;
END;
$$;


