--
-- Name: me_lead_lembretes_sync_titular_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_lead_lembretes_sync_titular_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.titular_ids IS NULL OR cardinality(NEW.titular_ids) = 0 THEN
    IF NEW.titular_id IS NOT NULL THEN
      NEW.titular_ids := ARRAY[NEW.titular_id];
    ELSIF NEW.criado_por IS NOT NULL THEN
      NEW.titular_ids := ARRAY[NEW.criado_por];
      NEW.titular_id := NEW.criado_por;
    ELSE
      RAISE EXCEPTION 'lead_lembretes exige ao menos um titular';
    END IF;
  END IF;

  IF COALESCE(NEW.origem_automatica, false) IS NOT TRUE THEN
    IF NEW.criado_por IS NOT NULL AND NOT (NEW.criado_por = ANY (NEW.titular_ids)) THEN
      NEW.titular_ids := array_prepend(NEW.criado_por, NEW.titular_ids);
    END IF;
  END IF;

  NEW.titular_id := NEW.titular_ids[1];
  RETURN NEW;
END;
$$;


--
-- Name: me_lead_linked_to_prestador(text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_lead_linked_to_prestador(_schema text, _lead_id bigint, _user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_linked BOOLEAN;
BEGIN
  IF _schema IS NULL OR _lead_id IS NULL OR _user_id IS NULL THEN
    RETURN FALSE;
  END IF;

  IF _schema !~ '^emp_[a-z0-9_]+$' THEN
    RETURN FALSE;
  END IF;

  EXECUTE format(
    $q$
    SELECT EXISTS (
      SELECT 1
      FROM %I.usuarios u
      WHERE u.id = $2
        AND u.tipo_usuario = 'prestador_servico'
    )
    AND EXISTS (
      SELECT 1
      FROM %I.lead_custom_field_values v
      INNER JOIN %I.lead_custom_field_definitions d ON d.id = v.field_id
      WHERE v.lead_id = $1
        AND d.tipo = 'usuario_sistema'
        AND d.ativo = true
        AND v.valor = $2::text
        AND (
          d.config_pontua_garbo IS NULL
          OR COALESCE((d.config_pontua_garbo->>'ativo')::boolean, true) IS TRUE
        )
    )
    $q$,
    _schema,
    _schema,
    _schema
  )
  INTO v_linked
  USING _lead_id, _user_id;

  RETURN COALESCE(v_linked, FALSE);
END;
$_$;


--
-- Name: FUNCTION me_lead_linked_to_prestador(_schema text, _lead_id bigint, _user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.me_lead_linked_to_prestador(_schema text, _lead_id bigint, _user_id uuid) IS 'True se o lead pertence ao prestador (valor no campo usuario_sistema / Pontua Garbo).';


--
-- Name: me_limpar_vinculos_auth_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_limpar_vinculos_auth_user(_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $_$
DECLARE
  r record;
  cleared integer := 0;
  def text;
  is_nullable boolean;
BEGIN
  IF _user_id IS NULL THEN
    RETURN 0;
  END IF;

  FOR r IN
    SELECT
      nsp.nspname AS schema_name,
      cls.relname AS table_name,
      att.attname AS column_name,
      pg_get_constraintdef(c.oid) AS constraint_def
    FROM pg_constraint c
    JOIN pg_class cls ON cls.oid = c.conrelid
    JOIN pg_namespace nsp ON nsp.oid = cls.relnamespace
    JOIN pg_attribute att ON att.attrelid = c.conrelid
      AND att.attnum = ANY (c.conkey)
      AND NOT att.attisdropped
    WHERE c.confrelid = 'auth.users'::regclass
      AND c.contype = 'f'
      AND nsp.nspname = 'public'
  LOOP
    def := r.constraint_def;
    IF def LIKE '%ON DELETE CASCADE%' OR def LIKE '%ON DELETE SET NULL%' THEN
      CONTINUE;
    END IF;

    SELECT a.is_nullable = 'YES'
    INTO is_nullable
    FROM information_schema.columns a
    WHERE a.table_schema = r.schema_name
      AND a.table_name = r.table_name
      AND a.column_name = r.column_name;

    BEGIN
      IF is_nullable THEN
        EXECUTE format(
          'UPDATE %I.%I SET %I = NULL WHERE %I = $1',
          r.schema_name, r.table_name, r.column_name, r.column_name
        ) USING _user_id;
      ELSE
        EXECUTE format(
          'DELETE FROM %I.%I WHERE %I = $1',
          r.schema_name, r.table_name, r.column_name
        ) USING _user_id;
      END IF;
      cleared := cleared + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'me_limpar_vinculos_auth_user %.%: %',
        r.schema_name, r.table_name, SQLERRM;
    END;
  END LOOP;

  RETURN cleared;
END;
$_$;


--
-- Name: FUNCTION me_limpar_vinculos_auth_user(_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.me_limpar_vinculos_auth_user(_user_id uuid) IS 'Limpa FKs em public que bloqueiam exclusão em auth.users (sem CASCADE/SET NULL).';


--
-- Name: me_pick_primary_role(public.selletos_crm_app_role[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_pick_primary_role(_roles public.selletos_crm_app_role[]) RETURNS public.selletos_crm_app_role
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (
      SELECT r
      FROM unnest(_roles) AS r
      ORDER BY CASE r::text
        WHEN 'admin' THEN 1
        WHEN 'vendedor' THEN 2
        WHEN 'projetista_admin' THEN 3
        WHEN 'projetista' THEN 4
        WHEN 'marketing' THEN 5
        ELSE 6
      END
      LIMIT 1
    ),
    'nenhum'::public.selletos_crm_app_role
  );
$$;


--
-- Name: me_pipeline_novo_lead_criar_tarefa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_pipeline_novo_lead_criar_tarefa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_schema text := TG_TABLE_SCHEMA;
  v_ativo boolean;
  v_incluir boolean;
  v_titular_ids uuid[];
  v_uid uuid := auth.uid();
  v_dest uuid[];
  v_titulo text;
  v_data_hora timestamptz;
BEGIN
  IF v_schema = 'public' THEN
    SELECT ativo, incluir_titular_cadastro, titular_ids
      INTO v_ativo, v_incluir, v_titular_ids
    FROM public."CRM-multi-empresas>pipeline_novo_lead_tarefa_config<"
    WHERE singleton_key = 'default'
    LIMIT 1;
  ELSE
    EXECUTE format(
      'SELECT ativo, incluir_titular_cadastro, titular_ids
         FROM %I.pipeline_novo_lead_tarefa_config
        WHERE singleton_key = %L
        LIMIT 1',
      v_schema,
      'default'
    )
    INTO v_ativo, v_incluir, v_titular_ids;
  END IF;

  IF v_ativo IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  v_dest := COALESCE(v_titular_ids, '{}'::uuid[]);

  IF v_incluir IS TRUE AND v_uid IS NOT NULL AND NOT (v_uid = ANY (v_dest)) THEN
    v_dest := array_prepend(v_uid, v_dest);
  END IF;

  SELECT ARRAY(
    SELECT DISTINCT x
    FROM unnest(v_dest) AS x
    WHERE x IS NOT NULL
  )
  INTO v_dest;

  IF v_dest IS NULL OR cardinality(v_dest) = 0 THEN
    RETURN NEW;
  END IF;

  v_titulo := 'Novo lead: ' || COALESCE(NEW.nome, 'sem nome');
  v_data_hora := (
    date_trunc('day', timezone('America/Sao_Paulo', now()))
    + interval '1 day'
    - interval '1 second'
  ) AT TIME ZONE 'America/Sao_Paulo';

  IF v_schema = 'public' THEN
    INSERT INTO public."CRM-multi-empresas>lead_lembretes<" (
      lead_id,
      titulo,
      descricao,
      data_hora,
      status,
      titular_id,
      titular_ids,
      criado_por,
      origem_automatica,
      anexos
    )
    VALUES (
      NEW.id,
      v_titulo,
      NULL,
      v_data_hora,
      'pendente',
      v_dest[1],
      v_dest,
      COALESCE(v_uid, v_dest[1]),
      true,
      '[]'::jsonb
    );
  ELSE
    EXECUTE format(
      'INSERT INTO %I.lead_lembretes (
         lead_id, titulo, descricao, data_hora, status,
         titular_id, titular_ids, criado_por, origem_automatica, anexos
       ) VALUES ($1, $2, NULL, $3, %L, $4, $5, $6, true, %L::jsonb)',
      v_schema,
      'pendente',
      '[]'
    )
    USING
      NEW.id,
      v_titulo,
      v_data_hora,
      v_dest[1],
      v_dest,
      COALESCE(v_uid, v_dest[1]);
  END IF;

  RETURN NEW;
EXCEPTION
  WHEN undefined_table THEN
    RETURN NEW;
  WHEN undefined_column THEN
    RETURN NEW;
  WHEN OTHERS THEN
    RAISE WARNING 'me_pipeline_novo_lead_criar_tarefa: %', SQLERRM;
    RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION me_pipeline_novo_lead_criar_tarefa(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.me_pipeline_novo_lead_criar_tarefa() IS 'Após INSERT em leads: cria lembrete automático conforme pipeline_novo_lead_tarefa_config do schema.';


--
-- Name: me_projetos_buscar_leads(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_projetos_buscar_leads(p_schema text, p_termo text, p_limit integer DEFAULT 20) RETURNS TABLE(id bigint, nome text, telefone text, status text, regiao text, vendedor_responsavel_id uuid, data_chegada date, no_funil boolean, stage_id uuid, stage_nome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid uuid := (SELECT auth.uid());
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 50);
  v_termo text := btrim(COALESCE(p_termo, ''));
  v_digitos text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario nao autenticado' USING ERRCODE = '28000';
  END IF;

  IF p_schema IS NULL OR p_schema NOT LIKE 'emp\_%' ESCAPE '\' THEN
    RETURN;
  END IF;

  IF to_regclass(format('%I.leads', p_schema)) IS NULL
     OR to_regclass(format('%I.lead_projetos', p_schema)) IS NULL THEN
    RETURN;
  END IF;

  IF NOT (
    public.me_is_super_admin(v_uid)
    OR public.me_get_empresa_role(p_schema, v_uid) = 'admin'
    OR public.me_empresa_has_any_role(
         p_schema,
         ARRAY['vendedor', 'projetista', 'projetista_admin'],
         v_uid
       )
  ) THEN
    RAISE EXCEPTION 'Sem permissao para pesquisar leads nesta empresa' USING ERRCODE = '42501';
  END IF;

  IF char_length(v_termo) < 2 THEN
    RETURN;
  END IF;

  v_digitos := regexp_replace(v_termo, '\D', '', 'g');

  RETURN QUERY EXECUTE format(
    'SELECT l.id,
            l.nome,
            l.telefone,
            l.status,
            l.regiao,
            l.vendedor_responsavel_id,
            l.data_chegada,
            (lp.id IS NOT NULL) AS no_funil,
            lp.stage_id,
            ps.nome AS stage_nome
       FROM %I.leads l
       LEFT JOIN %I.lead_projetos lp ON lp.lead_id = l.id
       LEFT JOIN %I.projeto_stages ps ON ps.id = lp.stage_id
      WHERE l.nome ILIKE $1
         OR (
              char_length($2) >= 3
              AND regexp_replace(COALESCE(l.telefone, ''''), ''\D'', '''', ''g'') LIKE $3
            )
      ORDER BY (l.nome ILIKE $4) DESC, l.nome ASC
      LIMIT $5',
    p_schema, p_schema, p_schema
  )
  USING '%' || v_termo || '%',
        v_digitos,
        '%' || v_digitos || '%',
        v_termo || '%',
        v_limit;
END;
$_$;


--
-- Name: FUNCTION me_projetos_buscar_leads(p_schema text, p_termo text, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.me_projetos_buscar_leads(p_schema text, p_termo text, p_limit integer) IS 'Busca leads da empresa para o setor de Projetos devolvendo apenas os campos da lista de resultados.';


--
-- Name: me_proteger_campo_pontua_garbo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_proteger_campo_pontua_garbo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF public.me_is_campo_pontua_garbo(OLD.tipo, OLD.nome, OLD.config_pontua_garbo) THEN
      RAISE EXCEPTION 'O campo Pontua Garbo é do sistema e não pode ser excluído dos cards.';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF public.me_is_campo_pontua_garbo(OLD.tipo, OLD.nome, OLD.config_pontua_garbo)
       OR public.me_is_campo_pontua_garbo(NEW.tipo, NEW.nome, NEW.config_pontua_garbo) THEN
      IF NEW.ativo IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'O campo Pontua Garbo é do sistema e não pode ser excluído dos cards.';
      END IF;
      NEW.tipo := 'usuario_sistema';
      NEW.nome := COALESCE(NULLIF(btrim(OLD.nome), ''), 'Pontua Garbo');
      IF NEW.config_pontua_garbo IS NULL
         OR COALESCE((NEW.config_pontua_garbo->>'ativo')::boolean, false) IS NOT TRUE THEN
        NEW.config_pontua_garbo := jsonb_build_object(
          'ativo', true,
          'percentual_padrao', COALESCE(
            NULLIF(NEW.config_pontua_garbo->>'percentual_padrao', '')::numeric,
            NULLIF(OLD.config_pontua_garbo->>'percentual_padrao', '')::numeric,
            10
          )
        );
      ELSE
        NEW.config_pontua_garbo := NEW.config_pontua_garbo || jsonb_build_object('ativo', true);
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION me_proteger_campo_pontua_garbo(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.me_proteger_campo_pontua_garbo() IS 'Impede exclusão ou desativação do campo Pontua Garbo nos cards de lead.';


--
-- Name: me_role_has_permission(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_role_has_permission(_role text, _resource text, _action text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (
      SELECT allowed
      FROM public."CRM-multi-empresas>user_permissions<"
      WHERE role = _role::public.selletos_crm_app_role
        AND resource = _resource
        AND action = _action
      LIMIT 1
    ),
    false
  );
$$;


