--
-- Name: me_vincular_usuario_empresa(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.me_vincular_usuario_empresa(p_email text, p_empresa_slug text, p_role text DEFAULT 'vendedor'::text, p_nome text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_user_id UUID;
  v_empresa_id UUID;
  v_schema TEXT;
  v_nome TEXT;
BEGIN
  IF NOT me_is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Acesso negado: apenas super admins';
  END IF;

  SELECT id INTO v_user_id
  FROM auth.users
  WHERE lower(email) = lower(trim(p_email))
  LIMIT 1;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não encontrado no Auth: %', p_email;
  END IF;

  SELECT id, schema_nome INTO v_empresa_id, v_schema
  FROM public."CRM-multi-empresas>empresas<"
  WHERE slug = p_empresa_slug OR schema_nome = 'emp_' || p_empresa_slug
  LIMIT 1;

  IF v_empresa_id IS NULL THEN
    RAISE EXCEPTION 'Empresa não encontrada: %', p_empresa_slug;
  END IF;

  v_nome := COALESCE(NULLIF(trim(p_nome), ''), split_part(p_email, '@', 1));

  EXECUTE format(
    $sql$
      INSERT INTO %I.usuarios (id, nome, email, status_convite)
      VALUES ($1, $2, $3, 'ATIVO')
      ON CONFLICT (id) DO UPDATE SET
        nome = EXCLUDED.nome,
        email = EXCLUDED.email,
        status_convite = 'ATIVO'
    $sql$,
    v_schema
  ) USING v_user_id, v_nome, lower(trim(p_email));

  EXECUTE format(
    $sql$
      INSERT INTO %I.user_roles (user_id, role)
      VALUES ($1, $2::app_role)
      ON CONFLICT (user_id) DO UPDATE SET role = EXCLUDED.role
    $sql$,
    v_schema
  ) USING v_user_id, p_role;

  INSERT INTO public."CRM-multi-empresas>usuario_empresa<" (user_id, empresa_id)
  VALUES (v_user_id, v_empresa_id)
  ON CONFLICT (user_id, empresa_id) DO NOTHING;

  RETURN v_user_id;
END;
$_$;


--
-- Name: FUNCTION me_vincular_usuario_empresa(p_email text, p_empresa_slug text, p_role text, p_nome text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.me_vincular_usuario_empresa(p_email text, p_empresa_slug text, p_role text, p_nome text) IS 'Corrige vínculo de usuário existente com empresa (schema emp_* + usuario_empresa).';


--
-- Name: movelaria_admissao_publica_obter(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_admissao_publica_obter(p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row movelaria_funcionarios%ROWTYPE;
BEGIN
  SELECT * INTO v_row
  FROM movelaria_funcionarios
  WHERE admissao_token = p_token AND ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Link de admissão inválido ou expirado.';
  END IF;

  RETURN jsonb_build_object(
    'id', v_row.id,
    'nome', v_row.nome,
    'tipo', v_row.tipo,
    'admissao_status', v_row.admissao_status,
    'admissao_dados', v_row.admissao_dados,
    'documentos', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'tipo_documento', d.tipo_documento,
        'nome_arquivo', d.nome_arquivo,
        'criado_em', d.criado_em
      ) ORDER BY d.criado_em)
      FROM movelaria_funcionario_documentos d
      WHERE d.funcionario_id = v_row.id AND d.origem = 'funcionario_publico'
    ), '[]'::jsonb)
  );
END;
$$;


--
-- Name: movelaria_admissao_publica_registrar_doc(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_admissao_publica_registrar_doc(p_token uuid, p_tipo_documento text, p_nome_arquivo text, p_tipo_mime text, p_storage_path text, p_kind text DEFAULT 'image'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_funcionario_id UUID;
  v_id UUID := gen_random_uuid();
BEGIN
  SELECT id INTO v_funcionario_id
  FROM movelaria_funcionarios
  WHERE admissao_token = p_token AND ativo = true;

  IF v_funcionario_id IS NULL THEN
    RAISE EXCEPTION 'Link de admissão inválido.';
  END IF;

  DELETE FROM movelaria_funcionario_documentos
  WHERE funcionario_id = v_funcionario_id
    AND tipo_documento = p_tipo_documento
    AND origem = 'funcionario_publico';

  INSERT INTO movelaria_funcionario_documentos (
    id, funcionario_id, categoria, tipo_documento,
    nome_arquivo, tipo_mime, storage_path, kind, origem
  ) VALUES (
    v_id, v_funcionario_id, 'admissao', p_tipo_documento,
    p_nome_arquivo, p_tipo_mime, p_storage_path, p_kind, 'funcionario_publico'
  );

  RETURN v_id;
END;
$$;


--
-- Name: movelaria_admissao_publica_salvar(uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_admissao_publica_salvar(p_token uuid, p_dados jsonb, p_finalizar boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row movelaria_funcionarios%ROWTYPE;
  v_status TEXT;
BEGIN
  SELECT * INTO v_row
  FROM movelaria_funcionarios
  WHERE admissao_token = p_token AND ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Link de admissão inválido ou expirado.';
  END IF;

  IF v_row.admissao_status = 'completo' AND p_finalizar THEN
    RAISE EXCEPTION 'Formulário já foi enviado.';
  END IF;

  v_status := CASE
    WHEN p_finalizar THEN 'preenchido_funcionario'
    ELSE CASE WHEN v_row.admissao_status = 'completo' THEN 'completo' ELSE 'pendente' END
  END;

  UPDATE movelaria_funcionarios
  SET
    admissao_dados = COALESCE(admissao_dados, '{}'::jsonb) || COALESCE(p_dados, '{}'::jsonb),
    admissao_status = v_status,
    cpf = COALESCE(NULLIF(p_dados->>'cpf', ''), cpf),
    telefone = COALESCE(NULLIF(p_dados->>'telefone', ''), telefone),
    email = COALESCE(NULLIF(p_dados->>'email', ''), email),
    atualizado_em = NOW()
  WHERE id = v_row.id
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'ok', true,
    'admissao_status', v_row.admissao_status
  );
END;
$$;


