--
-- Name: movelaria_aplicar_comissao_obra(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_aplicar_comissao_obra(p_obra_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_ok BOOLEAN;
BEGIN
  IF NOT movelaria_usuario_tem_algum_perfil(
    ARRAY['administrador', 'financeiro', 'administrador_obras']
  ) THEN
    RAISE EXCEPTION 'Acesso negado: somente administradores ou financeiro podem aplicar comissões';
  END IF;

  v_ok := movelaria_aplicar_comissao_obra_interno(p_obra_id);

  IF NOT v_ok THEN
    RAISE EXCEPTION 'Não foi possível gerar comissão: verifique se está habilitada e possui valores definidos';
  END IF;
END;
$$;


--
-- Name: movelaria_aplicar_comissao_obra_interno(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_aplicar_comissao_obra_interno(p_obra_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_habilitada      BOOLEAN;
  v_gerada          BOOLEAN;
  v_cliente_nome    TEXT;
  v_finalizado_em   TIMESTAMPTZ;
  v_data_vencimento DATE;
  v_qtd_itens       INTEGER;
  v_montador_nome   TEXT;
  r                 RECORD;
BEGIN
  SELECT comissao_habilitada, comissao_gerada, cliente_nome, finalizado_em
  INTO v_habilitada, v_gerada, v_cliente_nome, v_finalizado_em
  FROM movelaria_obras
  WHERE id = p_obra_id;

  IF NOT FOUND OR NOT v_habilitada OR v_gerada THEN
    RETURN false;
  END IF;

  SELECT COUNT(*)::INTEGER INTO v_qtd_itens
  FROM movelaria_obra_comissao_itens
  WHERE obra_id = p_obra_id AND valor > 0;

  IF v_qtd_itens = 0 THEN
    RETURN false;
  END IF;

  -- Só gera Contas a Pagar na conclusão (padrão 093)
  IF v_finalizado_em IS NULL OR COALESCE(
    (SELECT status_kanban FROM movelaria_obras WHERE id = p_obra_id),
    ''
  ) IS DISTINCT FROM 'concluida' THEN
    RETURN false;
  END IF;

  v_data_vencimento := COALESCE(
    (v_finalizado_em AT TIME ZONE 'America/Sao_Paulo')::DATE,
    CURRENT_DATE
  );

  FOR r IN
    SELECT ci.prestador_id, ci.valor, u.nome, u.email
    FROM movelaria_obra_comissao_itens ci
    JOIN movelaria_usuarios u ON u.id = ci.prestador_id
    WHERE ci.obra_id = p_obra_id AND ci.valor > 0
  LOOP
    v_montador_nome := COALESCE(NULLIF(TRIM(r.nome), ''), split_part(r.email, '@', 1));

    -- Evita duplicar se já existir conta desta obra+prestador
    IF EXISTS (
      SELECT 1 FROM movelaria_contas_pagar cp
      WHERE cp.obra_id = p_obra_id
        AND cp.prestador_id = r.prestador_id
    ) THEN
      CONTINUE;
    END IF;

    INSERT INTO movelaria_contas_pagar (
      prestador_id,
      obra_id,
      fornecedor_nome,
      descricao,
      observacao,
      valor_total,
      numero_parcela,
      total_parcelas,
      valor_parcela,
      data_vencimento,
      status
    ) VALUES (
      r.prestador_id,
      p_obra_id,
      'Comissão: ' || v_montador_nome,
      COALESCE(NULLIF(TRIM(v_cliente_nome), ''), 'Obra'),
      NULL,
      r.valor,
      1,
      1,
      r.valor,
      v_data_vencimento,
      'pendente'
    );
  END LOOP;

  UPDATE movelaria_obras
  SET comissao_gerada = true,
      atualizado_em = NOW()
  WHERE id = p_obra_id;

  RETURN true;
END;
$$;


--
-- Name: movelaria_atualizar_contrato(uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_atualizar_contrato(p_id uuid, p_cliente_nome text, p_identificador text, p_campos_valores jsonb, p_status text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
      UPDATE emp_garbo.contratos
      SET cliente_nome  = p_cliente_nome,
          identificador = p_identificador,
          campos_valores = p_campos_valores,
          status = COALESCE(p_status, status)
      WHERE id = p_id;
    $$;


--
-- Name: movelaria_atualizar_ficha_crm(uuid, text, text[], text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_atualizar_ficha_crm(p_id uuid, p_tipo_usuario text, p_roles text[] DEFAULT '{}'::text[], p_horario_inicio text DEFAULT NULL::text, p_horario_fim text DEFAULT NULL::text, p_status_convite text DEFAULT 'ATIVO'::text, p_titulo text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_email   TEXT;
  v_nome    TEXT;
  v_tipo    TEXT;
  v_status  TEXT;
  v_role    TEXT;
  v_inicio  TIME;
  v_fim     TIME;
BEGIN
  IF public.movelaria_meu_perfil() <> 'administrador' THEN
    RAISE EXCEPTION 'Acesso negado: somente administradores podem editar a ficha CRM';
  END IF;

  IF p_id IS NULL THEN
    RAISE EXCEPTION 'Usuário obrigatório.';
  END IF;

  v_tipo := NULLIF(btrim(COALESCE(p_tipo_usuario, '')), '');
  IF v_tipo IS NULL OR v_tipo = 'nenhum' THEN
    UPDATE emp_garbo.usuarios
    SET status_convite = 'INATIVO',
        atualizado_em = NOW()
    WHERE id = p_id;
    DELETE FROM emp_garbo.user_roles WHERE user_id = p_id;
    RETURN;
  END IF;

  IF v_tipo NOT IN ('colaborador', 'prestador_servico', 'lead') THEN
    RAISE EXCEPTION 'Tipo CRM inválido: %', v_tipo;
  END IF;

  v_status := COALESCE(NULLIF(btrim(p_status_convite), ''), 'ATIVO');
  IF v_status NOT IN ('ATIVO', 'INATIVO', 'PENDENTE') THEN
    RAISE EXCEPTION 'Status de convite inválido: %', v_status;
  END IF;

  v_inicio := NULLIF(btrim(COALESCE(p_horario_inicio, '')), '')::TIME;
  v_fim := NULLIF(btrim(COALESCE(p_horario_fim, '')), '')::TIME;

  SELECT COALESCE(m.email, c.email), COALESCE(m.nome, c.nome)
  INTO v_email, v_nome
  FROM (SELECT p_id AS id) x
  LEFT JOIN public.movelaria_usuarios m ON m.id = p_id
  LEFT JOIN emp_garbo.usuarios c ON c.id = p_id;

  IF v_email IS NULL THEN
    SELECT email INTO v_email FROM auth.users WHERE id = p_id;
  END IF;

  IF v_email IS NULL THEN
    RAISE EXCEPTION 'Não encontrei e-mail para este usuário.';
  END IF;

  INSERT INTO emp_garbo.usuarios (
    id, nome, email, tipo_usuario, status_convite,
    horario_acesso_inicio, horario_acesso_fim, titulo, atualizado_em
  )
  VALUES (
    p_id,
    COALESCE(NULLIF(btrim(v_nome), ''), split_part(v_email, '@', 1)),
    v_email,
    v_tipo,
    v_status,
    v_inicio,
    v_fim,
    NULLIF(btrim(COALESCE(p_titulo, '')), ''),
    NOW()
  )
  ON CONFLICT (id) DO UPDATE
    SET tipo_usuario = EXCLUDED.tipo_usuario,
        status_convite = EXCLUDED.status_convite,
        horario_acesso_inicio = EXCLUDED.horario_acesso_inicio,
        horario_acesso_fim = EXCLUDED.horario_acesso_fim,
        titulo = COALESCE(EXCLUDED.titulo, emp_garbo.usuarios.titulo),
        nome = COALESCE(EXCLUDED.nome, emp_garbo.usuarios.nome),
        email = COALESCE(EXCLUDED.email, emp_garbo.usuarios.email),
        atualizado_em = NOW();

  DELETE FROM emp_garbo.user_roles WHERE user_id = p_id;

  IF p_roles IS NOT NULL THEN
    FOREACH v_role IN ARRAY p_roles LOOP
      v_role := lower(btrim(v_role));
      IF v_role IN ('admin', 'vendedor', 'marketing', 'projetista', 'projetista_admin') THEN
        INSERT INTO emp_garbo.user_roles (user_id, role)
        VALUES (p_id, v_role::selletos_crm_app_role)
        ON CONFLICT (user_id, role) DO NOTHING;
      END IF;
    END LOOP;
  END IF;
END;
$$;


--
-- Name: movelaria_atualizar_fixo_funcionario(uuid, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_atualizar_fixo_funcionario(p_funcionario_id uuid, p_valor numeric, p_primeiro_vencimento date DEFAULT NULL::date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_perfil          TEXT := movelaria_meu_perfil();
  v_recorrencia_id  UUID;
  v_nome            TEXT;
  v_categoria       TEXT;
  v_usuario_id      UUID;
  v_valor           NUMERIC(12, 2);
  v_valor_anterior  NUMERIC(12, 2);
  v_data_anterior   DATE;
  v_vencimento      DATE;
  v_valor_mudou     BOOLEAN;
  v_data_mudou      BOOLEAN;
  v_descricao       TEXT;
BEGIN
  IF v_perfil NOT IN ('administrador', 'administrador_obras') THEN
    RAISE EXCEPTION 'Acesso negado: somente administradores podem alterar o fixo.';
  END IF;

  IF p_valor IS NULL OR p_valor < 0 THEN
    RAISE EXCEPTION 'Valor fixo inválido';
  END IF;

  IF p_primeiro_vencimento IS NOT NULL AND p_primeiro_vencimento < CURRENT_DATE - INTERVAL '5 years' THEN
    RAISE EXCEPTION 'Data de pagamento inválida';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM movelaria_funcionarios f
    WHERE f.id = p_funcionario_id
      AND f.ativo = true
      AND COALESCE(f.tipo, '') <> 'marceneiro'
  ) THEN
    RAISE EXCEPTION 'Funcionário não encontrado';
  END IF;

  v_valor := ROUND(p_valor::NUMERIC, 2);
  v_vencimento := p_primeiro_vencimento;

  SELECT f.fixo_recorrencia_id,
         COALESCE(NULLIF(TRIM(f.nome), ''), 'Funcionário'),
         COALESCE(f.categoria, 'outro'),
         f.usuario_id,
         f.valor_fixo_mensal,
         f.fixo_primeiro_vencimento
  INTO v_recorrencia_id, v_nome, v_categoria, v_usuario_id, v_valor_anterior, v_data_anterior
  FROM movelaria_funcionarios f
  WHERE f.id = p_funcionario_id;

  -- Pasta de montador deve ficar como categoria montador (métricas / Meu Financeiro)
  IF v_categoria IS DISTINCT FROM 'montador'
     AND EXISTS (
       SELECT 1 FROM movelaria_funcionarios f
       WHERE f.id = p_funcionario_id
         AND f.tipo IN ('montador', 'montador_admin')
     ) THEN
    UPDATE movelaria_funcionarios
    SET categoria = 'montador', atualizado_em = NOW()
    WHERE id = p_funcionario_id;
    v_categoria := 'montador';
  END IF;

  v_descricao := movelaria_fixo_descricao(v_categoria, v_nome);

  IF v_valor <= 0 THEN
    IF v_recorrencia_id IS NOT NULL THEN
      DELETE FROM movelaria_caixa_movimentacoes cm
      WHERE cm.conta_pagar_id IN (
        SELECT cp.id
        FROM movelaria_contas_pagar cp
        WHERE cp.recorrencia_id = v_recorrencia_id
          AND cp.status = 'pendente'
      );

      UPDATE movelaria_contas_pagar
      SET recorrencia_encerramento = CURRENT_DATE,
          atualizado_em = NOW()
      WHERE recorrencia_id = v_recorrencia_id
        AND status = 'pendente';
    END IF;

    UPDATE movelaria_funcionarios
    SET valor_fixo_mensal = 0,
        fixo_recorrencia_id = NULL,
        fixo_primeiro_vencimento = NULL,
        atualizado_em = NOW()
    WHERE id = p_funcionario_id;

    PERFORM movelaria_sync_admissao_salario_fixo(p_funcionario_id, 0);

    IF v_usuario_id IS NOT NULL AND movelaria_usuario_eh_montador(v_usuario_id) THEN
      UPDATE movelaria_usuarios
      SET valor_fixo_mensal = 0,
          fixo_recorrencia_id = NULL,
          fixo_primeiro_vencimento = NULL,
          atualizado_em = NOW()
      WHERE id = v_usuario_id;
    END IF;

    RETURN;
  END IF;

  IF v_vencimento IS NULL AND v_recorrencia_id IS NULL THEN
    v_vencimento := movelaria_fixo_vencimento_mes(
      CURRENT_DATE,
      EXTRACT(YEAR  FROM CURRENT_DATE)::INTEGER,
      EXTRACT(MONTH FROM CURRENT_DATE)::INTEGER
    );
    IF v_vencimento < CURRENT_DATE THEN
      v_vencimento := movelaria_fixo_vencimento_mes(
        CURRENT_DATE,
        EXTRACT(YEAR  FROM (CURRENT_DATE + INTERVAL '1 month'))::INTEGER,
        EXTRACT(MONTH FROM (CURRENT_DATE + INTERVAL '1 month'))::INTEGER
      );
    END IF;
  END IF;

  v_valor_mudou := v_valor IS DISTINCT FROM COALESCE(v_valor_anterior, 0);
  v_data_mudou := v_vencimento IS NOT NULL
    AND v_vencimento IS DISTINCT FROM v_data_anterior;

  UPDATE movelaria_funcionarios
  SET valor_fixo_mensal = v_valor,
      fixo_primeiro_vencimento = COALESCE(v_vencimento, fixo_primeiro_vencimento),
      atualizado_em = NOW()
  WHERE id = p_funcionario_id;

  PERFORM movelaria_sync_admissao_salario_fixo(p_funcionario_id, v_valor);

  IF v_usuario_id IS NOT NULL AND movelaria_usuario_eh_montador(v_usuario_id) THEN
    UPDATE movelaria_usuarios
    SET valor_fixo_mensal = v_valor,
        fixo_primeiro_vencimento = COALESCE(v_vencimento, fixo_primeiro_vencimento),
        atualizado_em = NOW()
    WHERE id = v_usuario_id;
  END IF;

  IF v_recorrencia_id IS NOT NULL THEN
    IF v_data_mudou THEN
      DELETE FROM movelaria_caixa_movimentacoes cm
      WHERE cm.conta_pagar_id IN (
        SELECT cp.id
        FROM movelaria_contas_pagar cp
        WHERE cp.recorrencia_id = v_recorrencia_id
          AND cp.status = 'pendente'
      );

      DELETE FROM movelaria_contas_pagar cp
      WHERE cp.recorrencia_id = v_recorrencia_id
        AND cp.status = 'pendente';
    ELSE
      UPDATE movelaria_contas_pagar cp
      SET valor_parcela = v_valor,
          valor_total = v_valor,
          recorrencia_valor_base = v_valor,
          recorrencia_encerramento = NULL,
          fornecedor_nome = v_nome,
          descricao = v_descricao,
          prestador_id = COALESCE(cp.prestador_id, v_usuario_id),
          atualizado_em = NOW()
      WHERE cp.recorrencia_id = v_recorrencia_id
        AND cp.status = 'pendente';

      IF v_valor_mudou THEN
        UPDATE movelaria_caixa_movimentacoes cm
        SET valor = v_valor
        FROM movelaria_contas_pagar cp
        WHERE cm.conta_pagar_id = cp.id
          AND cp.recorrencia_id = v_recorrencia_id
          AND cp.status = 'pendente'
          AND cm.tipo_movimentacao = 'reserva';
      END IF;
    END IF;
  END IF;

  PERFORM movelaria_expandir_fixo_funcionario(p_funcionario_id);
END;
$$;


--
-- Name: movelaria_atualizar_fixo_montador(uuid, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_atualizar_fixo_montador(p_montador_id uuid, p_valor numeric, p_primeiro_vencimento date DEFAULT NULL::date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_func_id UUID;
BEGIN
  SELECT f.id INTO v_func_id
  FROM movelaria_funcionarios f
  WHERE f.usuario_id = p_montador_id
    AND f.ativo = true
  ORDER BY f.criado_em
  LIMIT 1;

  IF v_func_id IS NOT NULL THEN
    PERFORM movelaria_atualizar_fixo_funcionario(v_func_id, p_valor, p_primeiro_vencimento);
    RETURN;
  END IF;

  -- Fallback legado se ainda não houver pasta RH
  IF NOT EXISTS (
    SELECT 1 FROM movelaria_usuarios u
    WHERE u.id = p_montador_id
      AND u.perfil IN ('montador', 'montador_admin')
      AND u.ativo = true
  ) THEN
    RAISE EXCEPTION 'Montador não encontrado';
  END IF;

  UPDATE movelaria_usuarios
  SET valor_fixo_mensal = ROUND(GREATEST(COALESCE(p_valor, 0), 0)::NUMERIC, 2),
      fixo_primeiro_vencimento = CASE
        WHEN COALESCE(p_valor, 0) <= 0 THEN NULL
        ELSE COALESCE(p_primeiro_vencimento, fixo_primeiro_vencimento)
      END,
      fixo_recorrencia_id = CASE
        WHEN COALESCE(p_valor, 0) <= 0 THEN NULL
        ELSE fixo_recorrencia_id
      END,
      atualizado_em = NOW()
  WHERE id = p_montador_id;

  IF COALESCE(p_valor, 0) > 0 THEN
    PERFORM movelaria_expandir_fixo_montador(p_montador_id);
  END IF;
END;
$$;


--
-- Name: movelaria_atualizar_perfil_usuario(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_atualizar_perfil_usuario(p_id uuid, p_perfil text, p_ativo boolean DEFAULT NULL::boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF movelaria_meu_perfil() <> 'administrador' THEN
    RAISE EXCEPTION 'Acesso negado: somente administradores podem alterar perfis';
  END IF;

  UPDATE movelaria_usuarios
  SET
    perfil        = COALESCE(p_perfil, perfil),
    ativo         = COALESCE(p_ativo, ativo),
    atualizado_em = NOW()
  WHERE id = p_id;
END;
$$;


--
-- Name: movelaria_atualizar_perfil_usuario(uuid, text, text, boolean, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_atualizar_perfil_usuario(p_id uuid, p_perfil text, p_nome text DEFAULT NULL::text, p_ativo boolean DEFAULT NULL::boolean, p_perfis_extras text[] DEFAULT NULL::text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_valid TEXT[] := movelaria_perfis_validos();
  v_extra TEXT;
BEGIN
  IF movelaria_meu_perfil() <> 'administrador' THEN
    RAISE EXCEPTION 'Acesso negado: somente administradores podem alterar perfis';
  END IF;
  IF p_perfil IS NOT NULL AND NOT (p_perfil = ANY(v_valid)) THEN
    RAISE EXCEPTION 'Perfil inválido: %', p_perfil;
  END IF;
  IF p_perfis_extras IS NOT NULL THEN
    FOREACH v_extra IN ARRAY p_perfis_extras LOOP
      IF NOT (v_extra = ANY(v_valid)) THEN
        RAISE EXCEPTION 'Perfil extra inválido: %', v_extra;
      END IF;
    END LOOP;
  END IF;

  UPDATE movelaria_usuarios
  SET
    perfil        = COALESCE(p_perfil, perfil),
    nome          = COALESCE(p_nome, nome),
    ativo         = COALESCE(p_ativo, ativo),
    perfis_extras = COALESCE(p_perfis_extras, perfis_extras),
    atualizado_em = NOW()
  WHERE id = p_id;
END;
$$;


--
-- Name: movelaria_briefing_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_briefing_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.atualizado_em = NOW();
  RETURN NEW;
END;
$$;


--
-- Name: movelaria_buscar_contrato(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_buscar_contrato(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
      SELECT
        to_jsonb(c) ||
        jsonb_build_object(
          'variaveis',
          COALESCE(
            (SELECT jsonb_agg(to_jsonb(v) ORDER BY v.ordem, v.nome)
             FROM emp_garbo.contratos_variaveis v),
            '[]'::jsonb
          )
        )
      FROM emp_garbo.contratos c WHERE c.id = p_id;
    $$;


--
-- Name: movelaria_caixa_skip_cleanup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_caixa_skip_cleanup() RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN COALESCE(current_setting('movelaria.skip_caixa_cleanup', true), '') = '1';
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$$;


--
-- Name: movelaria_concluir_obra(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_concluir_obra(p_obra_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_perfil TEXT := movelaria_meu_perfil();
  v_uid    UUID := auth.uid();
  v_inicio TIMESTAMPTZ;
  v_fim    TIMESTAMPTZ;
  v_fecha_obra BOOLEAN := false;
  v_comanda_equipe BOOLEAN;
BEGIN
  IF v_perfil IS NULL THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  IF v_perfil = 'montador' AND NOT movelaria_montador_acessa_obra(p_obra_id, v_uid) THEN
    RAISE EXCEPTION 'Acesso negado: obra não atribuída a você';
  END IF;

  IF v_perfil = 'montador_admin' AND NOT movelaria_montador_admin_acessa_obra(p_obra_id, v_uid) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  v_comanda_equipe := v_perfil IN ('administrador', 'administrador_obras', 'montador_admin');

  IF v_comanda_equipe THEN
    PERFORM movelaria_registrar_fim_todos_montadores(p_obra_id);
    v_fecha_obra := true;
  ELSIF v_perfil = 'montador'
     AND v_uid IS NOT NULL
     AND movelaria_montador_acessa_obra(p_obra_id, v_uid) THEN
    PERFORM movelaria_registrar_fim_montador(p_obra_id, v_uid);
    v_fecha_obra := movelaria_obra_todos_montadores_concluiram(p_obra_id);
  ELSE
    v_fecha_obra := true;
  END IF;

  IF v_fecha_obra THEN
    SELECT MIN(r.iniciado_em), MAX(r.finalizado_em)
    INTO v_inicio, v_fim
    FROM movelaria_obra_responsaveis r
    WHERE r.obra_id = p_obra_id
      AND (r.iniciado_em IS NOT NULL OR r.finalizado_em IS NOT NULL);

    IF v_inicio IS NULL THEN
      SELECT iniciado_em INTO v_inicio FROM movelaria_obras WHERE id = p_obra_id;
    END IF;

    UPDATE movelaria_obras
    SET iniciado_em        = COALESCE(v_inicio, iniciado_em),
        finalizado_em      = COALESCE(v_fim, NOW()),
        status_kanban      = 'concluida',
        duracao_real_horas = CASE
          WHEN v_inicio IS NOT NULL AND v_fim IS NOT NULL
            THEN ROUND(EXTRACT(EPOCH FROM (v_fim - v_inicio)) / 3600.0, 4)
          WHEN v_inicio IS NOT NULL
            THEN ROUND(EXTRACT(EPOCH FROM (COALESCE(v_fim, NOW()) - v_inicio)) / 3600.0, 4)
          ELSE duracao_real_horas
        END,
        atualizado_em      = NOW()
    WHERE id = p_obra_id
      AND finalizado_em IS NULL;

    PERFORM movelaria_aplicar_comissao_obra_interno(p_obra_id);
  END IF;
END;
$$;


--
-- Name: movelaria_criar_conta_pagar_pontua_garbo(uuid, uuid, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_criar_conta_pagar_pontua_garbo(p_liberacao_id uuid, p_prestador_id uuid, p_lead_id integer, p_valor_comissao numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
DECLARE
  v_arquiteto TEXT;
  v_lead_nome TEXT;
  v_descricao TEXT;
  v_valor NUMERIC(12, 2);
  v_conta_id UUID;
  v_obs TEXT;
BEGIN
  IF p_liberacao_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_valor := ROUND(COALESCE(p_valor_comissao, 0)::NUMERIC, 2);
  IF v_valor <= 0 THEN
    RETURN NULL;
  END IF;

  -- Já existe conta ligada a esta liberação?
  SELECT id INTO v_conta_id
  FROM movelaria_contas_pagar
  WHERE observacao LIKE '%pontua_liberacao:' || p_liberacao_id::TEXT || '%'
  LIMIT 1;

  IF v_conta_id IS NOT NULL THEN
    RETURN v_conta_id;
  END IF;

  SELECT NULLIF(btrim(u.nome), '') INTO v_arquiteto
  FROM emp_garbo.usuarios u
  WHERE u.id = p_prestador_id;

  SELECT NULLIF(btrim(l.nome), '') INTO v_lead_nome
  FROM emp_garbo.leads l
  WHERE l.id = p_lead_id;

  v_arquiteto := COALESCE(v_arquiteto, 'Arquiteto');
  v_descricao := v_arquiteto || ' — Pontua Garbo';
  v_obs := 'Lead: ' || COALESCE(v_lead_nome, '#' || p_lead_id::TEXT)
        || E'\npontua_liberacao:' || p_liberacao_id::TEXT;

  INSERT INTO movelaria_contas_pagar (
    fornecedor_nome,
    descricao,
    observacao,
    valor_total,
    numero_parcela,
    total_parcelas,
    valor_parcela,
    data_vencimento,
    status,
    valor_pago,
    grupo_lancamento_id
  ) VALUES (
    v_arquiteto,
    v_descricao,
    v_obs,
    v_valor,
    1,
    1,
    v_valor,
    CURRENT_DATE,
    'pendente',
    0,
    gen_random_uuid()
  )
  RETURNING id INTO v_conta_id;

  RETURN v_conta_id;
END;
$$;


--
-- Name: movelaria_criar_markup_orcamento_lead(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_criar_markup_orcamento_lead(p_lead_id text, p_titulo text, p_linhas jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
DECLARE
  v_id UUID;
  v_linhas JSONB;
  v_sum NUMERIC;
  v_fator NUMERIC;
  v_ajustado NUMERIC;
  v_modulos JSONB;
BEGIN
  IF NOT movelaria_usuario_tem_qualquer_perfil(ARRAY['administrador', 'financeiro']) THEN
    RAISE EXCEPTION 'Acesso negado: somente administrador ou financeiro criam markup.';
  END IF;

  IF p_lead_id IS NULL OR btrim(p_lead_id) = '' THEN
    RAISE EXCEPTION 'Lead obrigatório.';
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      (elem
        || jsonb_build_object(
          'quantidade', COALESCE((elem->>'quantidade')::NUMERIC, 0),
          'valor_unitario', COALESCE((elem->>'valor_unitario')::NUMERIC, 0),
          'valor_total', ROUND(
            COALESCE((elem->>'quantidade')::NUMERIC, 0)
            * COALESCE((elem->>'valor_unitario')::NUMERIC, 0)
          , 2),
          'ativo', COALESCE((elem->>'ativo')::BOOLEAN, true)
        )
      )
    ),
    '[]'::JSONB
  )
  INTO v_linhas
  FROM jsonb_array_elements(COALESCE(p_linhas, '[]'::JSONB)) AS elem;

  SELECT COALESCE(SUM(
    CASE
      WHEN COALESCE((elem->>'ativo')::BOOLEAN, true)
        THEN COALESCE((elem->>'valor_total')::NUMERIC, 0)
      ELSE 0
    END
  ), 0)
  INTO v_sum
  FROM jsonb_array_elements(v_linhas) AS elem;

  SELECT COALESCE(fator_sobras, 1) INTO v_fator
  FROM emp_garbo.markup_config
  LIMIT 1;

  v_ajustado := ROUND(v_sum * COALESCE(v_fator, 1), 2);
  v_modulos := jsonb_build_object(
    'materiais', jsonb_build_object('linhas', v_linhas),
    'totais', jsonb_build_object(
      'custo_materiais', v_sum,
      'custo_materiais_ajustado', v_ajustado,
      'custo_servicos', 0,
      'custo_despesas', 0,
      'preco_final', 0
    )
  );

  INSERT INTO emp_garbo.markup_orcamentos (
    lead_id, titulo, status, modulos, preco_final, atualizado_em
  )
  VALUES (
    p_lead_id::BIGINT,
    COALESCE(NULLIF(btrim(p_titulo), ''), 'Pedido de materiais'),
    'rascunho',
    v_modulos,
    0,
    NOW()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: movelaria_criar_obra_de_orcamento(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_criar_obra_de_orcamento(p_orcamento_id uuid, p_cliente_id uuid, p_cliente_nome text, p_lead_id text DEFAULT NULL::text, p_lousa text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
DECLARE
  v_id UUID;
  v_lead BIGINT;
BEGIN
  INSERT INTO movelaria_obras (
    origem_orcamento_id, origem_lead_id,
    cliente_id, cliente_nome, lousa, status_kanban
  ) VALUES (
    p_orcamento_id, p_lead_id,
    p_cliente_id, p_cliente_nome, p_lousa, 'datas_em_aberto'
  )
  RETURNING id INTO v_id;

  BEGIN
    IF p_lead_id IS NOT NULL AND btrim(p_lead_id) <> '' THEN
      v_lead := p_lead_id::BIGINT;
      PERFORM public.movelaria_criar_obra_producao(v_id, v_lead);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'obra_producao não criada: %', SQLERRM;
  END;

  RETURN v_id;
END;
$$;


--
-- Name: movelaria_criar_obra_producao(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_criar_obra_producao(p_obra_id uuid, p_lead_id bigint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
DECLARE
  v_id UUID;
  v_stage UUID;
BEGIN
  SELECT id INTO v_id FROM emp_garbo.obra_producao WHERE obra_id = p_obra_id;
  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  SELECT id INTO v_stage
  FROM emp_garbo.producao_stages
  WHERE ativo = true
  ORDER BY ordem ASC
  LIMIT 1;

  IF v_stage IS NULL THEN
    RAISE EXCEPTION 'Nenhuma coluna de produção configurada';
  END IF;

  INSERT INTO emp_garbo.obra_producao (obra_id, lead_id, stage_id)
  VALUES (p_obra_id, p_lead_id, v_stage)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: movelaria_criar_usuario(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_criar_usuario(p_email text, p_senha text, p_nome text DEFAULT NULL::text, p_perfil text DEFAULT 'marceneiro'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'auth', 'public'
    AS $$
DECLARE
  v_id    UUID;
  v_email TEXT := lower(trim(p_email));
BEGIN
  IF movelaria_meu_perfil() <> 'administrador' THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;
  IF NOT (p_perfil = ANY(movelaria_perfis_validos())) THEN
    RAISE EXCEPTION 'Perfil inválido: %', p_perfil;
  END IF;

  SELECT id INTO v_id FROM auth.users WHERE lower(email) = v_email;

  IF v_id IS NOT NULL THEN
    INSERT INTO public.movelaria_usuarios (id, email, nome, perfil, ativo)
    VALUES (v_id, v_email, p_nome, p_perfil, true)
    ON CONFLICT (id) DO UPDATE
      SET nome   = COALESCE(EXCLUDED.nome, public.movelaria_usuarios.nome),
          perfil = EXCLUDED.perfil,
          ativo  = true,
          atualizado_em = NOW();

    IF p_senha IS NOT NULL AND p_senha <> '' THEN
      UPDATE auth.users
      SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
          updated_at = NOW()
      WHERE id = v_id;
    END IF;

    UPDATE auth.users
    SET
      confirmation_token         = COALESCE(confirmation_token, ''),
      recovery_token             = COALESCE(recovery_token, ''),
      email_change_token_new     = COALESCE(email_change_token_new, ''),
      email_change               = COALESCE(email_change, ''),
      email_change_token_current = COALESCE(email_change_token_current, ''),
      phone_change_token         = COALESCE(phone_change_token, ''),
      reauthentication_token     = COALESCE(reauthentication_token, '')
    WHERE id = v_id;

    INSERT INTO auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    VALUES (
      gen_random_uuid(), v_id, v_email,
      jsonb_build_object('sub', v_id::text, 'email', v_email, 'email_verified', true),
      'email', NOW(), NOW(), NOW()
    )
    ON CONFLICT (provider, provider_id) DO NOTHING;

  ELSE
    v_id := gen_random_uuid();

    INSERT INTO auth.users (
      id, instance_id, aud, role,
      email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data,
      is_sso_user, is_anonymous,
      created_at, updated_at,
      confirmation_token, recovery_token,
      email_change_token_new, email_change,
      email_change_token_current, phone_change_token,
      reauthentication_token
    ) VALUES (
      v_id,
      '00000000-0000-0000-0000-000000000000',
      'authenticated', 'authenticated',
      v_email,
      extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
      NOW(),
      '{"provider":"email","providers":["email"]}'::jsonb,
      '{}'::jsonb,
      false, false,
      NOW(), NOW(),
      '', '', '', '', '', '', ''
    );

    INSERT INTO auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    VALUES (
      gen_random_uuid(), v_id, v_email,
      jsonb_build_object('sub', v_id::text, 'email', v_email, 'email_verified', true),
      'email', NOW(), NOW(), NOW()
    );

    INSERT INTO public.movelaria_usuarios (id, email, nome, perfil, ativo)
    VALUES (v_id, v_email, p_nome, p_perfil, true)
    ON CONFLICT (id) DO UPDATE
      SET nome = p_nome, perfil = p_perfil, ativo = true, atualizado_em = NOW();
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: movelaria_crm_agenda_boot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_agenda_boot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_config JSONB; v_reunioes JSONB; v_leads JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_venda() THEN RAISE EXCEPTION 'Acesso negado à agenda comercial'; END IF;
  SELECT to_jsonb(c) INTO v_config FROM emp_garbo.agenda_config c LIMIT 1;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', r.id, 'titulo', r.titulo, 'descricao', r.descricao,
    'data_hora_inicio', r.data_hora_inicio, 'data_hora_fim', r.data_hora_fim,
    'duracao_minutos', r.duracao_minutos, 'convidado_nome', r.convidado_nome,
    'convidado_whatsapp', r.convidado_whatsapp, 'convidado_email', r.convidado_email,
    'status', r.status, 'tipo', r.tipo, 'lead_id', r.lead_id, 'lead_nome', l.nome,
    'observacoes', r.observacoes, 'link_video_conferencia', r.link_video_conferencia
  ) ORDER BY r.data_hora_inicio DESC), '[]'::JSONB)
  INTO v_reunioes
  FROM emp_garbo.agenda_reunioes r
  LEFT JOIN emp_garbo.leads l ON l.id = r.lead_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', l.id, 'nome', l.nome) ORDER BY l.nome), '[]'::JSONB)
  INTO v_leads FROM emp_garbo.leads l;
  RETURN jsonb_build_object(
    'config', COALESCE(v_config, '{}'::JSONB),
    'reunioes', COALESCE(v_reunioes, '[]'::JSONB),
    'leads', COALESCE(v_leads, '[]'::JSONB)
  );
END;
$$;


--
-- Name: movelaria_crm_agenda_criar(text, timestamp with time zone, timestamp with time zone, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_agenda_criar(p_titulo text, p_inicio timestamp with time zone, p_fim timestamp with time zone, p_convidado text, p_whatsapp text, p_lead_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id UUID; v_row JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_venda() THEN RAISE EXCEPTION 'Acesso negado à agenda comercial'; END IF;
  IF NULLIF(BTRIM(p_titulo), '') IS NULL OR p_inicio IS NULL THEN
    RAISE EXCEPTION 'Título e horário são obrigatórios';
  END IF;
  INSERT INTO emp_garbo.agenda_reunioes (
    titulo, data_hora_inicio, data_hora_fim, duracao_minutos,
    convidado_nome, convidado_whatsapp, status, tipo, lead_id
  ) VALUES (
    BTRIM(p_titulo), p_inicio, COALESCE(p_fim, p_inicio + INTERVAL '30 minutes'),
    GREATEST(1, ROUND(EXTRACT(EPOCH FROM (COALESCE(p_fim, p_inicio + INTERVAL '30 minutes') - p_inicio)) / 60)::INT),
    NULLIF(BTRIM(p_convidado), ''), NULLIF(BTRIM(p_whatsapp), ''),
    'pendente', 'interno', p_lead_id
  ) RETURNING id INTO v_id;
  SELECT jsonb_build_object(
    'id', r.id, 'titulo', r.titulo, 'data_hora_inicio', r.data_hora_inicio,
    'data_hora_fim', r.data_hora_fim, 'convidado_nome', r.convidado_nome,
    'status', r.status, 'lead_id', r.lead_id
  ) INTO v_row FROM emp_garbo.agenda_reunioes r WHERE r.id = v_id;
  RETURN v_row;
END;
$$;


--
-- Name: movelaria_crm_agenda_publica(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_agenda_publica(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfg emp_garbo.agenda_config%ROWTYPE;
  v_ocupados JSONB;
BEGIN
  SELECT * INTO v_cfg
  FROM emp_garbo.agenda_config
  WHERE slug = NULLIF(btrim(p_slug), '') AND ativo = TRUE
  LIMIT 1;
  IF v_cfg.id IS NULL THEN
    RAISE EXCEPTION 'Agenda não encontrada';
  END IF;

  SELECT COALESCE(jsonb_agg(r.data_hora_inicio ORDER BY r.data_hora_inicio), '[]'::JSONB)
  INTO v_ocupados
  FROM emp_garbo.agenda_reunioes r
  WHERE r.status IS DISTINCT FROM 'cancelado'
    AND r.data_hora_inicio >= NOW()
    AND r.data_hora_inicio < NOW() + make_interval(days => GREATEST(1, v_cfg.antecedencia_maxima_dias));

  RETURN jsonb_build_object(
    'nome', v_cfg.nome_agenda,
    'slug', v_cfg.slug,
    'duracao_minutos', v_cfg.duracao_minutos,
    'intervalo_minutos', v_cfg.intervalo_minutos,
    'horario_inicio', v_cfg.horario_inicio,
    'horario_fim', v_cfg.horario_fim,
    'dias_disponiveis', v_cfg.dias_disponiveis,
    'texto', v_cfg.texto_pagina_agendamento,
    'antecedencia_minima_horas', v_cfg.antecedencia_minima_horas,
    'antecedencia_maxima_dias', v_cfg.antecedencia_maxima_dias,
    'ocupados', COALESCE(v_ocupados, '[]'::JSONB)
  );
END;
$$;


--
-- Name: movelaria_crm_agenda_publica_criar(text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_agenda_publica_criar(p_slug text, p_nome text, p_whatsapp text, p_inicio timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfg emp_garbo.agenda_config%ROWTYPE;
  v_id UUID;
  v_fim TIMESTAMPTZ;
  v_digits TEXT := regexp_replace(COALESCE(p_whatsapp, ''), '\D', '', 'g');
BEGIN
  SELECT * INTO v_cfg
  FROM emp_garbo.agenda_config
  WHERE slug = NULLIF(btrim(p_slug), '') AND ativo = TRUE
  LIMIT 1;
  IF v_cfg.id IS NULL THEN RAISE EXCEPTION 'Agenda não encontrada'; END IF;
  IF NULLIF(btrim(p_nome), '') IS NULL THEN RAISE EXCEPTION 'Informe o nome'; END IF;
  IF length(COALESCE(v_digits, '')) < 8 THEN RAISE EXCEPTION 'Informe o WhatsApp'; END IF;
  IF p_inicio IS NULL THEN RAISE EXCEPTION 'Informe data e horário'; END IF;
  IF p_inicio < NOW() + make_interval(hours => GREATEST(0, v_cfg.antecedencia_minima_horas)) THEN
    RAISE EXCEPTION 'Este horário precisa de mais antecedência';
  END IF;
  IF EXISTS (
    SELECT 1 FROM emp_garbo.agenda_reunioes r
    WHERE r.status IS DISTINCT FROM 'cancelado'
      AND r.data_hora_inicio = p_inicio
  ) THEN
    RAISE EXCEPTION 'Este horário já foi reservado';
  END IF;

  v_fim := p_inicio + make_interval(mins => GREATEST(15, v_cfg.duracao_minutos));

  INSERT INTO emp_garbo.agenda_reunioes (
    titulo, data_hora_inicio, data_hora_fim, duracao_minutos,
    convidado_nome, convidado_whatsapp, status, tipo
  ) VALUES (
    'Agendamento: ' || btrim(p_nome),
    p_inicio, v_fim, GREATEST(15, v_cfg.duracao_minutos),
    btrim(p_nome), v_digits, 'pendente', 'publico'
  ) RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id, 'inicio', p_inicio);
END;
$$;


--
-- Name: movelaria_crm_agenda_salvar(uuid, text, timestamp with time zone, timestamp with time zone, text, text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_agenda_salvar(p_id uuid, p_titulo text, p_inicio timestamp with time zone, p_fim timestamp with time zone, p_convidado text, p_whatsapp text, p_status text, p_lead_id bigint, p_observacoes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row JSONB; v_status TEXT;
BEGIN
  IF NOT public.movelaria_crm_pode_venda() THEN RAISE EXCEPTION 'Acesso negado à agenda comercial'; END IF;
  IF p_id IS NULL OR NULLIF(BTRIM(p_titulo), '') IS NULL OR p_inicio IS NULL THEN
    RAISE EXCEPTION 'Título e horário são obrigatórios';
  END IF;
  v_status := COALESCE(NULLIF(BTRIM(p_status), ''), 'pendente');
  UPDATE emp_garbo.agenda_reunioes SET
    titulo = BTRIM(p_titulo),
    data_hora_inicio = p_inicio,
    data_hora_fim = COALESCE(p_fim, p_inicio + INTERVAL '30 minutes'),
    duracao_minutos = GREATEST(1, ROUND(EXTRACT(EPOCH FROM (COALESCE(p_fim, p_inicio + INTERVAL '30 minutes') - p_inicio)) / 60)::INT),
    convidado_nome = NULLIF(BTRIM(p_convidado), ''),
    convidado_whatsapp = NULLIF(BTRIM(p_whatsapp), ''),
    status = v_status,
    lead_id = p_lead_id,
    observacoes = NULLIF(BTRIM(p_observacoes), ''),
    atualizado_em = NOW(),
    confirmado_em = CASE WHEN v_status = 'confirmado' THEN COALESCE(confirmado_em, NOW()) ELSE confirmado_em END,
    concluido_em = CASE WHEN v_status = 'concluido' THEN COALESCE(concluido_em, NOW()) ELSE concluido_em END,
    cancelado_em = CASE WHEN v_status = 'cancelado' THEN COALESCE(cancelado_em, NOW()) ELSE cancelado_em END
  WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reunião não encontrada'; END IF;
  SELECT jsonb_build_object(
    'id', r.id, 'titulo', r.titulo, 'data_hora_inicio', r.data_hora_inicio,
    'data_hora_fim', r.data_hora_fim, 'convidado_nome', r.convidado_nome,
    'convidado_whatsapp', r.convidado_whatsapp, 'status', r.status,
    'lead_id', r.lead_id, 'observacoes', r.observacoes
  ) INTO v_row FROM emp_garbo.agenda_reunioes r WHERE r.id = p_id;
  RETURN v_row;
END;
$$;


--
-- Name: movelaria_crm_automacoes_boot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_automacoes_boot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_atalhos JSONB;
  v_neg JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_automacao_mkt() THEN
    RAISE EXCEPTION 'Acesso negado às automações';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', a.id, 'titulo', a.titulo, 'mensagem', a.mensagem,
    'url_img', a.url_img, 'url_pdf', a.url_pdf, 'url_audio', a.url_audio
  ) ORDER BY a.titulo), '[]'::JSONB)
  INTO v_atalhos FROM emp_garbo.atalhos a;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', n.id, 'telefone', n."numeroTelefone"
  ) ORDER BY n.id DESC), '[]'::JSONB)
  INTO v_neg FROM emp_garbo.negativacao_numeros n;

  RETURN jsonb_build_object(
    'atalhos', COALESCE(v_atalhos, '[]'::JSONB),
    'negativados', COALESCE(v_neg, '[]'::JSONB)
  );
END;
$$;


--
-- Name: movelaria_crm_automacoes_salvar_atalho(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_automacoes_salvar_atalho(p_id bigint, p_titulo text, p_mensagem text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id BIGINT;
BEGIN
  IF NOT public.movelaria_crm_pode_automacao_mkt() THEN
    RAISE EXCEPTION 'Acesso negado às automações';
  END IF;
  IF NULLIF(btrim(p_titulo), '') IS NULL THEN RAISE EXCEPTION 'Informe o título'; END IF;
  IF p_id IS NULL THEN
    INSERT INTO emp_garbo.atalhos (titulo, mensagem, user_auth, all_can_see)
    VALUES (btrim(p_titulo), COALESCE(p_mensagem, ''), auth.uid(), TRUE)
    RETURNING id INTO v_id;
  ELSE
    UPDATE emp_garbo.atalhos SET titulo = btrim(p_titulo), mensagem = COALESCE(p_mensagem, '')
    WHERE id = p_id RETURNING id INTO v_id;
  END IF;
  RETURN jsonb_build_object('id', v_id);
END;
$$;


--
-- Name: movelaria_crm_automacoes_salvar_negativado(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_automacoes_salvar_negativado(p_telefone bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id BIGINT;
BEGIN
  IF NOT (public.movelaria_crm_colaborador_roles() && ARRAY['admin', 'vendedor']::TEXT[]) THEN
    RAISE EXCEPTION 'Acesso negado à negativação';
  END IF;
  IF p_telefone IS NULL THEN RAISE EXCEPTION 'Informe o telefone'; END IF;
  INSERT INTO emp_garbo.negativacao_numeros ("numeroTelefone") VALUES (p_telefone)
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id);
END;
$$;


--
-- Name: movelaria_crm_chat_boot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_chat_boot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contatos JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_venda() THEN
    RAISE EXCEPTION 'Acesso negado ao chat interno';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', c.id, 'nome', c.nome, 'telefone', c.telefone, 'lead_id', c.lead_id,
    'ultima_mensagem_em', c.ultima_mensagem_em, 'nao_lidas', COALESCE(c.mensagens_nao_lidas, 0)
  ) ORDER BY c.ultima_mensagem_em DESC NULLS LAST), '[]'::JSONB)
  INTO v_contatos FROM emp_garbo.chat_contatos c;

  RETURN jsonb_build_object('contatos', COALESCE(v_contatos, '[]'::JSONB));
END;
$$;


--
-- Name: movelaria_crm_colaborador_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_colaborador_roles() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tipo   TEXT;
  v_status TEXT;
  v_roles  TEXT[];
BEGIN
  IF auth.uid() IS NULL THEN RETURN '{}'::TEXT[]; END IF;
  SELECT c.tipo_usuario, c.status_convite INTO v_tipo, v_status
  FROM emp_garbo.usuarios c WHERE c.id = auth.uid();
  IF v_tipo IS DISTINCT FROM 'colaborador' OR v_status IS DISTINCT FROM 'ATIVO' THEN
    RETURN '{}'::TEXT[];
  END IF;
  SELECT COALESCE(array_agg(r.role::TEXT), '{}'::TEXT[])
  INTO v_roles
  FROM emp_garbo.user_roles r
  WHERE r.user_id = auth.uid();
  RETURN v_roles;
END;
$$;


--
-- Name: movelaria_crm_contrato_criar(text, text, bigint, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_contrato_criar(p_identificador text, p_cliente_nome text, p_lead_id bigint, p_campos jsonb, p_conteudo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id UUID; v_row JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_venda() THEN RAISE EXCEPTION 'Acesso negado aos contratos'; END IF;
  INSERT INTO emp_garbo.contratos (identificador, cliente_nome, status, lead_id, campos_valores, conteudo_final, criado_por)
  VALUES (
    COALESCE(NULLIF(BTRIM(p_identificador), ''), 'Rascunho'),
    COALESCE(NULLIF(BTRIM(p_cliente_nome), ''), 'Rascunho'),
    'rascunho', p_lead_id, COALESCE(p_campos, '{}'::JSONB), COALESCE(p_conteudo, ''), auth.uid()
  ) RETURNING id INTO v_id;
  SELECT jsonb_build_object(
    'id', c.id, 'identificador', c.identificador, 'cliente_nome', c.cliente_nome,
    'status', c.status, 'lead_id', c.lead_id, 'campos_valores', COALESCE(c.campos_valores, '{}'::JSONB),
    'conteudo_final', COALESCE(c.conteudo_final, ''), 'created_at', c.created_at
  ) INTO v_row FROM emp_garbo.contratos c WHERE c.id = v_id;
  RETURN v_row;
END;
$$;


--
-- Name: movelaria_crm_contrato_salvar(uuid, text, text, text, bigint, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_contrato_salvar(p_id uuid, p_identificador text, p_cliente_nome text, p_status text, p_lead_id bigint, p_campos jsonb, p_conteudo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_venda() THEN RAISE EXCEPTION 'Acesso negado aos contratos'; END IF;
  IF p_id IS NULL OR NULLIF(BTRIM(p_identificador), '') IS NULL THEN
    RAISE EXCEPTION 'Identificador é obrigatório';
  END IF;
  UPDATE emp_garbo.contratos SET
    identificador = BTRIM(p_identificador),
    cliente_nome = COALESCE(NULLIF(BTRIM(p_cliente_nome), ''), cliente_nome),
    status = COALESCE(NULLIF(BTRIM(p_status), ''), status),
    lead_id = p_lead_id,
    campos_valores = COALESCE(p_campos, campos_valores),
    conteudo_final = COALESCE(p_conteudo, conteudo_final)
  WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contrato não encontrado'; END IF;
  SELECT jsonb_build_object(
    'id', c.id, 'identificador', c.identificador, 'cliente_nome', c.cliente_nome,
    'status', c.status, 'lead_id', c.lead_id, 'campos_valores', COALESCE(c.campos_valores, '{}'::JSONB),
    'conteudo_final', COALESCE(c.conteudo_final, ''), 'created_at', c.created_at
  ) INTO v_row FROM emp_garbo.contratos c WHERE c.id = p_id;
  RETURN v_row;
END;
$$;


--
-- Name: movelaria_crm_contratos_boot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_contratos_boot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_contratos JSONB; v_modelos JSONB; v_variaveis JSONB; v_leads JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_venda() THEN RAISE EXCEPTION 'Acesso negado aos contratos'; END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', c.id, 'identificador', c.identificador, 'cliente_nome', c.cliente_nome,
    'status', c.status, 'lead_id', c.lead_id, 'lead_nome', l.nome,
    'campos_valores', COALESCE(c.campos_valores, '{}'::JSONB),
    'conteudo_final', COALESCE(c.conteudo_final, ''),
    'created_at', c.created_at
  ) ORDER BY c.created_at DESC), '[]'::JSONB)
  INTO v_contratos
  FROM emp_garbo.contratos c
  LEFT JOIN emp_garbo.leads l ON l.id = c.lead_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', m.id, 'nome', m.nome, 'conteudo', m.conteudo, 'ativo', m.ativo
  ) ORDER BY m.nome), '[]'::JSONB)
  INTO v_modelos FROM emp_garbo.contratos_modelos m;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', v.id, 'nome', v.nome, 'label', v.label, 'tipo', v.tipo,
    'obrigatorio', v.obrigatorio, 'ordem', v.ordem
  ) ORDER BY v.ordem, v.nome), '[]'::JSONB)
  INTO v_variaveis FROM emp_garbo.contratos_variaveis v;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', l.id, 'nome', l.nome) ORDER BY l.nome), '[]'::JSONB)
  INTO v_leads FROM emp_garbo.leads l;

  RETURN jsonb_build_object(
    'contratos', COALESCE(v_contratos, '[]'::JSONB),
    'modelos', COALESCE(v_modelos, '[]'::JSONB),
    'variaveis', COALESCE(v_variaveis, '[]'::JSONB),
    'leads', COALESCE(v_leads, '[]'::JSONB)
  );
END;
$$;


--
-- Name: movelaria_crm_criar_lead(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_criar_lead(p_nome text, p_telefone text, p_origem text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id BIGINT;
  v_status TEXT;
BEGIN
  IF NOT public.movelaria_crm_pode_pipeline() THEN
    RAISE EXCEPTION 'Acesso negado ao pipeline comercial';
  END IF;
  IF NULLIF(BTRIM(p_nome), '') IS NULL THEN
    RAISE EXCEPTION 'Nome do lead é obrigatório';
  END IF;

  SELECT s.nome
  INTO v_status
  FROM emp_garbo.pipeline_custom_stages s
  WHERE s.ativo IS TRUE
  ORDER BY s.ordem, s.nome
  LIMIT 1;

  INSERT INTO emp_garbo.leads (nome, telefone, origem, status, vendedor_responsavel_id)
  VALUES (
    BTRIM(p_nome),
    NULLIF(BTRIM(p_telefone), ''),
    NULLIF(BTRIM(p_origem), ''),
    COALESCE(v_status, 'Novo Lead'),
    auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: movelaria_crm_eventos_boot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_eventos_boot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_eventos JSONB;
  v_paginas JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_venda() THEN
    RAISE EXCEPTION 'Acesso negado aos eventos';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', e.id, 'titulo', e.titulo, 'data_evento', e.data_evento,
    'tipo', e.tipo, 'tipo_custom', e.tipo_custom, 'observacoes', e.observacoes, 'fixado', e.fixado
  ) ORDER BY e.fixado DESC, e.data_evento DESC), '[]'::JSONB)
  INTO v_eventos FROM emp_garbo.eventos e;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', p.id, 'evento_id', p.evento_id, 'secao', p.secao,
    'titulo', p.titulo, 'corpo', p.corpo, 'ordem', p.ordem
  ) ORDER BY p.ordem, p.titulo), '[]'::JSONB)
  INTO v_paginas FROM emp_garbo.evento_paginas p;

  RETURN jsonb_build_object(
    'eventos', COALESCE(v_eventos, '[]'::JSONB),
    'paginas', COALESCE(v_paginas, '[]'::JSONB)
  );
END;
$$;


--
-- Name: movelaria_crm_gastos_boot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_gastos_boot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fontes JSONB;
  v_subs JSONB;
  v_cols JSONB;
  v_lanc JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_gastos() THEN
    RAISE EXCEPTION 'Acesso negado ao controle de gastos';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', f.id, 'nome', f.nome, 'icone', f.icone, 'cor', f.cor, 'ativo', COALESCE(f.ativo, TRUE), 'ordem', f.ordem
  ) ORDER BY f.ordem, f.nome), '[]'::JSONB)
  INTO v_fontes FROM emp_garbo.mkt_fontes f;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', s.id, 'fonte_id', s.fonte_id, 'nome', s.nome, 'descricao', s.descricao, 'ativo', COALESCE(s.ativo, TRUE), 'ordem', s.ordem
  ) ORDER BY s.ordem, s.nome), '[]'::JSONB)
  INTO v_subs FROM emp_garbo.mkt_sub_fontes s;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', c.id, 'sub_fonte_id', c.sub_fonte_id, 'nome', c.nome, 'tipo', c.tipo, 'ordem', c.ordem
  ) ORDER BY c.ordem, c.nome), '[]'::JSONB)
  INTO v_cols FROM emp_garbo.mkt_config_colunas c;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', l.id, 'coluna_id', l.coluna_id, 'data', l.data, 'valor_numerico', l.valor_numerico, 'observacao', l.observacao
  ) ORDER BY l.data DESC), '[]'::JSONB)
  INTO v_lanc FROM emp_garbo.mkt_lancamentos l;

  RETURN jsonb_build_object(
    'fontes', COALESCE(v_fontes, '[]'::JSONB),
    'sub_fontes', COALESCE(v_subs, '[]'::JSONB),
    'colunas', COALESCE(v_cols, '[]'::JSONB),
    'lancamentos', COALESCE(v_lanc, '[]'::JSONB)
  );
END;
$$;


--
-- Name: movelaria_crm_gastos_salvar_fonte(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_gastos_salvar_fonte(p_id uuid, p_nome text, p_cor text DEFAULT '#f2d892'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_ordem INT;
BEGIN
  IF NOT public.movelaria_crm_pode_gastos() THEN
    RAISE EXCEPTION 'Acesso negado ao controle de gastos';
  END IF;
  IF NULLIF(btrim(p_nome), '') IS NULL THEN RAISE EXCEPTION 'Informe o nome da fonte'; END IF;
  IF p_id IS NULL THEN
    SELECT COALESCE(MAX(ordem), 0) + 1 INTO v_ordem FROM emp_garbo.mkt_fontes;
    INSERT INTO emp_garbo.mkt_fontes (nome, cor, icone, ativo, ordem)
    VALUES (btrim(p_nome), COALESCE(NULLIF(btrim(p_cor), ''), '#f2d892'), 'wallet', TRUE, v_ordem)
    RETURNING id INTO v_id;
  ELSE
    UPDATE emp_garbo.mkt_fontes SET nome = btrim(p_nome), cor = COALESCE(NULLIF(btrim(p_cor), ''), cor), atualizado_em = NOW()
    WHERE id = p_id RETURNING id INTO v_id;
  END IF;
  RETURN jsonb_build_object('id', v_id);
END;
$$;


--
-- Name: movelaria_crm_gastos_salvar_lancamento(uuid, uuid, date, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_gastos_salvar_lancamento(p_id uuid, p_coluna_id uuid, p_data date, p_valor numeric, p_observacao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  IF NOT public.movelaria_crm_pode_gastos() THEN
    RAISE EXCEPTION 'Acesso negado ao controle de gastos';
  END IF;
  IF p_coluna_id IS NULL OR p_data IS NULL THEN RAISE EXCEPTION 'Informe a coluna e a data'; END IF;
  IF p_id IS NULL THEN
    INSERT INTO emp_garbo.mkt_lancamentos (coluna_id, data, valor_numerico, observacao)
    VALUES (p_coluna_id, p_data, COALESCE(p_valor, 0), NULLIF(btrim(p_observacao), ''))
    RETURNING id INTO v_id;
  ELSE
    UPDATE emp_garbo.mkt_lancamentos
    SET valor_numerico = COALESCE(p_valor, 0), observacao = NULLIF(btrim(p_observacao), ''), atualizado_em = NOW()
    WHERE id = p_id RETURNING id INTO v_id;
  END IF;
  RETURN jsonb_build_object('id', v_id);
END;
$$;


--
-- Name: movelaria_crm_gastos_salvar_subfonte(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_gastos_salvar_subfonte(p_id uuid, p_fonte_id uuid, p_nome text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_ordem INT;
  v_col UUID;
BEGIN
  IF NOT public.movelaria_crm_pode_gastos() THEN
    RAISE EXCEPTION 'Acesso negado ao controle de gastos';
  END IF;
  IF p_fonte_id IS NULL THEN RAISE EXCEPTION 'Fonte inválida'; END IF;
  IF NULLIF(btrim(p_nome), '') IS NULL THEN RAISE EXCEPTION 'Informe o nome'; END IF;
  IF p_id IS NULL THEN
    SELECT COALESCE(MAX(ordem), 0) + 1 INTO v_ordem FROM emp_garbo.mkt_sub_fontes WHERE fonte_id = p_fonte_id;
    INSERT INTO emp_garbo.mkt_sub_fontes (fonte_id, nome, ativo, ordem)
    VALUES (p_fonte_id, btrim(p_nome), TRUE, v_ordem)
    RETURNING id INTO v_id;
    INSERT INTO emp_garbo.mkt_config_colunas (sub_fonte_id, nome, tipo, ordem, largura, editavel)
    VALUES (v_id, 'Valor', 'currency', 1, 140, TRUE)
    RETURNING id INTO v_col;
  ELSE
    UPDATE emp_garbo.mkt_sub_fontes SET nome = btrim(p_nome), atualizado_em = NOW()
    WHERE id = p_id RETURNING id INTO v_id;
  END IF;
  RETURN jsonb_build_object('id', v_id);
END;
$$;


--
-- Name: movelaria_crm_lead_ia_boot(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_lead_ia_boot(p_lead_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_analises JSONB;
  v_renders JSONB;
  v_chat JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_pipeline() THEN
    RAISE EXCEPTION 'Acesso negado à IA do lead';
  END IF;
  IF p_lead_id IS NULL THEN RAISE EXCEPTION 'Informe o lead'; END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(x)), '[]'::JSONB)
  INTO v_analises
  FROM (
    SELECT a.id, a.modelo, a.conteudo, a.perguntas_briefing, a.criado_em
    FROM emp_garbo.lead_ai_analises a
    WHERE a.lead_id = p_lead_id
    ORDER BY a.criado_em DESC
    LIMIT 12
  ) x;

  SELECT COALESCE(jsonb_agg(row_to_json(x)), '[]'::JSONB)
  INTO v_renders
  FROM (
    SELECT r.id, r.output_public_url, r.vision_model, r.image_model, r.criado_em, r.edit_notas
    FROM emp_garbo.lead_ai_renders r
    WHERE r.lead_id = p_lead_id
    ORDER BY r.criado_em DESC
    LIMIT 12
  ) x;

  SELECT COALESCE(jsonb_agg(row_to_json(x)), '[]'::JSONB)
  INTO v_chat
  FROM (
    SELECT m.id, m.role, m.content, m.modelo, m.criado_em
    FROM emp_garbo.lead_ai_chat_messages m
    WHERE m.lead_id = p_lead_id
    ORDER BY m.criado_em DESC
    LIMIT 30
  ) x;

  RETURN jsonb_build_object(
    'analises', COALESCE(v_analises, '[]'::JSONB),
    'renders', COALESCE(v_renders, '[]'::JSONB),
    'chat', COALESCE(v_chat, '[]'::JSONB)
  );
END;
$$;


--
-- Name: movelaria_crm_lousa_boot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_lousa_boot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_leads JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_pipeline() THEN RAISE EXCEPTION 'Acesso negado à lousa do lead'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'lead_id', q.lead_id, 'lead_nome', q.lead_nome,
    'fotos', q.fotos, 'tracos', q.tracos
  ) ORDER BY q.fotos DESC, q.lead_nome), '[]'::JSONB)
  INTO v_leads
  FROM (
    SELECT i.lead_id, l.nome AS lead_nome, COUNT(DISTINCT i.id)::INT AS fotos,
      (SELECT COUNT(*)::INT FROM emp_garbo.lead_whiteboard_drawings d WHERE d.lead_id = i.lead_id) AS tracos
    FROM emp_garbo.lead_whiteboard_images i
    LEFT JOIN emp_garbo.leads l ON l.id = i.lead_id
    GROUP BY i.lead_id, l.nome
  ) q;
  RETURN jsonb_build_object('leads', COALESCE(v_leads, '[]'::JSONB));
END;
$$;


--
-- Name: movelaria_crm_lousa_obter(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_lousa_obter(p_lead_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_lead TEXT; v_images JSONB; v_drawings JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_pipeline() THEN RAISE EXCEPTION 'Acesso negado à lousa do lead'; END IF;
  IF p_lead_id IS NULL THEN RAISE EXCEPTION 'Lead inválido'; END IF;
  SELECT nome INTO v_lead FROM emp_garbo.leads WHERE id = p_lead_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', i.id, 'file_url', i.file_url, 'file_name', i.file_name,
    'position_x', i.position_x, 'position_y', i.position_y,
    'width', i.width, 'height', i.height, 'z_index', i.z_index
  ) ORDER BY i.z_index, i.criado_em), '[]'::JSONB)
  INTO v_images FROM emp_garbo.lead_whiteboard_images i WHERE i.lead_id = p_lead_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', d.id, 'path_data', d.path_data, 'cor', d.cor, 'stroke_width', d.stroke_width
  ) ORDER BY d.criado_em), '[]'::JSONB)
  INTO v_drawings FROM emp_garbo.lead_whiteboard_drawings d WHERE d.lead_id = p_lead_id;
  RETURN jsonb_build_object(
    'lead_id', p_lead_id, 'lead_nome', v_lead,
    'images', COALESCE(v_images, '[]'::JSONB),
    'drawings', COALESCE(v_drawings, '[]'::JSONB)
  );
END;
$$;


--
-- Name: movelaria_crm_marketing_boot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_marketing_boot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cols JSONB;
  v_cards JSONB;
  v_folders JSONB;
  v_nodes JSONB;
  v_tasks JSONB;
  v_agents JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_marketing() THEN
    RAISE EXCEPTION 'Acesso negado ao marketing';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', c.id, 'nome', c.nome, 'ordem', c.ordem
  ) ORDER BY c.ordem, c.nome), '[]'::JSONB)
  INTO v_cols FROM emp_garbo.marketing_columns c;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', x.id,
    'titulo', x.titulo,
    'script_copy', x.script_copy,
    'column_id', x.column_id,
    'urgente', COALESCE(x.urgente, FALSE),
    'performando', COALESCE(x.performando, FALSE),
    'ordem', x.ordem,
    'criado_em', x.criado_em
  ) ORDER BY x.ordem, x.criado_em), '[]'::JSONB)
  INTO v_cards FROM emp_garbo.marketing_content_cards x;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', f.id, 'nome', f.nome, 'descricao', f.descricao, 'total', COALESCE(cnt.n, 0)
  ) ORDER BY f.nome), '[]'::JSONB)
  INTO v_folders
  FROM emp_garbo.marketing_media_folders f
  LEFT JOIN (
    SELECT folder_id, COUNT(*)::INT AS n
    FROM emp_garbo.marketing_medias
    GROUP BY folder_id
  ) cnt ON cnt.folder_id = f.id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', n.id, 'titulo', n.titulo, 'conteudo', n.conteudo,
    'classificacao', n.classificacao, 'enviado_producao', COALESCE(n.enviado_producao, FALSE),
    'card_id', n.card_id, 'criado_em', n.criado_em
  ) ORDER BY n.criado_em DESC), '[]'::JSONB)
  INTO v_nodes FROM emp_garbo.marketing_planning_nodes n;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', t.id, 'titulo', t.titulo, 'descricao', t.descricao,
    'status', t.status, 'data_agendada', t.data_agendada, 'hora_agendada', t.hora_agendada,
    'content_card_id', t.content_card_id
  ) ORDER BY t.data_agendada NULLS LAST, t.titulo), '[]'::JSONB)
  INTO v_tasks FROM emp_garbo.marketing_tasks t;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', a.id, 'nome', a.nome, 'slug', a.slug, 'ativo', COALESCE(a.ativo, TRUE)
  ) ORDER BY a.ordem, a.nome), '[]'::JSONB)
  INTO v_agents FROM emp_garbo.marketing_ai_agents a;

  RETURN jsonb_build_object(
    'colunas', COALESCE(v_cols, '[]'::JSONB),
    'cards', COALESCE(v_cards, '[]'::JSONB),
    'pastas', COALESCE(v_folders, '[]'::JSONB),
    'sem_pasta', (SELECT COUNT(*)::INT FROM emp_garbo.marketing_medias WHERE folder_id IS NULL),
    'total_midias', (SELECT COUNT(*)::INT FROM emp_garbo.marketing_medias),
    'nodes', COALESCE(v_nodes, '[]'::JSONB),
    'tarefas', COALESCE(v_tasks, '[]'::JSONB),
    'agentes', COALESCE(v_agents, '[]'::JSONB)
  );
END;
$$;


