--
-- Name: movelaria_crm_mover_lead(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_mover_lead(p_lead_id bigint, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.movelaria_crm_pode_pipeline() THEN
    RAISE EXCEPTION 'Acesso negado ao pipeline comercial';
  END IF;
  IF p_lead_id IS NULL OR NULLIF(BTRIM(p_status), '') IS NULL THEN
    RAISE EXCEPTION 'Lead e etapa são obrigatórios';
  END IF;

  UPDATE emp_garbo.leads
  SET status = BTRIM(p_status),
      atualizado_em = NOW()
  WHERE id = p_lead_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lead não encontrado';
  END IF;
END;
$$;


--
-- Name: movelaria_crm_notificacao_ler(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_notificacao_ler(p_id uuid, p_todas boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.movelaria_crm_pode_comunicacao() THEN
    RAISE EXCEPTION 'Acesso negado às notificações do CRM';
  END IF;
  IF COALESCE(p_todas, FALSE) THEN
    UPDATE emp_garbo.notifications SET read = TRUE
    WHERE user_id = auth.uid() AND read = FALSE;
  ELSE
    IF p_id IS NULL THEN RAISE EXCEPTION 'Informe a notificação'; END IF;
    UPDATE emp_garbo.notifications SET read = TRUE
    WHERE id = p_id AND user_id = auth.uid();
  END IF;
  RETURN jsonb_build_object('ok', TRUE);
END;
$$;


--
-- Name: movelaria_crm_notificacoes(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_notificacoes(p_limit integer DEFAULT 40, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_items JSONB;
  v_unread INT;
  v_total INT;
  v_lim INT := GREATEST(1, LEAST(COALESCE(p_limit, 40), 80));
  v_off INT := GREATEST(0, COALESCE(p_offset, 0));
BEGIN
  IF NOT public.movelaria_crm_pode_comunicacao() THEN
    RAISE EXCEPTION 'Acesso negado às notificações do CRM';
  END IF;

  SELECT COUNT(*)::INT, COUNT(*) FILTER (WHERE n.read = FALSE)::INT
  INTO v_total, v_unread
  FROM emp_garbo.notifications n
  WHERE n.user_id = auth.uid();

  SELECT COALESCE(jsonb_agg(row_to_json(x)), '[]'::JSONB)
  INTO v_items
  FROM (
    SELECT n.id, n.lead_id, n.vendor_name, n.notification_type, n.message, n.read, n.created_at
    FROM emp_garbo.notifications n
    WHERE n.user_id = auth.uid()
    ORDER BY n.created_at DESC
    LIMIT v_lim OFFSET v_off
  ) x;

  RETURN jsonb_build_object(
    'items', COALESCE(v_items, '[]'::JSONB),
    'total', v_total,
    'nao_lidas', v_unread
  );
END;
$$;


--
-- Name: movelaria_crm_pipeline_boot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_pipeline_boot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stages JSONB;
  v_pages  JSONB;
  v_leads  JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_pipeline() THEN
    RAISE EXCEPTION 'Acesso negado ao pipeline comercial';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'nome', s.nome,
    'ordem', s.ordem
  ) ORDER BY s.ordem, s.nome), '[]'::JSONB)
  INTO v_stages
  FROM emp_garbo.pipeline_custom_stages s
  WHERE s.ativo IS TRUE;

  SELECT COALESCE(jsonb_agg(pagina ORDER BY (pagina->>'ordem')::INT, pagina->>'nome'), '[]'::JSONB)
  INTO v_pages
  FROM (
    SELECT jsonb_build_object(
      'id', p.id,
      'nome', p.nome,
      'slug', p.slug,
      'ordem', p.ordem,
      'colunas', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', c.id,
          'nome', c.nome,
          'ordem', c.ordem,
          'fontes', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
              'tipo', f.tipo_fonte,
              'valor', f.valor_fonte,
              'ativo', f.ativo
            ))
            FROM emp_garbo.kanban_column_sources f
            WHERE f.coluna_id = c.id
          ), '[]'::JSONB),
          'overrides', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
              'leadId', o.lead_id,
              'acao', o.acao
            ))
            FROM emp_garbo.kanban_card_overrides o
            WHERE o.coluna_id = c.id AND o.ativo IS TRUE
          ), '[]'::JSONB)
        ) ORDER BY c.ordem, c.nome)
        FROM emp_garbo.kanban_columns c
        WHERE c.pagina_id = p.id AND c.ativo IS TRUE
      ), '[]'::JSONB)
    ) AS pagina
    FROM emp_garbo.kanban_pages p
    WHERE p.ativo IS TRUE
  ) q;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', l.id,
    'nome', l.nome,
    'telefone', l.telefone,
    'email', l.email,
    'origem', l.origem,
    'status', l.status,
    'valorNegocio', l.valor_negocio,
    'valorOrcamento', l.valor_orcamento,
    'dataChegada', l.data_chegada,
    'vendedorId', l.vendedor_responsavel_id,
    'vendedorNome', v.nome,
    'darAtencao', COALESCE(l.dar_atencao, FALSE),
    'observacoes', l.observacoes
  ) ORDER BY l.data_chegada DESC, l.id DESC), '[]'::JSONB)
  INTO v_leads
  FROM emp_garbo.leads l
  LEFT JOIN emp_garbo.usuarios v ON v.id = l.vendedor_responsavel_id;

  RETURN jsonb_build_object(
    'etapas', v_stages,
    'quadros', v_pages,
    'leads', v_leads
  );
END;
$$;


