--
-- Name: movelaria_crm_pontua_admin_boot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_pontua_admin_boot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prest JSONB;
  v_saques JSONB;
  v_libs JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_pontua_fin() THEN
    RAISE EXCEPTION 'Acesso negado ao financeiro Pontua';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', u.id, 'nome', u.nome, 'email', u.email, 'titulo', COALESCE(u.titulo, 'Prestador de Serviço'),
    'telefone', u.telefone
  ) ORDER BY u.nome), '[]'::JSONB)
  INTO v_prest
  FROM emp_garbo.usuarios u
  WHERE u.tipo_usuario = 'prestador_servico' AND u.status_convite = 'ATIVO';

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', s.id,
    'prestador_id', s.prestador_id,
    'valor_solicitado', s.valor_solicitado,
    'chave_pix', s.chave_pix,
    'tipo_chave_pix', s.tipo_chave_pix,
    'status', s.status,
    'criado_em', s.criado_em,
    'processado_em', s.processado_em
  ) ORDER BY s.criado_em DESC), '[]'::JSONB)
  INTO v_saques
  FROM emp_garbo.prestador_saque_pedidos s;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', l.id, 'lead_id', l.lead_id, 'prestador_id', l.prestador_id, 'status', l.status, 'field_id', l.field_id
  ) ORDER BY l.criado_em DESC NULLS LAST), '[]'::JSONB)
  INTO v_libs
  FROM emp_garbo.pontua_garbo_comissao_liberacoes l
  WHERE l.status = 'aguardando_liberacao';

  RETURN jsonb_build_object(
    'prestadores', COALESCE(v_prest, '[]'::JSONB),
    'saques', COALESCE(v_saques, '[]'::JSONB),
    'liberacoes', COALESCE(v_libs, '[]'::JSONB)
  );
END;
$$;


--
-- Name: movelaria_crm_pontua_aprovar_saque(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_pontua_aprovar_saque(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row emp_garbo.prestador_saque_pedidos%ROWTYPE;
BEGIN
  IF NOT (public.movelaria_crm_colaborador_roles() && ARRAY['admin']::TEXT[]) THEN
    RAISE EXCEPTION 'Só o admin do CRM aprova saque';
  END IF;
  SELECT * INTO v_row FROM emp_garbo.prestador_saque_pedidos WHERE id = p_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Pedido não encontrado'; END IF;
  IF v_row.status IS DISTINCT FROM 'pendente' THEN RAISE EXCEPTION 'Pedido já processado'; END IF;

  INSERT INTO emp_garbo.pontua_garbo_lancamentos (prestador_id, tipo, valor, descricao, criado_por, saque_pedido_id)
  VALUES (v_row.prestador_id, 'saque', v_row.valor_solicitado,
          'Retirada PIX: ' || COALESCE(v_row.chave_pix, ''), auth.uid(), v_row.id);

  UPDATE emp_garbo.prestador_saque_pedidos
  SET status = 'aprovado', processado_em = NOW(), processado_por = auth.uid()
  WHERE id = p_id;

  RETURN jsonb_build_object('ok', TRUE);
END;
$$;


--
-- Name: movelaria_crm_pontua_liberar_comissao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_pontua_liberar_comissao(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (public.movelaria_crm_colaborador_roles() && ARRAY['admin']::TEXT[]) THEN
    RAISE EXCEPTION 'Só o admin do CRM libera comissão';
  END IF;
  UPDATE emp_garbo.pontua_garbo_comissao_liberacoes
  SET status = 'liberada'
  WHERE id = p_id AND status = 'aguardando_liberacao';
  IF NOT FOUND THEN RAISE EXCEPTION 'Liberação não encontrada'; END IF;
  RETURN jsonb_build_object('ok', TRUE);
END;
$$;


--
-- Name: movelaria_crm_pontua_rejeitar_saque(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_pontua_rejeitar_saque(p_id uuid, p_obs text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (public.movelaria_crm_colaborador_roles() && ARRAY['admin']::TEXT[]) THEN
    RAISE EXCEPTION 'Só o admin do CRM rejeita saque';
  END IF;
  UPDATE emp_garbo.prestador_saque_pedidos
  SET status = 'rejeitado', obs_admin = NULLIF(btrim(p_obs), ''), processado_em = NOW(), processado_por = auth.uid()
  WHERE id = p_id AND status = 'pendente';
  IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado ou já processado'; END IF;
  RETURN jsonb_build_object('ok', TRUE);
END;
$$;


--
-- Name: movelaria_crm_portal_boot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_portal_boot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid          UUID := auth.uid();
  v_perfil       JSONB;
  v_leads        JSONB;
  v_permissoes   JSONB;
  v_lancamentos  JSONB;
  v_saques       JSONB;
  v_titulos      JSONB;
  v_defs         JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_prestador() THEN
    RAISE EXCEPTION 'Acesso negado ao portal do parceiro';
  END IF;

  SELECT jsonb_build_object(
    'id', c.id,
    'nome', c.nome,
    'email', c.email,
    'telefone', c.telefone,
    'avatar_url', c.avatar_url,
    'titulo', COALESCE(c.titulo, 'Prestador de Serviço'),
    'comissao_ativa', COALESCE(c.comissao_ativa, FALSE),
    'chave_pix', c.chave_pix,
    'tipo_chave_pix', COALESCE(c.tipo_chave_pix, 'cpf')
  )
  INTO v_perfil
  FROM emp_garbo.usuarios c
  WHERE c.id = v_uid;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', d.id,
    'nome', d.nome,
    'ativo', d.ativo,
    'config_pontua_garbo', COALESCE(d.config_pontua_garbo, '{}'::JSONB)
  ) ORDER BY d.ordem, d.nome), '[]'::JSONB)
  INTO v_defs
  FROM emp_garbo.lead_custom_field_definitions d
  WHERE d.tipo = 'usuario_sistema';

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'lead_id', l.id,
    'lead_nome', l.nome,
    'lead_status', l.status,
    'valor_orcamento', COALESCE(l.valor_orcamento, 0),
    'valor_negocio', COALESCE(l.valor_negocio, 0),
    'field_id', v.field_id,
    'field_nome', d.nome,
    'percentual', COALESCE(v.pontua_garbo_percentual, NULLIF((d.config_pontua_garbo->>'percentual_padrao')::NUMERIC, 0), 5),
    'venda_realizada_em', l.venda_realizada_em,
    'data_chegada', l.data_chegada,
    'criado_em', l.criado_em,
    'lead_email', l.email,
    'lead_telefone', l.telefone,
    'lead_empresa', l.empresa,
    'lead_origem', l.origem,
    'lead_regiao', l.regiao,
    'liberacao_id', lib.id,
    'liberacao_status', lib.status
  ) ORDER BY COALESCE(l.venda_realizada_em, l.criado_em) DESC NULLS LAST), '[]'::JSONB)
  INTO v_leads
  FROM emp_garbo.lead_custom_field_values v
  JOIN emp_garbo.lead_custom_field_definitions d ON d.id = v.field_id
  JOIN emp_garbo.leads l ON l.id = v.lead_id
  LEFT JOIN emp_garbo.pontua_garbo_comissao_liberacoes lib
    ON lib.lead_id = v.lead_id
   AND lib.field_id = v.field_id
   AND lib.prestador_id = v_uid
  WHERE v.valor = v_uid::TEXT
    AND d.tipo = 'usuario_sistema'
    AND COALESCE(d.ativo, TRUE);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'lead_id', p.lead_id,
    'prestador_id', p.prestador_id,
    'pode_ver_detalhes', COALESCE(p.pode_ver_detalhes, FALSE),
    'pode_ver_lousa', COALESCE(p.pode_ver_lousa, FALSE),
    'pode_ver_anotacoes', COALESCE(p.pode_ver_anotacoes, FALSE),
    'pode_ver_anexos', COALESCE(p.pode_ver_anexos, FALSE),
    'pode_ver_fotos', COALESCE(p.pode_ver_fotos, FALSE),
    'pode_ver_pdfs', COALESCE(p.pode_ver_pdfs, FALSE),
    'anexos_visiveis', p.anexos_visiveis,
    'pode_ver_orcamento', COALESCE(p.pode_ver_orcamento, FALSE),
    'orcamentos_visiveis', p.orcamentos_visiveis
  )), '[]'::JSONB)
  INTO v_permissoes
  FROM emp_garbo.lead_prestador_permissoes p
  WHERE p.prestador_id = v_uid;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', x.id, 'tipo', x.tipo, 'valor', x.valor, 'descricao', x.descricao, 'criado_em', x.criado_em
  ) ORDER BY x.criado_em DESC), '[]'::JSONB)
  INTO v_lancamentos
  FROM emp_garbo.pontua_garbo_lancamentos x
  WHERE x.prestador_id = v_uid;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', s.id,
    'valor_solicitado', s.valor_solicitado,
    'chave_pix', s.chave_pix,
    'tipo_chave_pix', s.tipo_chave_pix,
    'status', s.status,
    'obs_admin', s.obs_admin,
    'criado_em', s.criado_em,
    'processado_em', s.processado_em
  ) ORDER BY s.criado_em DESC), '[]'::JSONB)
  INTO v_saques
  FROM emp_garbo.prestador_saque_pedidos s
  WHERE s.prestador_id = v_uid;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', t.id, 'nome', t.nome) ORDER BY t.nome), '[]'::JSONB)
  INTO v_titulos
  FROM emp_garbo.prestador_titulos t;

  RETURN jsonb_build_object(
    'perfil', v_perfil,
    'defs', COALESCE(v_defs, '[]'::JSONB),
    'leads', COALESCE(v_leads, '[]'::JSONB),
    'permissoes', COALESCE(v_permissoes, '[]'::JSONB),
    'lancamentos', COALESCE(v_lancamentos, '[]'::JSONB),
    'saques', COALESCE(v_saques, '[]'::JSONB),
    'titulos', COALESCE(v_titulos, '[]'::JSONB)
  );
END;
$$;


--
-- Name: movelaria_crm_portal_lead(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_portal_lead(p_lead_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_perm emp_garbo.lead_prestador_permissoes%ROWTYPE;
  v_lead JSONB;
  v_lousa_images JSONB;
  v_lousa_drawings JSONB;
  v_slides JSONB;
  v_aberto BOOLEAN;
BEGIN
  IF NOT public.movelaria_crm_pode_prestador() THEN
    RAISE EXCEPTION 'Acesso negado ao portal do parceiro';
  END IF;
  IF p_lead_id IS NULL THEN RAISE EXCEPTION 'Lead inválido'; END IF;

  SELECT * INTO v_perm
  FROM emp_garbo.lead_prestador_permissoes
  WHERE lead_id = p_lead_id AND prestador_id = v_uid;

  v_aberto := COALESCE(v_perm.pode_ver_detalhes, FALSE)
    OR COALESCE(v_perm.pode_ver_lousa, FALSE)
    OR COALESCE(v_perm.pode_ver_fotos, FALSE)
    OR COALESCE(v_perm.pode_ver_pdfs, FALSE)
    OR COALESCE(v_perm.pode_ver_anexos, FALSE)
    OR COALESCE(v_perm.pode_ver_orcamento, FALSE);

  IF NOT v_aberto THEN
    RAISE EXCEPTION 'Visualização não liberada para este lead';
  END IF;

  IF COALESCE(v_perm.pode_ver_detalhes, FALSE) THEN
    SELECT jsonb_build_object(
      'id', l.id,
      'nome', l.nome,
      'empresa', l.empresa,
      'email', l.email,
      'telefone', l.telefone,
      'origem', l.origem,
      'status', l.status,
      'valor_orcamento', COALESCE(l.valor_orcamento, 0),
      'valor_negocio', COALESCE(l.valor_negocio, 0),
      'data_chegada', l.data_chegada,
      'regiao', l.regiao,
      'observacoes', CASE WHEN COALESCE(v_perm.pode_ver_anotacoes, FALSE) THEN l.observacoes ELSE NULL END
    )
    INTO v_lead
    FROM emp_garbo.leads l
    WHERE l.id = p_lead_id;
  ELSE
    SELECT jsonb_build_object('id', l.id, 'nome', l.nome, 'status', l.status)
    INTO v_lead
    FROM emp_garbo.leads l
    WHERE l.id = p_lead_id;
  END IF;

  IF COALESCE(v_perm.pode_ver_lousa, FALSE) OR COALESCE(v_perm.pode_ver_fotos, FALSE) THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', i.id, 'file_url', i.file_url, 'file_name', i.file_name,
      'position_x', i.position_x, 'position_y', i.position_y,
      'width', i.width, 'height', i.height, 'z_index', i.z_index
    ) ORDER BY i.z_index, i.criado_em), '[]'::JSONB)
    INTO v_lousa_images
    FROM emp_garbo.lead_whiteboard_images i
    WHERE i.lead_id = p_lead_id;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', d.id, 'path_data', d.path_data, 'cor', d.cor, 'stroke_width', d.stroke_width
    ) ORDER BY d.criado_em), '[]'::JSONB)
    INTO v_lousa_drawings
    FROM emp_garbo.lead_whiteboard_drawings d
    WHERE d.lead_id = p_lead_id;
  ELSE
    v_lousa_images := '[]'::JSONB;
    v_lousa_drawings := '[]'::JSONB;
  END IF;

  IF COALESCE(v_perm.pode_ver_orcamento, FALSE) THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', s.id,
      'identificador', s.identificador,
      'cliente_nome', s.cliente_nome,
      'status', s.status
    ) ORDER BY s.atualizado_em DESC NULLS LAST), '[]'::JSONB)
    INTO v_slides
    FROM emp_garbo.orcamento_slides s
    WHERE s.lead_id = p_lead_id
      AND (
        v_perm.orcamentos_visiveis IS NULL
        OR s.id = ANY (v_perm.orcamentos_visiveis)
      );
  ELSE
    v_slides := '[]'::JSONB;
  END IF;

  RETURN jsonb_build_object(
    'lead', v_lead,
    'pode_ver_detalhes', COALESCE(v_perm.pode_ver_detalhes, FALSE),
    'pode_ver_lousa', COALESCE(v_perm.pode_ver_lousa, FALSE),
    'pode_ver_anotacoes', COALESCE(v_perm.pode_ver_anotacoes, FALSE),
    'pode_ver_fotos', COALESCE(v_perm.pode_ver_fotos, FALSE),
    'pode_ver_pdfs', COALESCE(v_perm.pode_ver_pdfs, FALSE),
    'pode_ver_orcamento', COALESCE(v_perm.pode_ver_orcamento, FALSE),
    'lousa_images', COALESCE(v_lousa_images, '[]'::JSONB),
    'lousa_drawings', COALESCE(v_lousa_drawings, '[]'::JSONB),
    'slides', COALESCE(v_slides, '[]'::JSONB)
  );
END;
$$;


--
-- Name: movelaria_crm_portal_saldo_sacar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_portal_saldo_sacar(p_uid uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_liberado NUMERIC := 0;
  v_ajustes  NUMERIC := 0;
  v_saques   NUMERIC := 0;
BEGIN
  IF p_uid IS DISTINCT FROM auth.uid() OR NOT public.movelaria_crm_pode_prestador() THEN
    RAISE EXCEPTION 'Acesso negado ao portal do parceiro';
  END IF;

  SELECT COALESCE(SUM(
    (
      CASE
        WHEN public.movelaria_crm_portal_status_e_ganho(l.status)
          THEN COALESCE(NULLIF(l.valor_negocio, 0), COALESCE(l.valor_orcamento, 0), 0)
        ELSE COALESCE(l.valor_orcamento, 0)
      END
      * COALESCE(v.pontua_garbo_percentual, NULLIF((d.config_pontua_garbo->>'percentual_padrao')::NUMERIC, 0), 5)
      / 100.0
    )
  ), 0)
  INTO v_liberado
  FROM emp_garbo.lead_custom_field_values v
  JOIN emp_garbo.lead_custom_field_definitions d ON d.id = v.field_id
  JOIN emp_garbo.leads l ON l.id = v.lead_id
  JOIN emp_garbo.pontua_garbo_comissao_liberacoes lib
    ON lib.lead_id = v.lead_id
   AND lib.field_id = v.field_id
   AND lib.prestador_id = p_uid
   AND lib.status = 'liberada'
  WHERE v.valor = p_uid::TEXT
    AND d.tipo = 'usuario_sistema'
    AND COALESCE(d.ativo, TRUE)
    AND COALESCE((d.config_pontua_garbo->>'ativo')::BOOLEAN, TRUE)
    AND public.movelaria_crm_portal_status_e_ganho(l.status);

  SELECT COALESCE(SUM(CASE WHEN tipo = 'ajuste' THEN valor ELSE 0 END), 0),
         COALESCE(SUM(CASE WHEN tipo = 'saque' THEN valor ELSE 0 END), 0)
  INTO v_ajustes, v_saques
  FROM emp_garbo.pontua_garbo_lancamentos
  WHERE prestador_id = p_uid;

  RETURN GREATEST(0, ROUND((v_liberado + v_ajustes - v_saques)::NUMERIC, 2));
END;
$$;


--
-- Name: movelaria_crm_portal_salvar_perfil(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_portal_salvar_perfil(p_telefone text, p_chave_pix text, p_tipo_chave_pix text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_tipo TEXT;
BEGIN
  IF NOT public.movelaria_crm_pode_prestador() THEN
    RAISE EXCEPTION 'Acesso negado ao portal do parceiro';
  END IF;
  v_tipo := COALESCE(NULLIF(btrim(p_tipo_chave_pix), ''), 'cpf');
  IF v_tipo NOT IN ('cpf', 'cnpj', 'email', 'telefone', 'aleatoria') THEN
    RAISE EXCEPTION 'Tipo de chave PIX inválido';
  END IF;

  UPDATE emp_garbo.usuarios
  SET telefone = NULLIF(btrim(p_telefone), ''),
      chave_pix = NULLIF(btrim(p_chave_pix), ''),
      tipo_chave_pix = v_tipo,
      atualizado_em = NOW()
  WHERE id = v_uid;

  RETURN jsonb_build_object('ok', TRUE);
END;
$$;


--
-- Name: movelaria_crm_portal_solicitar_saque(numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_portal_solicitar_saque(p_valor numeric, p_chave_pix text, p_tipo_chave_pix text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_tipo TEXT;
  v_chave TEXT;
  v_valor NUMERIC;
  v_saldo NUMERIC;
  v_pendente NUMERIC;
  v_disponivel NUMERIC;
  v_id UUID;
BEGIN
  IF NOT public.movelaria_crm_pode_prestador() THEN
    RAISE EXCEPTION 'Acesso negado ao portal do parceiro';
  END IF;

  v_chave := NULLIF(btrim(p_chave_pix), '');
  IF v_chave IS NULL THEN RAISE EXCEPTION 'Informe a chave PIX'; END IF;
  v_tipo := COALESCE(NULLIF(btrim(p_tipo_chave_pix), ''), 'cpf');
  IF v_tipo NOT IN ('cpf', 'cnpj', 'email', 'telefone', 'aleatoria') THEN
    RAISE EXCEPTION 'Tipo de chave PIX inválido';
  END IF;
  v_valor := ROUND(COALESCE(p_valor, 0), 2);
  IF v_valor <= 0 THEN RAISE EXCEPTION 'Informe um valor válido maior que zero.'; END IF;

  v_saldo := public.movelaria_crm_portal_saldo_sacar(v_uid);
  SELECT COALESCE(SUM(valor_solicitado), 0) INTO v_pendente
  FROM emp_garbo.prestador_saque_pedidos
  WHERE prestador_id = v_uid AND status = 'pendente';
  v_disponivel := GREATEST(0, ROUND((v_saldo - v_pendente)::NUMERIC, 2));

  IF v_valor > v_disponivel THEN
    RAISE EXCEPTION 'Saldo insuficiente. Disponível para sacar: %', v_disponivel;
  END IF;

  INSERT INTO emp_garbo.prestador_saque_pedidos (
    prestador_id, valor_solicitado, chave_pix, tipo_chave_pix, status
  ) VALUES (
    v_uid, v_valor, v_chave, v_tipo, 'pendente'
  )
  RETURNING id INTO v_id;

  UPDATE emp_garbo.usuarios
  SET chave_pix = v_chave, tipo_chave_pix = v_tipo, atualizado_em = NOW()
  WHERE id = v_uid;

  RETURN jsonb_build_object('id', v_id, 'status', 'pendente');
END;
$$;


--
-- Name: movelaria_crm_portal_status_e_ganho(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_portal_status_e_ganho(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_status IS NULL OR btrim(p_status) = '' THEN FALSE
    WHEN p_status ILIKE '%perdid%' THEN FALSE
    WHEN p_status ILIKE '%venda realizada%' THEN TRUE
    WHEN p_status ILIKE '%ganh%' THEN TRUE
    ELSE FALSE
  END;
$$;


--
-- Name: movelaria_crm_salvar_lead(bigint, text, text, text, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_salvar_lead(p_lead_id bigint, p_nome text, p_telefone text, p_email text, p_origem text, p_observacoes text, p_valor_negocio numeric, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.movelaria_crm_pode_pipeline() THEN
    RAISE EXCEPTION 'Acesso negado ao pipeline comercial';
  END IF;
  IF p_lead_id IS NULL OR NULLIF(BTRIM(p_nome), '') IS NULL THEN
    RAISE EXCEPTION 'Nome do lead é obrigatório';
  END IF;

  UPDATE emp_garbo.leads
  SET nome = BTRIM(p_nome),
      telefone = NULLIF(BTRIM(p_telefone), ''),
      email = NULLIF(BTRIM(p_email), ''),
      origem = NULLIF(BTRIM(p_origem), ''),
      observacoes = NULLIF(BTRIM(p_observacoes), ''),
      valor_negocio = COALESCE(p_valor_negocio, 0),
      status = COALESCE(NULLIF(BTRIM(p_status), ''), status),
      atualizado_em = NOW()
  WHERE id = p_lead_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lead não encontrado';
  END IF;
END;
$$;


--
-- Name: movelaria_crm_slide_criar(text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_slide_criar(p_cliente_nome text, p_lead_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id    UUID;
  v_ident TEXT;
  v_nome  TEXT;
  v_row   JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_slides() THEN
    RAISE EXCEPTION 'Acesso negado aos slides de orçamento';
  END IF;

  IF p_lead_id IS NOT NULL THEN
    SELECT nome INTO v_nome FROM emp_garbo.leads WHERE id = p_lead_id;
  END IF;

  v_nome := COALESCE(NULLIF(BTRIM(p_cliente_nome), ''), NULLIF(BTRIM(v_nome), ''), 'Cliente');
  v_ident := 'RASC-' || upper(regexp_replace(v_nome, '[^a-zA-Z0-9]+', '-', 'g'))
    || '-' || substr(replace(gen_random_uuid()::TEXT, '-', ''), 1, 4);

  INSERT INTO emp_garbo.orcamento_slides (
    identificador, lead_id, cliente_nome, status, dados, criado_por
  ) VALUES (
    v_ident,
    p_lead_id,
    v_nome,
    'rascunho',
    jsonb_build_object(
      '_meta', jsonb_build_object('etapa', 1),
      'precificacao', jsonb_build_object('valor_final', 0, 'parcelas', 1)
    ),
    auth.uid()
  )
  RETURNING id INTO v_id;

  SELECT jsonb_build_object(
    'id', s.id,
    'identificador', s.identificador,
    'lead_id', s.lead_id,
    'cliente_nome', s.cliente_nome,
    'status', s.status,
    'dados', COALESCE(s.dados, '{}'::JSONB),
    'atualizado_em', s.atualizado_em
  )
  INTO v_row
  FROM emp_garbo.orcamento_slides s
  WHERE s.id = v_id;

  RETURN v_row;
END;
$$;


--
-- Name: movelaria_crm_slide_salvar(uuid, text, text, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_slide_salvar(p_id uuid, p_cliente_nome text, p_identificador text, p_lead_id bigint, p_status text, p_dados jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_slides() THEN
    RAISE EXCEPTION 'Acesso negado aos slides de orçamento';
  END IF;
  IF p_id IS NULL OR NULLIF(BTRIM(p_cliente_nome), '') IS NULL THEN
    RAISE EXCEPTION 'Nome do cliente é obrigatório';
  END IF;

  UPDATE emp_garbo.orcamento_slides
  SET cliente_nome = BTRIM(p_cliente_nome),
      identificador = COALESCE(NULLIF(BTRIM(p_identificador), ''), identificador),
      lead_id = p_lead_id,
      status = COALESCE(NULLIF(BTRIM(p_status), ''), status),
      dados = COALESCE(p_dados, dados),
      atualizado_em = NOW()
  WHERE id = p_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Orçamento não encontrado';
  END IF;

  SELECT jsonb_build_object(
    'id', s.id,
    'identificador', s.identificador,
    'lead_id', s.lead_id,
    'cliente_nome', s.cliente_nome,
    'status', s.status,
    'dados', COALESCE(s.dados, '{}'::JSONB),
    'atualizado_em', s.atualizado_em
  )
  INTO v_row
  FROM emp_garbo.orcamento_slides s
  WHERE s.id = p_id;

  RETURN v_row;
END;
$$;


--
-- Name: movelaria_crm_slides_boot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_slides_boot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_slides JSONB;
  v_leads  JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_slides() THEN
    RAISE EXCEPTION 'Acesso negado aos slides de orçamento';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', s.id,
    'identificador', s.identificador,
    'lead_id', s.lead_id,
    'lead_nome', l.nome,
    'cliente_nome', s.cliente_nome,
    'status', s.status,
    'dados', COALESCE(s.dados, '{}'::JSONB),
    'criado_em', s.criado_em,
    'atualizado_em', s.atualizado_em
  ) ORDER BY s.atualizado_em DESC NULLS LAST), '[]'::JSONB)
  INTO v_slides
  FROM emp_garbo.orcamento_slides s
  LEFT JOIN emp_garbo.leads l ON l.id = s.lead_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', l.id,
    'nome', l.nome
  ) ORDER BY l.nome), '[]'::JSONB)
  INTO v_leads
  FROM emp_garbo.leads l;

  RETURN jsonb_build_object(
    'slides', COALESCE(v_slides, '[]'::JSONB),
    'leads', COALESCE(v_leads, '[]'::JSONB)
  );
END;
$$;


--
-- Name: movelaria_crm_whatsapp_historico(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_whatsapp_historico(p_telefone text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_digits TEXT := regexp_replace(COALESCE(p_telefone, ''), '\D', '', 'g');
  v_items JSONB;
BEGIN
  IF NOT public.movelaria_crm_pode_pipeline() THEN
    RAISE EXCEPTION 'Acesso negado ao WhatsApp do lead';
  END IF;
  IF v_digits IS NULL OR length(v_digits) < 8 THEN
    RETURN jsonb_build_object('items', '[]'::JSONB);
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(x) ORDER BY x.criado_em), '[]'::JSONB)
  INTO v_items
  FROM (
    SELECT m.id, m.telefone, m.tipo_remetente, m.tipo_mensagem, m.conteudo,
           m.url_midia, m.origem, m.criado_em
    FROM emp_garbo.chat_mensagens m
    WHERE regexp_replace(m.telefone, '\D', '', 'g') = v_digits
       OR regexp_replace(m.telefone, '\D', '', 'g') = ('55' || v_digits)
       OR ('55' || regexp_replace(m.telefone, '\D', '', 'g')) = v_digits
    ORDER BY m.criado_em DESC
    LIMIT 80
  ) x;

  RETURN jsonb_build_object('items', COALESCE(v_items, '[]'::JSONB));
END;
$$;


--
-- Name: movelaria_crm_whatsapp_registrar(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_crm_whatsapp_registrar(p_telefone text, p_conteudo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_digits TEXT := regexp_replace(COALESCE(p_telefone, ''), '\D', '', 'g');
  v_id UUID;
BEGIN
  IF NOT public.movelaria_crm_pode_venda() THEN
    RAISE EXCEPTION 'Acesso negado para enviar WhatsApp';
  END IF;
  IF v_digits IS NULL OR length(v_digits) < 8 THEN RAISE EXCEPTION 'Informe o telefone'; END IF;
  IF NULLIF(btrim(p_conteudo), '') IS NULL THEN RAISE EXCEPTION 'Escreva a mensagem'; END IF;

  INSERT INTO emp_garbo.chat_mensagens (
    telefone, tipo_remetente, usuario_id, tipo_mensagem, conteudo, origem, enviada, lida
  ) VALUES (
    v_digits, 'atendente', auth.uid(), 'texto', btrim(p_conteudo), 'crm', TRUE, TRUE
  ) RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id);
END;
$$;


--
-- Name: movelaria_dia_admissao_to_isodow(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_dia_admissao_to_isodow(p_dia text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE lower(trim(COALESCE(p_dia, '')))
    WHEN 'segunda' THEN 1
    WHEN 'terca' THEN 2
    WHEN 'quarta' THEN 3
    WHEN 'quinta' THEN 4
    WHEN 'sexta' THEN 5
    WHEN 'sabado' THEN 6
    WHEN 'domingo' THEN 7
    ELSE NULL
  END;
$$;


--
-- Name: movelaria_excluir_lead_ganho(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_excluir_lead_ganho(p_lead_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
DECLARE
  v_lead_id TEXT := NULLIF(trim(COALESCE(p_lead_id, '')), '');
BEGIN
  IF v_lead_id IS NULL THEN
    RAISE EXCEPTION 'Lead inválido para exclusão.';
  END IF;

  INSERT INTO movelaria_leads_ganhos_excluidos (lead_id)
  VALUES (v_lead_id)
  ON CONFLICT (lead_id) DO NOTHING;
END;
$$;


--
-- Name: movelaria_excluir_linha_caixa(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_excluir_linha_caixa(p_destinatario_id text, p_destinatario_nome text, p_mes integer, p_ano integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_perfil          TEXT;
  v_nome_key        TEXT;
  v_dest_uuid       UUID;
  v_start           DATE;
  v_end             DATE;
  v_mov_apagadas    INTEGER := 0;
  v_cp_apagadas     INTEGER := 0;
  v_is_virtual      BOOLEAN;
BEGIN
  v_perfil := movelaria_meu_perfil();
  IF v_perfil IS DISTINCT FROM 'administrador'
     AND v_perfil IS DISTINCT FROM 'financeiro' THEN
    RAISE EXCEPTION 'Acesso negado: somente administrador ou financeiro podem excluir do Caixa.';
  END IF;

  IF p_mes IS NULL OR p_mes < 1 OR p_mes > 12 OR p_ano IS NULL OR p_ano < 2000 THEN
    RAISE EXCEPTION 'Mês/ano inválidos.';
  END IF;

  v_nome_key := lower(trim(COALESCE(p_destinatario_nome, '')));
  IF v_nome_key = '' THEN
    RAISE EXCEPTION 'Destinatário inválido.';
  END IF;

  v_is_virtual := COALESCE(p_destinatario_id, '') LIKE '__virtual__:%';
  v_start := make_date(p_ano, p_mes, 1);
  v_end   := (v_start + INTERVAL '1 month' - INTERVAL '1 day')::DATE;

  IF NOT v_is_virtual THEN
    BEGIN
      v_dest_uuid := p_destinatario_id::UUID;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'Destinatário inválido.';
    END;

    DELETE FROM movelaria_caixa_movimentacoes
    WHERE destinatario_id = v_dest_uuid
      AND mes_referencia = p_mes
      AND ano_referencia = p_ano;
    GET DIAGNOSTICS v_mov_apagadas = ROW_COUNT;
  END IF;

  WITH alvo AS (
    SELECT cp.id
    FROM movelaria_contas_pagar cp
    WHERE cp.data_vencimento >= v_start
      AND cp.data_vencimento <= v_end
      AND lower(trim(COALESCE(cp.fornecedor_nome, ''))) = v_nome_key
  ),
  del AS (
    DELETE FROM movelaria_contas_pagar cp
    USING alvo
    WHERE cp.id = alvo.id
    RETURNING cp.id
  )
  SELECT COUNT(*)::INTEGER INTO v_cp_apagadas FROM del;

  RETURN jsonb_build_object(
    'ok', true,
    'movimentacoes_apagadas', v_mov_apagadas,
    'contas_pagar_apagadas', v_cp_apagadas
  );
END;
$$;


--
-- Name: movelaria_excluir_movimentacao_caixa(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_excluir_movimentacao_caixa(p_movimentacao_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_perfil TEXT;
  v_count  INTEGER := 0;
BEGIN
  v_perfil := movelaria_meu_perfil();
  IF v_perfil IS DISTINCT FROM 'administrador'
     AND v_perfil IS DISTINCT FROM 'financeiro' THEN
    RAISE EXCEPTION 'Acesso negado: somente administrador ou financeiro podem excluir do Caixa.';
  END IF;

  IF p_movimentacao_id IS NULL THEN
    RAISE EXCEPTION 'Movimentação inválida.';
  END IF;

  DELETE FROM movelaria_caixa_movimentacoes
  WHERE id = p_movimentacao_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'Movimentação não encontrada.';
  END IF;

  RETURN jsonb_build_object('ok', true, 'movimentacoes_apagadas', v_count);
END;
$$;


--
-- Name: movelaria_excluir_usuario(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_excluir_usuario(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public'
    AS $$
BEGIN
  IF movelaria_meu_perfil() <> 'administrador' THEN
    RAISE EXCEPTION 'Acesso negado: somente administradores podem excluir usuários';
  END IF;
  IF p_id = auth.uid() THEN
    RAISE EXCEPTION 'Não é possível excluir o próprio usuário';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM movelaria_usuarios WHERE id = p_id) THEN
    RAISE EXCEPTION 'Usuário não encontrado';
  END IF;

  -- Contas em aberto (fixo/comissão) saem de Contas a Pagar
  DELETE FROM movelaria_contas_pagar
  WHERE prestador_id = p_id
    AND status <> 'pago';

  -- Contas já pagas: desvincula, mantém o histórico financeiro
  UPDATE movelaria_contas_pagar
  SET prestador_id = NULL
  WHERE prestador_id = p_id;

  -- Pasta de funcionário: dispensa e solta o login (ponto permanece)
  UPDATE movelaria_funcionarios
  SET
    ativo = false,
    usuario_id = NULL,
    dispensado_em = COALESCE(dispensado_em, NOW()),
    atualizado_em = NOW()
  WHERE usuario_id = p_id;

  -- Remove o login (cascateia o perfil; ponto.usuario_id vira NULL)
  DELETE FROM auth.users WHERE id = p_id;
END;
$$;


--
-- Name: movelaria_expandir_fixo_funcionario(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_expandir_fixo_funcionario(p_funcionario_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_func_id               UUID := p_funcionario_id;
  v_usuario_id            UUID;
  v_valor                 NUMERIC(12, 2);
  v_recorrencia_id        UUID;
  v_nome                  TEXT;
  v_categoria             TEXT;
  v_primeiro_vencimento   DATE;
  v_horizonte             DATE;
  v_encerramento          DATE;
  v_cursor                DATE;
  v_prox                  DATE;
  v_ano                   INTEGER;
  v_mes                   INTEGER;
  v_descricao             TEXT;
BEGIN
  SELECT f.id,
         f.usuario_id,
         f.valor_fixo_mensal,
         f.fixo_recorrencia_id,
         f.fixo_primeiro_vencimento,
         COALESCE(NULLIF(TRIM(f.nome), ''), 'Funcionário'),
         COALESCE(f.categoria, 'outro')
  INTO v_func_id, v_usuario_id, v_valor, v_recorrencia_id, v_primeiro_vencimento, v_nome, v_categoria
  FROM movelaria_funcionarios f
  WHERE f.id = v_func_id
    AND f.ativo = true
    AND COALESCE(f.tipo, '') <> 'marceneiro';

  IF NOT FOUND OR COALESCE(v_valor, 0) <= 0 OR v_primeiro_vencimento IS NULL THEN
    RETURN;
  END IF;

  IF v_usuario_id IS NOT NULL AND movelaria_usuario_eh_montador(v_usuario_id) THEN
    UPDATE movelaria_usuarios u
    SET valor_fixo_mensal = v_valor,
        fixo_primeiro_vencimento = COALESCE(v_primeiro_vencimento, u.fixo_primeiro_vencimento),
        fixo_recorrencia_id = COALESCE(u.fixo_recorrencia_id, v_recorrencia_id),
        atualizado_em = NOW()
    WHERE u.id = v_usuario_id
      AND u.ativo = true;

    PERFORM movelaria_expandir_fixo_montador(v_usuario_id);

    SELECT u.fixo_recorrencia_id
    INTO v_recorrencia_id
    FROM movelaria_usuarios u
    WHERE u.id = v_usuario_id;

    IF v_recorrencia_id IS NOT NULL THEN
      UPDATE movelaria_funcionarios
      SET fixo_recorrencia_id = v_recorrencia_id,
          categoria = CASE
            WHEN tipo IN ('montador', 'montador_admin') THEN 'montador'
            ELSE categoria
          END,
          atualizado_em = NOW()
      WHERE id = v_func_id;

      UPDATE movelaria_contas_pagar
      SET prestador_id = COALESCE(prestador_id, v_usuario_id),
          atualizado_em = NOW()
      WHERE recorrencia_id = v_recorrencia_id
        AND status = 'pendente'
        AND prestador_id IS NULL;
    END IF;

    RETURN;
  END IF;

  v_descricao := movelaria_fixo_descricao(v_categoria, v_nome);
  v_horizonte := (CURRENT_DATE + INTERVAL '12 months')::DATE;
  v_encerramento := NULL;

  IF v_recorrencia_id IS NULL THEN
    SELECT cp.recorrencia_id
    INTO v_recorrencia_id
    FROM movelaria_contas_pagar cp
    WHERE cp.recorrencia_id IS NOT NULL
      AND (
        (v_usuario_id IS NOT NULL AND cp.prestador_id = v_usuario_id)
        OR (
          cp.prestador_id IS NULL
          AND LOWER(TRIM(COALESCE(cp.fornecedor_nome, ''))) = LOWER(TRIM(v_nome))
        )
      )
      AND (
        COALESCE(cp.descricao, '') LIKE 'Fixo montador:%'
        OR COALESCE(cp.descricao, '') LIKE 'Fixo:%'
      )
    ORDER BY cp.criado_em DESC
    LIMIT 1;

    IF v_recorrencia_id IS NULL THEN
      v_recorrencia_id := gen_random_uuid();
    END IF;

    UPDATE movelaria_funcionarios
    SET fixo_recorrencia_id = v_recorrencia_id,
        atualizado_em = NOW()
    WHERE id = v_func_id;
  END IF;

  SELECT MIN(cp.recorrencia_encerramento)
  INTO v_encerramento
  FROM movelaria_contas_pagar cp
  WHERE cp.recorrencia_id = v_recorrencia_id
    AND cp.recorrencia_encerramento IS NOT NULL;

  v_cursor := v_primeiro_vencimento;
  WHILE v_cursor <= v_horizonte LOOP
    v_ano := EXTRACT(YEAR FROM v_cursor)::INTEGER;
    v_mes := EXTRACT(MONTH FROM v_cursor)::INTEGER;

    IF v_encerramento IS NOT NULL AND v_cursor > v_encerramento THEN
      EXIT;
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM movelaria_contas_pagar cp
      WHERE cp.recorrencia_id = v_recorrencia_id
        AND EXTRACT(MONTH FROM cp.data_vencimento) = v_mes
        AND EXTRACT(YEAR FROM cp.data_vencimento) = v_ano
    ) THEN
      INSERT INTO movelaria_contas_pagar (
        prestador_id,
        fornecedor_nome,
        descricao,
        valor_total,
        numero_parcela,
        total_parcelas,
        valor_parcela,
        data_vencimento,
        status,
        recorrente,
        recorrencia_id,
        recorrencia_valor_base
      ) VALUES (
        v_usuario_id,
        v_nome,
        v_descricao,
        v_valor,
        1,
        1,
        v_valor,
        v_cursor,
        'pendente',
        true,
        v_recorrencia_id,
        v_valor
      );
    END IF;

    v_prox := (v_cursor + INTERVAL '1 month')::DATE;
    v_cursor := make_date(
      EXTRACT(YEAR FROM v_prox)::INTEGER,
      EXTRACT(MONTH FROM v_prox)::INTEGER,
      LEAST(
        EXTRACT(DAY FROM v_primeiro_vencimento)::INTEGER,
        EXTRACT(DAY FROM (date_trunc('month', v_prox) + INTERVAL '1 month - 1 day'))::INTEGER
      )
    );
  END LOOP;

  UPDATE movelaria_contas_pagar cp
  SET prestador_id = COALESCE(cp.prestador_id, v_usuario_id),
      fornecedor_nome = v_nome,
      descricao = v_descricao,
      valor_parcela = v_valor,
      valor_total = v_valor,
      recorrencia_valor_base = v_valor,
      atualizado_em = NOW()
  WHERE cp.recorrencia_id = v_recorrencia_id
    AND cp.status = 'pendente';
END;
$$;


--
-- Name: movelaria_expandir_fixo_montador(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_expandir_fixo_montador(p_montador_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_montador_id           UUID := COALESCE(p_montador_id, auth.uid());
  v_valor                 NUMERIC(12, 2);
  v_recorrencia_id        UUID;
  v_nome                  TEXT;
  v_primeiro_vencimento   DATE;
  v_horizonte             DATE;
  v_encerramento          DATE;
  v_cursor                DATE;
  v_prox                  DATE;
  v_ano                   INTEGER;
  v_mes                   INTEGER;
BEGIN
  SELECT u.valor_fixo_mensal,
         u.fixo_recorrencia_id,
         u.fixo_primeiro_vencimento,
         COALESCE(NULLIF(TRIM(u.nome), ''), split_part(u.email, '@', 1))
  INTO v_valor, v_recorrencia_id, v_primeiro_vencimento, v_nome
  FROM movelaria_usuarios u
  WHERE u.id = v_montador_id
    AND u.perfil IN ('montador', 'montador_admin')
    AND u.ativo = true;

  IF NOT FOUND OR COALESCE(v_valor, 0) <= 0 OR v_primeiro_vencimento IS NULL THEN
    RETURN;
  END IF;

  v_horizonte := (CURRENT_DATE + INTERVAL '12 months')::DATE;
  v_encerramento := NULL;

  IF v_recorrencia_id IS NULL THEN
    -- Tenta reaproveitar recorrência órfã pelo nome/descrição
    SELECT cp.recorrencia_id
    INTO v_recorrencia_id
    FROM movelaria_contas_pagar cp
    WHERE cp.recorrencia_id IS NOT NULL
      AND COALESCE(cp.descricao, '') LIKE 'Fixo montador:%'
      AND (
        cp.prestador_id = v_montador_id
        OR (
          cp.prestador_id IS NULL
          AND (
            LOWER(TRIM(COALESCE(cp.fornecedor_nome, ''))) = LOWER(TRIM(v_nome))
            OR LOWER(TRIM(COALESCE(cp.descricao, ''))) = LOWER('Fixo montador: ' || v_nome)
          )
        )
      )
    ORDER BY cp.data_vencimento ASC
    LIMIT 1;

    IF v_recorrencia_id IS NULL THEN
      v_recorrencia_id := gen_random_uuid();
    END IF;

    UPDATE movelaria_usuarios
    SET fixo_recorrencia_id = v_recorrencia_id,
        fixo_primeiro_vencimento = COALESCE(fixo_primeiro_vencimento, v_primeiro_vencimento),
        atualizado_em = NOW()
    WHERE id = v_montador_id;
  END IF;

  -- Religa cobranças da série que perderam o prestador_id
  UPDATE movelaria_contas_pagar cp
  SET prestador_id = v_montador_id,
      fornecedor_nome = COALESCE(NULLIF(TRIM(cp.fornecedor_nome), ''), v_nome),
      descricao = CASE
        WHEN COALESCE(cp.descricao, '') LIKE 'Fixo montador:%' THEN cp.descricao
        ELSE 'Fixo montador: ' || v_nome
      END,
      valor_parcela = CASE WHEN cp.status = 'pendente' THEN v_valor ELSE cp.valor_parcela END,
      valor_total = CASE WHEN cp.status = 'pendente' THEN v_valor ELSE cp.valor_total END,
      recorrencia_valor_base = v_valor,
      recorrencia_encerramento = NULL,
      atualizado_em = NOW()
  WHERE cp.recorrencia_id = v_recorrencia_id
    AND (cp.prestador_id IS NULL OR cp.prestador_id = v_montador_id);

  SELECT cp.recorrencia_encerramento
  INTO v_encerramento
  FROM movelaria_contas_pagar cp
  WHERE cp.recorrencia_id = v_recorrencia_id
  ORDER BY cp.data_vencimento ASC
  LIMIT 1;

  IF v_encerramento IS NOT NULL AND v_encerramento < v_horizonte THEN
    v_horizonte := v_encerramento;
  END IF;

  v_cursor := date_trunc('month', v_primeiro_vencimento)::DATE;

  WHILE v_cursor <= date_trunc('month', v_horizonte)::DATE LOOP
    v_ano := EXTRACT(YEAR FROM v_cursor)::INTEGER;
    v_mes := EXTRACT(MONTH FROM v_cursor)::INTEGER;
    v_prox := movelaria_fixo_vencimento_mes(v_primeiro_vencimento, v_ano, v_mes);

    IF v_prox >= v_primeiro_vencimento
       AND v_prox <= v_horizonte
       AND movelaria_fixo_mes_elegivel(v_primeiro_vencimento, v_mes, v_ano)
       AND NOT EXISTS (
         -- Já existe na série (mesmo com prestador_id nulo)
         SELECT 1
         FROM movelaria_contas_pagar cp
         WHERE cp.recorrencia_id = v_recorrencia_id
           AND EXTRACT(MONTH FROM cp.data_vencimento) = v_mes
           AND EXTRACT(YEAR  FROM cp.data_vencimento) = v_ano
       )
       AND NOT EXISTS (
         -- Já existe outra cobrança de fixo do mesmo montador no mês
         SELECT 1
         FROM movelaria_contas_pagar cp
         WHERE cp.prestador_id = v_montador_id
           AND COALESCE(cp.descricao, '') LIKE 'Fixo montador:%'
           AND EXTRACT(MONTH FROM cp.data_vencimento) = v_mes
           AND EXTRACT(YEAR  FROM cp.data_vencimento) = v_ano
       )
    THEN
      INSERT INTO movelaria_contas_pagar (
        prestador_id,
        fornecedor_nome,
        descricao,
        valor_total,
        numero_parcela,
        total_parcelas,
        valor_parcela,
        data_vencimento,
        status,
        recorrente,
        recorrencia_id,
        recorrencia_valor_base,
        recorrencia_encerramento
      ) VALUES (
        v_montador_id,
        v_nome,
        'Fixo montador: ' || v_nome,
        v_valor,
        1,
        1,
        v_valor,
        v_prox,
        'pendente',
        true,
        v_recorrencia_id,
        v_valor,
        v_encerramento
      );
    END IF;

    v_cursor := (v_cursor + INTERVAL '1 month')::DATE;
  END LOOP;
END;
$$;


--
-- Name: movelaria_expandir_todos_fixo_montadores(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_expandir_todos_fixo_montadores() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_perfil TEXT := movelaria_meu_perfil();
  r RECORD;
  v_count INTEGER := 0;
BEGIN
  IF v_perfil NOT IN ('administrador', 'administrador_obras', 'financeiro', 'montador_admin') THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  IF NOT pg_try_advisory_xact_lock(hashtext('movelaria_expandir_todos_fixo_montadores')) THEN
    RETURN 0;
  END IF;

  FOR r IN
    SELECT f.id
    FROM movelaria_funcionarios f
    WHERE f.ativo = true
      AND COALESCE(f.tipo, '') <> 'marceneiro'
      AND COALESCE(f.valor_fixo_mensal, 0) > 0
      AND f.fixo_primeiro_vencimento IS NOT NULL
  LOOP
    BEGIN
      PERFORM movelaria_expandir_fixo_funcionario(r.id);
      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Falha ao expandir fixo do funcionário %: %', r.id, SQLERRM;
    END;
  END LOOP;

  FOR r IN
    SELECT u.id
    FROM movelaria_usuarios u
    WHERE u.ativo
      AND COALESCE(u.valor_fixo_mensal, 0) > 0
      AND u.perfil IN ('montador', 'montador_admin')
      AND u.fixo_primeiro_vencimento IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM movelaria_funcionarios f
        WHERE f.usuario_id = u.id
          AND COALESCE(f.valor_fixo_mensal, 0) > 0
      )
  LOOP
    BEGIN
      PERFORM movelaria_expandir_fixo_montador(r.id);
      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Falha ao expandir fixo do usuário %: %', r.id, SQLERRM;
    END;
  END LOOP;

  RETURN v_count;
END;
$$;


