--
-- Name: movelaria_fixo_mes_elegivel(date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_fixo_mes_elegivel(p_primeiro_vencimento date, p_mes integer, p_ano integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  IF p_primeiro_vencimento IS NULL THEN
    RETURN FALSE;
  END IF;

  RETURN make_date(p_ano, p_mes, 1)
    >= date_trunc('month', p_primeiro_vencimento)::DATE;
END;
$$;


--
-- Name: movelaria_fixo_vencimento(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_fixo_vencimento(p_mes integer, p_ano integer) RETURNS date
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT make_date(p_ano, p_mes, 10);
$$;


--
-- Name: movelaria_fixo_vencimento_mes(date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_fixo_vencimento_mes(p_referencia date, p_ano integer, p_mes integer) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_dia INTEGER;
  v_max INTEGER;
BEGIN
  IF p_referencia IS NULL THEN
    RETURN make_date(p_ano, p_mes, 10);
  END IF;

  v_dia := EXTRACT(DAY FROM p_referencia)::INTEGER;
  v_max := EXTRACT(DAY FROM (
    date_trunc('month', make_date(p_ano, p_mes, 1)) + INTERVAL '1 month - 1 day'
  ))::INTEGER;

  RETURN make_date(p_ano, p_mes, LEAST(v_dia, v_max));
END;
$$;


