  WHERE usuario_id = p_usuario_id AND ativo = true
  LIMIT 1;
$$;


--
-- Name: movelaria_funcionario_recibo_ao_pagar_cp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_funcionario_recibo_ao_pagar_cp() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_funcionario_id UUID;
  v_texto TEXT;
  v_valor NUMERIC;
BEGIN
  IF NEW.prestador_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.status <> 'pago' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'pago' THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_funcionario_id
  FROM movelaria_funcionarios
  WHERE usuario_id = NEW.prestador_id AND ativo = true
  LIMIT 1;

  IF v_funcionario_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM movelaria_funcionario_recibos
    WHERE conta_pagar_id = NEW.id
  ) THEN
    RETURN NEW;
  END IF;

  v_valor := COALESCE(NEW.valor_pago, NEW.valor_parcela, NEW.valor_total, 0);

  v_texto := movelaria_gerar_texto_recibo_prestador(
    NEW.prestador_id,
    v_valor,
    COALESCE(NEW.data_pagamento, CURRENT_DATE),
    COALESCE(NEW.descricao, NEW.fornecedor_nome, 'Pagamento')
  );

  INSERT INTO movelaria_funcionario_recibos (
    funcionario_id,
    conta_pagar_id,
    status,
    texto_recibo,
    valor,
    data_pagamento,
    enviado_em
  ) VALUES (
    v_funcionario_id,
    NEW.id,
    'aguardando_assinatura',
    v_texto,
    v_valor,
    COALESCE(NEW.data_pagamento, CURRENT_DATE),
    NOW()
  );

  RETURN NEW;
END;
$$;


--
-- Name: movelaria_funcionario_recibo_assinar(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_funcionario_recibo_assinar(p_recibo_id uuid, p_assinatura_path text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_funcionario_id UUID;
BEGIN
  SELECT r.funcionario_id INTO v_funcionario_id
  FROM movelaria_funcionario_recibos r
  JOIN movelaria_funcionarios f ON f.id = r.funcionario_id
  JOIN movelaria_contas_pagar cp ON cp.id = r.conta_pagar_id
  WHERE r.id = p_recibo_id
    AND r.status IN ('gerado', 'aguardando_assinatura')
    AND cp.status = 'pago'
    AND f.usuario_id = auth.uid();

  IF v_funcionario_id IS NULL AND movelaria_meu_perfil() NOT IN ('administrador', 'financeiro') THEN
    RAISE EXCEPTION 'Recibo não disponível para assinatura.';
  END IF;

  UPDATE movelaria_funcionario_recibos r
  SET
    status = 'assinado',
    arquivo_assinado_path = p_assinatura_path,
    assinado_em = NOW(),
    atualizado_em = NOW()
  FROM movelaria_contas_pagar cp
  WHERE r.id = p_recibo_id
    AND cp.id = r.conta_pagar_id
    AND cp.status = 'pago'
    AND r.status IN ('gerado', 'aguardando_assinatura');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Recibo não encontrado, já assinado ou pagamento ainda não confirmado no financeiro.';
  END IF;
END;
$$;


--
-- Name: movelaria_funcionario_recibo_enviar_assinatura(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_funcionario_recibo_enviar_assinatura(p_recibo_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF movelaria_meu_perfil() NOT IN ('administrador', 'financeiro') THEN
    RAISE EXCEPTION 'Acesso negado.';
  END IF;

  UPDATE movelaria_funcionario_recibos
  SET status = 'aguardando_assinatura', enviado_em = NOW(), atualizado_em = NOW()
  WHERE id = p_recibo_id AND status IN ('gerado', 'aguardando_assinatura');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Recibo não encontrado ou já assinado.';
  END IF;
END;
$$;


--
-- Name: movelaria_gerar_texto_recibo_prestador(uuid, numeric, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_gerar_texto_recibo_prestador(p_prestador_id uuid, p_valor numeric, p_data_pagamento date, p_descricao text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_config movelaria_recibo_prestador_config%ROWTYPE;
  v_nome TEXT;
  v_cpf TEXT;
  v_texto TEXT;
BEGIN
  SELECT * INTO v_config FROM movelaria_recibo_prestador_config WHERE ativo = true LIMIT 1;
  IF NOT FOUND THEN
    v_config.template_texto := 'RECIBO — {{valor_pagamento}} — {{descricao_pagamento}}';
    v_config.cnpj := '';
  END IF;

  SELECT COALESCE(u.nome, u.email), COALESCE(f.cpf, '')
  INTO v_nome, v_cpf
  FROM movelaria_usuarios u
  LEFT JOIN movelaria_funcionarios f ON f.usuario_id = u.id
  WHERE u.id = p_prestador_id;

  v_texto := v_config.template_texto;
  v_texto := replace(v_texto, '{{nome_empresa}}', 'GARBO MOVELARIA');
  v_texto := replace(v_texto, '{{cnpj}}', COALESCE(v_config.cnpj, ''));
  v_texto := replace(v_texto, '{{nome_prestador}}', COALESCE(v_nome, ''));
  v_texto := replace(v_texto, '{{cpf_prestador}}', COALESCE(v_cpf, ''));
  v_texto := replace(v_texto, '{{valor_pagamento}}', 'R$ ' || TO_CHAR(COALESCE(p_valor, 0), 'FM999G999G990D00'));
  v_texto := replace(v_texto, '{{data_pagamento}}', TO_CHAR(COALESCE(p_data_pagamento, CURRENT_DATE), 'DD/MM/YYYY'));
  v_texto := replace(v_texto, '{{descricao_pagamento}}', COALESCE(NULLIF(TRIM(p_descricao), ''), 'Pagamento de serviços'));
  RETURN v_texto;
END;
$_$;


--
-- Name: movelaria_get_leads_ganhos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_get_leads_ganhos() RETURNS TABLE(id text, nome text, telefone text, email text, origem text, status text, valor_orcamento numeric, observacoes text, criado_em timestamp with time zone, ja_processado boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $_$
BEGIN
  RETURN QUERY
  SELECT
    l.id::TEXT,
    l.nome,
    NULLIF(trim(COALESCE(l.telefone, '')), ''),
    NULLIF(trim(COALESCE(l.email, '')), ''),
    l.origem,
    l.status,
    (SELECT CASE
      WHEN COALESCE(raw_val, '') ~ '^-?[0-9]{1,3}(\.[0-9]{3})+(,[0-9]{1,2})?$'
        THEN REPLACE(REPLACE(raw_val, '.', ''), ',', '.')::NUMERIC
      WHEN COALESCE(raw_val, '') ~ '^-?[0-9]+([.][0-9]+)?$'
        THEN raw_val::NUMERIC
      WHEN COALESCE(raw_val, '') ~ '^-?[0-9]+(,[0-9]+)?$'
        THEN REPLACE(raw_val, ',', '.')::NUMERIC
      ELSE NULL
    END
    FROM (
      SELECT NULLIF(trim(COALESCE(
        NULLIF(trim(to_jsonb(l) ->> 'valor_negocio'), ''),
        NULLIF(trim(to_jsonb(l) ->> 'valor_orcamento'), '')
      )), '') AS raw_val
    ) v
    ) AS valor_orcamento,
    COALESCE(
      NULLIF(trim(COALESCE(to_jsonb(l) ->> 'observacoes', '')), ''),
      NULLIF(trim(COALESCE(to_jsonb(l) ->> 'observacao',  '')), '')
    ) AS observacoes,
    l.criado_em,
    (
      EXISTS (
        SELECT 1 FROM movelaria_orcamentos_fechados o WHERE o.lead_id = l.id::TEXT
      )
      OR
      EXISTS (
        SELECT 1 FROM movelaria_leads_ganhos_excluidos e WHERE e.lead_id = l.id::TEXT
      )
    ) AS ja_processado
  FROM emp_garbo.leads l
  WHERE l.status = 'Orçamentos ganhos'
  ORDER BY l.criado_em DESC;
END;
$_$;


--
-- Name: movelaria_horarios_admissao_from_jornada(time without time zone, time without time zone, time without time zone, time without time zone, integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_horarios_admissao_from_jornada(p_hora_entrada time without time zone, p_hora_saida_intervalo time without time zone, p_hora_retorno_intervalo time without time zone, p_hora_saida time without time zone, p_dias_uteis integer[]) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_dias INT[];
  v_dia_nome TEXT;
  v_dow INT;
  v_ativos JSONB := '[]'::JSONB;
  v_semana JSONB := '{}'::JSONB;
  v_dia JSONB;
BEGIN
  SELECT COALESCE(ARRAY_AGG(d ORDER BY d), ARRAY[1, 2, 3, 4, 5])
  INTO v_dias
  FROM unnest(COALESCE(NULLIF(p_dias_uteis, '{}'), ARRAY[1, 2, 3, 4, 5])) AS d
  WHERE d BETWEEN 1 AND 7;

  v_dia := jsonb_build_object(
    'chegada', movelaria_fmt_hora_hhmm(p_hora_entrada),
    'saida_almoco', movelaria_fmt_hora_hhmm(COALESCE(p_hora_saida_intervalo, TIME '12:00')),
    'retorno_almoco', movelaria_fmt_hora_hhmm(COALESCE(p_hora_retorno_intervalo, TIME '13:00')),
    'saida_servico', movelaria_fmt_hora_hhmm(p_hora_saida)
  );

  FOREACH v_dow IN ARRAY v_dias
  LOOP
    v_dia_nome := movelaria_isodow_to_dia_admissao(v_dow);
    IF v_dia_nome IS NULL THEN
      CONTINUE;
    END IF;
    IF v_ativos @> jsonb_build_array(v_dia_nome) THEN
      CONTINUE;
    END IF;
    v_ativos := v_ativos || jsonb_build_array(v_dia_nome);
    v_semana := v_semana || jsonb_build_object(v_dia_nome, v_dia);
  END LOOP;

  RETURN jsonb_build_object(
    'horarios_dias_ativos', v_ativos,
    'horarios_semana', v_semana
  );
END;
$$;


--
-- Name: movelaria_importar_contas_pagar_lote(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_importar_contas_pagar_lote(p_itens jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item JSONB;
  v_inseridas INTEGER := 0;
  v_ignoradas INTEGER := 0;
  v_fornecedor_nome TEXT;
  v_descricao TEXT;
  v_observacao TEXT;
  v_vencimento DATE;
  v_valor NUMERIC(12, 2);
  v_fornecedor_id UUID;
  v_chave TEXT;
  v_id UUID;
  v_ids UUID[] := ARRAY[]::UUID[];
BEGIN
  IF movelaria_meu_perfil() NOT IN ('administrador', 'financeiro') THEN
    RAISE EXCEPTION 'Sem permissão para importar contas a pagar.';
  END IF;

  IF p_itens IS NULL OR jsonb_typeof(p_itens) <> 'array' THEN
    RAISE EXCEPTION 'Lista de itens inválida para importação.';
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS _import_contas_pagar_chaves (
    chave TEXT PRIMARY KEY
  ) ON COMMIT DROP;

  TRUNCATE _import_contas_pagar_chaves;

  FOR v_item IN
    SELECT value FROM jsonb_array_elements(p_itens) AS t(value)
  LOOP
    v_fornecedor_nome := btrim(COALESCE(v_item->>'fornecedor_nome', ''));
    v_descricao := btrim(COALESCE(v_item->>'descricao', ''));
    v_observacao := nullif(btrim(COALESCE(v_item->>'observacao', '')), '');
    v_vencimento := NULLIF(v_item->>'vencimento', '')::DATE;
    v_valor := NULLIF(v_item->>'valor', '')::NUMERIC(12, 2);

    BEGIN
      v_fornecedor_id := NULLIF(v_item->>'fornecedor_id', '')::UUID;
    EXCEPTION
      WHEN invalid_text_representation THEN
        v_fornecedor_id := NULL;
    END;

    IF v_fornecedor_nome = ''
      OR v_descricao = ''
      OR v_vencimento IS NULL
      OR v_valor IS NULL
      OR v_valor <= 0
    THEN
      v_ignoradas := v_ignoradas + 1;
      CONTINUE;
    END IF;

    v_chave :=
      movelaria_normalizar_import_texto(v_fornecedor_nome) || '|' ||
      movelaria_normalizar_import_texto(v_descricao) || '|' ||
      v_vencimento::TEXT || '|' ||
      to_char(v_valor, 'FM999999990.00');

    IF EXISTS (SELECT 1 FROM _import_contas_pagar_chaves k WHERE k.chave = v_chave) THEN
      v_ignoradas := v_ignoradas + 1;
      CONTINUE;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM movelaria_contas_pagar cp
      WHERE movelaria_normalizar_import_texto(COALESCE(cp.fornecedor_nome, '')) =
            movelaria_normalizar_import_texto(v_fornecedor_nome)
        AND movelaria_normalizar_import_texto(COALESCE(cp.descricao, '')) =
            movelaria_normalizar_import_texto(v_descricao)
        AND cp.data_vencimento = v_vencimento
        AND cp.valor_parcela = v_valor
    ) THEN
      v_ignoradas := v_ignoradas + 1;
      CONTINUE;
    END IF;

    INSERT INTO movelaria_contas_pagar (
      fornecedor_id,
      fornecedor_nome,
      descricao,
      observacao,
      valor_total,
      numero_parcela,
      total_parcelas,
      valor_parcela,
      data_vencimento,
      status,
      valor_pago,
      grupo_lancamento_id
    ) VALUES (
      v_fornecedor_id,
      v_fornecedor_nome,
      v_descricao,
      v_observacao,
      v_valor,
      1,
      1,
      v_valor,
      v_vencimento,
      'pendente',
      0,
      gen_random_uuid()
    )
    RETURNING id INTO v_id;

    INSERT INTO _import_contas_pagar_chaves (chave) VALUES (v_chave);
    v_inseridas := v_inseridas + 1;
    v_ids := array_append(v_ids, v_id);
  END LOOP;

  RETURN jsonb_build_object(
    'inseridas', v_inseridas,
    'ignoradas', v_ignoradas,
    'ids', to_jsonb(v_ids)
  );
END;
$$;


--
-- Name: movelaria_iniciar_obra(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_iniciar_obra(p_obra_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_perfil TEXT := movelaria_meu_perfil();
  v_uid    UUID := auth.uid();
  v_comanda_equipe BOOLEAN;
BEGIN
  IF v_perfil IS NULL THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  IF v_perfil = 'montador' AND NOT movelaria_montador_acessa_obra(p_obra_id, v_uid) THEN
    RAISE EXCEPTION 'Acesso negado: obra não atribuída a você';
  END IF;

  IF v_perfil = 'montador_admin' AND NOT movelaria_montador_admin_acessa_obra(p_obra_id, v_uid) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  v_comanda_equipe := v_perfil IN ('administrador', 'administrador_obras', 'montador_admin');

  IF v_comanda_equipe THEN
    PERFORM movelaria_registrar_inicio_todos_montadores(p_obra_id);
  ELSIF v_perfil = 'montador'
     AND v_uid IS NOT NULL
     AND movelaria_montador_acessa_obra(p_obra_id, v_uid) THEN
    PERFORM movelaria_registrar_inicio_montador(p_obra_id, v_uid);
  END IF;

  UPDATE movelaria_obras
  SET iniciado_em   = COALESCE(iniciado_em, NOW()),
      status_kanban = CASE
        WHEN status_kanban NOT IN ('concluida', 'cancelada') THEN 'em_andamento'
        ELSE status_kanban
      END,
      atualizado_em = NOW()
  WHERE id = p_obra_id;
END;
$$;


--
-- Name: movelaria_isodow_to_dia_admissao(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_isodow_to_dia_admissao(p_dow integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_dow
    WHEN 1 THEN 'segunda'
    WHEN 2 THEN 'terca'
    WHEN 3 THEN 'quarta'
    WHEN 4 THEN 'quinta'
    WHEN 5 THEN 'sexta'
    WHEN 6 THEN 'sabado'
    WHEN 7 THEN 'domingo'
    ELSE NULL
  END;
$$;


--
-- Name: movelaria_jornada_from_admissao_dados(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_jornada_from_admissao_dados(p_dados jsonb) RETURNS TABLE(hora_entrada time without time zone, hora_saida_intervalo time without time zone, hora_retorno_intervalo time without time zone, hora_saida time without time zone, dias_uteis integer[])
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_semana JSONB := COALESCE(p_dados->'horarios_semana', '{}'::JSONB);
  v_ativos JSONB := COALESCE(p_dados->'horarios_dias_ativos', '[]'::JSONB);
  v_ordem TEXT[] := ARRAY['segunda','terca','quarta','quinta','sexta','sabado','domingo'];
  v_dia TEXT;
  v_base JSONB;
  v_dias INT[] := ARRAY[]::INT[];
  v_dow INT;
  v_chegada TEXT;
  v_saida TEXT;
BEGIN
  IF jsonb_typeof(v_ativos) = 'array' AND jsonb_array_length(v_ativos) > 0 THEN
    FOR v_dia IN SELECT jsonb_array_elements_text(v_ativos)
    LOOP
      v_dow := movelaria_dia_admissao_to_isodow(v_dia);
      IF v_dow IS NOT NULL AND NOT (v_dow = ANY (v_dias)) THEN
        v_dias := array_append(v_dias, v_dow);
      END IF;
    END LOOP;
  END IF;

  IF coalesce(array_length(v_dias, 1), 0) = 0 THEN
    FOREACH v_dia IN ARRAY v_ordem
    LOOP
      IF v_semana ? v_dia AND (
        NULLIF(trim(COALESCE(v_semana->v_dia->>'chegada', '')), '') IS NOT NULL
        OR NULLIF(trim(COALESCE(v_semana->v_dia->>'saida_servico', '')), '') IS NOT NULL
      ) THEN
        v_dias := array_append(v_dias, movelaria_dia_admissao_to_isodow(v_dia));
      END IF;
    END LOOP;
  END IF;

  IF coalesce(array_length(v_dias, 1), 0) = 0 THEN
    RETURN;
  END IF;

  v_dias := (SELECT ARRAY_AGG(d ORDER BY d) FROM unnest(v_dias) AS d);

  FOREACH v_dia IN ARRAY v_ordem
  LOOP
    IF movelaria_dia_admissao_to_isodow(v_dia) = ANY (v_dias)
      AND v_semana ? v_dia
      AND NULLIF(trim(COALESCE(v_semana->v_dia->>'chegada', '')), '') IS NOT NULL
      AND NULLIF(trim(COALESCE(v_semana->v_dia->>'saida_servico', '')), '') IS NOT NULL
    THEN
      v_base := v_semana->v_dia;
      EXIT;
    END IF;
  END LOOP;

  IF v_base IS NULL THEN
    RETURN;
  END IF;

  v_chegada := trim(v_base->>'chegada');
  v_saida := trim(v_base->>'saida_servico');

  RETURN QUERY SELECT
    v_chegada::TIME,
    COALESCE(NULLIF(trim(COALESCE(v_base->>'saida_almoco', '')), '')::TIME, TIME '12:00'),
    COALESCE(NULLIF(trim(COALESCE(v_base->>'retorno_almoco', '')), '')::TIME, TIME '13:00'),
    v_saida::TIME,
    v_dias;
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: movelaria_funcionario_jornada; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.movelaria_funcionario_jornada (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    funcionario_id uuid NOT NULL,
    hora_entrada time without time zone DEFAULT '08:00:00'::time without time zone NOT NULL,
    hora_saida_intervalo time without time zone DEFAULT '12:00:00'::time without time zone NOT NULL,
    hora_retorno_intervalo time without time zone DEFAULT '13:00:00'::time without time zone NOT NULL,
    hora_saida time without time zone DEFAULT '17:00:00'::time without time zone NOT NULL,
    tolerancia_minutos integer DEFAULT 5 NOT NULL,
    dias_uteis integer[] DEFAULT ARRAY[1, 2, 3, 4, 5] NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    horarios_semana jsonb,
    CONSTRAINT movelaria_funcionario_jornada_tolerancia_minutos_check CHECK (((tolerancia_minutos >= 0) AND (tolerancia_minutos <= 60)))
);


--
-- Name: COLUMN movelaria_funcionario_jornada.horarios_semana; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.movelaria_funcionario_jornada.horarios_semana IS 'Grade por dia (mesma estrutura de admissao_dados.horarios_semana). Flat hora_* continua como fallback.';


--
-- Name: movelaria_jornada_hora_no_dia(public.movelaria_funcionario_jornada, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_jornada_hora_no_dia(p_jornada public.movelaria_funcionario_jornada, p_dow integer, p_campo text) RETURNS time without time zone
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_dia TEXT;
  v_raw TEXT;
  v_semana JSONB := COALESCE(p_jornada.horarios_semana, '{}'::JSONB);
BEGIN
  v_dia := movelaria_isodow_to_dia_admissao(p_dow);
  IF v_dia IS NOT NULL AND v_semana ? v_dia THEN
    v_raw := NULLIF(trim(COALESCE(v_semana->v_dia->>p_campo, '')), '');
    IF v_raw IS NOT NULL THEN
      RETURN v_raw::TIME;
    END IF;
  END IF;

  RETURN CASE p_campo
    WHEN 'chegada' THEN p_jornada.hora_entrada
    WHEN 'saida_almoco' THEN p_jornada.hora_saida_intervalo
    WHEN 'retorno_almoco' THEN p_jornada.hora_retorno_intervalo
    WHEN 'saida_servico' THEN p_jornada.hora_saida
    ELSE NULL
  END;
END;
$$;


--
-- Name: movelaria_jornada_minutos_no_dia(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_jornada_minutos_no_dia(p_funcionario_id uuid, p_data date) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_jornada movelaria_funcionario_jornada%ROWTYPE;
  v_dow INT;
  v_entrada TIME;
  v_saida_intervalo TIME;
  v_retorno_intervalo TIME;
  v_saida TIME;
  v_total INT;
  v_intervalo INT;
BEGIN
  SELECT * INTO v_jornada
  FROM movelaria_funcionario_jornada
  WHERE funcionario_id = p_funcionario_id AND ativo = true
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  v_dow := EXTRACT(ISODOW FROM p_data)::INT;
  v_entrada := movelaria_jornada_hora_no_dia(v_jornada, v_dow, 'chegada');
  v_saida_intervalo := movelaria_jornada_hora_no_dia(v_jornada, v_dow, 'saida_almoco');
  v_retorno_intervalo := movelaria_jornada_hora_no_dia(v_jornada, v_dow, 'retorno_almoco');
  v_saida := movelaria_jornada_hora_no_dia(v_jornada, v_dow, 'saida_servico');

  IF v_entrada IS NULL OR v_saida IS NULL THEN
    RETURN 0;
  END IF;

  v_total := FLOOR(EXTRACT(EPOCH FROM (v_saida - v_entrada)) / 60)::INT;
  IF v_total < 0 THEN
    v_total := 0;
  END IF;

  IF v_saida_intervalo IS NOT NULL AND v_retorno_intervalo IS NOT NULL THEN
    v_intervalo := FLOOR(EXTRACT(EPOCH FROM (v_retorno_intervalo - v_saida_intervalo)) / 60)::INT;
    IF v_intervalo > 0 THEN
      v_total := GREATEST(0, v_total - v_intervalo);
    END IF;
  END IF;

  RETURN v_total;
END;
$$;


--
-- Name: movelaria_lead_midias_por_leads(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_lead_midias_por_leads(p_lead_ids text[]) RETURNS TABLE(id text, lead_id text, tipo text, titulo text, file_name text, file_url text, folder_nome text, criado_em timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
DECLARE
  v_pode_docs BOOLEAN := false;
BEGIN
  IF auth.uid() IS NULL OR movelaria_meu_perfil() IS NULL THEN
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM movelaria_usuarios u
    WHERE u.id = auth.uid()
      AND u.ativo = true
      AND (
        u.perfil IN ('montador_admin', 'administrador', 'administrador_obras')
        OR 'montador_admin' = ANY (COALESCE(u.perfis_extras, '{}'::TEXT[]))
        OR 'administrador' = ANY (COALESCE(u.perfis_extras, '{}'::TEXT[]))
        OR 'administrador_obras' = ANY (COALESCE(u.perfis_extras, '{}'::TEXT[]))
      )
  ) INTO v_pode_docs;

  IF p_lead_ids IS NULL OR cardinality(p_lead_ids) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    m.id::TEXT,
    m.lead_id::TEXT,
    m.tipo,
    m.titulo,
    m.file_name,
    m.file_url,
    f.nome,
    m.criado_em
  FROM emp_garbo.marketing_medias m
  LEFT JOIN emp_garbo.marketing_media_folders f ON f.id = m.folder_id
  WHERE m.lead_id IS NOT NULL
    AND m.lead_id::TEXT = ANY (p_lead_ids)
    AND (
      m.tipo = 'imagem'
      OR (v_pode_docs AND m.tipo = 'pdf')
    )
  ORDER BY m.criado_em DESC NULLS LAST;
END;
$$;


--
-- Name: movelaria_listar_contratos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_listar_contratos() RETURNS TABLE(id uuid, identificador text, cliente_nome text, status text, created_at timestamp with time zone, lead_id bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
      SELECT id, identificador, cliente_nome, status, created_at, lead_id
      FROM emp_garbo.contratos
      ORDER BY created_at DESC;
    $$;


--
-- Name: movelaria_listar_fixo_montadores(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_listar_fixo_montadores(p_mes integer, p_ano integer) RETURNS TABLE(funcionario_id uuid, montador_id uuid, montador_nome text, categoria text, valor_fixo_mensal numeric, primeiro_vencimento date, status_mes text, conta_pagar_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_perfil TEXT := movelaria_meu_perfil();
  r        RECORD;
  v_cp_id  UUID;
  v_status TEXT;
  v_valor  NUMERIC(12, 2);
  v_venc   DATE;
  v_uid    UUID;
BEGIN
  IF v_perfil NOT IN ('administrador', 'administrador_obras', 'financeiro', 'montador_admin') THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  FOR r IN
    SELECT f.id,
           f.usuario_id,
           COALESCE(NULLIF(TRIM(f.nome), ''), 'Funcionário') AS nome,
           COALESCE(f.categoria, 'outro') AS categoria,
           f.valor_fixo_mensal AS valor_func,
           f.fixo_primeiro_vencimento AS venc_func,
           u.valor_fixo_mensal AS valor_user,
           u.fixo_primeiro_vencimento AS venc_user
    FROM movelaria_funcionarios f
    LEFT JOIN movelaria_usuarios u ON u.id = f.usuario_id
    WHERE f.ativo = true
      AND COALESCE(f.tipo, '') <> 'marceneiro'
    ORDER BY f.nome NULLS LAST, f.criado_em
  LOOP
    v_uid := r.usuario_id;
    -- Preferência: valor no funcionário; se zerado e há usuário montador, usa o do usuário
    v_valor := COALESCE(NULLIF(r.valor_func, 0), r.valor_user, 0);
    v_venc := COALESCE(r.venc_func, r.venc_user);

    v_cp_id := NULL;
    v_status := 'sem_fixo';

    IF COALESCE(v_valor, 0) > 0
      AND movelaria_fixo_mes_elegivel(v_venc, p_mes, p_ano) THEN
      SELECT cp.id, cp.status
      INTO v_cp_id, v_status
      FROM movelaria_contas_pagar cp
      WHERE (
          COALESCE(cp.descricao, '') LIKE 'Fixo montador:%'
          OR COALESCE(cp.descricao, '') LIKE 'Fixo:%'
        )
        AND (
          (v_uid IS NOT NULL AND cp.prestador_id = v_uid)
          OR (
            v_uid IS NULL
            AND LOWER(TRIM(COALESCE(cp.fornecedor_nome, ''))) = LOWER(TRIM(r.nome))
          )
        )
        AND EXTRACT(MONTH FROM cp.data_vencimento) = p_mes
        AND EXTRACT(YEAR  FROM cp.data_vencimento) = p_ano
      ORDER BY cp.criado_em ASC, cp.id ASC
      LIMIT 1;

      IF v_cp_id IS NULL THEN
        v_status := 'pendente';
      ELSIF v_status = 'pago' THEN
        v_status := 'pago';
      ELSE
        v_status := 'pendente';
      END IF;
    END IF;

    funcionario_id      := r.id;
    montador_id         := v_uid; -- usuario_id (comissão / compat)
    montador_nome       := r.nome;
    categoria           := r.categoria;
    valor_fixo_mensal   := COALESCE(v_valor, 0);
    primeiro_vencimento := v_venc;
    status_mes          := v_status;
    conta_pagar_id      := v_cp_id;
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: movelaria_listar_identidades(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_listar_identidades() RETURNS TABLE(id uuid, email text, nome text, perfil text, perfis_extras text[], ativo boolean, criado_em timestamp with time zone, tem_movelaria boolean, crm_tipo_usuario text, crm_status_convite text, crm_roles text[], crm_horario_inicio text, crm_horario_fim text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.movelaria_meu_perfil() <> 'administrador' THEN
    RAISE EXCEPTION 'Acesso negado: somente administradores podem listar usuários';
  END IF;

  RETURN QUERY
  WITH ids AS (
    SELECT m.id FROM public.movelaria_usuarios m
    UNION
    SELECT c.id FROM emp_garbo.usuarios c
  )
  SELECT
    i.id,
    COALESCE(m.email, c.email, ''),
    COALESCE(m.nome, c.nome),
    m.perfil,
    COALESCE(m.perfis_extras, '{}'::TEXT[]),
    COALESCE(m.ativo, c.status_convite = 'ATIVO', false),
    COALESCE(m.criado_em, c.criado_em, NOW()),
    (m.id IS NOT NULL),
    c.tipo_usuario,
    c.status_convite,
    COALESCE((
      SELECT array_agg(r.role::TEXT ORDER BY r.role::TEXT)
      FROM emp_garbo.user_roles r
      WHERE r.user_id = i.id
    ), '{}'::TEXT[]),
    to_char(c.horario_acesso_inicio, 'HH24:MI'),
    to_char(c.horario_acesso_fim, 'HH24:MI')
  FROM ids i
  LEFT JOIN public.movelaria_usuarios m ON m.id = i.id
  LEFT JOIN emp_garbo.usuarios c ON c.id = i.id
  ORDER BY COALESCE(m.nome, c.nome, m.email, c.email);
END;
$$;


--
-- Name: movelaria_listar_montadores(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_listar_montadores() RETURNS TABLE(id uuid, email text, nome text, perfil text, ativo boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
  IF NOT movelaria_usuario_tem_algum_perfil(
    ARRAY['administrador', 'montador_admin', 'administrador_obras', 'financeiro']
  ) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  RETURN QUERY
    SELECT
      u.id,
      u.email,
      COALESCE(
        NULLIF(trim(u.nome), ''),
        (
          SELECT NULLIF(trim(f.nome), '')
          FROM movelaria_funcionarios f
          WHERE f.ativo = true
            AND f.tipo IN ('montador', 'montador_admin')
            AND (
              f.usuario_id = u.id
              OR (f.email IS NOT NULL AND lower(f.email) = lower(u.email))
            )
          ORDER BY
            CASE WHEN f.tipo = 'montador_admin' THEN 0 ELSE 1 END,
            f.atualizado_em DESC NULLS LAST
          LIMIT 1
        ),
        split_part(u.email, '@', 1)
      ) AS nome,
      CASE
        WHEN u.perfil = 'montador_admin'
          OR 'montador_admin' = ANY (COALESCE(u.perfis_extras, ARRAY[]::text[]))
          OR EXISTS (
            SELECT 1 FROM movelaria_funcionarios f
            WHERE f.ativo = true
              AND f.tipo = 'montador_admin'
              AND (
                f.usuario_id = u.id
                OR (f.email IS NOT NULL AND lower(f.email) = lower(u.email))
              )
          )
          THEN 'montador_admin'::text
        ELSE 'montador'::text
      END AS perfil,
      u.ativo
    FROM movelaria_usuarios u
    WHERE u.ativo = true
      AND (
        u.perfil IN ('montador', 'montador_admin')
        OR COALESCE(u.perfis_extras, ARRAY[]::text[])
           && ARRAY['montador', 'montador_admin']
        OR EXISTS (
          SELECT 1 FROM movelaria_funcionarios f
          WHERE f.ativo = true
            AND f.tipo IN ('montador', 'montador_admin')
            AND (
              f.usuario_id = u.id
              OR (f.email IS NOT NULL AND lower(f.email) = lower(u.email))
            )
          )
      )
    ORDER BY 3 NULLS LAST, u.email;
END;
$$;


--
-- Name: movelaria_listar_obras(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_listar_obras() RETURNS TABLE(id uuid, origem_orcamento_id uuid, origem_lead_id text, cliente_id uuid, cliente_nome text, lousa text, descricao text, endereco_obra text, tipo_obra_id uuid, tipo_obra_nome text, grupo_obra_id uuid, grupo_obra_nome text, montador_admin_id uuid, montador_admin_nome text, montador_id uuid, montador_nome text, montador_ids uuid[], montador_nomes text[], data_prevista_inicio date, data_prevista_fim date, tempo_maximo_horas numeric, status_kanban text, iniciado_em timestamp with time zone, finalizado_em timestamp with time zone, concluido_em_atraso boolean, pedido_material_feito boolean, data_entrega_pedido date, numero_pedido_cort_claud text, criado_em timestamp with time zone, atualizado_em timestamp with time zone, comissao_habilitada boolean, comissao_total numeric, comissao_gerada boolean, dias_trabalho integer[], horario_inicio text, horario_fim text, comissao_prestador_ids uuid[], comissao_prestador_nomes text[], comissao_valores numeric[], comissao_ocultos boolean[], montadores_execucao jsonb, atraso_permanente boolean, atraso_marcado_em timestamp with time zone, data_prevista_inicio_original date, data_prevista_fim_original date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_uid                 UUID := auth.uid();
  v_ve_todas            BOOLEAN := movelaria_usuario_tem_algum_perfil(
    ARRAY['administrador', 'financeiro', 'administrador_obras', 'visualizador']
  );
  v_eh_montador_admin   BOOLEAN := movelaria_usuario_tem_perfil('montador_admin');
  v_eh_montador         BOOLEAN := movelaria_usuario_tem_perfil('montador');
BEGIN
  RETURN QUERY
  SELECT
    o.id, o.origem_orcamento_id, o.origem_lead_id, o.cliente_id,
    o.cliente_nome, o.lousa, o.descricao, o.endereco_obra,
    o.tipo_obra_id, t.nome,
    o.grupo_obra_id, g.nome,
    o.montador_admin_id,
    CASE
      WHEN uma.id IS NULL THEN NULL
      ELSE COALESCE(NULLIF(TRIM(uma.nome), ''), split_part(uma.email, '@', 1))
    END,
    o.montador_id,
    CASE
      WHEN um.id IS NULL THEN NULL
      ELSE COALESCE(NULLIF(TRIM(um.nome), ''), split_part(um.email, '@', 1))
    END,
    COALESCE(resp.ids,   ARRAY[]::UUID[]),
    COALESCE(resp.nomes, ARRAY[]::TEXT[]),
    o.data_prevista_inicio, o.data_prevista_fim, o.tempo_maximo_horas,
    o.status_kanban, o.iniciado_em, o.finalizado_em, o.concluido_em_atraso,
    COALESCE(o.pedido_material_feito, false),
    o.data_entrega_pedido,
    o.numero_pedido_cort_claud,
    o.criado_em, o.atualizado_em,
    o.comissao_habilitada, o.comissao_total, o.comissao_gerada,
    o.dias_trabalho, o.horario_inicio, o.horario_fim,
    COALESCE(com.ids,   ARRAY[]::UUID[]),
    COALESCE(com.nomes, ARRAY[]::TEXT[]),
    COALESCE(com.valores, ARRAY[]::NUMERIC[]),
    COALESCE(com.ocultos, ARRAY[]::BOOLEAN[]),
    COALESCE(exec.data, '[]'::jsonb),
    COALESCE(o.atraso_permanente, false),
    o.atraso_marcado_em,
    o.data_prevista_inicio_original,
    o.data_prevista_fim_original
  FROM movelaria_obras o
  LEFT JOIN movelaria_tipos_obra t  ON t.id = o.tipo_obra_id
  LEFT JOIN movelaria_grupos_obra g ON g.id = o.grupo_obra_id
  LEFT JOIN movelaria_usuarios um   ON um.id = o.montador_id
  LEFT JOIN movelaria_usuarios uma  ON uma.id = o.montador_admin_id
  LEFT JOIN LATERAL (
    SELECT
      array_agg(r.montador_id ORDER BY r.criado_em) AS ids,
      array_agg(
        COALESCE(NULLIF(TRIM(u.nome), ''), split_part(u.email, '@', 1))
        ORDER BY r.criado_em
      ) AS nomes
    FROM movelaria_obra_responsaveis r
    JOIN movelaria_usuarios u ON u.id = r.montador_id
    WHERE r.obra_id = o.id
  ) resp ON true
  LEFT JOIN LATERAL (
    SELECT jsonb_agg(
      jsonb_build_object(
        'montador_id', r.montador_id,
        'iniciado_em', r.iniciado_em,
        'finalizado_em', r.finalizado_em
      ) ORDER BY r.criado_em
    ) AS data
    FROM movelaria_obra_responsaveis r
    WHERE r.obra_id = o.id
  ) exec ON true
  LEFT JOIN LATERAL (
    SELECT
      array_agg(ci.prestador_id ORDER BY ci.criado_em) AS ids,
      array_agg(
        COALESCE(NULLIF(TRIM(pu.nome), ''), split_part(pu.email, '@', 1))
        ORDER BY ci.criado_em
      ) AS nomes,
      array_agg(ci.valor ORDER BY ci.criado_em) AS valores,
      array_agg(COALESCE(ci.oculto_prestador, false) ORDER BY ci.criado_em) AS ocultos
    FROM movelaria_obra_comissao_itens ci
    JOIN movelaria_usuarios pu ON pu.id = ci.prestador_id
    WHERE ci.obra_id = o.id
      AND ci.valor > 0
      AND (
        v_ve_todas
        OR NOT (COALESCE(ci.oculto_prestador, false) AND ci.prestador_id = v_uid)
      )
  ) com ON true
  WHERE (
    v_ve_todas
    OR (v_eh_montador_admin AND movelaria_montador_admin_acessa_obra(o.id, v_uid))
    OR (v_eh_montador AND movelaria_montador_acessa_obra(o.id, v_uid))
  )
  ORDER BY o.criado_em DESC;
END;
$$;


--
-- Name: movelaria_funcionario_recibos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.movelaria_funcionario_recibos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    funcionario_id uuid NOT NULL,
    conta_pagar_id uuid,
    status text DEFAULT 'gerado'::text NOT NULL,
    texto_recibo text DEFAULT ''::text NOT NULL,
    arquivo_original_path text,
    arquivo_assinado_path text,
    valor numeric(12,2),
    data_pagamento date,
    enviado_em timestamp with time zone,
    assinado_em timestamp with time zone,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT movelaria_funcionario_recibos_status_check CHECK ((status = ANY (ARRAY['gerado'::text, 'aguardando_assinatura'::text, 'assinado'::text])))
);


--
-- Name: movelaria_listar_recibos_prestador(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_listar_recibos_prestador() RETURNS SETOF public.movelaria_funcionario_recibos
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_funcionario_id UUID;
BEGIN
  SELECT id INTO v_funcionario_id
  FROM movelaria_funcionarios
  WHERE usuario_id = auth.uid() AND ativo = true;

  IF v_funcionario_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT r.*
  FROM movelaria_funcionario_recibos r
  WHERE r.funcionario_id = v_funcionario_id
  ORDER BY r.criado_em DESC;
END;
$$;


--
-- Name: movelaria_listar_titulares_agenda(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_listar_titulares_agenda() RETURNS TABLE(id uuid, nome text, avatar_url text, perfil_casa text, crm_roles text[], grupo text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid        UUID := auth.uid();
  v_perfil     TEXT;
  v_crm_colab  BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  v_perfil := public.movelaria_meu_perfil();

  SELECT EXISTS (
    SELECT 1
    FROM emp_garbo.usuarios c
    WHERE c.id = v_uid
      AND c.status_convite = 'ATIVO'
      AND c.tipo_usuario = 'colaborador'
  )
  INTO v_crm_colab;

  IF v_perfil IS NULL AND NOT v_crm_colab THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  IF v_perfil = 'visualizador' AND NOT v_crm_colab THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  RETURN QUERY
  WITH ids AS (
    SELECT m.id
    FROM public.movelaria_usuarios m
    WHERE m.ativo = true
      AND m.perfil IS DISTINCT FROM 'visualizador'
    UNION
    SELECT c.id
    FROM emp_garbo.usuarios c
    WHERE c.status_convite = 'ATIVO'
      AND c.tipo_usuario = 'colaborador'
  )
  SELECT
    i.id,
    COALESCE(NULLIF(btrim(m.nome), ''), NULLIF(btrim(c.nome), ''), split_part(COALESCE(m.email, c.email, ''), '@', 1), 'Usuário') AS nome,
    c.avatar_url,
    m.perfil AS perfil_casa,
    COALESCE((
      SELECT array_agg(r.role::TEXT ORDER BY r.role::TEXT)
      FROM emp_garbo.user_roles r
      WHERE r.user_id = i.id
        AND r.role::TEXT <> 'nenhum'
    ), '{}'::TEXT[]) AS crm_roles,
    CASE
      WHEN m.perfil IN ('montador', 'montador_admin') THEN 'montador'
      ELSE 'equipe'
    END AS grupo
  FROM ids i
  LEFT JOIN public.movelaria_usuarios m ON m.id = i.id
  LEFT JOIN emp_garbo.usuarios c ON c.id = i.id
  ORDER BY
    CASE WHEN m.perfil IN ('montador', 'montador_admin') THEN 1 ELSE 0 END,
    COALESCE(m.nome, c.nome, m.email, c.email);
END;
$$;


--
-- Name: movelaria_listar_usuarios(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_listar_usuarios() RETURNS TABLE(id uuid, email text, nome text, perfil text, perfis_extras text[], ativo boolean, criado_em timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
  IF movelaria_meu_perfil() <> 'administrador' THEN
    RAISE EXCEPTION 'Acesso negado: somente administradores podem listar usuários';
  END IF;
  RETURN QUERY
    SELECT u.id, u.email, u.nome, u.perfil, u.perfis_extras, u.ativo, u.criado_em
    FROM   movelaria_usuarios u
    ORDER BY u.criado_em ASC;
END;
$$;


--
-- Name: movelaria_markup_catalogo_categorias(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_markup_catalogo_categorias() RETURNS TABLE(id uuid, nome text, ordem integer, ativo boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
BEGIN
  IF NOT movelaria_usuario_tem_qualquer_perfil(ARRAY['administrador', 'financeiro']) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT c.id, c.nome, c.ordem, c.ativo
  FROM emp_garbo.markup_categorias c
  ORDER BY c.ordem, c.nome;
END;
$$;


--
-- Name: movelaria_markup_catalogo_listar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_markup_catalogo_listar() RETURNS TABLE(id uuid, categoria_id uuid, categoria_nome text, nome text, variacao text, preco_unitario numeric, unidade text, quantidade_padrao numeric, ativo boolean, ordem integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
BEGIN
  IF NOT movelaria_usuario_tem_qualquer_perfil(ARRAY['administrador', 'financeiro']) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    p.categoria_id,
    c.nome,
    p.nome,
    p.variacao,
    p.preco_unitario,
    p.unidade,
    p.quantidade_padrao,
    p.ativo,
    p.ordem
  FROM emp_garbo.markup_produtos p
  LEFT JOIN emp_garbo.markup_categorias c ON c.id = p.categoria_id
  ORDER BY COALESCE(c.ordem, 999), p.ordem, p.nome;
END;
$$;


--
-- Name: movelaria_markup_catalogo_salvar_categoria(uuid, text, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_markup_catalogo_salvar_categoria(p_id uuid, p_nome text, p_ordem integer, p_ativo boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
DECLARE
  v_id UUID;
  v_slug TEXT;
BEGIN
  IF NOT movelaria_usuario_tem_qualquer_perfil(ARRAY['administrador', 'financeiro']) THEN
    RAISE EXCEPTION 'Acesso negado: somente administrador ou financeiro editam categorias.';
  END IF;

  IF p_nome IS NULL OR btrim(p_nome) = '' THEN
    RAISE EXCEPTION 'Nome da categoria é obrigatório.';
  END IF;

  v_slug := lower(regexp_replace(btrim(p_nome), '[^a-zA-Z0-9]+', '-', 'g'));

  IF p_id IS NULL THEN
    INSERT INTO emp_garbo.markup_categorias (nome, slug, ordem, ativo)
    VALUES (
      btrim(p_nome),
      NULLIF(v_slug, ''),
      COALESCE(p_ordem, 0),
      COALESCE(p_ativo, true)
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE emp_garbo.markup_categorias
    SET
      nome = btrim(p_nome),
      ordem = COALESCE(p_ordem, 0),
      ativo = COALESCE(p_ativo, true)
    WHERE id = p_id
    RETURNING id INTO v_id;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: movelaria_markup_catalogo_salvar_produto(uuid, uuid, text, text, numeric, text, numeric, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_markup_catalogo_salvar_produto(p_id uuid, p_categoria_id uuid, p_nome text, p_variacao text, p_preco_unitario numeric, p_unidade text, p_quantidade_padrao numeric, p_ativo boolean, p_ordem integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  IF NOT movelaria_usuario_tem_qualquer_perfil(ARRAY['administrador', 'financeiro']) THEN
    RAISE EXCEPTION 'Acesso negado: somente administrador ou financeiro editam o catálogo.';
  END IF;

  IF p_nome IS NULL OR btrim(p_nome) = '' THEN
    RAISE EXCEPTION 'Nome do produto é obrigatório.';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO emp_garbo.markup_produtos (
      categoria_id, nome, variacao, preco_unitario, unidade,
      quantidade_padrao, ativo, ordem, atualizado_em
    )
    VALUES (
      p_categoria_id,
      btrim(p_nome),
      NULLIF(btrim(COALESCE(p_variacao, '')), ''),
      COALESCE(p_preco_unitario, 0),
      COALESCE(NULLIF(btrim(p_unidade), ''), 'un'),
      p_quantidade_padrao,
      COALESCE(p_ativo, true),
      COALESCE(p_ordem, 0),
      NOW()
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE emp_garbo.markup_produtos
    SET
      categoria_id = p_categoria_id,
      nome = btrim(p_nome),
      variacao = NULLIF(btrim(COALESCE(p_variacao, '')), ''),
      preco_unitario = COALESCE(p_preco_unitario, 0),
      unidade = COALESCE(NULLIF(btrim(p_unidade), ''), 'un'),
      quantidade_padrao = p_quantidade_padrao,
      ativo = COALESCE(p_ativo, true),
      ordem = COALESCE(p_ordem, 0),
      atualizado_em = NOW()
    WHERE id = p_id
    RETURNING id INTO v_id;

    IF v_id IS NULL THEN
      RAISE EXCEPTION 'Produto não encontrado.';
    END IF;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: movelaria_markup_custos_por_leads(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_markup_custos_por_leads(p_lead_ids text[]) RETURNS TABLE(lead_id text, custo_materiais numeric, custo_servicos numeric, custo_despesas numeric, preco_final numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM movelaria_usuarios u
    WHERE u.id = auth.uid()
      AND u.ativo = true
      AND (
        u.perfil IN ('administrador', 'financeiro')
        OR 'administrador' = ANY (COALESCE(u.perfis_extras, '{}'::TEXT[]))
        OR 'financeiro' = ANY (COALESCE(u.perfis_extras, '{}'::TEXT[]))
      )
  ) THEN
    RETURN;
  END IF;

  IF p_lead_ids IS NULL OR cardinality(p_lead_ids) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT DISTINCT ON (m.lead_id)
    m.lead_id::TEXT,
    COALESCE((m.modulos->'totais'->>'custo_materiais')::NUMERIC, 0),
    COALESCE((m.modulos->'totais'->>'custo_servicos')::NUMERIC, 0),
    COALESCE((m.modulos->'totais'->>'custo_despesas')::NUMERIC, 0),
    COALESCE(
      NULLIF((m.modulos->'totais'->>'preco_final')::NUMERIC, NULL),
      m.preco_final,
      0
    )
  FROM emp_garbo.markup_orcamentos m
  WHERE m.lead_id IS NOT NULL
    AND m.lead_id::TEXT = ANY (p_lead_ids)
  ORDER BY m.lead_id, m.atualizado_em DESC NULLS LAST;
END;
$$;


--
-- Name: movelaria_markup_itens_por_leads(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_markup_itens_por_leads(p_lead_ids text[]) RETURNS TABLE(lead_id text, orcamento_id uuid, titulo text, custo_materiais numeric, custo_servicos numeric, custo_despesas numeric, preco_final numeric, linhas jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
BEGIN
  IF NOT movelaria_usuario_tem_qualquer_perfil(
    ARRAY['administrador', 'financeiro', 'administrador_obras', 'montador_admin']
  ) THEN
    RETURN;
  END IF;

  IF p_lead_ids IS NULL OR cardinality(p_lead_ids) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT DISTINCT ON (m.lead_id)
    m.lead_id::TEXT,
    m.id,
    m.titulo,
    COALESCE((m.modulos->'totais'->>'custo_materiais')::NUMERIC, 0),
    COALESCE((m.modulos->'totais'->>'custo_servicos')::NUMERIC, 0),
    COALESCE((m.modulos->'totais'->>'custo_despesas')::NUMERIC, 0),
    COALESCE(
      NULLIF((m.modulos->'totais'->>'preco_final')::NUMERIC, NULL),
      m.preco_final,
      0
    ),
    COALESCE(m.modulos->'materiais'->'linhas', '[]'::JSONB)
  FROM emp_garbo.markup_orcamentos m
  WHERE m.lead_id IS NOT NULL
    AND m.lead_id::TEXT = ANY (p_lead_ids)
  ORDER BY m.lead_id, m.atualizado_em DESC NULLS LAST;
END;
$$;


--
-- Name: movelaria_metricas_comissao_obras_montador(integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_metricas_comissao_obras_montador(p_mes integer DEFAULT (EXTRACT(month FROM CURRENT_DATE))::integer, p_ano integer DEFAULT (EXTRACT(year FROM CURRENT_DATE))::integer, p_montador_id uuid DEFAULT NULL::uuid) RETURNS TABLE(obra_id uuid, cliente_nome text, tipo_obra_nome text, status_kanban text, comissao_valor numeric, situacao text, oculto_prestador boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_perfil         TEXT := movelaria_meu_perfil();
  v_uid            UUID := auth.uid();
  v_filtrar_oculto BOOLEAN;
BEGIN
  IF v_perfil IS NULL THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  IF p_montador_id IS NULL THEN
    RAISE EXCEPTION 'Montador não informado';
  END IF;

  IF v_perfil = 'montador' AND p_montador_id IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  v_filtrar_oculto := (
    v_perfil = 'montador'
    OR (v_perfil = 'montador_admin' AND p_montador_id = v_uid)
  );

  RETURN QUERY
  SELECT
    o.id,
    o.cliente_nome,
    t.nome,
    o.status_kanban,
    ci.valor,
    'concluida'::TEXT,
    COALESCE(ci.oculto_prestador, false)
  FROM movelaria_obra_comissao_itens ci
  JOIN movelaria_obras o ON o.id = ci.obra_id
  LEFT JOIN movelaria_tipos_obra t ON t.id = o.tipo_obra_id
  WHERE ci.prestador_id = p_montador_id
    AND (NOT v_filtrar_oculto OR NOT COALESCE(ci.oculto_prestador, false))
    AND o.status_kanban = 'concluida'
    AND o.finalizado_em IS NOT NULL
    AND o.comissao_habilitada = true
    AND ci.valor > 0
    AND EXTRACT(MONTH FROM o.finalizado_em AT TIME ZONE 'America/Sao_Paulo') = p_mes
    AND EXTRACT(YEAR  FROM o.finalizado_em AT TIME ZONE 'America/Sao_Paulo') = p_ano

  UNION ALL

  SELECT
    o.id,
    o.cliente_nome,
    t.nome,
    o.status_kanban,
    ci.valor,
    'em_aberto'::TEXT,
    COALESCE(ci.oculto_prestador, false)
  FROM movelaria_obra_comissao_itens ci
  JOIN movelaria_obras o ON o.id = ci.obra_id
  LEFT JOIN movelaria_tipos_obra t ON t.id = o.tipo_obra_id
  WHERE ci.prestador_id = p_montador_id
    AND (NOT v_filtrar_oculto OR NOT COALESCE(ci.oculto_prestador, false))
    AND o.status_kanban NOT IN ('concluida', 'cancelada')
    AND o.comissao_habilitada = true
    AND ci.valor > 0
    AND EXTRACT(MONTH FROM movelaria_obra_data_referencia(o.data_prevista_fim, o.data_prevista_inicio, o.criado_em)) = p_mes
    AND EXTRACT(YEAR  FROM movelaria_obra_data_referencia(o.data_prevista_fim, o.data_prevista_inicio, o.criado_em)) = p_ano

  ORDER BY 6, 2;
END;
$$;


--
-- Name: movelaria_metricas_obras(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_metricas_obras(p_mes integer DEFAULT (EXTRACT(month FROM CURRENT_DATE))::integer, p_ano integer DEFAULT (EXTRACT(year FROM CURRENT_DATE))::integer) RETURNS TABLE(tipo_obra_id uuid, tipo_obra_nome text, total_obras bigint, obras_concluidas bigint, tempo_medio_real_horas numeric, tempo_total_real_horas numeric, tempo_maximo_horas_default numeric, obras_em_atraso bigint, total_comissoes numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
  IF movelaria_meu_perfil() IS NULL THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  RETURN QUERY
  SELECT
    t.id,
    t.nome,
    COUNT(o.id) FILTER (
      WHERE o.status_kanban != 'cancelada'
        AND movelaria_obra_mes_entrega(o.data_prevista_fim, p_mes, p_ano)
    ),
    COUNT(o.id) FILTER (
      WHERE o.status_kanban = 'concluida'
        AND movelaria_obra_mes_entrega(o.data_prevista_fim, p_mes, p_ano)
    ),
    ROUND(
      AVG(COALESCE(o.duracao_real_horas, EXTRACT(EPOCH FROM (o.finalizado_em - o.iniciado_em)) / 3600.0))
      FILTER (
        WHERE o.status_kanban = 'concluida'
          AND o.finalizado_em IS NOT NULL
          AND o.iniciado_em IS NOT NULL
          AND movelaria_obra_mes_entrega(o.data_prevista_fim, p_mes, p_ano)
      ),
      2
    ),
    ROUND(
      COALESCE(
        SUM(COALESCE(o.duracao_real_horas, EXTRACT(EPOCH FROM (o.finalizado_em - o.iniciado_em)) / 3600.0))
        FILTER (
          WHERE o.status_kanban = 'concluida'
            AND o.finalizado_em IS NOT NULL
            AND o.iniciado_em IS NOT NULL
            AND movelaria_obra_mes_entrega(o.data_prevista_fim, p_mes, p_ano)
        ),
        0
      ),
      2
    ),
    t.tempo_maximo_horas_default,
    COUNT(o.id) FILTER (
      WHERE o.status_kanban = 'concluida'
        AND o.concluido_em_atraso = true
        AND movelaria_obra_mes_entrega(o.data_prevista_fim, p_mes, p_ano)
    ),
    COALESCE((
      SELECT SUM(ci.valor)
      FROM movelaria_obra_comissao_itens ci
      JOIN movelaria_obras ox ON ox.id = ci.obra_id
      WHERE ox.tipo_obra_id = t.id
        AND ox.comissao_habilitada = true
        AND ci.valor > 0
        AND (
          (
            ox.status_kanban = 'concluida'
            AND ox.finalizado_em IS NOT NULL
            AND EXTRACT(MONTH FROM ox.finalizado_em AT TIME ZONE 'America/Sao_Paulo') = p_mes
            AND EXTRACT(YEAR  FROM ox.finalizado_em AT TIME ZONE 'America/Sao_Paulo') = p_ano
          )
          OR EXISTS (
            SELECT 1 FROM movelaria_contas_pagar cp
            WHERE cp.obra_id = ox.id
              AND EXTRACT(MONTH FROM cp.data_vencimento AT TIME ZONE 'America/Sao_Paulo') = p_mes
              AND EXTRACT(YEAR  FROM cp.data_vencimento AT TIME ZONE 'America/Sao_Paulo') = p_ano
          )
        )
    ), 0)
  FROM movelaria_tipos_obra t
  LEFT JOIN movelaria_obras o ON o.tipo_obra_id = t.id
  WHERE t.ativo = true
  GROUP BY t.id, t.nome, t.tempo_maximo_horas_default
  ORDER BY t.nome;
END;
$$;


--
-- Name: movelaria_metricas_obras_por_montador(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_metricas_obras_por_montador(p_mes integer DEFAULT (EXTRACT(month FROM CURRENT_DATE))::integer, p_ano integer DEFAULT (EXTRACT(year FROM CURRENT_DATE))::integer) RETURNS TABLE(montador_id uuid, montador_nome text, comissao_concluida numeric, comissao_em_aberto numeric, comissao_gerada numeric, obras_concluidas bigint, obras_em_aberto bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
  IF movelaria_meu_perfil() IS NULL THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  RETURN QUERY
  WITH montadores AS (
    SELECT
      u.id,
      COALESCE(NULLIF(TRIM(u.nome), ''), split_part(u.email, '@', 1)) AS nome
    FROM movelaria_usuarios u
    WHERE u.perfil IN ('montador', 'montador_admin')
      AND u.ativo = true
  ),
  concluida AS (
    SELECT
      ci.prestador_id,
      SUM(ci.valor) AS valor,
      COUNT(DISTINCT o.id) AS qtd
    FROM movelaria_obra_comissao_itens ci
    JOIN movelaria_obras o ON o.id = ci.obra_id
    WHERE o.status_kanban = 'concluida'
      AND o.finalizado_em IS NOT NULL
      AND o.comissao_habilitada = true
      AND ci.valor > 0
      AND EXTRACT(MONTH FROM o.finalizado_em AT TIME ZONE 'America/Sao_Paulo') = p_mes
      AND EXTRACT(YEAR  FROM o.finalizado_em AT TIME ZONE 'America/Sao_Paulo') = p_ano
    GROUP BY ci.prestador_id
  ),
  em_aberto AS (
    SELECT
      ci.prestador_id,
      SUM(ci.valor) AS valor,
      COUNT(DISTINCT o.id) AS qtd
    FROM movelaria_obra_comissao_itens ci
    JOIN movelaria_obras o ON o.id = ci.obra_id
    WHERE o.status_kanban NOT IN ('concluida', 'cancelada')
      AND o.comissao_habilitada = true
      AND ci.valor > 0
      AND EXTRACT(MONTH FROM movelaria_obra_data_referencia(o.data_prevista_fim, o.data_prevista_inicio, o.criado_em)) = p_mes
      AND EXTRACT(YEAR  FROM movelaria_obra_data_referencia(o.data_prevista_fim, o.data_prevista_inicio, o.criado_em)) = p_ano
    GROUP BY ci.prestador_id
  ),
  gerada AS (
    SELECT
      cp.prestador_id,
      SUM(cp.valor_parcela) AS valor
    FROM movelaria_contas_pagar cp
    WHERE cp.prestador_id IS NOT NULL
      AND (
        cp.prestador_id IS NOT NULL
        OR cp.descricao ILIKE 'Comissão:%'
        OR cp.obra_id IS NOT NULL
      )
      AND EXTRACT(MONTH FROM cp.data_vencimento AT TIME ZONE 'America/Sao_Paulo') = p_mes
      AND EXTRACT(YEAR  FROM cp.data_vencimento AT TIME ZONE 'America/Sao_Paulo') = p_ano
    GROUP BY cp.prestador_id
  )
  SELECT
    m.id,
    m.nome,
    COALESCE(c.valor, 0),
    COALESCE(a.valor, 0),
    COALESCE(g.valor, 0),
    COALESCE(c.qtd, 0),
    COALESCE(a.qtd, 0)
  FROM montadores m
  LEFT JOIN concluida c ON c.prestador_id = m.id
  LEFT JOIN em_aberto a ON a.prestador_id = m.id
  LEFT JOIN gerada g ON g.prestador_id = m.id
  WHERE COALESCE(c.valor, 0) > 0
     OR COALESCE(a.valor, 0) > 0
     OR COALESCE(g.valor, 0) > 0
  ORDER BY (COALESCE(c.valor, 0) + COALESCE(a.valor, 0) + COALESCE(g.valor, 0)) DESC, m.nome;
END;
$$;


--
-- Name: movelaria_metricas_obras_por_obra(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_metricas_obras_por_obra(p_mes integer DEFAULT (EXTRACT(month FROM CURRENT_DATE))::integer, p_ano integer DEFAULT (EXTRACT(year FROM CURRENT_DATE))::integer) RETURNS TABLE(obra_id uuid, montador_id uuid, montador_nome text, cliente_nome text, tipo_obra_nome text, status_kanban text, iniciado_em timestamp with time zone, finalizado_em timestamp with time zone, duracao_horas numeric, duracao_em_andamento boolean, mes_referencia date, comissao_habilitada boolean, comissao_valor numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_perfil TEXT := movelaria_meu_perfil();
  v_uid    UUID := auth.uid();
BEGIN
  IF v_perfil IS NULL THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  RETURN QUERY
  SELECT
    o.id,
    r.montador_id,
    COALESCE(NULLIF(TRIM(u.nome), ''), split_part(u.email, '@', 1)),
    o.cliente_nome,
    t.nome,
    o.status_kanban,
    r.iniciado_em,
    r.finalizado_em,
    CASE
      WHEN r.finalizado_em IS NOT NULL AND r.iniciado_em IS NOT NULL
        THEN ROUND(EXTRACT(EPOCH FROM (r.finalizado_em - r.iniciado_em)) / 3600.0, 4)
      WHEN r.iniciado_em IS NOT NULL AND r.finalizado_em IS NULL
        THEN ROUND(EXTRACT(EPOCH FROM (NOW() - r.iniciado_em)) / 3600.0, 4)
      ELSE NULL
    END,
    (r.iniciado_em IS NOT NULL AND r.finalizado_em IS NULL),
    movelaria_obra_data_referencia(o.data_prevista_fim, o.data_prevista_inicio, o.criado_em),
    o.comissao_habilitada,
    COALESCE((
      SELECT ci.valor
      FROM movelaria_obra_comissao_itens ci
      WHERE ci.obra_id = o.id
        AND ci.prestador_id = r.montador_id
        AND ci.valor > 0
    ), 0)
  FROM movelaria_obras o
  JOIN movelaria_obra_responsaveis r ON r.obra_id = o.id
  JOIN movelaria_usuarios u ON u.id = r.montador_id
  LEFT JOIN movelaria_tipos_obra t ON t.id = o.tipo_obra_id
  WHERE o.status_kanban != 'cancelada'
    AND (
      (
        EXTRACT(MONTH FROM movelaria_obra_data_referencia(o.data_prevista_fim, o.data_prevista_inicio, o.criado_em)) = p_mes
        AND EXTRACT(YEAR  FROM movelaria_obra_data_referencia(o.data_prevista_fim, o.data_prevista_inicio, o.criado_em)) = p_ano
      )
      OR (
        r.finalizado_em IS NOT NULL
        AND EXTRACT(MONTH FROM r.finalizado_em AT TIME ZONE 'America/Sao_Paulo') = p_mes
        AND EXTRACT(YEAR  FROM r.finalizado_em AT TIME ZONE 'America/Sao_Paulo') = p_ano
      )
      OR (
        r.iniciado_em IS NOT NULL
        AND EXTRACT(MONTH FROM r.iniciado_em AT TIME ZONE 'America/Sao_Paulo') = p_mes
        AND EXTRACT(YEAR  FROM r.iniciado_em AT TIME ZONE 'America/Sao_Paulo') = p_ano
      )
    )
    AND (
      v_perfil IN ('administrador', 'financeiro', 'administrador_obras', 'visualizador')
      OR (v_perfil = 'montador_admin' AND movelaria_montador_admin_acessa_obra(o.id, v_uid))
      OR (v_perfil = 'montador' AND movelaria_montador_acessa_obra(o.id, v_uid))
    )
  ORDER BY r.finalizado_em DESC NULLS LAST, r.iniciado_em DESC NULLS LAST, o.criado_em DESC, u.nome;
END;
$$;


--
-- Name: movelaria_metricas_obras_resumo(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_metricas_obras_resumo(p_mes integer DEFAULT (EXTRACT(month FROM CURRENT_DATE))::integer, p_ano integer DEFAULT (EXTRACT(year FROM CURRENT_DATE))::integer) RETURNS TABLE(comissao_a_pagar_mes numeric, comissao_em_aberto numeric, comissoes_geradas_mes numeric, obras_concluidas_mes bigint, obras_abertas_comissao bigint, mes_referencia integer, ano_referencia integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
  IF movelaria_meu_perfil() IS NULL THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  RETURN QUERY
  SELECT
    COALESCE((
      SELECT SUM(ci.valor)
      FROM movelaria_obra_comissao_itens ci
      JOIN movelaria_obras o ON o.id = ci.obra_id
      WHERE o.status_kanban = 'concluida'
        AND o.finalizado_em IS NOT NULL
        AND o.comissao_habilitada = true
        AND ci.valor > 0
        AND EXTRACT(MONTH FROM o.finalizado_em AT TIME ZONE 'America/Sao_Paulo') = p_mes
        AND EXTRACT(YEAR  FROM o.finalizado_em AT TIME ZONE 'America/Sao_Paulo') = p_ano
    ), 0),
    0::NUMERIC,
    COALESCE((
      SELECT SUM(cp.valor_parcela)
      FROM movelaria_contas_pagar cp
      WHERE (
          cp.prestador_id IS NOT NULL
          OR cp.descricao ILIKE 'Comissão:%'
          OR cp.obra_id IS NOT NULL
        )
        AND EXTRACT(MONTH FROM cp.data_vencimento AT TIME ZONE 'America/Sao_Paulo') = p_mes
        AND EXTRACT(YEAR  FROM cp.data_vencimento AT TIME ZONE 'America/Sao_Paulo') = p_ano
    ), 0),
    (
      SELECT COUNT(*)
      FROM movelaria_obras o
      WHERE o.status_kanban = 'concluida'
        AND o.finalizado_em IS NOT NULL
        AND EXTRACT(MONTH FROM o.finalizado_em AT TIME ZONE 'America/Sao_Paulo') = p_mes
        AND EXTRACT(YEAR  FROM o.finalizado_em AT TIME ZONE 'America/Sao_Paulo') = p_ano
    ),
    0::BIGINT,
    p_mes,
    p_ano;
END;
$$;


--
-- Name: movelaria_meu_perfil(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_meu_perfil() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT perfil
  FROM   movelaria_usuarios
  WHERE  id = auth.uid()
    AND  ativo = true
$$;


--
-- Name: movelaria_montador_acessa_obra(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_montador_acessa_obra(p_obra_id uuid, p_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM movelaria_obras o
    WHERE o.id = p_obra_id
      AND (
        o.montador_id = p_uid
        OR EXISTS (
          SELECT 1
          FROM movelaria_obra_responsaveis r
          WHERE r.obra_id = o.id AND r.montador_id = p_uid
        )
      )
  );
$$;


--
-- Name: movelaria_montador_admin_acessa_obra(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_montador_admin_acessa_obra(p_obra_id uuid, p_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM movelaria_obras o
    WHERE o.id = p_obra_id
      AND (
        o.montador_admin_id = p_uid
        OR EXISTS (
          SELECT 1
          FROM movelaria_grupos_obra g
          WHERE g.id = o.grupo_obra_id
            AND g.montador_admin_id = p_uid
        )
      )
  );
$$;


--
-- Name: movelaria_montador_admin_pode_acessar_obra(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_montador_admin_pode_acessar_obra(p_montador_admin_id uuid, p_grupo_obra_id uuid, p_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT
    p_montador_admin_id = p_uid
    OR EXISTS (
      SELECT 1
      FROM movelaria_grupos_obra g
      WHERE g.id = p_grupo_obra_id
        AND g.montador_admin_id = p_uid
    );
$$;


--
-- Name: movelaria_nome_destinatario_prestador(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_nome_destinatario_prestador(p_prestador_id uuid, p_is_comissao boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_nome TEXT;
BEGIN
  IF p_prestador_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(NULLIF(TRIM(u.nome), ''), split_part(u.email, '@', 1))
  INTO v_nome
  FROM movelaria_usuarios u
  WHERE u.id = p_prestador_id;

  IF NULLIF(TRIM(v_nome), '') IS NULL THEN
    RETURN NULL;
  END IF;

  IF p_is_comissao THEN
    RETURN 'Comissão: ' || v_nome;
  END IF;

  RETURN v_nome;
END;
$$;


--
-- Name: movelaria_normalizar_import_texto(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_normalizar_import_texto(p_texto text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  RETURN lower(
    regexp_replace(
      translate(
        COALESCE(p_texto, ''),
        'áàâãäéèêëíìîïóòôõöúùûüçñÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑ',
        'aaaaaeeeeiiiiooooouuuucnAAAAAEEEEIIIIOOOOOUUUUCN'
      ),
      '[^a-z0-9]',
      '',
      'g'
    )
  );
END;
$$;


--
-- Name: movelaria_obra_before_insert_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_obra_before_insert_defaults() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_perfil TEXT := movelaria_meu_perfil();
  v_uid    UUID := auth.uid();
BEGIN
  IF v_perfil = 'montador_admin' AND v_uid IS NOT NULL THEN
    NEW.montador_admin_id := v_uid;

    IF NEW.grupo_obra_id IS NULL THEN
      SELECT g.id
      INTO NEW.grupo_obra_id
      FROM movelaria_grupos_obra g
      WHERE g.montador_admin_id = v_uid
        AND g.ativo = true
      ORDER BY g.nome
      LIMIT 1;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: movelaria_obra_before_update_limpa_finalizacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_obra_before_update_limpa_finalizacao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status_kanban IS DISTINCT FROM 'concluida'
     AND COALESCE(NEW.finalizado_em, OLD.finalizado_em) IS NOT NULL THEN
    NEW.finalizado_em := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: movelaria_obra_before_update_montador_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_obra_before_update_montador_admin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF movelaria_usuario_tem_perfil('montador_admin')
     AND NOT movelaria_usuario_tem_algum_perfil(
       ARRAY['administrador', 'financeiro', 'administrador_obras']
     )
     AND v_uid IS NOT NULL
  THEN
    IF EXISTS (
      SELECT 1
      FROM movelaria_grupos_obra g
      WHERE g.id = NEW.grupo_obra_id
        AND g.montador_admin_id = v_uid
    ) THEN
      NEW.montador_admin_id := v_uid;
    ELSIF NEW.montador_admin_id IS NULL THEN
      NEW.montador_admin_id := v_uid;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: movelaria_obra_data_referencia(date, date, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_obra_data_referencia(p_data_fim date, p_data_inicio date, p_criado_em timestamp with time zone) RETURNS date
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT COALESCE(p_data_fim, p_data_inicio, p_criado_em::DATE);
$$;


--
-- Name: movelaria_obra_datas_after_update_historico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_obra_datas_after_update_historico() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.data_prevista_inicio IS DISTINCT FROM OLD.data_prevista_inicio
     OR NEW.data_prevista_fim IS DISTINCT FROM OLD.data_prevista_fim
  THEN
    -- Só registra se já havia alguma data antes OU se ambas mudaram de null→valor
    -- (reajustes e primeiras definições posteriores a create parcial)
    INSERT INTO movelaria_obras_datas_historico (
      obra_id,
      data_inicio_anterior,
      data_fim_anterior,
      data_inicio_nova,
      data_fim_nova,
      alterado_por
    ) VALUES (
      NEW.id,
      OLD.data_prevista_inicio,
      OLD.data_prevista_fim,
      NEW.data_prevista_inicio,
      NEW.data_prevista_fim,
      auth.uid()
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: movelaria_obra_datas_before_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_obra_datas_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.data_prevista_inicio IS NOT NULL AND NEW.data_prevista_inicio_original IS NULL THEN
      NEW.data_prevista_inicio_original := NEW.data_prevista_inicio;
    END IF;
    IF NEW.data_prevista_fim IS NOT NULL AND NEW.data_prevista_fim_original IS NULL THEN
      NEW.data_prevista_fim_original := NEW.data_prevista_fim;
    END IF;
  ELSE
    -- UPDATE: originais só na 1ª definição; nunca sobrescreve
    IF OLD.data_prevista_inicio_original IS NOT NULL THEN
      NEW.data_prevista_inicio_original := OLD.data_prevista_inicio_original;
    ELSIF NEW.data_prevista_inicio IS NOT NULL THEN
      NEW.data_prevista_inicio_original := NEW.data_prevista_inicio;
    END IF;

    IF OLD.data_prevista_fim_original IS NOT NULL THEN
      NEW.data_prevista_fim_original := OLD.data_prevista_fim_original;
    ELSIF NEW.data_prevista_fim IS NOT NULL THEN
      NEW.data_prevista_fim_original := NEW.data_prevista_fim;
    END IF;

    -- Impede limpar a marca (mesmo se o client tentar)
    IF COALESCE(OLD.atraso_permanente, false) THEN
      NEW.atraso_permanente := true;
      NEW.atraso_marcado_em := COALESCE(OLD.atraso_marcado_em, NEW.atraso_marcado_em, now());
    END IF;
  END IF;

  -- Atraso permanente: liga se o prazo (atual OU anterior no update) já venceu
  -- com obra aberta. Assim, reagendar para o futuro NÃO limpa o atraso.
  IF NEW.status_kanban IS DISTINCT FROM 'concluida'
     AND NEW.status_kanban IS DISTINCT FROM 'cancelada'
  THEN
    IF (
         (NEW.data_prevista_fim IS NOT NULL AND NEW.data_prevista_fim < CURRENT_DATE)
         OR (
           TG_OP = 'UPDATE'
           AND OLD.data_prevista_fim IS NOT NULL
           AND OLD.data_prevista_fim < CURRENT_DATE
         )
       )
       AND NOT COALESCE(NEW.atraso_permanente, false)
    THEN
      NEW.atraso_permanente := true;
      NEW.atraso_marcado_em := COALESCE(NEW.atraso_marcado_em, now());
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: movelaria_obra_mes_entrega(date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_obra_mes_entrega(p_data_fim date, p_mes integer, p_ano integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_data_fim IS NOT NULL
    AND EXTRACT(MONTH FROM p_data_fim) = p_mes
    AND EXTRACT(YEAR FROM p_data_fim) = p_ano;
$$;


--
-- Name: movelaria_obra_todos_montadores_concluiram(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_obra_todos_montadores_concluiram(p_obra_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_total INT;
  v_pendentes INT;
BEGIN
  SELECT COUNT(*), COUNT(*) FILTER (WHERE r.finalizado_em IS NULL)
  INTO v_total, v_pendentes
  FROM movelaria_obra_responsaveis r
  WHERE r.obra_id = p_obra_id;

  IF v_total = 0 THEN
    RETURN true;
  END IF;

  RETURN v_pendentes = 0;
END;
$$;


--
-- Name: movelaria_obter_meu_usuario(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_obter_meu_usuario() RETURNS TABLE(id uuid, email text, nome text, perfil text, perfis_extras text[], ativo boolean, criado_em timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
    SELECT u.id, u.email, u.nome, u.perfil, u.perfis_extras, u.ativo, u.criado_em
    FROM   movelaria_usuarios u
    WHERE  u.id = auth.uid();
END;
$$;


--
-- Name: movelaria_obter_minha_identidade(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_obter_minha_identidade() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid   UUID := auth.uid();
  v_mov   JSONB;
  v_crm   JSONB;
  v_roles TEXT[];
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('movelaria', NULL, 'crm', NULL);
  END IF;

  SELECT jsonb_build_object(
    'id', u.id,
    'email', u.email,
    'nome', u.nome,
    'perfil', u.perfil,
    'perfis_extras', COALESCE(u.perfis_extras, '{}'::TEXT[]),
    'ativo', u.ativo,
    'criado_em', u.criado_em
  )
  INTO v_mov
  FROM public.movelaria_usuarios u
  WHERE u.id = v_uid;

  SELECT COALESCE(array_agg(r.role::TEXT ORDER BY r.role::TEXT), '{}'::TEXT[])
  INTO v_roles
  FROM emp_garbo.user_roles r
  WHERE r.user_id = v_uid;

  SELECT jsonb_build_object(
    'id', c.id,
    'nome', c.nome,
    'email', c.email,
    'tipo_usuario', c.tipo_usuario,
    'status_convite', c.status_convite,
    'roles', COALESCE(v_roles, '{}'::TEXT[]),
    'horario_acesso_inicio', to_char(c.horario_acesso_inicio, 'HH24:MI'),
    'horario_acesso_fim', to_char(c.horario_acesso_fim, 'HH24:MI'),
    'titulo', c.titulo,
    'comissao_ativa', c.comissao_ativa
  )
  INTO v_crm
  FROM emp_garbo.usuarios c
  WHERE c.id = v_uid;

  RETURN jsonb_build_object(
    'movelaria', v_mov,
    'crm', v_crm
  );
END;
$$;


--
-- Name: movelaria_painel_evolucao(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_painel_evolucao(p_inicio timestamp with time zone, p_fim timestamp with time zone) RETURNS TABLE(id uuid, obra_id uuid, obra_nome text, nome_arquivo text, kind text, storage_path text, preview_path text, tirado_em timestamp with time zone, criado_por uuid, criador_nome text, observacao text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_perfil TEXT := movelaria_meu_perfil();
  v_uid    UUID := auth.uid();
BEGIN
  RETURN QUERY
  SELECT
    e.id, e.obra_id, o.cliente_nome,
    e.nome_arquivo, e.kind,
    e.storage_path, e.preview_path,
    e.tirado_em, e.criado_por,
    u.nome,
    NULLIF(TRIM(e.observacao), '')
  FROM movelaria_obra_evolucao e
  JOIN movelaria_obras o ON o.id = e.obra_id
  LEFT JOIN movelaria_usuarios u ON u.id = e.criado_por
  WHERE e.tirado_em >= p_inicio
    AND e.tirado_em <= p_fim
    AND (
      v_perfil IN ('administrador', 'financeiro', 'administrador_obras', 'visualizador')
      OR (v_perfil = 'montador_admin' AND movelaria_montador_admin_acessa_obra(o.id, v_uid))
      OR (v_perfil = 'montador' AND movelaria_montador_acessa_obra(o.id, v_uid))
    )
  ORDER BY e.tirado_em DESC;
END;
$$;


