--
-- Name: movelaria_ponto_ajustar_marcacao(uuid, time without time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_ajustar_marcacao(p_marcacao_id uuid, p_hora time without time zone, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_marc movelaria_funcionario_ponto_marcacoes%ROWTYPE;
  v_jornada movelaria_funcionario_jornada%ROWTYPE;
  v_data DATE;
  v_ajustado TIMESTAMPTZ;
  v_hora TIME;
  v_hora_ref TIME;
  v_atraso INT := 0;
  v_status TEXT := 'normal';
  v_motivo TEXT := trim(COALESCE(p_motivo, ''));
BEGIN
  IF p_hora IS NULL THEN
    RAISE EXCEPTION 'Informe o novo horário.';
  END IF;

  IF length(v_motivo) < 3 THEN
    RAISE EXCEPTION 'Informe o motivo do ajuste (mínimo 3 caracteres).';
  END IF;

  SELECT * INTO v_marc
  FROM movelaria_funcionario_ponto_marcacoes
  WHERE id = p_marcacao_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Marcação não encontrada.';
  END IF;

  PERFORM movelaria_ponto_assert_edicao_registros(v_marc.funcionario_id);

  v_data := movelaria_ponto_data_local(v_marc.registrado_em);
  v_ajustado := ((v_data + p_hora) AT TIME ZONE 'America/Sao_Paulo');
  v_hora := p_hora;

  SELECT * INTO v_jornada
  FROM movelaria_funcionario_jornada
  WHERE funcionario_id = v_marc.funcionario_id AND ativo = true;

  IF FOUND THEN
    IF v_marc.tipo = 'entrada' THEN
      v_hora_ref := v_jornada.hora_entrada;
    ELSIF v_marc.tipo = 'retorno_intervalo' THEN
      v_hora_ref := v_jornada.hora_retorno_intervalo;
    END IF;

    IF v_hora_ref IS NOT NULL THEN
      v_atraso := GREATEST(0,
        EXTRACT(EPOCH FROM (v_hora - v_hora_ref)) / 60 - v_jornada.tolerancia_minutos
      )::INT;
      IF v_atraso > 0 THEN v_status := 'atraso'; END IF;
    END IF;
  END IF;

  UPDATE movelaria_funcionario_ponto_marcacoes
  SET
    registrado_em_ajustado = v_ajustado,
    ajuste_motivo = v_motivo,
    ajustado_por = auth.uid(),
    ajustado_em = NOW(),
    atraso_minutos = v_atraso,
    status = v_status
  WHERE id = p_marcacao_id
  RETURNING * INTO v_marc;

  RETURN to_jsonb(v_marc);
END;
$$;


--
-- Name: movelaria_ponto_assert_edicao_registros(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_assert_edicao_registros(p_funcionario_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_perfil TEXT := movelaria_meu_perfil();
  v_uid UUID;
BEGIN
  IF v_perfil IN ('administrador', 'financeiro') THEN
    RETURN;
  END IF;

  IF v_perfil IS DISTINCT FROM 'montador_admin' THEN
    RAISE EXCEPTION 'Sem permissão para alterar registros de ponto.';
  END IF;

  SELECT usuario_id INTO v_uid
  FROM movelaria_funcionarios
  WHERE id = p_funcionario_id;

  IF v_uid IS NOT NULL AND v_uid = auth.uid() THEN
    RAISE EXCEPTION 'Ponto de sua titularidade não poderá ser alterado.';
  END IF;
END;
$$;


--
-- Name: movelaria_ponto_atualizar_comprovante(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_atualizar_comprovante(p_marcacao_id uuid, p_comprovante_path text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Permite service role / edge function via SECURITY DEFINER
  UPDATE movelaria_funcionario_ponto_marcacoes
  SET comprovante_pdf_path = p_comprovante_path
  WHERE id = p_marcacao_id;
END;
$$;


--
-- Name: movelaria_ponto_banco_componentes(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_banco_componentes(p_funcionario_id uuid, p_inicio date, p_fim date) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_he INT := 0;
  v_atrasos INT := 0;
  v_faltas INT := 0;
  v_pagas INT := 0;
BEGIN
  IF p_inicio IS NULL OR p_fim IS NULL OR p_fim < p_inicio THEN
    RETURN jsonb_build_object(
      'hora_extra_minutos', 0,
      'atrasos_minutos', 0,
      'faltas_banco_minutos', 0,
      'he_pagas_minutos', 0,
      'saldo_minutos', 0
    );
  END IF;

  SELECT COALESCE(SUM(
    GREATEST(
      0,
      FLOOR(
        EXTRACT(
          EPOCH FROM (
            movelaria_ponto_hora_local(
              movelaria_ponto_ts_efetivo(m.registrado_em, m.registrado_em_ajustado)
            ) - j.hora_saida
          )
        ) / 60
      )::INT
    )
  ), 0)::INT
  INTO v_he
  FROM movelaria_funcionario_ponto_marcacoes m
  INNER JOIN movelaria_funcionario_jornada j
    ON j.funcionario_id = p_funcionario_id AND j.ativo = true
  WHERE m.funcionario_id = p_funcionario_id
    AND m.tipo = 'saida'
    AND movelaria_ponto_data_local(m.registrado_em) BETWEEN p_inicio AND p_fim;

  SELECT COALESCE(SUM(GREATEST(0, COALESCE(m.atraso_minutos, 0))), 0)::INT
  INTO v_atrasos
  FROM movelaria_funcionario_ponto_marcacoes m
  WHERE m.funcionario_id = p_funcionario_id
    AND m.tipo = 'entrada'
    AND movelaria_ponto_data_local(m.registrado_em) BETWEEN p_inicio AND p_fim;

  SELECT COALESCE(SUM(
    movelaria_ponto_falta_minutos_debito(
      o.funcionario_id, o.data, o.abater_banco_horas, o.minutos_abatidos, o.observacao
    )
  ), 0)::INT
  INTO v_faltas
  FROM movelaria_funcionario_ponto_ocorrencias o
  WHERE o.funcionario_id = p_funcionario_id
    AND o.tipo = 'falta'
    AND o.data BETWEEN p_inicio AND p_fim;

  SELECT COALESCE(SUM(bm.minutos), 0)::INT
  INTO v_pagas
  FROM movelaria_ponto_banco_movimentos bm
  WHERE bm.funcionario_id = p_funcionario_id
    AND bm.tipo = 'pagamento_he'
    AND movelaria_ponto_data_local(bm.criado_em) BETWEEN p_inicio AND p_fim;

  RETURN jsonb_build_object(
    'hora_extra_minutos', v_he,
    'atrasos_minutos', v_atrasos,
    'faltas_banco_minutos', v_faltas,
    'he_pagas_minutos', v_pagas,
    'saldo_minutos', v_he - v_atrasos - v_faltas - v_pagas
  );
END;
$$;


--
-- Name: movelaria_ponto_bater(uuid, text, text, double precision, double precision, double precision, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_bater(p_marcacao_id uuid, p_foto_path text, p_assinatura_path text, p_latitude double precision, p_longitude double precision, p_precisao_metros double precision, p_hash_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_funcionario movelaria_funcionarios%ROWTYPE;
  v_jornada movelaria_funcionario_jornada%ROWTYPE;
  v_tipo TEXT;
  v_data DATE := movelaria_ponto_data_local();
  v_hora TIME := movelaria_ponto_hora_local();
  v_dow INT := movelaria_ponto_dia_semana_local();
  v_hora_ref TIME;
  v_atraso INT := 0;
  v_status TEXT := 'normal';
  v_marc movelaria_funcionario_ponto_marcacoes%ROWTYPE;
  v_doc_id UUID;
  v_comprovante_path TEXT;
  v_nome_comprovante TEXT;
BEGIN
  SELECT * INTO v_funcionario
  FROM movelaria_funcionarios
  WHERE usuario_id = auth.uid() AND ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Nenhum cadastro de funcionário vinculado ao seu usuário.';
  END IF;

  IF v_funcionario.tipo NOT IN ('montador', 'montador_admin', 'administrador_obras') THEN
    RAISE EXCEPTION 'Seu perfil não está habilitado para bater ponto.';
  END IF;

  SELECT * INTO v_jornada
  FROM movelaria_funcionario_jornada
  WHERE funcionario_id = v_funcionario.id AND ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Jornada de trabalho não configurada. Contate o RH.';
  END IF;

  IF NOT (v_dow = ANY(v_jornada.dias_uteis)) THEN
    RAISE EXCEPTION 'Hoje não é dia útil na sua jornada.';
  END IF;

  -- Se a pessoa está batendo ponto, remove falta automática indevida do dia
  DELETE FROM movelaria_funcionario_ponto_ocorrencias
  WHERE funcionario_id = v_funcionario.id
    AND data = v_data
    AND tipo = 'falta'
    AND COALESCE(automatica, false) = true;

  -- Só bloqueia folga ou falta MANUAL (lançada pelo RH)
  IF EXISTS (
    SELECT 1 FROM movelaria_funcionario_ponto_ocorrencias
    WHERE funcionario_id = v_funcionario.id
      AND data = v_data
      AND (
        tipo = 'folga'
        OR (tipo = 'falta' AND COALESCE(automatica, false) = false)
      )
  ) THEN
    RAISE EXCEPTION 'Não é possível bater ponto: folga ou falta registrada para hoje.';
  END IF;

  v_tipo := movelaria_ponto_proximo_tipo(v_funcionario.id, v_data);
  IF v_tipo IS NULL THEN
    RAISE EXCEPTION 'Todas as batidas de hoje já foram registradas.';
  END IF;

  IF p_latitude IS NULL OR p_longitude IS NULL THEN
    RAISE EXCEPTION 'Localização é obrigatória para registrar o ponto.';
  END IF;

  IF p_foto_path IS NULL OR p_assinatura_path IS NULL THEN
    RAISE EXCEPTION 'Foto e assinatura são obrigatórias.';
  END IF;

  IF v_tipo = 'entrada' THEN
    v_hora_ref := v_jornada.hora_entrada;
  ELSIF v_tipo = 'retorno_intervalo' THEN
    v_hora_ref := v_jornada.hora_retorno_intervalo;
  END IF;

  IF v_hora_ref IS NOT NULL THEN
    v_atraso := GREATEST(0,
      EXTRACT(EPOCH FROM (v_hora - v_hora_ref)) / 60 - v_jornada.tolerancia_minutos
    )::INT;
    IF v_atraso > 0 THEN v_status := 'atraso'; END IF;
  END IF;

  v_comprovante_path := v_funcionario.id::text || '/ponto/' || p_marcacao_id::text || '/comprovante.pdf';
  v_nome_comprovante := 'Comprovante Ponto ' || TO_CHAR(NOW() AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI') || '.pdf';

  INSERT INTO movelaria_funcionario_documentos (
    id, funcionario_id, categoria, tipo_documento, nome_arquivo,
    tipo_mime, storage_path, preview_path, kind, origem
  ) VALUES (
    gen_random_uuid(), v_funcionario.id, 'ponto', 'comprovante_ponto', v_nome_comprovante,
    'application/pdf', v_comprovante_path, p_foto_path, 'pdf', 'funcionario_sistema'
  )
  RETURNING id INTO v_doc_id;

  INSERT INTO movelaria_funcionario_ponto_marcacoes (
    id, funcionario_id, usuario_id, tipo,
    latitude, longitude, precisao_metros,
    foto_path, assinatura_path, comprovante_pdf_path, documento_id,
    hash_sha256, status, atraso_minutos
  ) VALUES (
    p_marcacao_id, v_funcionario.id, auth.uid(), v_tipo,
    p_latitude, p_longitude, p_precisao_metros,
    p_foto_path, p_assinatura_path, v_comprovante_path, v_doc_id,
    COALESCE(p_hash_sha256, ''), v_status, v_atraso
  )
  RETURNING * INTO v_marc;

  UPDATE movelaria_rep_config SET nsr_atual = v_marc.nsr, atualizado_em = NOW()
  WHERE ativo = true;

  RETURN jsonb_build_object(
    'marcacao', to_jsonb(v_marc),
    'documento_id', v_doc_id,
    'funcionario_id', v_funcionario.id,
    'funcionario_nome', v_funcionario.nome,
    'comprovante_path', v_comprovante_path
  );
END;
$$;


--
-- Name: movelaria_ponto_data_local(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_data_local(p_ts timestamp with time zone DEFAULT now()) RETURNS date
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT (p_ts AT TIME ZONE 'America/Sao_Paulo')::DATE;
$$;


--
-- Name: movelaria_ponto_controle_diario(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_controle_diario(p_data date DEFAULT public.movelaria_ponto_data_local()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF movelaria_meu_perfil() NOT IN ('administrador', 'financeiro', 'montador_admin') THEN
    RAISE EXCEPTION 'Sem permissão para visualizar o controle de ponto.';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(row ORDER BY row->>'nome')
    FROM (
      SELECT jsonb_build_object(
        'funcionario_id', f.id,
        'nome', f.nome,
        'tipo', f.tipo,
        'hora_prevista', j.hora_entrada,
        'jornada', CASE WHEN j.id IS NOT NULL THEN jsonb_build_object(
          'hora_entrada', j.hora_entrada,
          'hora_saida_intervalo', j.hora_saida_intervalo,
          'hora_retorno_intervalo', j.hora_retorno_intervalo,
          'hora_saida', j.hora_saida
        ) ELSE NULL END,
        'status_dia', COALESCE(
          (movelaria_ponto_status_dia(f.id, p_data)->>'status_dia'),
          'pendente'
        ),
        'ocorrencia', (movelaria_ponto_status_dia(f.id, p_data)->>'ocorrencia'),
        'entrada', (
          SELECT to_jsonb(m)
          FROM movelaria_funcionario_ponto_marcacoes m
          WHERE m.funcionario_id = f.id
            AND m.tipo = 'entrada'
            AND movelaria_ponto_data_local(m.registrado_em) = p_data
          ORDER BY m.registrado_em DESC
          LIMIT 1
        ),
        'marcacoes', COALESCE((
          SELECT jsonb_agg(to_jsonb(m) ORDER BY m.registrado_em)
          FROM movelaria_funcionario_ponto_marcacoes m
          WHERE m.funcionario_id = f.id
            AND movelaria_ponto_data_local(m.registrado_em) = p_data
        ), '[]'::jsonb)
      ) AS row
      FROM movelaria_funcionarios f
      LEFT JOIN movelaria_funcionario_jornada j ON j.funcionario_id = f.id AND j.ativo = true
      WHERE f.ativo = true
        AND f.tipo IN ('montador', 'montador_admin', 'administrador_obras')
    ) sub
  ), '[]'::jsonb);
END;
$$;


--
-- Name: movelaria_ponto_data_faltas_ate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_data_faltas_ate() RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN EXTRACT(HOUR FROM (NOW() AT TIME ZONE 'America/Sao_Paulo')) >= 23
      THEN movelaria_ponto_data_local()
    ELSE movelaria_ponto_data_local() - 1
  END;
$$;


--
-- Name: movelaria_ponto_data_inicio_vinculo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_data_inicio_vinculo(p_funcionario_id uuid) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    NULLIF(f.admissao_dados->>'data_admissao', '')::DATE,
    movelaria_ponto_data_local(f.criado_em)
  )
  FROM movelaria_funcionarios f
  WHERE f.id = p_funcionario_id;
$$;


--
-- Name: movelaria_ponto_desconsiderar_falta(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_desconsiderar_falta(p_funcionario_id uuid, p_data date, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_funcionario movelaria_funcionarios%ROWTYPE;
  v_jornada movelaria_funcionario_jornada%ROWTYPE;
  v_motivo TEXT := trim(COALESCE(p_motivo, ''));
  v_dow INT;
  v_hora_entrada TIME;
  v_hora_saida_intervalo TIME;
  v_hora_retorno_intervalo TIME;
  v_hora_saida TIME;
  v_tipos TEXT[];
  v_horas TIME[];
  v_i INT;
  v_tipo TEXT;
  v_hora TIME;
  v_registrado TIMESTAMPTZ;
  v_hash TEXT;
  v_marc movelaria_funcionario_ponto_marcacoes%ROWTYPE;
  v_marcacoes JSONB := '[]'::JSONB;
  v_ultimo_nsr BIGINT := 0;
BEGIN
  IF movelaria_meu_perfil() NOT IN ('administrador', 'financeiro') THEN
    RAISE EXCEPTION 'Sem permissão para desconsiderar falta.';
  END IF;

  IF p_funcionario_id IS NULL THEN
    RAISE EXCEPTION 'Informe o funcionário.';
  END IF;

  IF p_data IS NULL THEN
    RAISE EXCEPTION 'Informe a data da falta.';
  END IF;

  IF length(v_motivo) < 3 THEN
    RAISE EXCEPTION 'Informe o motivo (mínimo 3 caracteres).';
  END IF;

  IF p_data > movelaria_ponto_data_local() THEN
    RAISE EXCEPTION 'Não é possível desconsiderar falta em data futura.';
  END IF;

  SELECT * INTO v_funcionario
  FROM movelaria_funcionarios
  WHERE id = p_funcionario_id AND ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Funcionário não encontrado ou inativo.';
  END IF;

  IF v_funcionario.usuario_id IS NULL THEN
    RAISE EXCEPTION 'Funcionário sem usuário vinculado — não é possível gerar batida oficial.';
  END IF;

  IF v_funcionario.tipo NOT IN ('montador', 'montador_admin', 'administrador_obras') THEN
    RAISE EXCEPTION 'Este perfil de funcionário não usa ponto eletrônico.';
  END IF;

  SELECT * INTO v_jornada
  FROM movelaria_funcionario_jornada
  WHERE funcionario_id = v_funcionario.id AND ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Jornada de trabalho não configurada para este funcionário.';
  END IF;

  v_dow := EXTRACT(ISODOW FROM p_data)::INT;
  IF NOT (v_dow = ANY(v_jornada.dias_uteis)) THEN
    RAISE EXCEPTION 'A data informada não é dia útil na jornada deste funcionário.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM movelaria_funcionario_ponto_ocorrencias
    WHERE funcionario_id = v_funcionario.id
      AND data = p_data
      AND tipo IN ('folga', 'abono')
  ) THEN
    RAISE EXCEPTION 'Não é possível desconsiderar: há folga ou abono neste dia.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM movelaria_funcionario_ponto_marcacoes
    WHERE funcionario_id = v_funcionario.id
      AND movelaria_ponto_data_local(registrado_em) = p_data
  ) THEN
    RAISE EXCEPTION 'Já existem batidas neste dia — não é possível desconsiderar a falta.';
  END IF;

  v_hora_entrada := movelaria_jornada_hora_no_dia(v_jornada, v_dow, 'chegada');
  v_hora_saida_intervalo := movelaria_jornada_hora_no_dia(v_jornada, v_dow, 'saida_almoco');
  v_hora_retorno_intervalo := movelaria_jornada_hora_no_dia(v_jornada, v_dow, 'retorno_almoco');
  v_hora_saida := movelaria_jornada_hora_no_dia(v_jornada, v_dow, 'saida_servico');

  IF v_hora_entrada IS NULL OR v_hora_saida IS NULL THEN
    RAISE EXCEPTION 'Jornada incompleta: faltam horário de entrada ou saída.';
  END IF;

  IF v_hora_saida_intervalo IS NOT NULL AND v_hora_retorno_intervalo IS NOT NULL THEN
    v_tipos := ARRAY['entrada', 'saida_intervalo', 'retorno_intervalo', 'saida'];
    v_horas := ARRAY[v_hora_entrada, v_hora_saida_intervalo, v_hora_retorno_intervalo, v_hora_saida];
  ELSE
    v_tipos := ARRAY['entrada', 'saida'];
    v_horas := ARRAY[v_hora_entrada, v_hora_saida];
  END IF;

  -- Remove qualquer falta do dia (automática ou justificada / abatida)
  DELETE FROM movelaria_funcionario_ponto_ocorrencias
  WHERE funcionario_id = v_funcionario.id
    AND data = p_data
    AND tipo = 'falta';

  FOR v_i IN 1 .. array_length(v_tipos, 1) LOOP
    v_tipo := v_tipos[v_i];
    v_hora := v_horas[v_i];
    v_registrado := ((p_data + v_hora) AT TIME ZONE 'America/Sao_Paulo');

    v_hash := encode(
      extensions.digest(
        (
          'rh_manual|desconsiderar|' || v_funcionario.id::text || '|' || v_tipo || '|' ||
          p_data::text || '|' || v_hora::text || '|' || v_motivo || '|' ||
          COALESCE(auth.uid()::text, '') || '|' || clock_timestamp()::text || '|' || v_i::text
        )::bytea,
        'sha256'
      ),
      'hex'
    );

    INSERT INTO movelaria_funcionario_ponto_marcacoes (
      funcionario_id, usuario_id, tipo, registrado_em,
      hash_sha256, status, atraso_minutos, offline,
      origem, registro_motivo,
      ajuste_motivo, ajustado_por, ajustado_em
    ) VALUES (
      v_funcionario.id, v_funcionario.usuario_id, v_tipo, v_registrado,
      v_hash, 'normal', 0, false,
      'rh_manual', v_motivo,
      'Desconsiderar falta: ' || v_motivo, auth.uid(), NOW()
    )
    RETURNING * INTO v_marc;

    v_ultimo_nsr := v_marc.nsr;
    v_marcacoes := v_marcacoes || jsonb_build_array(to_jsonb(v_marc));
  END LOOP;

  UPDATE movelaria_rep_config
  SET nsr_atual = v_ultimo_nsr, atualizado_em = NOW()
  WHERE ativo = true;

  RETURN jsonb_build_object(
    'funcionario_id', v_funcionario.id,
    'data', to_char(p_data, 'YYYY-MM-DD'),
    'motivo', v_motivo,
    'marcacoes', v_marcacoes,
    'nsr_ultimo', v_ultimo_nsr
  );
END;
$$;


--
-- Name: movelaria_ponto_detectar_faltas(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_detectar_faltas(p_data date DEFAULT public.movelaria_ponto_data_local((now() - '1 day'::interval))) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INT := 0;
  v_rec RECORD;
  v_hora_sp INT := EXTRACT(HOUR FROM (NOW() AT TIME ZONE 'America/Sao_Paulo'))::INT;
  v_minutos INT;
BEGIN
  IF p_data > movelaria_ponto_data_local() THEN
    RETURN 0;
  END IF;
  IF p_data = movelaria_ponto_data_local() AND v_hora_sp < 23 THEN
    RETURN 0;
  END IF;

  FOR v_rec IN
    SELECT j.funcionario_id
    FROM movelaria_funcionario_jornada j
    JOIN movelaria_funcionarios f ON f.id = j.funcionario_id AND f.ativo = true
    WHERE j.ativo = true
      AND f.tipo IN ('montador', 'montador_admin', 'administrador_obras')
      AND EXTRACT(ISODOW FROM p_data)::INT = ANY(j.dias_uteis)
      AND p_data >= movelaria_ponto_data_inicio_vinculo(f.id)
      AND p_data <= movelaria_ponto_data_local()
      AND NOT EXISTS (
        SELECT 1 FROM movelaria_funcionario_ponto_marcacoes m
        WHERE m.funcionario_id = j.funcionario_id
          AND movelaria_ponto_data_local(m.registrado_em) = p_data
      )
      AND NOT EXISTS (
        SELECT 1 FROM movelaria_funcionario_ponto_ocorrencias o
        WHERE o.funcionario_id = j.funcionario_id
          AND o.data = p_data
          AND o.tipo IN ('folga', 'abono', 'falta')
      )
  LOOP
    v_minutos := movelaria_jornada_minutos_no_dia(v_rec.funcionario_id, p_data);

    INSERT INTO movelaria_funcionario_ponto_ocorrencias (
      funcionario_id, data, tipo, observacao, automatica,
      abater_banco_horas, minutos_abatidos
    ) VALUES (
      v_rec.funcionario_id, p_data, 'falta', 'Falta detectada automaticamente.', true,
      true, NULLIF(v_minutos, 0)
    )
    ON CONFLICT (funcionario_id, data, tipo) DO NOTHING;
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: movelaria_ponto_dia_semana_local(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_dia_semana_local(p_ts timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT EXTRACT(ISODOW FROM (p_ts AT TIME ZONE 'America/Sao_Paulo'))::INT;
$$;


--
-- Name: movelaria_ponto_falta_debita_caixa(boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_falta_debita_caixa(p_abater boolean, p_observacao text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(p_abater, false)
    OR NOT movelaria_ponto_falta_tem_justificativa(p_observacao);
$$;


--
-- Name: movelaria_ponto_falta_minutos_debito(uuid, date, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_falta_minutos_debito(p_funcionario_id uuid, p_data date, p_abater boolean, p_minutos integer, p_observacao text) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_debita BOOLEAN;
BEGIN
  v_debita := COALESCE(p_abater, false)
    OR NOT movelaria_ponto_falta_tem_justificativa(p_observacao);
  IF NOT v_debita THEN
    RETURN 0;
  END IF;
  RETURN GREATEST(
    0,
    COALESCE(
      NULLIF(p_minutos, 0),
      movelaria_jornada_minutos_no_dia(p_funcionario_id, p_data),
      0
    )
  );
END;
$$;


--
-- Name: movelaria_ponto_falta_tem_justificativa(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_falta_tem_justificativa(p_observacao text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT NULLIF(trim(COALESCE(p_observacao, '')), '') IS NOT NULL
    AND trim(p_observacao) <> 'Falta detectada automaticamente.';
$$;


--
-- Name: movelaria_ponto_nsr_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.movelaria_ponto_nsr_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: movelaria_funcionario_ponto_marcacoes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.movelaria_funcionario_ponto_marcacoes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nsr bigint DEFAULT nextval('public.movelaria_ponto_nsr_seq'::regclass) NOT NULL,
    funcionario_id uuid NOT NULL,
    usuario_id uuid,
    tipo text NOT NULL,
    registrado_em timestamp with time zone DEFAULT now() NOT NULL,
    latitude double precision,
    longitude double precision,
    precisao_metros double precision,
    foto_path text,
    assinatura_path text,
    comprovante_pdf_path text,
    documento_id uuid,
    hash_sha256 text DEFAULT ''::text NOT NULL,
    status text DEFAULT 'normal'::text NOT NULL,
    atraso_minutos integer DEFAULT 0 NOT NULL,
    offline boolean DEFAULT false NOT NULL,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    registrado_em_ajustado timestamp with time zone,
    ajuste_motivo text,
    ajustado_por uuid,
    ajustado_em timestamp with time zone,
    origem text DEFAULT 'app'::text NOT NULL,
    registro_motivo text,
    CONSTRAINT movelaria_funcionario_ponto_marcacoes_origem_check CHECK ((origem = ANY (ARRAY['app'::text, 'rh_manual'::text]))),
    CONSTRAINT movelaria_funcionario_ponto_marcacoes_status_check CHECK ((status = ANY (ARRAY['normal'::text, 'atraso'::text, 'irregular'::text]))),
    CONSTRAINT movelaria_funcionario_ponto_marcacoes_tipo_check CHECK ((tipo = ANY (ARRAY['entrada'::text, 'saida_intervalo'::text, 'retorno_intervalo'::text, 'saida'::text])))
);


--
-- Name: COLUMN movelaria_funcionario_ponto_marcacoes.origem; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.movelaria_funcionario_ponto_marcacoes.origem IS 'app = batida pelo funcionário; rh_manual = lançamento oficial pelo RH.';


--
-- Name: COLUMN movelaria_funcionario_ponto_marcacoes.registro_motivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.movelaria_funcionario_ponto_marcacoes.registro_motivo IS 'Motivo obrigatório quando origem = rh_manual.';


--
-- Name: movelaria_ponto_hora_efetiva(public.movelaria_funcionario_ponto_marcacoes); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_hora_efetiva(p_marcacao public.movelaria_funcionario_ponto_marcacoes) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(p_marcacao.registrado_em_ajustado, p_marcacao.registrado_em);
$$;


--
-- Name: movelaria_ponto_hora_local(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_hora_local(p_ts timestamp with time zone DEFAULT now()) RETURNS time without time zone
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT (p_ts AT TIME ZONE 'America/Sao_Paulo')::TIME;
$$;


--
-- Name: movelaria_ponto_job_faltas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_job_faltas() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agora_sp TIMESTAMP := (NOW() AT TIME ZONE 'America/Sao_Paulo');
  v_data DATE;
BEGIN
  -- Cron sobe às 23:59 SP (02:59 UTC): fecha o dia que está terminando.
  -- Se o job atrasar e virar após meia-noite SP, fecha o dia que acabou.
  IF EXTRACT(HOUR FROM v_agora_sp) < 6 THEN
    v_data := v_agora_sp::DATE - 1;
  ELSE
    v_data := v_agora_sp::DATE;
  END IF;

  PERFORM movelaria_ponto_detectar_faltas(v_data);
END;
$$;


--
-- Name: movelaria_ponto_marcacao_guard_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_marcacao_guard_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.nsr IS DISTINCT FROM NEW.nsr
    OR OLD.funcionario_id IS DISTINCT FROM NEW.funcionario_id
    OR OLD.tipo IS DISTINCT FROM NEW.tipo
    OR OLD.registrado_em IS DISTINCT FROM NEW.registrado_em
    OR OLD.latitude IS DISTINCT FROM NEW.latitude
    OR OLD.longitude IS DISTINCT FROM NEW.longitude
    OR OLD.foto_path IS DISTINCT FROM NEW.foto_path
    OR OLD.assinatura_path IS DISTINCT FROM NEW.assinatura_path
    OR OLD.hash_sha256 IS DISTINCT FROM NEW.hash_sha256
    OR OLD.origem IS DISTINCT FROM NEW.origem
    OR OLD.registro_motivo IS DISTINCT FROM NEW.registro_motivo
    OR (OLD.usuario_id IS DISTINCT FROM NEW.usuario_id AND NEW.usuario_id IS NOT NULL)
  THEN
    RAISE EXCEPTION 'Marcações de ponto são imutáveis (REP-P).';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: movelaria_ponto_marcacao_imutavel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_marcacao_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Marcações de ponto são imutáveis (REP-P).';
END;
$$;


--
-- Name: movelaria_ponto_pagar_hora_extra(uuid, integer, numeric, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_pagar_hora_extra(p_funcionario_id uuid, p_minutos integer, p_valor_hora numeric, p_data_vencimento date, p_observacao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_hoje DATE := movelaria_ponto_data_local();
  v_inicio DATE := DATE '2026-07-01';
  v_comp JSONB;
  v_saldo INT;
  v_minutos INT := GREATEST(0, FLOOR(COALESCE(p_minutos, 0))::INT);
  v_valor_hora NUMERIC(12, 4) := COALESCE(p_valor_hora, 0);
  v_valor_total NUMERIC(12, 2);
  v_func RECORD;
  v_cp_id UUID;
  v_mov_id UUID;
  v_desc TEXT;
  v_h INT;
  v_m INT;
BEGIN
  IF movelaria_meu_perfil() NOT IN ('administrador', 'financeiro') THEN
    RAISE EXCEPTION 'Sem permissão.';
  END IF;

  IF v_minutos <= 0 THEN
    RAISE EXCEPTION 'Informe minutos positivos para pagar.';
  END IF;

  IF v_valor_hora < 0 THEN
    RAISE EXCEPTION 'Valor/hora inválido.';
  END IF;

  IF p_data_vencimento IS NULL THEN
    RAISE EXCEPTION 'Informe a data de vencimento.';
  END IF;

  SELECT f.id, f.nome, f.usuario_id
  INTO v_func
  FROM movelaria_funcionarios f
  WHERE f.id = p_funcionario_id AND f.ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Funcionário não encontrado.';
  END IF;

  v_comp := movelaria_ponto_banco_componentes(p_funcionario_id, v_inicio, v_hoje);
  v_saldo := COALESCE((v_comp->>'saldo_minutos')::INT, 0);

  IF v_minutos > v_saldo THEN
    RAISE EXCEPTION 'Minutos (%) excedem o saldo disponível (%).', v_minutos, v_saldo;
  END IF;

  v_valor_total := ROUND((v_minutos::NUMERIC / 60.0) * v_valor_hora, 2);
  v_h := v_minutos / 60;
  v_m := v_minutos % 60;
  v_desc := format(
    'Horas extras — %sh %smin (R$ %s/h)',
    v_h,
    lpad(v_m::TEXT, 2, '0'),
    trim(to_char(v_valor_hora, 'FM999999990.00'))
  );

  INSERT INTO movelaria_contas_pagar (
    prestador_id,
    fornecedor_nome,
    descricao,
    observacao,
    valor_total,
    numero_parcela,
    total_parcelas,
    valor_parcela,
    data_vencimento,
    status,
    valor_pago,
    grupo_lancamento_id
  ) VALUES (
    v_func.usuario_id,
    v_func.nome,
    v_desc,
    NULLIF(trim(COALESCE(p_observacao, '')), ''),
    v_valor_total,
    1,
    1,
    v_valor_total,
    p_data_vencimento,
    'pendente',
    0,
    gen_random_uuid()
  )
  RETURNING id INTO v_cp_id;

  INSERT INTO movelaria_ponto_banco_movimentos (
    funcionario_id, tipo, minutos, valor_hora, valor_total,
    conta_pagar_id, observacao, criado_por
  ) VALUES (
    p_funcionario_id, 'pagamento_he', v_minutos, v_valor_hora, v_valor_total,
    v_cp_id, NULLIF(trim(COALESCE(p_observacao, '')), ''), auth.uid()
  )
  RETURNING id INTO v_mov_id;

  RETURN jsonb_build_object(
    'movimento_id', v_mov_id,
    'conta_pagar_id', v_cp_id,
    'minutos', v_minutos,
    'valor_hora', v_valor_hora,
    'valor_total', v_valor_total,
    'saldo_restante_minutos', v_saldo - v_minutos,
    'descricao', v_desc
  );
END;
$_$;


--
-- Name: movelaria_ponto_proximo_tipo(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_proximo_tipo(p_funcionario_id uuid, p_data date DEFAULT public.movelaria_ponto_data_local()) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tipos TEXT[] := ARRAY['entrada', 'saida_intervalo', 'retorno_intervalo', 'saida'];
  v_feito TEXT[];
  v_t TEXT;
BEGIN
  SELECT COALESCE(array_agg(tipo ORDER BY registrado_em), ARRAY[]::TEXT[])
  INTO v_feito
  FROM movelaria_funcionario_ponto_marcacoes
  WHERE funcionario_id = p_funcionario_id
    AND movelaria_ponto_data_local(registrado_em) = p_data;

  FOREACH v_t IN ARRAY v_tipos LOOP
    IF NOT (v_t = ANY(v_feito)) THEN
      RETURN v_t;
    END IF;
  END LOOP;

  RETURN NULL;
END;
$$;


--
-- Name: movelaria_ponto_registrar_manual(uuid, date, text, time without time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_registrar_manual(p_funcionario_id uuid, p_data date, p_tipo text, p_hora time without time zone, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_funcionario movelaria_funcionarios%ROWTYPE;
  v_jornada movelaria_funcionario_jornada%ROWTYPE;
  v_motivo TEXT := trim(COALESCE(p_motivo, ''));
  v_tipo TEXT := lower(trim(COALESCE(p_tipo, '')));
  v_registrado TIMESTAMPTZ;
  v_hora TIME;
  v_hora_ref TIME;
  v_atraso INT := 0;
  v_status TEXT := 'normal';
  v_marc movelaria_funcionario_ponto_marcacoes%ROWTYPE;
  v_hash TEXT;
  v_dow INT;
BEGIN
  IF p_funcionario_id IS NULL THEN
    RAISE EXCEPTION 'Informe o funcionário.';
  END IF;

  PERFORM movelaria_ponto_assert_edicao_registros(p_funcionario_id);

  IF p_data IS NULL THEN
    RAISE EXCEPTION 'Informe a data do ponto.';
  END IF;

  IF p_hora IS NULL THEN
    RAISE EXCEPTION 'Informe o horário da batida.';
  END IF;

  IF length(v_motivo) < 3 THEN
    RAISE EXCEPTION 'Informe o motivo do registro (mínimo 3 caracteres).';
  END IF;

  IF v_tipo NOT IN ('entrada', 'saida_intervalo', 'retorno_intervalo', 'saida') THEN
    RAISE EXCEPTION 'Tipo de batida inválido.';
  END IF;

  IF p_data > movelaria_ponto_data_local() THEN
    RAISE EXCEPTION 'Não é possível registrar ponto em data futura.';
  END IF;

  SELECT * INTO v_funcionario
  FROM movelaria_funcionarios
  WHERE id = p_funcionario_id AND ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Funcionário não encontrado ou inativo.';
  END IF;

  IF v_funcionario.usuario_id IS NULL THEN
    RAISE EXCEPTION 'Funcionário sem usuário vinculado — não é possível gerar batida oficial.';
  END IF;

  IF v_funcionario.tipo NOT IN ('montador', 'montador_admin', 'administrador_obras') THEN
    RAISE EXCEPTION 'Este perfil de funcionário não usa ponto eletrônico.';
  END IF;

  SELECT * INTO v_jornada
  FROM movelaria_funcionario_jornada
  WHERE funcionario_id = v_funcionario.id AND ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Jornada de trabalho não configurada para este funcionário.';
  END IF;

  v_dow := EXTRACT(ISODOW FROM p_data)::INT;
  IF NOT (v_dow = ANY(v_jornada.dias_uteis)) THEN
    RAISE EXCEPTION 'A data informada não é dia útil na jornada deste funcionário.';
  END IF;

  DELETE FROM movelaria_funcionario_ponto_ocorrencias
  WHERE funcionario_id = v_funcionario.id
    AND data = p_data
    AND tipo = 'falta'
    AND COALESCE(automatica, false) = true;

  IF EXISTS (
    SELECT 1 FROM movelaria_funcionario_ponto_ocorrencias
    WHERE funcionario_id = v_funcionario.id
      AND data = p_data
      AND (
        tipo = 'folga'
        OR (tipo = 'falta' AND COALESCE(automatica, false) = false)
      )
  ) THEN
    RAISE EXCEPTION 'Não é possível registrar ponto: há folga ou falta lançada pelo RH neste dia.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM movelaria_funcionario_ponto_marcacoes
    WHERE funcionario_id = v_funcionario.id
      AND movelaria_ponto_data_local(registrado_em) = p_data
      AND tipo = v_tipo
  ) THEN
    RAISE EXCEPTION 'Já existe batida de % neste dia.', v_tipo;
  END IF;

  v_registrado := ((p_data + p_hora) AT TIME ZONE 'America/Sao_Paulo');
  v_hora := p_hora;

  IF v_tipo = 'entrada' THEN
    v_hora_ref := v_jornada.hora_entrada;
  ELSIF v_tipo = 'retorno_intervalo' THEN
    v_hora_ref := v_jornada.hora_retorno_intervalo;
  END IF;

  IF v_hora_ref IS NOT NULL THEN
    v_atraso := GREATEST(0,
      EXTRACT(EPOCH FROM (v_hora - v_hora_ref)) / 60 - v_jornada.tolerancia_minutos
    )::INT;
    IF v_atraso > 0 THEN v_status := 'atraso'; END IF;
  END IF;

  v_hash := encode(
    extensions.digest(
      (
        'rh_manual|' || v_funcionario.id::text || '|' || v_tipo || '|' ||
        p_data::text || '|' || v_hora::text || '|' || v_motivo || '|' ||
        COALESCE(auth.uid()::text, '') || '|' || clock_timestamp()::text
      )::bytea,
      'sha256'
    ),
    'hex'
  );

  INSERT INTO movelaria_funcionario_ponto_marcacoes (
    funcionario_id, usuario_id, tipo, registrado_em,
    hash_sha256, status, atraso_minutos, offline,
    origem, registro_motivo,
    ajuste_motivo, ajustado_por, ajustado_em
  ) VALUES (
    v_funcionario.id, v_funcionario.usuario_id, v_tipo, v_registrado,
    v_hash, v_status, v_atraso, false,
    'rh_manual', v_motivo,
    'Registro RH: ' || v_motivo, auth.uid(), NOW()
  )
  RETURNING * INTO v_marc;

  UPDATE movelaria_rep_config SET nsr_atual = v_marc.nsr, atualizado_em = NOW()
  WHERE ativo = true;

  RETURN to_jsonb(v_marc);
END;
$$;


--
-- Name: movelaria_ponto_remover_ocorrencia(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_remover_ocorrencia(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF movelaria_meu_perfil() NOT IN ('administrador', 'financeiro') THEN
    RAISE EXCEPTION 'Sem permissão.';
  END IF;
  DELETE FROM movelaria_funcionario_ponto_ocorrencias WHERE id = p_id;
END;
$$;


--
-- Name: movelaria_ponto_resumo_periodo(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_resumo_periodo(p_periodo text DEFAULT 'mes'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hoje DATE := movelaria_ponto_data_local();
  v_faltas_ate DATE := movelaria_ponto_data_faltas_ate();
  v_inicio DATE;
  v_fim DATE;
  v_periodo TEXT := lower(trim(COALESCE(p_periodo, 'mes')));
  v_funcionarios JSONB;
  v_he_empresa INT;
  v_faltas_empresa INT;
BEGIN
  IF movelaria_meu_perfil() NOT IN ('administrador', 'financeiro') THEN
    RAISE EXCEPTION 'Sem permissão para visualizar o resumo de ponto.';
  END IF;

  IF v_periodo NOT IN ('semana', 'mes', 'mes_passado', 'ano') THEN
    RAISE EXCEPTION 'Período inválido. Use semana, mes, mes_passado ou ano.';
  END IF;

  IF v_periodo = 'semana' THEN
    v_inicio := v_hoje - ((EXTRACT(ISODOW FROM v_hoje)::INT) - 1);
    v_fim := v_inicio + 6;
  ELSIF v_periodo = 'mes' THEN
    v_inicio := date_trunc('month', v_hoje)::DATE;
    v_fim := (date_trunc('month', v_hoje) + INTERVAL '1 month - 1 day')::DATE;
  ELSIF v_periodo = 'mes_passado' THEN
    v_inicio := (date_trunc('month', v_hoje) - INTERVAL '1 month')::DATE;
    v_fim := (date_trunc('month', v_hoje) - INTERVAL '1 day')::DATE;
  ELSE
    v_inicio := date_trunc('year', v_hoje)::DATE;
    v_fim := (date_trunc('year', v_hoje) + INTERVAL '1 year - 1 day')::DATE;
  END IF;

  PERFORM movelaria_ponto_sincronizar_faltas_periodo(v_inicio, v_fim);

  SELECT COALESCE(jsonb_agg(row ORDER BY row->>'nome'), '[]'::jsonb)
  INTO v_funcionarios
  FROM (
    SELECT jsonb_build_object(
      'funcionario_id', f.id,
      'nome', f.nome,
      'tipo', f.tipo,
      'hora_extra_minutos', COALESCE((
        SELECT SUM(
          GREATEST(
            0,
            FLOOR(
              EXTRACT(
                EPOCH FROM (
                  movelaria_ponto_hora_local(
                    movelaria_ponto_ts_efetivo(m.registrado_em, m.registrado_em_ajustado)
                  ) - j.hora_saida
                )
              ) / 60
            )::INT
          )
        )::INT
        FROM movelaria_funcionario_ponto_marcacoes m
        INNER JOIN movelaria_funcionario_jornada j
          ON j.funcionario_id = f.id AND j.ativo = true
        WHERE m.funcionario_id = f.id
          AND m.tipo = 'saida'
          AND movelaria_ponto_data_local(m.registrado_em) BETWEEN v_inicio AND v_fim
      ), 0),
      'faltas_datas', COALESCE((
        SELECT jsonb_agg(to_char(d.dia, 'YYYY-MM-DD') ORDER BY d.dia)
        FROM generate_series(
          GREATEST(
            v_inicio,
            COALESCE(
              NULLIF(f.admissao_dados->>'data_admissao', '')::DATE,
              movelaria_ponto_data_local(f.criado_em)
            )
          ),
          LEAST(v_fim, v_faltas_ate),
          INTERVAL '1 day'
        ) AS d(dia)
        INNER JOIN movelaria_funcionario_jornada j
          ON j.funcionario_id = f.id AND j.ativo = true
        WHERE EXTRACT(ISODOW FROM d.dia)::INT = ANY(j.dias_uteis)
          AND NOT EXISTS (
            SELECT 1 FROM movelaria_funcionario_ponto_marcacoes m
            WHERE m.funcionario_id = f.id
              AND movelaria_ponto_data_local(m.registrado_em) = d.dia
          )
          AND NOT EXISTS (
            SELECT 1 FROM movelaria_funcionario_ponto_ocorrencias o
            WHERE o.funcionario_id = f.id
              AND o.data = d.dia
              AND o.tipo IN ('folga', 'abono')
          )
      ), '[]'::jsonb),
      'faltas', COALESCE((
        SELECT COUNT(*)::INT
        FROM generate_series(
          GREATEST(
            v_inicio,
            COALESCE(
              NULLIF(f.admissao_dados->>'data_admissao', '')::DATE,
              movelaria_ponto_data_local(f.criado_em)
            )
          ),
          LEAST(v_fim, v_faltas_ate),
          INTERVAL '1 day'
        ) AS d(dia)
        INNER JOIN movelaria_funcionario_jornada j
          ON j.funcionario_id = f.id AND j.ativo = true
        WHERE EXTRACT(ISODOW FROM d.dia)::INT = ANY(j.dias_uteis)
          AND NOT EXISTS (
            SELECT 1 FROM movelaria_funcionario_ponto_marcacoes m
            WHERE m.funcionario_id = f.id
              AND movelaria_ponto_data_local(m.registrado_em) = d.dia
          )
          AND NOT EXISTS (
            SELECT 1 FROM movelaria_funcionario_ponto_ocorrencias o
            WHERE o.funcionario_id = f.id
              AND o.data = d.dia
              AND o.tipo IN ('folga', 'abono')
          )
      ), 0),
      'chegadas', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'data', to_char(movelaria_ponto_data_local(m.registrado_em), 'YYYY-MM-DD'),
            'hora', to_char(
              movelaria_ponto_hora_local(
                movelaria_ponto_ts_efetivo(m.registrado_em, m.registrado_em_ajustado)
              ),
              'HH24:MI'
            ),
            'atraso_minutos', COALESCE(m.atraso_minutos, 0),
            'tipo', m.tipo
          )
          ORDER BY movelaria_ponto_ts_efetivo(m.registrado_em, m.registrado_em_ajustado)
        )
        FROM movelaria_funcionario_ponto_marcacoes m
        WHERE m.funcionario_id = f.id
          AND m.tipo IN ('entrada', 'retorno_intervalo')
          AND movelaria_ponto_data_local(m.registrado_em) BETWEEN v_inicio AND v_fim
      ), '[]'::jsonb),
      'saidas', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'data', to_char(movelaria_ponto_data_local(m.registrado_em), 'YYYY-MM-DD'),
            'hora', to_char(
              movelaria_ponto_hora_local(
                movelaria_ponto_ts_efetivo(m.registrado_em, m.registrado_em_ajustado)
              ),
              'HH24:MI'
            ),
            'atraso_minutos', COALESCE(m.atraso_minutos, 0),
            'tipo', m.tipo
          )
          ORDER BY movelaria_ponto_ts_efetivo(m.registrado_em, m.registrado_em_ajustado)
        )
        FROM movelaria_funcionario_ponto_marcacoes m
        WHERE m.funcionario_id = f.id
          AND m.tipo IN ('saida_intervalo', 'saida')
          AND movelaria_ponto_data_local(m.registrado_em) BETWEEN v_inicio AND v_fim
      ), '[]'::jsonb)
    ) AS row
    FROM movelaria_funcionarios f
    WHERE f.ativo = true
      AND f.tipo IN ('montador', 'montador_admin', 'administrador_obras')
  ) sub;

  SELECT COALESCE(SUM((f->>'hora_extra_minutos')::INT), 0)::INT
  INTO v_he_empresa
  FROM jsonb_array_elements(v_funcionarios) f;

  SELECT COALESCE(SUM((f->>'faltas')::INT), 0)::INT
  INTO v_faltas_empresa
  FROM jsonb_array_elements(v_funcionarios) f;

  RETURN jsonb_build_object(
    'periodo', v_periodo,
    'inicio', to_char(v_inicio, 'YYYY-MM-DD'),
    'fim', to_char(v_fim, 'YYYY-MM-DD'),
    'empresa', jsonb_build_object(
      'hora_extra_minutos', v_he_empresa,
      'faltas_total', v_faltas_empresa
    ),
    'funcionarios', v_funcionarios
  );
END;
$$;


--
-- Name: movelaria_ponto_resumo_periodo(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_resumo_periodo(p_periodo text DEFAULT 'mes'::text, p_referencia text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hoje DATE := movelaria_ponto_data_local();
  v_faltas_ate DATE := movelaria_ponto_data_faltas_ate();
  v_inicio DATE;
  v_fim DATE;
  v_periodo TEXT := lower(trim(COALESCE(p_periodo, 'mes')));
  v_ref TEXT := NULLIF(trim(COALESCE(p_referencia, '')), '');
  v_ref_date DATE;
  v_funcionarios JSONB;
  v_he_empresa INT;
  v_faltas_empresa INT;
BEGIN
  IF movelaria_meu_perfil() NOT IN ('administrador', 'financeiro', 'montador_admin') THEN
    RAISE EXCEPTION 'Sem permissão para visualizar o resumo de ponto.';
  END IF;

  IF v_periodo = 'mes_passado' THEN
    v_periodo := 'mes';
    IF v_ref IS NULL THEN
      v_ref := to_char(date_trunc('month', v_hoje) - INTERVAL '1 month', 'YYYY-MM');
    END IF;
  END IF;

  IF v_periodo NOT IN ('semana', 'mes', 'ano') THEN
    RAISE EXCEPTION 'Período inválido. Use semana, mes ou ano.';
  END IF;

  IF v_periodo = 'semana' THEN
    v_inicio := v_hoje - ((EXTRACT(ISODOW FROM v_hoje)::INT) - 1);
    v_fim := v_inicio + 6;
  ELSIF v_periodo = 'mes' THEN
    IF v_ref IS NOT NULL THEN
      BEGIN
        v_ref_date := (v_ref || '-01')::DATE;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'Referência de mês inválida. Use YYYY-MM (ex.: 2026-07).';
      END;
      v_inicio := date_trunc('month', v_ref_date)::DATE;
      v_fim := (date_trunc('month', v_ref_date) + INTERVAL '1 month - 1 day')::DATE;
    ELSE
      v_inicio := date_trunc('month', v_hoje)::DATE;
      v_fim := (date_trunc('month', v_hoje) + INTERVAL '1 month - 1 day')::DATE;
    END IF;
  ELSE
    v_inicio := date_trunc('year', v_hoje)::DATE;
    v_fim := (date_trunc('year', v_hoje) + INTERVAL '1 year - 1 day')::DATE;
  END IF;

  PERFORM movelaria_ponto_sincronizar_faltas_periodo(v_inicio, v_fim);

  SELECT COALESCE(jsonb_agg(row ORDER BY row->>'nome'), '[]'::jsonb)
  INTO v_funcionarios
  FROM (
    SELECT jsonb_build_object(
      'funcionario_id', f.id,
      'nome', f.nome,
      'tipo', f.tipo,
      'hora_extra_minutos', COALESCE((
        SELECT SUM(
          GREATEST(
            0,
            FLOOR(
              EXTRACT(
                EPOCH FROM (
                  movelaria_ponto_hora_local(
                    movelaria_ponto_ts_efetivo(m.registrado_em, m.registrado_em_ajustado)
                  ) - j.hora_saida
                )
              ) / 60
            )::INT
          )
        )::INT
        FROM movelaria_funcionario_ponto_marcacoes m
        INNER JOIN movelaria_funcionario_jornada j
          ON j.funcionario_id = f.id AND j.ativo = true
        WHERE m.funcionario_id = f.id
          AND m.tipo = 'saida'
          AND movelaria_ponto_data_local(m.registrado_em) BETWEEN v_inicio AND v_fim
      ), 0),
      'faltas_datas', COALESCE((
        SELECT jsonb_agg(to_char(x.dia, 'YYYY-MM-DD') ORDER BY x.dia)
        FROM (
          SELECT d.dia::date AS dia
          FROM generate_series(
            GREATEST(
              v_inicio,
              COALESCE(
                NULLIF(f.admissao_dados->>'data_admissao', '')::DATE,
                movelaria_ponto_data_local(f.criado_em)
              )
            ),
            LEAST(v_fim, v_faltas_ate),
            INTERVAL '1 day'
          ) AS d(dia)
          INNER JOIN movelaria_funcionario_jornada j
            ON j.funcionario_id = f.id AND j.ativo = true
          WHERE EXTRACT(ISODOW FROM d.dia)::INT = ANY(j.dias_uteis)
            AND NOT EXISTS (
              SELECT 1 FROM movelaria_funcionario_ponto_marcacoes m
              WHERE m.funcionario_id = f.id
                AND movelaria_ponto_data_local(m.registrado_em) = d.dia
            )
            AND NOT EXISTS (
              SELECT 1 FROM movelaria_funcionario_ponto_ocorrencias o
              WHERE o.funcionario_id = f.id
                AND o.data = d.dia
                AND o.tipo IN ('folga', 'abono')
            )
          UNION
          SELECT o.data AS dia
          FROM movelaria_funcionario_ponto_ocorrencias o
          WHERE o.funcionario_id = f.id
            AND o.tipo = 'falta'
            AND o.data BETWEEN v_inicio AND LEAST(v_fim, v_faltas_ate)
        ) x
      ), '[]'::jsonb),
      'faltas', COALESCE((
        SELECT COUNT(*)::INT
        FROM (
          SELECT d.dia::date AS dia
          FROM generate_series(
            GREATEST(
              v_inicio,
              COALESCE(
                NULLIF(f.admissao_dados->>'data_admissao', '')::DATE,
                movelaria_ponto_data_local(f.criado_em)
              )
            ),
            LEAST(v_fim, v_faltas_ate),
            INTERVAL '1 day'
          ) AS d(dia)
          INNER JOIN movelaria_funcionario_jornada j
            ON j.funcionario_id = f.id AND j.ativo = true
          WHERE EXTRACT(ISODOW FROM d.dia)::INT = ANY(j.dias_uteis)
            AND NOT EXISTS (
              SELECT 1 FROM movelaria_funcionario_ponto_marcacoes m
              WHERE m.funcionario_id = f.id
                AND movelaria_ponto_data_local(m.registrado_em) = d.dia
            )
            AND NOT EXISTS (
              SELECT 1 FROM movelaria_funcionario_ponto_ocorrencias o
              WHERE o.funcionario_id = f.id
                AND o.data = d.dia
                AND o.tipo IN ('folga', 'abono')
            )
          UNION
          SELECT o.data AS dia
          FROM movelaria_funcionario_ponto_ocorrencias o
          WHERE o.funcionario_id = f.id
            AND o.tipo = 'falta'
            AND o.data BETWEEN v_inicio AND LEAST(v_fim, v_faltas_ate)
        ) x
      ), 0),
      'faltas_detalhe', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'data', to_char(x.dia, 'YYYY-MM-DD'),
            'observacao', x.observacao,
            'abater_banco_horas', x.abater_banco_horas,
            'minutos_abatidos', x.minutos_abatidos
          )
          ORDER BY x.dia
        )
        FROM (
          SELECT
            d.dia::date AS dia,
            COALESCE(o.observacao, 'Falta detectada automaticamente.') AS observacao,
            movelaria_ponto_falta_debita_caixa(
              COALESCE(o.abater_banco_horas, false),
              o.observacao
            ) AS abater_banco_horas,
            NULLIF(
              movelaria_ponto_falta_minutos_debito(
                f.id,
                d.dia::date,
                COALESCE(o.abater_banco_horas, false),
                o.minutos_abatidos,
                o.observacao
              ),
              0
            ) AS minutos_abatidos
          FROM generate_series(
            GREATEST(
              v_inicio,
              COALESCE(
                NULLIF(f.admissao_dados->>'data_admissao', '')::DATE,
                movelaria_ponto_data_local(f.criado_em)
              )
            ),
            LEAST(v_fim, v_faltas_ate),
            INTERVAL '1 day'
          ) AS d(dia)
          INNER JOIN movelaria_funcionario_jornada j
            ON j.funcionario_id = f.id AND j.ativo = true
          LEFT JOIN movelaria_funcionario_ponto_ocorrencias o
            ON o.funcionario_id = f.id
            AND o.data = d.dia
            AND o.tipo = 'falta'
          WHERE EXTRACT(ISODOW FROM d.dia)::INT = ANY(j.dias_uteis)
            AND NOT EXISTS (
              SELECT 1 FROM movelaria_funcionario_ponto_marcacoes m
              WHERE m.funcionario_id = f.id
                AND movelaria_ponto_data_local(m.registrado_em) = d.dia
            )
            AND NOT EXISTS (
              SELECT 1 FROM movelaria_funcionario_ponto_ocorrencias ox
              WHERE ox.funcionario_id = f.id
                AND ox.data = d.dia
                AND ox.tipo IN ('folga', 'abono')
            )
          UNION
          SELECT
            o.data AS dia,
            o.observacao,
            movelaria_ponto_falta_debita_caixa(o.abater_banco_horas, o.observacao),
            NULLIF(
              movelaria_ponto_falta_minutos_debito(
                o.funcionario_id, o.data, o.abater_banco_horas, o.minutos_abatidos, o.observacao
              ),
              0
            )
          FROM movelaria_funcionario_ponto_ocorrencias o
          WHERE o.funcionario_id = f.id
            AND o.tipo = 'falta'
            AND o.data BETWEEN v_inicio AND LEAST(v_fim, v_faltas_ate)
        ) x
      ), '[]'::jsonb),
      'faltas_banco_minutos', COALESCE((
        SELECT SUM(
          movelaria_ponto_falta_minutos_debito(
            o.funcionario_id, o.data, o.abater_banco_horas, o.minutos_abatidos, o.observacao
          )
        )::INT
        FROM movelaria_funcionario_ponto_ocorrencias o
        WHERE o.funcionario_id = f.id
          AND o.tipo = 'falta'
          AND o.data BETWEEN v_inicio AND LEAST(v_fim, v_faltas_ate)
      ), 0),
      'he_pagas_minutos', COALESCE((
        SELECT SUM(bm.minutos)::INT
        FROM movelaria_ponto_banco_movimentos bm
        WHERE bm.funcionario_id = f.id
          AND bm.tipo = 'pagamento_he'
          AND movelaria_ponto_data_local(bm.criado_em) BETWEEN v_inicio AND v_fim
      ), 0),
      'chegadas', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'data', to_char(movelaria_ponto_data_local(m.registrado_em), 'YYYY-MM-DD'),
            'hora', to_char(
              movelaria_ponto_hora_local(
                movelaria_ponto_ts_efetivo(m.registrado_em, m.registrado_em_ajustado)
              ),
              'HH24:MI'
            ),
            'atraso_minutos', COALESCE(m.atraso_minutos, 0),
            'hora_extra_minutos', 0,
            'tipo', m.tipo
          )
          ORDER BY movelaria_ponto_ts_efetivo(m.registrado_em, m.registrado_em_ajustado)
        )
        FROM movelaria_funcionario_ponto_marcacoes m
        WHERE m.funcionario_id = f.id
          AND m.tipo IN ('entrada', 'retorno_intervalo')
          AND movelaria_ponto_data_local(m.registrado_em) BETWEEN v_inicio AND v_fim
      ), '[]'::jsonb),
      'saidas', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'data', to_char(movelaria_ponto_data_local(m.registrado_em), 'YYYY-MM-DD'),
            'hora', to_char(
              movelaria_ponto_hora_local(
                movelaria_ponto_ts_efetivo(m.registrado_em, m.registrado_em_ajustado)
              ),
              'HH24:MI'
            ),
            'atraso_minutos', COALESCE(m.atraso_minutos, 0),
            'hora_extra_minutos', CASE
              WHEN m.tipo = 'saida' THEN COALESCE((
                SELECT GREATEST(
                  0,
                  FLOOR(
                    EXTRACT(
                      EPOCH FROM (
                        movelaria_ponto_hora_local(
                          movelaria_ponto_ts_efetivo(m.registrado_em, m.registrado_em_ajustado)
                        ) - j.hora_saida
                      )
                    ) / 60
                  )::INT
                )
                FROM movelaria_funcionario_jornada j
                WHERE j.funcionario_id = f.id AND j.ativo = true
                LIMIT 1
              ), 0)
              ELSE 0
            END,
            'tipo', m.tipo
          )
          ORDER BY movelaria_ponto_ts_efetivo(m.registrado_em, m.registrado_em_ajustado)
        )
        FROM movelaria_funcionario_ponto_marcacoes m
        WHERE m.funcionario_id = f.id
          AND m.tipo IN ('saida_intervalo', 'saida')
          AND movelaria_ponto_data_local(m.registrado_em) BETWEEN v_inicio AND v_fim
      ), '[]'::jsonb)
    ) AS row
    FROM movelaria_funcionarios f
    WHERE f.ativo = true
      AND f.tipo IN ('montador', 'montador_admin', 'administrador_obras')
  ) sub;

  SELECT COALESCE(SUM((f->>'hora_extra_minutos')::INT), 0)::INT
  INTO v_he_empresa
  FROM jsonb_array_elements(v_funcionarios) f;

  SELECT COALESCE(SUM((f->>'faltas')::INT), 0)::INT
  INTO v_faltas_empresa
  FROM jsonb_array_elements(v_funcionarios) f;

  RETURN jsonb_build_object(
    'periodo', v_periodo,
    'inicio', to_char(v_inicio, 'YYYY-MM-DD'),
    'fim', to_char(v_fim, 'YYYY-MM-DD'),
    'referencia', CASE
      WHEN v_periodo = 'mes' THEN to_char(v_inicio, 'YYYY-MM')
      ELSE NULL
    END,
    'empresa', jsonb_build_object(
      'hora_extra_minutos', v_he_empresa,
      'faltas_total', v_faltas_empresa
    ),
    'funcionarios', v_funcionarios
  );
END;
$$;


--
-- Name: movelaria_ponto_saldo_acumulado(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_saldo_acumulado(p_funcionario_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hoje DATE := movelaria_ponto_data_local();
  v_inicio DATE := DATE '2026-07-01';
  v_comp JSONB;
  v_jornada movelaria_funcionario_jornada%ROWTYPE;
  v_min_ref INT := 0;
  v_dow INT;
  v_data_ref DATE;
  v_func RECORD;
  v_fixo NUMERIC(12, 2) := 0;
BEGIN
  IF movelaria_meu_perfil() NOT IN ('administrador', 'financeiro', 'montador_admin') THEN
    RAISE EXCEPTION 'Sem permissão.';
  END IF;

  SELECT f.id, f.nome, f.usuario_id, COALESCE(f.valor_fixo_mensal, 0) AS valor_fixo_mensal
  INTO v_func
  FROM movelaria_funcionarios f
  WHERE f.id = p_funcionario_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Funcionário não encontrado.';
  END IF;

  v_fixo := COALESCE(v_func.valor_fixo_mensal, 0);
  v_comp := movelaria_ponto_banco_componentes(p_funcionario_id, v_inicio, v_hoje);

  SELECT * INTO v_jornada
  FROM movelaria_funcionario_jornada
  WHERE funcionario_id = p_funcionario_id AND ativo = true
  LIMIT 1;

  IF FOUND AND v_jornada.dias_uteis IS NOT NULL AND array_length(v_jornada.dias_uteis, 1) > 0 THEN
    v_dow := v_jornada.dias_uteis[1];
    -- Encontra a próxima data com esse ISODOW a partir de hoje (ou hoje se bater)
    v_data_ref := v_hoje + ((v_dow - EXTRACT(ISODOW FROM v_hoje)::INT + 7) % 7);
    v_min_ref := movelaria_jornada_minutos_no_dia(p_funcionario_id, v_data_ref);
  END IF;

  IF v_min_ref <= 0 THEN
    v_min_ref := 480; -- fallback 8h
  END IF;

  RETURN jsonb_build_object(
    'funcionario_id', p_funcionario_id,
    'nome', v_func.nome,
    'usuario_id', v_func.usuario_id,
    'valor_fixo_mensal', v_fixo,
    'inicio', to_char(v_inicio, 'YYYY-MM-DD'),
    'fim', to_char(v_hoje, 'YYYY-MM-DD'),
    'hora_extra_minutos', COALESCE((v_comp->>'hora_extra_minutos')::INT, 0),
    'atrasos_minutos', COALESCE((v_comp->>'atrasos_minutos')::INT, 0),
    'faltas_banco_minutos', COALESCE((v_comp->>'faltas_banco_minutos')::INT, 0),
    'he_pagas_minutos', COALESCE((v_comp->>'he_pagas_minutos')::INT, 0),
    'saldo_minutos', COALESCE((v_comp->>'saldo_minutos')::INT, 0),
    'minutos_jornada_ref', v_min_ref,
    'dias_uteis', COALESCE(v_jornada.dias_uteis, ARRAY[1,2,3,4,5]::INT[])
  );
END;
$$;


--
-- Name: movelaria_ponto_salvar_jornada(uuid, time without time zone, time without time zone, time without time zone, time without time zone, integer, integer[], boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_salvar_jornada(p_funcionario_id uuid, p_hora_entrada time without time zone, p_hora_saida_intervalo time without time zone, p_hora_retorno_intervalo time without time zone, p_hora_saida time without time zone, p_tolerancia_minutos integer DEFAULT 5, p_dias_uteis integer[] DEFAULT ARRAY[1, 2, 3, 4, 5], p_ativo boolean DEFAULT true, p_grade jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row movelaria_funcionario_jornada%ROWTYPE;
  v_patch JSONB;
  v_semana JSONB;
  v_ativos JSONB;
BEGIN
  IF NOT movelaria_usuario_tem_algum_perfil(
    ARRAY['administrador', 'financeiro', 'administrador_obras']
  ) THEN
    RAISE EXCEPTION 'Sem permissão para configurar jornada.';
  END IF;

  PERFORM set_config('movelaria.sync_horarios', '1', true);

  IF p_grade IS NOT NULL AND p_grade ? 'horarios_semana' THEN
    v_semana := p_grade->'horarios_semana';
    v_ativos := COALESCE(p_grade->'horarios_dias_ativos', '[]'::JSONB);
  ELSE
    v_semana := NULL;
    v_ativos := NULL;
  END IF;

  INSERT INTO movelaria_funcionario_jornada (
    funcionario_id, hora_entrada, hora_saida_intervalo,
    hora_retorno_intervalo, hora_saida, tolerancia_minutos, dias_uteis, ativo,
    horarios_semana
  ) VALUES (
    p_funcionario_id, p_hora_entrada, p_hora_saida_intervalo,
    p_hora_retorno_intervalo, p_hora_saida, p_tolerancia_minutos, p_dias_uteis, p_ativo,
    v_semana
  )
  ON CONFLICT (funcionario_id) DO UPDATE SET
    hora_entrada = EXCLUDED.hora_entrada,
    hora_saida_intervalo = EXCLUDED.hora_saida_intervalo,
    hora_retorno_intervalo = EXCLUDED.hora_retorno_intervalo,
    hora_saida = EXCLUDED.hora_saida,
    tolerancia_minutos = EXCLUDED.tolerancia_minutos,
    dias_uteis = EXCLUDED.dias_uteis,
    ativo = EXCLUDED.ativo,
    horarios_semana = COALESCE(EXCLUDED.horarios_semana, movelaria_funcionario_jornada.horarios_semana),
    atualizado_em = NOW()
  RETURNING * INTO v_row;

  IF v_semana IS NOT NULL THEN
    v_patch := jsonb_build_object(
      'horarios_semana', v_semana,
      'horarios_dias_ativos', COALESCE(v_ativos, '[]'::JSONB)
    );
  ELSIF v_row.horarios_semana IS NOT NULL AND v_row.horarios_semana <> '{}'::JSONB THEN
    -- Atualiza só os dias marcados, sem forçar o mesmo horário em todos
    v_patch := jsonb_build_object(
      'horarios_semana', v_row.horarios_semana,
      'horarios_dias_ativos', (
        SELECT COALESCE(jsonb_agg(movelaria_isodow_to_dia_admissao(d) ORDER BY d), '[]'::JSONB)
        FROM unnest(v_row.dias_uteis) AS d
      )
    );
  ELSE
    v_patch := movelaria_horarios_admissao_from_jornada(
      v_row.hora_entrada,
      v_row.hora_saida_intervalo,
      v_row.hora_retorno_intervalo,
      v_row.hora_saida,
      v_row.dias_uteis
    );
  END IF;

  UPDATE movelaria_funcionarios
  SET
    admissao_dados = COALESCE(admissao_dados, '{}'::JSONB) || v_patch,
    atualizado_em = NOW()
  WHERE id = p_funcionario_id;

  RETURN to_jsonb(v_row);
END;
$$;


--
-- Name: movelaria_ponto_salvar_ocorrencia(uuid, date, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_salvar_ocorrencia(p_funcionario_id uuid, p_data date, p_tipo text, p_observacao text DEFAULT NULL::text, p_abater_banco_horas boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row movelaria_funcionario_ponto_ocorrencias%ROWTYPE;
  v_abater BOOLEAN := false;
  v_minutos INT := NULL;
  v_justificada BOOLEAN := false;
  v_obs TEXT := NULLIF(trim(COALESCE(p_observacao, '')), '');
BEGIN
  IF movelaria_meu_perfil() NOT IN ('administrador', 'financeiro') THEN
    RAISE EXCEPTION 'Sem permissão.';
  END IF;

  IF p_tipo NOT IN ('folga', 'falta', 'abono') THEN
    RAISE EXCEPTION 'Tipo de ocorrência inválido.';
  END IF;

  -- Folga/abono: tira a falta do dia (some da lista e do débito)
  IF p_tipo IN ('folga', 'abono') THEN
    DELETE FROM movelaria_funcionario_ponto_ocorrencias
    WHERE funcionario_id = p_funcionario_id
      AND data = p_data
      AND tipo = 'falta';

    INSERT INTO movelaria_funcionario_ponto_ocorrencias (
      funcionario_id, data, tipo, observacao, registrado_por,
      abater_banco_horas, minutos_abatidos, automatica
    ) VALUES (
      p_funcionario_id, p_data, p_tipo, v_obs, auth.uid(),
      false, NULL, false
    )
    ON CONFLICT (funcionario_id, data, tipo) DO UPDATE SET
      observacao = EXCLUDED.observacao,
      registrado_por = auth.uid(),
      abater_banco_horas = false,
      minutos_abatidos = NULL,
      automatica = false
    RETURNING * INTO v_row;

    RETURN to_jsonb(v_row);
  END IF;

  -- Falta: justificativa real remove débito; sem justificativa debita
  v_justificada := movelaria_ponto_falta_tem_justificativa(v_obs);

  IF v_justificada THEN
    v_abater := false;
    v_minutos := NULL;
  ELSE
    -- Injustificada: debita por padrão (NULL ou true); só false evita
    v_abater := COALESCE(p_abater_banco_horas, true);
    IF v_abater THEN
      v_minutos := NULLIF(movelaria_jornada_minutos_no_dia(p_funcionario_id, p_data), 0);
    END IF;
  END IF;

  INSERT INTO movelaria_funcionario_ponto_ocorrencias (
    funcionario_id, data, tipo, observacao, registrado_por,
    abater_banco_horas, minutos_abatidos, automatica
  ) VALUES (
    p_funcionario_id, p_data, 'falta',
    COALESCE(v_obs, 'Falta detectada automaticamente.'),
    auth.uid(),
    v_abater, v_minutos, false
  )
  ON CONFLICT (funcionario_id, data, tipo) DO UPDATE SET
    observacao = EXCLUDED.observacao,
    registrado_por = auth.uid(),
    abater_banco_horas = EXCLUDED.abater_banco_horas,
    minutos_abatidos = EXCLUDED.minutos_abatidos,
    automatica = CASE
      WHEN movelaria_funcionario_ponto_ocorrencias.automatica
        AND movelaria_ponto_falta_tem_justificativa(EXCLUDED.observacao)
      THEN false
      WHEN EXCLUDED.observacao = 'Falta detectada automaticamente.'
        AND EXCLUDED.abater_banco_horas
      THEN true
      ELSE movelaria_funcionario_ponto_ocorrencias.automatica
    END
  RETURNING * INTO v_row;

  RETURN to_jsonb(v_row);
END;
$$;


--
-- Name: movelaria_ponto_sincronizar_faltas_periodo(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_sincronizar_faltas_periodo(p_inicio date, p_fim date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dia DATE;
  v_total INT := 0;
  v_fim DATE := LEAST(p_fim, movelaria_ponto_data_faltas_ate());
BEGIN
  IF p_inicio IS NULL OR v_fim IS NULL OR p_inicio > v_fim THEN
    RETURN 0;
  END IF;

  v_dia := p_inicio;
  WHILE v_dia <= v_fim LOOP
    v_total := v_total + movelaria_ponto_detectar_faltas(v_dia);
    v_dia := v_dia + 1;
  END LOOP;

  RETURN v_total;
END;
$$;


--
-- Name: movelaria_ponto_status_dia(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_status_dia(p_funcionario_id uuid DEFAULT NULL::uuid, p_data date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_func_id UUID;
  v_data DATE := COALESCE(p_data, movelaria_ponto_data_local());
  v_jornada movelaria_funcionario_jornada%ROWTYPE;
  v_proximo TEXT;
  v_ocorrencia TEXT;
  v_marcacoes JSONB;
  v_status_dia TEXT := 'pendente';
  v_hora_sp INT := EXTRACT(HOUR FROM (NOW() AT TIME ZONE 'America/Sao_Paulo'))::INT;
BEGIN
  IF p_funcionario_id IS NULL THEN
    SELECT id INTO v_func_id FROM movelaria_funcionarios
    WHERE usuario_id = auth.uid() AND ativo = true;
  ELSE
    v_func_id := p_funcionario_id;
  END IF;

  IF v_func_id IS NULL THEN RETURN NULL; END IF;

  SELECT * INTO v_jornada FROM movelaria_funcionario_jornada
  WHERE funcionario_id = v_func_id;

  -- Falta automática no dia corrente (antes das 23h) não bloqueia nem aparece como ocorrência
  SELECT tipo INTO v_ocorrencia FROM movelaria_funcionario_ponto_ocorrencias
  WHERE funcionario_id = v_func_id AND data = v_data
    AND NOT (
      tipo = 'falta'
      AND COALESCE(automatica, false) = true
      AND v_data = movelaria_ponto_data_local()
      AND v_hora_sp < 23
    )
  ORDER BY criado_em DESC LIMIT 1;

  v_proximo := movelaria_ponto_proximo_tipo(v_func_id, v_data);

  SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.registrado_em), '[]'::jsonb)
  INTO v_marcacoes
  FROM movelaria_funcionario_ponto_marcacoes m
  WHERE m.funcionario_id = v_func_id AND movelaria_ponto_data_local(m.registrado_em) = v_data;

  IF v_ocorrencia = 'folga' THEN v_status_dia := 'folga';
  ELSIF v_ocorrencia = 'falta' THEN v_status_dia := 'falta';
  ELSIF EXISTS (SELECT 1 FROM jsonb_array_elements(v_marcacoes) e WHERE e->>'status' = 'atraso') THEN v_status_dia := 'atraso';
  ELSIF v_proximo IS NULL AND jsonb_array_length(v_marcacoes) > 0 THEN v_status_dia := 'completo';
  ELSIF jsonb_array_length(v_marcacoes) > 0 THEN v_status_dia := 'em_dia';
  END IF;

  RETURN jsonb_build_object(
    'funcionario_id', v_func_id,
    'data', v_data,
    'jornada', CASE WHEN v_jornada.id IS NOT NULL THEN to_jsonb(v_jornada) ELSE NULL END,
    'proximo_tipo', v_proximo,
    'ocorrencia', v_ocorrencia,
    'status_dia', v_status_dia,
    'marcacoes', v_marcacoes
  );
END;
$$;


--
-- Name: movelaria_ponto_ts_efetivo(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_ponto_ts_efetivo(p_registrado timestamp with time zone, p_ajustado timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(p_ajustado, p_registrado);
$$;


--
-- Name: movelaria_prestador_financeiro(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_prestador_financeiro(p_mes integer, p_ano integer) RETURNS TABLE(tipo text, obra_id uuid, conta_pagar_id uuid, cliente_nome text, descricao text, valor numeric, status text, data_referencia date, categoria text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid                   UUID := auth.uid();
  v_valor_fixo            NUMERIC(12, 2);
  v_nome                  TEXT;
  v_primeiro_vencimento   DATE;
  v_recorrencia_id        UUID;
  v_tem_fixo_cp           BOOLEAN;
  v_vencimento_mes        DATE;
BEGIN
  IF NOT movelaria_usuario_tem_algum_perfil(
    ARRAY['montador', 'montador_admin', 'administrador', 'financeiro', 'administrador_obras']
  ) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  SELECT COALESCE(NULLIF(u.valor_fixo_mensal, 0), f.valor_fixo_mensal, 0),
         COALESCE(NULLIF(TRIM(u.nome), ''), NULLIF(TRIM(f.nome), ''), split_part(u.email, '@', 1)),
         COALESCE(u.fixo_primeiro_vencimento, f.fixo_primeiro_vencimento),
         COALESCE(u.fixo_recorrencia_id, f.fixo_recorrencia_id)
  INTO v_valor_fixo, v_nome, v_primeiro_vencimento, v_recorrencia_id
  FROM movelaria_usuarios u
  LEFT JOIN LATERAL (
    SELECT ff.valor_fixo_mensal, ff.fixo_primeiro_vencimento, ff.fixo_recorrencia_id, ff.nome
    FROM movelaria_funcionarios ff
    WHERE ff.ativo = true
      AND (
        ff.usuario_id = u.id
        OR (ff.email IS NOT NULL AND lower(ff.email) = lower(u.email))
      )
    ORDER BY
      CASE WHEN COALESCE(ff.valor_fixo_mensal, 0) > 0 THEN 0 ELSE 1 END,
      ff.atualizado_em DESC NULLS LAST
    LIMIT 1
  ) f ON true
  WHERE u.id = v_uid;

  IF COALESCE(v_valor_fixo, 0) > 0 THEN
    PERFORM movelaria_expandir_fixo_montador(v_uid);

    v_vencimento_mes := movelaria_fixo_vencimento_mes(
      COALESCE(v_primeiro_vencimento, CURRENT_DATE),
      p_ano,
      p_mes
    );

    SELECT EXISTS (
      SELECT 1
      FROM movelaria_contas_pagar cp
      WHERE cp.prestador_id = v_uid
        AND (
          COALESCE(cp.descricao, '') LIKE 'Fixo montador:%'
          OR COALESCE(cp.descricao, '') LIKE 'Fixo:%'
        )
        AND EXTRACT(MONTH FROM cp.data_vencimento) = p_mes
        AND EXTRACT(YEAR  FROM cp.data_vencimento) = p_ano
    ) INTO v_tem_fixo_cp;

    IF NOT v_tem_fixo_cp
       AND (v_primeiro_vencimento IS NULL OR v_vencimento_mes >= v_primeiro_vencimento) THEN
      IF v_recorrencia_id IS NULL THEN
        v_recorrencia_id := gen_random_uuid();

        UPDATE movelaria_usuarios
        SET fixo_recorrencia_id = v_recorrencia_id,
            valor_fixo_mensal = v_valor_fixo,
            fixo_primeiro_vencimento = COALESCE(fixo_primeiro_vencimento, v_vencimento_mes),
            atualizado_em = NOW()
        WHERE id = v_uid;
      END IF;

      INSERT INTO movelaria_contas_pagar (
        prestador_id,
        fornecedor_nome,
        descricao,
        valor_total,
        numero_parcela,
        total_parcelas,
        valor_parcela,
        data_vencimento,
        status,
        recorrente,
        recorrencia_id,
        recorrencia_valor_base
      ) VALUES (
        v_uid,
        v_nome,
        'Fixo montador: ' || v_nome,
        v_valor_fixo,
        1,
        1,
        v_valor_fixo,
        v_vencimento_mes,
        'pendente',
        true,
        v_recorrencia_id,
        v_valor_fixo
      );

      v_tem_fixo_cp := true;
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    'pagamento'::TEXT,
    cp.obra_id,
    cp.id,
    COALESCE(
      (SELECT o2.cliente_nome FROM movelaria_obras o2 WHERE o2.id = cp.obra_id),
      split_part(cp.descricao, ': ', 2),
      cp.fornecedor_nome
    ),
    cp.descricao,
    cp.valor_parcela,
    cp.status,
    COALESCE(cp.data_pagamento, cp.data_vencimento),
    CASE
      WHEN COALESCE(cp.descricao, '') LIKE 'Fixo montador:%' THEN 'fixo'::TEXT
      WHEN COALESCE(cp.descricao, '') LIKE 'Fixo:%' THEN 'fixo'::TEXT
      ELSE 'comissao'::TEXT
    END
  FROM movelaria_contas_pagar cp
  WHERE cp.prestador_id = v_uid
    AND EXTRACT(MONTH FROM cp.data_vencimento) = p_mes
    AND EXTRACT(YEAR  FROM cp.data_vencimento) = p_ano
    AND (
      COALESCE(cp.descricao, '') LIKE 'Fixo montador:%'
      OR COALESCE(cp.descricao, '') LIKE 'Fixo:%'
      OR NOT EXISTS (
        SELECT 1
        FROM movelaria_obra_comissao_itens ci
        WHERE ci.obra_id = cp.obra_id
          AND ci.prestador_id = cp.prestador_id
          AND COALESCE(ci.oculto_prestador, false)
      )
    )

  UNION ALL

  SELECT
    'pagamento'::TEXT,
    NULL::UUID,
    NULL::UUID,
    v_nome,
    'Recebimento fixo mensal',
    v_valor_fixo,
    'pendente'::TEXT,
    movelaria_fixo_vencimento_mes(
      COALESCE(v_primeiro_vencimento, CURRENT_DATE),
      p_ano,
      p_mes
    ),
    'fixo'::TEXT
  WHERE COALESCE(v_valor_fixo, 0) > 0
    AND NOT COALESCE(v_tem_fixo_cp, false)

  ORDER BY 8, 4;
END;
$$;


--
-- Name: movelaria_puxar_lead_producao(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_puxar_lead_producao(p_lead_id bigint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
DECLARE
  v_id UUID;
  v_stage UUID;
  v_obra UUID;
BEGIN
  IF NOT emp_garbo.me_can_access_producao(auth.uid()) THEN
    RAISE EXCEPTION 'Acesso negado à produção';
  END IF;

  SELECT id INTO v_id FROM emp_garbo.obra_producao WHERE lead_id = p_lead_id;
  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  SELECT id INTO v_stage
  FROM emp_garbo.producao_stages
  WHERE ativo = true
  ORDER BY ordem ASC
  LIMIT 1;

  IF v_stage IS NULL THEN
    RAISE EXCEPTION 'Nenhuma coluna de produção configurada';
  END IF;

  SELECT id INTO v_obra
  FROM public.movelaria_obras
  WHERE origem_lead_id = p_lead_id::text
  ORDER BY criado_em DESC NULLS LAST
  LIMIT 1;

  INSERT INTO emp_garbo.obra_producao (obra_id, lead_id, stage_id)
  VALUES (v_obra, p_lead_id, v_stage)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: movelaria_reabrir_obra(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_reabrir_obra(p_obra_id uuid, p_status_destino text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_perfil TEXT := movelaria_meu_perfil();
  v_uid    UUID := auth.uid();
  v_status TEXT;
  v_status_atual TEXT;
  v_iniciado TIMESTAMPTZ;
  v_data_inicio DATE;
  v_data_fim DATE;
  v_hoje DATE := (NOW() AT TIME ZONE 'America/Sao_Paulo')::DATE;
BEGIN
  IF v_perfil IS NULL THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  IF v_perfil NOT IN ('administrador', 'administrador_obras', 'montador_admin') THEN
    RAISE EXCEPTION 'Acesso negado: somente montador administrativo ou administradores podem reabrir a obra';
  END IF;

  IF v_perfil = 'montador_admin' AND NOT movelaria_montador_admin_acessa_obra(p_obra_id, v_uid) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  SELECT status_kanban, iniciado_em, data_prevista_inicio, data_prevista_fim
  INTO v_status_atual, v_iniciado, v_data_inicio, v_data_fim
  FROM movelaria_obras
  WHERE id = p_obra_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Obra não encontrada';
  END IF;

  IF v_status_atual IS DISTINCT FROM 'concluida' THEN
    RAISE EXCEPTION 'Só é possível reabrir uma obra marcada como concluída';
  END IF;

  IF p_status_destino IS NOT NULL THEN
    IF p_status_destino NOT IN ('datas_em_aberto', 'datas_em_atraso', 'datas_definidas', 'em_andamento') THEN
      RAISE EXCEPTION 'Status de destino inválido para reabrir a obra';
    END IF;
    v_status := p_status_destino;
  ELSIF v_iniciado IS NOT NULL THEN
    v_status := 'em_andamento';
  ELSIF v_data_fim IS NOT NULL AND v_data_fim < v_hoje THEN
    v_status := 'datas_em_atraso';
  ELSIF v_data_inicio IS NOT NULL OR v_data_fim IS NOT NULL THEN
    v_status := 'datas_definidas';
  ELSE
    v_status := 'datas_em_aberto';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM movelaria_contas_pagar cp
    WHERE cp.obra_id = p_obra_id
      AND cp.fornecedor_nome ILIKE 'Comissão:%'
      AND (
        cp.status IN ('pago', 'parcialmente_pago')
        OR COALESCE(cp.valor_pago, 0) > 0.009
      )
  ) THEN
    RAISE EXCEPTION 'Não é possível reabrir: a comissão desta obra já foi paga. Estorne o pagamento em Contas a Pagar primeiro.';
  END IF;

  -- Remove reservas/pagamentos ligados às comissões geradas desta obra
  DELETE FROM movelaria_caixa_movimentacoes m
  WHERE m.conta_pagar_id IN (
    SELECT cp.id
    FROM movelaria_contas_pagar cp
    WHERE cp.obra_id = p_obra_id
      AND cp.fornecedor_nome ILIKE 'Comissão:%'
  );

  -- Remove os lançamentos gerados; os valores definidos na obra permanecem
  DELETE FROM movelaria_contas_pagar
  WHERE obra_id = p_obra_id
    AND fornecedor_nome ILIKE 'Comissão:%';

  UPDATE movelaria_obra_responsaveis
  SET finalizado_em = NULL
  WHERE obra_id = p_obra_id
    AND finalizado_em IS NOT NULL;

  UPDATE movelaria_obras
  SET status_kanban      = v_status,
      finalizado_em      = NULL,
      duracao_real_horas = NULL,
      comissao_gerada    = false,
      atualizado_em      = NOW()
  WHERE id = p_obra_id;
END;
$$;


--
-- Name: movelaria_recalcular_saldo_caixa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_recalcular_saldo_caixa() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_destinatario_id UUID;
    target_mes INTEGER;
    target_ano INTEGER;
    v_rows INTEGER;
BEGIN
    IF (TG_OP = 'DELETE') THEN
        target_destinatario_id := OLD.destinatario_id;
        target_mes := OLD.mes_referencia;
        target_ano := OLD.ano_referencia;
    ELSE
        target_destinatario_id := NEW.destinatario_id;
        target_mes := NEW.mes_referencia;
        target_ano := NEW.ano_referencia;
    END IF;

    INSERT INTO movelaria_caixa_saldo_acumulado (destinatario_id, mes_referencia, ano_referencia, total_reservado, total_pago, saldo)
    SELECT
        destinatario_id,
        mes_referencia,
        ano_referencia,
        COALESCE(SUM(CASE WHEN tipo_movimentacao = 'reserva' THEN valor ELSE 0 END), 0) AS total_reservado,
        COALESCE(SUM(CASE WHEN tipo_movimentacao = 'pagamento' THEN valor ELSE 0 END), 0) AS total_pago,
        COALESCE(SUM(CASE WHEN tipo_movimentacao = 'reserva' THEN valor ELSE -valor END), 0) AS saldo
    FROM movelaria_caixa_movimentacoes
    WHERE destinatario_id = target_destinatario_id
      AND mes_referencia = target_mes
      AND ano_referencia = target_ano
    GROUP BY destinatario_id, mes_referencia, ano_referencia
    ON CONFLICT (destinatario_id, mes_referencia, ano_referencia) DO UPDATE SET
        total_reservado = EXCLUDED.total_reservado,
        total_pago = EXCLUDED.total_pago,
        saldo = EXCLUDED.saldo;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        UPDATE movelaria_caixa_saldo_acumulado
        SET total_reservado = 0, total_pago = 0, saldo = 0
        WHERE destinatario_id = target_destinatario_id
          AND mes_referencia = target_mes
          AND ano_referencia = target_ano;
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: movelaria_redefinir_senha(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_redefinir_senha(p_id uuid, p_senha text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'auth', 'public'
    AS $$
DECLARE
  v_email TEXT;
BEGIN
  IF movelaria_meu_perfil() <> 'administrador' THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  IF p_senha IS NULL OR length(p_senha) < 6 THEN
    RAISE EXCEPTION 'Senha inválida: mínimo de 6 caracteres';
  END IF;

  UPDATE auth.users
  SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
      confirmation_token         = COALESCE(confirmation_token, ''),
      recovery_token             = COALESCE(recovery_token, ''),
      email_change_token_new     = COALESCE(email_change_token_new, ''),
      email_change               = COALESCE(email_change, ''),
      email_change_token_current = COALESCE(email_change_token_current, ''),
      phone_change_token         = COALESCE(phone_change_token, ''),
      reauthentication_token     = COALESCE(reauthentication_token, ''),
      updated_at = NOW()
  WHERE id = p_id
  RETURNING email INTO v_email;

  IF v_email IS NULL THEN
    RAISE EXCEPTION 'Usuário não encontrado';
  END IF;
END;
$$;


--
-- Name: movelaria_registrar_fim_montador(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
