--
-- Name: movelaria_registrar_historico_transacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_registrar_historico_transacao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_user_email TEXT;
  v_registro_id UUID;
BEGIN
  IF v_user_id IS NOT NULL THEN
    SELECT email INTO v_user_email
    FROM movelaria_usuarios
    WHERE id = v_user_id;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_registro_id := NEW.id;
  ELSIF TG_OP = 'UPDATE' THEN
    v_registro_id := NEW.id;
  ELSE
    v_registro_id := OLD.id;
  END IF;

  INSERT INTO movelaria_transacoes_historico (
    tabela_origem,
    registro_id,
    acao,
    dados_antes,
    dados_depois,
    usuario_id,
    usuario_email
  ) VALUES (
    TG_TABLE_NAME,
    v_registro_id,
    lower(TG_OP),
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END,
    v_user_id,
    v_user_email
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


