--
-- Name: movelaria_registrar_usuario_existente(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_registrar_usuario_existente(p_email text, p_nome text DEFAULT NULL::text, p_perfil text DEFAULT 'marceneiro'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'auth', 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  IF movelaria_meu_perfil() <> 'administrador' THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;
  IF p_perfil NOT IN ('administrador','financeiro','marceneiro','montador','montador_admin') THEN
    RAISE EXCEPTION 'Perfil inválido: %', p_perfil;
  END IF;

  -- Busca por email em auth.users (case-insensitive)
  SELECT id INTO v_id
  FROM auth.users
  WHERE lower(email) = lower(p_email)
  LIMIT 1;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'Nenhum usuário encontrado com o e-mail "%"', p_email;
  END IF;

  -- Cria ou atualiza o perfil movelaria
  INSERT INTO public.movelaria_usuarios (id, email, nome, perfil, ativo)
  VALUES (v_id, p_email, p_nome, p_perfil, true)
  ON CONFLICT (id) DO UPDATE
    SET nome          = COALESCE(EXCLUDED.nome, public.movelaria_usuarios.nome),
        perfil        = EXCLUDED.perfil,
        ativo         = true,
        atualizado_em = NOW();

  RETURN v_id;
END;
$$;


--
-- Name: movelaria_registrar_usuario_existente(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_registrar_usuario_existente(p_email text, p_nome text DEFAULT NULL::text, p_perfil text DEFAULT 'marceneiro'::text, p_senha text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'auth', 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  IF movelaria_meu_perfil() <> 'administrador' THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;
  IF NOT (p_perfil = ANY(movelaria_perfis_validos())) THEN
    RAISE EXCEPTION 'Perfil inválido: %', p_perfil;
  END IF;

  SELECT id INTO v_id FROM auth.users WHERE lower(email) = lower(p_email);
  IF v_id IS NULL THEN
    RAISE EXCEPTION 'Nenhum usuário encontrado com o e-mail "%"', p_email;
  END IF;

  INSERT INTO public.movelaria_usuarios (id, email, nome, perfil, ativo)
  VALUES (v_id, lower(p_email), p_nome, p_perfil, true)
  ON CONFLICT (id) DO UPDATE
    SET nome   = COALESCE(EXCLUDED.nome, public.movelaria_usuarios.nome),
        perfil = EXCLUDED.perfil,
        ativo  = true,
        atualizado_em = NOW();

  IF p_senha IS NOT NULL AND p_senha <> '' THEN
    UPDATE auth.users
    SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
        updated_at = NOW()
    WHERE id = v_id;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: movelaria_rep_obter_config(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_rep_obter_config() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row movelaria_rep_config%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM movelaria_rep_config WHERE ativo = true LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;

  RETURN jsonb_build_object(
    'id', v_row.id,
    'razao_social', v_row.razao_social,
    'cnpj', v_row.cnpj,
    'inpi_registro', v_row.inpi_registro,
    'versao_software', v_row.versao_software,
    'certificado_valido_ate', v_row.certificado_valido_ate,
    'nsr_atual', v_row.nsr_atual,
    'ativo', v_row.ativo,
    'certificado_configurado', v_row.certificado_path IS NOT NULL AND v_row.certificado_path <> '',
    'certificado_senha_configurada', v_row.certificado_senha IS NOT NULL AND v_row.certificado_senha <> '',
    'certificado_nome', CASE
      WHEN v_row.certificado_path IS NULL OR v_row.certificado_path = '' THEN NULL
      ELSE regexp_replace(v_row.certificado_path, '^.*[/\\]', '')
    END
  );
END;
$$;


--
-- Name: movelaria_rep_salvar_config(text, text, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_rep_salvar_config(p_razao_social text, p_cnpj text, p_inpi_registro text DEFAULT NULL::text, p_versao_software text DEFAULT '1.0.0'::text, p_certificado_valido_ate date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row movelaria_rep_config%ROWTYPE;
  v_cnpj TEXT := regexp_replace(COALESCE(p_cnpj, ''), '\D', '', 'g');
BEGIN
  IF movelaria_meu_perfil() <> 'administrador' THEN
    RAISE EXCEPTION 'Somente administradores podem alterar a configuração REP-P.';
  END IF;

  IF length(v_cnpj) <> 14 THEN
    RAISE EXCEPTION 'CNPJ inválido. Informe 14 dígitos.';
  END IF;

  IF trim(COALESCE(p_razao_social, '')) = '' THEN
    RAISE EXCEPTION 'Razão social é obrigatória.';
  END IF;

  UPDATE movelaria_rep_config
  SET
    razao_social = trim(p_razao_social),
    cnpj = v_cnpj,
    inpi_registro = NULLIF(trim(COALESCE(p_inpi_registro, '')), ''),
    versao_software = COALESCE(NULLIF(trim(p_versao_software), ''), '1.0.0'),
    certificado_valido_ate = p_certificado_valido_ate,
    atualizado_em = NOW()
  WHERE ativo = true
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    INSERT INTO movelaria_rep_config (
      razao_social, cnpj, inpi_registro, versao_software, certificado_valido_ate, ativo
    ) VALUES (
      trim(p_razao_social), v_cnpj,
      NULLIF(trim(COALESCE(p_inpi_registro, '')), ''),
      COALESCE(NULLIF(trim(p_versao_software), ''), '1.0.0'),
      p_certificado_valido_ate,
      true
    )
    RETURNING * INTO v_row;
  END IF;

  RETURN to_jsonb(v_row);
END;
$$;


--
-- Name: movelaria_rep_salvar_config(text, text, text, text, date, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_rep_salvar_config(p_razao_social text, p_cnpj text, p_inpi_registro text DEFAULT NULL::text, p_versao_software text DEFAULT '1.0.0'::text, p_certificado_valido_ate date DEFAULT NULL::date, p_certificado_path text DEFAULT NULL::text, p_certificado_senha text DEFAULT NULL::text, p_atualizar_senha boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row movelaria_rep_config%ROWTYPE;
  v_cnpj TEXT := regexp_replace(COALESCE(p_cnpj, ''), '\D', '', 'g');
BEGIN
  IF movelaria_meu_perfil() <> 'administrador' THEN
    RAISE EXCEPTION 'Somente administradores podem alterar a configuração REP-P.';
  END IF;

  IF length(v_cnpj) <> 14 THEN
    RAISE EXCEPTION 'CNPJ inválido. Informe 14 dígitos.';
  END IF;

  IF trim(COALESCE(p_razao_social, '')) = '' THEN
    RAISE EXCEPTION 'Razão social é obrigatória.';
  END IF;

  UPDATE movelaria_rep_config
  SET
    razao_social = trim(p_razao_social),
    cnpj = v_cnpj,
    inpi_registro = NULLIF(trim(COALESCE(p_inpi_registro, '')), ''),
    versao_software = COALESCE(NULLIF(trim(p_versao_software), ''), '1.0.0'),
    certificado_valido_ate = p_certificado_valido_ate,
    certificado_path = COALESCE(NULLIF(trim(p_certificado_path), ''), certificado_path),
    certificado_senha = CASE
      WHEN p_atualizar_senha THEN NULLIF(trim(COALESCE(p_certificado_senha, '')), '')
      ELSE certificado_senha
    END,
    atualizado_em = NOW()
  WHERE ativo = true
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    INSERT INTO movelaria_rep_config (
      razao_social, cnpj, inpi_registro, versao_software,
      certificado_valido_ate, certificado_path, certificado_senha, ativo
    ) VALUES (
      trim(p_razao_social), v_cnpj,
      NULLIF(trim(COALESCE(p_inpi_registro, '')), ''),
      COALESCE(NULLIF(trim(p_versao_software), ''), '1.0.0'),
      p_certificado_valido_ate,
      NULLIF(trim(COALESCE(p_certificado_path, '')), ''),
      NULLIF(trim(COALESCE(p_certificado_senha, '')), ''),
      true
    )
    RETURNING * INTO v_row;
  END IF;

  RETURN movelaria_rep_obter_config();
END;
$$;


--
-- Name: movelaria_reserva_da_conta(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_reserva_da_conta(p_conta_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(SUM(valor), 0)::NUMERIC(12,2)
  FROM movelaria_caixa_movimentacoes
  WHERE conta_pagar_id = p_conta_id
    AND tipo_movimentacao = 'reserva';
$$;


--
-- Name: movelaria_resolver_caixa_destinatario_prestador(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_resolver_caixa_destinatario_prestador(p_nome text, p_prestador_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_id   UUID;
  v_nome TEXT := NULLIF(TRIM(p_nome), '');
BEGIN
  -- Se o nome já veio no padrão "Comissão: …", usa como está
  IF v_nome IS NULL AND p_prestador_id IS NOT NULL THEN
    v_nome := movelaria_nome_destinatario_prestador(p_prestador_id, false);
  END IF;

  IF v_nome IS NULL THEN
    RETURN NULL;
  END IF;

  -- Nunca criar destinatário com título de obra antiga "Comissão: Cliente"
  -- sem prestador: isso misturava várias pessoas.
  IF v_nome ~* '^Comissão:\s*' AND p_prestador_id IS NOT NULL THEN
    -- Se não for "Comissão: NomeDoPrestador", força o padrão correto
    IF LOWER(TRIM(v_nome)) IS DISTINCT FROM LOWER(TRIM(movelaria_nome_destinatario_prestador(p_prestador_id, true)))
       AND EXISTS (
         SELECT 1 FROM movelaria_usuarios u
         WHERE u.id = p_prestador_id
           AND LOWER(TRIM(v_nome)) NOT LIKE LOWER('Comissão: ' || COALESCE(NULLIF(TRIM(u.nome), ''), split_part(u.email, '@', 1)))
       )
    THEN
      v_nome := movelaria_nome_destinatario_prestador(p_prestador_id, true);
    END IF;
  END IF;

  SELECT id INTO v_id
  FROM movelaria_caixa_destinatarios
  WHERE LOWER(TRIM(nome)) = LOWER(v_nome)
    AND ativo = true
  LIMIT 1;

  IF v_id IS NULL THEN
    INSERT INTO movelaria_caixa_destinatarios (nome, tipo, observacoes)
    VALUES (
      v_nome,
      'marceneiro',
      CASE WHEN p_prestador_id IS NOT NULL
        THEN 'Prestador obra — ' || p_prestador_id::TEXT
        ELSE 'Prestador obra'
      END
    )
    RETURNING id INTO v_id;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: movelaria_salvar_markup_itens(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_salvar_markup_itens(p_orcamento_id uuid, p_linhas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
DECLARE
  v_modulos JSONB;
  v_linhas JSONB;
  v_sum NUMERIC;
  v_fator NUMERIC;
  v_ajustado NUMERIC;
BEGIN
  IF NOT movelaria_usuario_tem_qualquer_perfil(ARRAY['administrador', 'financeiro']) THEN
    RAISE EXCEPTION 'Acesso negado: somente administrador ou financeiro editam o markup.';
  END IF;

  IF p_linhas IS NULL OR jsonb_typeof(p_linhas) <> 'array' THEN
    RAISE EXCEPTION 'Linhas inválidas.';
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      (elem
        || jsonb_build_object(
          'quantidade', COALESCE((elem->>'quantidade')::NUMERIC, 0),
          'valor_unitario', COALESCE((elem->>'valor_unitario')::NUMERIC, 0),
          'valor_total', ROUND(
            COALESCE((elem->>'quantidade')::NUMERIC, 0)
            * COALESCE((elem->>'valor_unitario')::NUMERIC, 0)
          , 2),
          'ativo', COALESCE((elem->>'ativo')::BOOLEAN, true)
        )
      )
    ),
    '[]'::JSONB
  )
  INTO v_linhas
  FROM jsonb_array_elements(p_linhas) AS elem;

  SELECT COALESCE(SUM(
    CASE
      WHEN COALESCE((elem->>'ativo')::BOOLEAN, true)
        THEN COALESCE((elem->>'valor_total')::NUMERIC, 0)
      ELSE 0
    END
  ), 0)
  INTO v_sum
  FROM jsonb_array_elements(v_linhas) AS elem;

  SELECT COALESCE(fator_sobras, 1) INTO v_fator
  FROM emp_garbo.markup_config
  LIMIT 1;

  v_ajustado := ROUND(v_sum * COALESCE(v_fator, 1), 2);

  SELECT COALESCE(modulos, '{}'::JSONB)
  INTO v_modulos
  FROM emp_garbo.markup_orcamentos
  WHERE id = p_orcamento_id;

  IF v_modulos IS NULL THEN
    RAISE EXCEPTION 'Orçamento de markup não encontrado.';
  END IF;

  IF v_modulos->'materiais' IS NULL THEN
    v_modulos := jsonb_set(v_modulos, '{materiais}', '{"linhas":[]}'::JSONB, true);
  END IF;
  IF v_modulos->'totais' IS NULL THEN
    v_modulos := jsonb_set(v_modulos, '{totais}', '{}'::JSONB, true);
  END IF;

  v_modulos := jsonb_set(v_modulos, '{materiais,linhas}', v_linhas, true);
  v_modulos := jsonb_set(v_modulos, '{totais,custo_materiais}', to_jsonb(v_sum), true);
  v_modulos := jsonb_set(v_modulos, '{totais,custo_materiais_ajustado}', to_jsonb(v_ajustado), true);

  UPDATE emp_garbo.markup_orcamentos
  SET
    modulos = v_modulos,
    atualizado_em = NOW()
  WHERE id = p_orcamento_id;

  RETURN jsonb_build_object(
    'orcamento_id', p_orcamento_id,
    'custo_materiais', v_sum,
    'custo_materiais_ajustado', v_ajustado,
    'linhas', v_linhas
  );
END;
$$;


--
-- Name: movelaria_obra_markup_custos_filtro; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.movelaria_obra_markup_custos_filtro (
    obra_id uuid NOT NULL,
    incluir_materiais boolean DEFAULT true NOT NULL,
    incluir_servicos boolean DEFAULT true NOT NULL,
    incluir_despesas boolean DEFAULT true NOT NULL,
    atualizado_por uuid,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE movelaria_obra_markup_custos_filtro; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.movelaria_obra_markup_custos_filtro IS 'Categorias do markup marcadas por obra na Agenda (compartilhado: Admin/Financeiro).';


--
-- Name: movelaria_salvar_obra_markup_custos_filtro(uuid, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_salvar_obra_markup_custos_filtro(p_obra_id uuid, p_materiais boolean, p_servicos boolean, p_despesas boolean) RETURNS public.movelaria_obra_markup_custos_filtro
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row movelaria_obra_markup_custos_filtro;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM movelaria_usuarios u
    WHERE u.id = auth.uid()
      AND u.ativo = true
      AND (
        u.perfil IN ('administrador', 'financeiro')
        OR 'administrador' = ANY (COALESCE(u.perfis_extras, '{}'::TEXT[]))
        OR 'financeiro' = ANY (COALESCE(u.perfis_extras, '{}'::TEXT[]))
      )
  ) THEN
    RAISE EXCEPTION 'Acesso negado: somente Administrador ou Financeiro podem alterar o filtro de custos.';
  END IF;

  IF p_obra_id IS NULL THEN
    RAISE EXCEPTION 'obra_id é obrigatório';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM movelaria_obras o WHERE o.id = p_obra_id) THEN
    RAISE EXCEPTION 'Obra não encontrada';
  END IF;

  INSERT INTO movelaria_obra_markup_custos_filtro AS t (
    obra_id,
    incluir_materiais,
    incluir_servicos,
    incluir_despesas,
    atualizado_por,
    atualizado_em
  )
  VALUES (
    p_obra_id,
    COALESCE(p_materiais, true),
    COALESCE(p_servicos, true),
    COALESCE(p_despesas, true),
    auth.uid(),
    NOW()
  )
  ON CONFLICT (obra_id) DO UPDATE
  SET
    incluir_materiais = EXCLUDED.incluir_materiais,
    incluir_servicos = EXCLUDED.incluir_servicos,
    incluir_despesas = EXCLUDED.incluir_despesas,
    atualizado_por = EXCLUDED.atualizado_por,
    atualizado_em = NOW()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


--
-- Name: movelaria_sincronizar_obra_comissao(uuid, boolean, uuid[], numeric[], boolean[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_sincronizar_obra_comissao(p_obra_id uuid, p_habilitada boolean, p_prestador_ids uuid[], p_valores numeric[], p_ocultos boolean[] DEFAULT NULL::boolean[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_gerada BOOLEAN;
  v_concluida BOOLEAN;
  i        INTEGER;
  v_oculto BOOLEAN;
BEGIN
  IF NOT movelaria_usuario_tem_algum_perfil(
    ARRAY['administrador', 'financeiro', 'administrador_obras']
  ) THEN
    RAISE EXCEPTION 'Acesso negado: somente administradores ou financeiro podem configurar comissões';
  END IF;

  SELECT comissao_gerada,
         (status_kanban = 'concluida' AND finalizado_em IS NOT NULL)
  INTO v_gerada, v_concluida
  FROM movelaria_obras
  WHERE id = p_obra_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Obra não encontrada';
  END IF;
  IF v_gerada THEN
    RAISE EXCEPTION 'Comissão já foi gerada para esta obra e não pode ser alterada';
  END IF;

  IF p_prestador_ids IS NULL OR p_valores IS NULL THEN
    RAISE EXCEPTION 'Listas de prestadores e valores são obrigatórias';
  END IF;

  IF array_length(p_prestador_ids, 1) IS DISTINCT FROM array_length(p_valores, 1) THEN
    RAISE EXCEPTION 'Quantidade de prestadores e valores deve ser igual';
  END IF;

  IF p_ocultos IS NOT NULL
     AND array_length(p_ocultos, 1) IS DISTINCT FROM array_length(p_prestador_ids, 1) THEN
    RAISE EXCEPTION 'Quantidade de flags ocultos deve ser igual à de prestadores';
  END IF;

  DELETE FROM movelaria_obra_comissao_itens ci
  WHERE ci.obra_id = p_obra_id
    AND NOT (ci.prestador_id = ANY(p_prestador_ids));

  IF p_habilitada AND array_length(p_prestador_ids, 1) > 0 THEN
    FOR i IN 1..array_length(p_prestador_ids, 1) LOOP
      IF COALESCE(p_valores[i], 0) > 0 THEN
        v_oculto := CASE
          WHEN p_ocultos IS NULL THEN false
          ELSE COALESCE(p_ocultos[i], false)
        END;

        INSERT INTO movelaria_obra_comissao_itens (obra_id, prestador_id, valor, oculto_prestador)
        VALUES (p_obra_id, p_prestador_ids[i], ROUND(p_valores[i], 2), v_oculto)
        ON CONFLICT (obra_id, prestador_id) DO UPDATE
          SET valor = EXCLUDED.valor,
              oculto_prestador = CASE
                WHEN p_ocultos IS NULL THEN movelaria_obra_comissao_itens.oculto_prestador
                ELSE EXCLUDED.oculto_prestador
              END,
              atualizado_em = NOW();
      ELSE
        DELETE FROM movelaria_obra_comissao_itens ci
        WHERE ci.obra_id = p_obra_id
          AND ci.prestador_id = p_prestador_ids[i];
      END IF;
    END LOOP;
  ELSE
    DELETE FROM movelaria_obra_comissao_itens WHERE obra_id = p_obra_id;
  END IF;

  UPDATE movelaria_obras
  SET comissao_habilitada = p_habilitada,
      comissao_total = COALESCE((
        SELECT SUM(ci.valor) FROM movelaria_obra_comissao_itens ci WHERE ci.obra_id = p_obra_id
      ), 0),
      atualizado_em = NOW()
  WHERE id = p_obra_id;

  IF v_concluida AND p_habilitada THEN
    PERFORM movelaria_aplicar_comissao_obra_interno(p_obra_id);
  END IF;
END;
$$;


--
-- Name: movelaria_sincronizar_obra_montadores(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_sincronizar_obra_montadores(p_obra_id uuid, p_montador_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_ids UUID[] := ARRAY[]::UUID[];
  v_id  UUID;
BEGIN
  IF NOT movelaria_usuario_tem_algum_perfil(
    ARRAY['administrador', 'montador_admin', 'administrador_obras', 'financeiro']
  ) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM movelaria_obras WHERE id = p_obra_id) THEN
    RAISE EXCEPTION 'Obra não encontrada';
  END IF;

  IF p_montador_ids IS NOT NULL THEN
    FOREACH v_id IN ARRAY p_montador_ids LOOP
      IF v_id IS NOT NULL AND NOT (v_id = ANY (v_ids)) THEN
        v_ids := array_append(v_ids, v_id);
      END IF;
    END LOOP;
  END IF;

  DELETE FROM movelaria_obra_responsaveis WHERE obra_id = p_obra_id;

  IF coalesce(array_length(v_ids, 1), 0) > 0 THEN
    INSERT INTO movelaria_obra_responsaveis (obra_id, montador_id)
    SELECT p_obra_id, unnest(v_ids);
  END IF;

  UPDATE movelaria_obras
  SET montador_id   = CASE
                        WHEN coalesce(array_length(v_ids, 1), 0) > 0 THEN v_ids[1]
                        ELSE NULL
                      END,
      atualizado_em = NOW()
  WHERE id = p_obra_id;
END;
$$;


--
-- Name: movelaria_sync_admissao_salario_fixo(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_sync_admissao_salario_fixo(p_funcionario_id uuid, p_valor numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txt TEXT;
BEGIN
  IF p_valor IS NULL OR p_valor <= 0 THEN
    UPDATE movelaria_funcionarios
    SET admissao_dados = CASE
          WHEN admissao_dados ? 'salario' THEN admissao_dados - 'salario'
          ELSE COALESCE(admissao_dados, '{}'::jsonb)
        END,
        atualizado_em = NOW()
    WHERE id = p_funcionario_id;
    RETURN;
  END IF;

  v_txt := TRIM(to_char(ROUND(p_valor::NUMERIC, 2), 'FM999999990.00'));

  UPDATE movelaria_funcionarios
  SET admissao_dados = jsonb_set(
        COALESCE(admissao_dados, '{}'::jsonb),
        '{salario}',
        to_jsonb(v_txt),
        true
      ),
      atualizado_em = NOW()
  WHERE id = p_funcionario_id;
END;
$$;


--
-- Name: movelaria_sync_caixa_pagamento_para_conta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_sync_caixa_pagamento_para_conta() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_cp RECORD;
  v_pago NUMERIC(12,2);
  v_total_faltante NUMERIC(12,2);
  v_faltante NUMERIC(12,2);
  v_alocado NUMERIC(12,2);
  v_novo_pago NUMERIC(12,2);
  v_novo_status TEXT;
  v_ja_pago NUMERIC(12,2);
  v_reservado NUMERIC(12,2);
BEGIN
  IF NEW.tipo_movimentacao IS DISTINCT FROM 'pagamento' THEN
    RETURN NEW;
  END IF;

  -- 1) Pagamento ligado diretamente à conta
  IF NEW.conta_pagar_id IS NOT NULL THEN
    SELECT COALESCE(SUM(valor), 0) INTO v_pago
    FROM movelaria_caixa_movimentacoes
    WHERE conta_pagar_id = NEW.conta_pagar_id
      AND tipo_movimentacao = 'pagamento';

    SELECT * INTO v_cp FROM movelaria_contas_pagar WHERE id = NEW.conta_pagar_id;
    IF FOUND THEN
      IF v_cp.status = 'pago'
         AND COALESCE(v_cp.valor_pago, 0) >= v_cp.valor_parcela - 0.009 THEN
        RETURN NEW;
      END IF;

      v_novo_pago := GREATEST(COALESCE(v_cp.valor_pago, 0), v_pago);
      IF v_novo_pago >= v_cp.valor_parcela - 0.009 THEN
        UPDATE movelaria_contas_pagar
        SET status = 'pago',
            valor_pago = v_cp.valor_parcela,
            data_pagamento = COALESCE(NEW.data_movimentacao, CURRENT_DATE),
            atualizado_em = NOW()
        WHERE id = v_cp.id;
      ELSIF v_novo_pago > 0.009 THEN
        UPDATE movelaria_contas_pagar
        SET status = 'parcialmente_pago',
            valor_pago = v_novo_pago,
            data_pagamento = COALESCE(NEW.data_movimentacao, CURRENT_DATE),
            atualizado_em = NOW()
        WHERE id = v_cp.id;
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  -- 2) Pagamento consolidado do destinatário no mês (Caixa "Pagar")
  IF NEW.destinatario_id IS NULL
     OR NEW.mes_referencia IS NULL
     OR NEW.ano_referencia IS NULL THEN
    RETURN NEW;
  END IF;

  v_pago := COALESCE(NEW.valor, 0);

  IF v_pago <= 0.009 THEN
    RETURN NEW;
  END IF;

  -- Falta cobrir = min(parcela aberta, reserva ainda não refletida em valor_pago).
  -- Se Contas a Pagar já registrou o mesmo valor da reserva, não aloca de novo.
  SELECT COALESCE(SUM(
    LEAST(
      GREATEST(cp.valor_parcela - COALESCE(cp.valor_pago, 0), 0),
      GREATEST(movelaria_reserva_da_conta(cp.id) - COALESCE(cp.valor_pago, 0), 0)
    )
  ), 0)
  INTO v_total_faltante
  FROM movelaria_contas_pagar cp
  WHERE cp.id IN (
    SELECT m.conta_pagar_id
    FROM movelaria_caixa_movimentacoes m
    WHERE m.destinatario_id = NEW.destinatario_id
      AND m.mes_referencia = NEW.mes_referencia
      AND m.ano_referencia = NEW.ano_referencia
      AND m.tipo_movimentacao = 'reserva'
      AND m.conta_pagar_id IS NOT NULL
  )
  AND NOT (
    cp.status = 'pago'
    AND COALESCE(cp.valor_pago, 0) >= cp.valor_parcela - 0.009
  )
  AND NOT EXISTS (
    SELECT 1 FROM movelaria_caixa_movimentacoes p
    WHERE p.conta_pagar_id = cp.id
      AND p.tipo_movimentacao = 'pagamento'
  );

  IF v_total_faltante <= 0.009 THEN
    RETURN NEW;
  END IF;

  PERFORM set_config('movelaria.skip_caixa_cleanup', '1', true);

  FOR v_cp IN
    SELECT cp.*
    FROM movelaria_contas_pagar cp
    WHERE cp.id IN (
      SELECT m.conta_pagar_id
      FROM movelaria_caixa_movimentacoes m
      WHERE m.destinatario_id = NEW.destinatario_id
        AND m.mes_referencia = NEW.mes_referencia
        AND m.ano_referencia = NEW.ano_referencia
        AND m.tipo_movimentacao = 'reserva'
        AND m.conta_pagar_id IS NOT NULL
    )
    AND NOT (
      cp.status = 'pago'
      AND COALESCE(cp.valor_pago, 0) >= cp.valor_parcela - 0.009
    )
    AND NOT EXISTS (
      SELECT 1 FROM movelaria_caixa_movimentacoes p
      WHERE p.conta_pagar_id = cp.id
        AND p.tipo_movimentacao = 'pagamento'
    )
    ORDER BY cp.data_vencimento NULLS LAST, cp.criado_em NULLS LAST, cp.id
  LOOP
    v_ja_pago := COALESCE(v_cp.valor_pago, 0);
    v_reservado := movelaria_reserva_da_conta(v_cp.id);

    -- Já espelhado em Contas a Pagar até o valor reservado → não soma de novo
    IF v_ja_pago >= v_reservado - 0.009 THEN
      CONTINUE;
    END IF;

    v_faltante := LEAST(
      GREATEST(v_cp.valor_parcela - v_ja_pago, 0),
      GREATEST(v_reservado - v_ja_pago, 0)
    );
    IF v_faltante <= 0.009 THEN
      CONTINUE;
    END IF;

    IF v_pago >= v_total_faltante - 0.009 THEN
      v_alocado := v_faltante;
    ELSE
      v_alocado := ROUND((v_faltante / v_total_faltante) * v_pago, 2);
    END IF;

    IF v_alocado <= 0.009 THEN
      CONTINUE;
    END IF;

    v_novo_pago := ROUND(v_ja_pago + v_alocado, 2);
    IF v_novo_pago < v_ja_pago THEN
      CONTINUE;
    END IF;

    IF v_novo_pago >= v_cp.valor_parcela - 0.009 THEN
      v_novo_pago := v_cp.valor_parcela;
      v_novo_status := 'pago';
    ELSE
      v_novo_status := 'parcialmente_pago';
    END IF;

    UPDATE movelaria_contas_pagar
    SET status = v_novo_status,
        valor_pago = v_novo_pago,
        data_pagamento = COALESCE(NEW.data_movimentacao, CURRENT_DATE),
        atualizado_em = NOW()
    WHERE id = v_cp.id
      AND NOT (
        status = 'pago'
        AND COALESCE(valor_pago, 0) >= valor_parcela - 0.009
      )
      AND COALESCE(valor_pago, 0) <= v_novo_pago + 0.009;
  END LOOP;

  PERFORM set_config('movelaria.skip_caixa_cleanup', '0', true);

  RETURN NEW;
END;
$$;


--
-- Name: movelaria_sync_cliente_lead_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_sync_cliente_lead_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
BEGIN
  PERFORM public.movelaria_upsert_cliente_from_lead(
    NEW.nome,
    NEW.telefone,
    NEW.email,
    NEW.origem,
    COALESCE(NEW.data_chegada, NEW.criado_em::date, CURRENT_DATE)
  );
  RETURN NEW;
END;
$$;


--
-- Name: movelaria_sync_clientes_from_leads(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_sync_clientes_from_leads() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'emp_garbo'
    AS $$
DECLARE
  v_inserted INTEGER := 0;
  v_updated INTEGER := 0;
BEGIN
  -- Atualiza clientes já existentes (match por telefone ou email).
  WITH leads_norm AS (
    SELECT
      trim(nome) AS nome,
      NULLIF(trim(telefone), '') AS telefone,
      NULLIF(trim(email), '') AS email,
      COALESCE(NULLIF(trim(origem), ''), 'Lead Garbo') AS origem,
      COALESCE(data_chegada, criado_em::date, CURRENT_DATE) AS data_cadastro
    FROM emp_garbo.leads
    WHERE NULLIF(trim(nome), '') IS NOT NULL
  ),
  updated_rows AS (
    UPDATE movelaria_clientes c
    SET
      nome = COALESCE(NULLIF(ln.nome, ''), c.nome),
      telefone = COALESCE(ln.telefone, c.telefone),
      email = COALESCE(ln.email, c.email),
      origem = COALESCE(ln.origem, c.origem),
      data_cadastro = COALESCE(ln.data_cadastro, c.data_cadastro),
      atualizado_em = NOW()
    FROM leads_norm ln
    WHERE (
      (ln.telefone IS NOT NULL AND c.telefone = ln.telefone)
      OR (ln.email IS NOT NULL AND c.email = ln.email)
    )
    RETURNING c.id
  )
  SELECT COUNT(*) INTO v_updated FROM updated_rows;

  -- Insere apenas quem ainda não existe por telefone/email.
  WITH leads_norm AS (
    SELECT
      trim(nome) AS nome,
      NULLIF(trim(telefone), '') AS telefone,
      NULLIF(trim(email), '') AS email,
      COALESCE(NULLIF(trim(origem), ''), 'Lead Garbo') AS origem,
      COALESCE(data_chegada, criado_em::date, CURRENT_DATE) AS data_cadastro
    FROM emp_garbo.leads
    WHERE NULLIF(trim(nome), '') IS NOT NULL
  ),
  inserted_rows AS (
    INSERT INTO movelaria_clientes (
      nome,
      telefone,
      email,
      origem,
      data_cadastro
    )
    SELECT
      ln.nome,
      ln.telefone,
      ln.email,
      ln.origem,
      ln.data_cadastro
    FROM leads_norm ln
    WHERE NOT EXISTS (
      SELECT 1
      FROM movelaria_clientes c
      WHERE
        (ln.telefone IS NOT NULL AND c.telefone = ln.telefone)
        OR (ln.email IS NOT NULL AND c.email = ln.email)
    )
    RETURNING id
  )
  SELECT COUNT(*) INTO v_inserted FROM inserted_rows;

  RETURN jsonb_build_object(
    'inserted', v_inserted,
    'updated', v_updated
  );
END;
$$;


