--
-- Name: movelaria_sync_funcionario_de_usuario(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_sync_funcionario_de_usuario() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tipo TEXT;
  v_nome TEXT;
  v_existing UUID;
  v_func_id UUID;
  v_categoria TEXT;
BEGIN
  v_tipo := CASE NEW.perfil
    WHEN 'marceneiro' THEN 'marceneiro'
    WHEN 'financeiro' THEN 'financeiro'
    WHEN 'montador' THEN 'montador'
    WHEN 'montador_admin' THEN 'montador_admin'
    WHEN 'administrador_obras' THEN 'administrador_obras'
    ELSE NULL
  END;

  v_categoria := CASE NEW.perfil
    WHEN 'montador' THEN 'montador'
    WHEN 'montador_admin' THEN 'montador'
    WHEN 'administrador_obras' THEN 'administrativo'
    WHEN 'financeiro' THEN 'financeiro'
    ELSE 'outro'
  END;

  v_nome := COALESCE(NULLIF(TRIM(NEW.nome), ''), split_part(NEW.email, '@', 1));

  IF v_tipo IS NULL OR NOT COALESCE(NEW.ativo, false) THEN
    UPDATE movelaria_funcionarios
    SET ativo = false, atualizado_em = NOW()
    WHERE usuario_id = NEW.id;
    RETURN NEW;
  END IF;

  SELECT id INTO v_existing
  FROM movelaria_funcionarios
  WHERE usuario_id = NEW.id
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    UPDATE movelaria_funcionarios
    SET
      nome = v_nome,
      email = NEW.email,
      tipo = v_tipo,
      categoria = COALESCE(NULLIF(TRIM(categoria), ''), v_categoria),
      ativo = true,
      atualizado_em = NOW()
    WHERE id = v_existing;
    v_func_id := v_existing;
  ELSE
    SELECT id INTO v_existing
    FROM movelaria_funcionarios
    WHERE usuario_id IS NULL
      AND email IS NOT NULL
      AND lower(email) = lower(NEW.email)
    LIMIT 1;

    IF v_existing IS NOT NULL THEN
      UPDATE movelaria_funcionarios
      SET
        usuario_id = NEW.id,
        nome = v_nome,
        email = NEW.email,
        tipo = v_tipo,
        categoria = COALESCE(NULLIF(TRIM(categoria), ''), v_categoria),
        ativo = true,
        atualizado_em = NOW()
      WHERE id = v_existing;
      v_func_id := v_existing;
    ELSE
      INSERT INTO movelaria_funcionarios (
        nome, email, tipo, categoria, usuario_id, admissao_status, ativo
      )
      VALUES (v_nome, NEW.email, v_tipo, v_categoria, NEW.id, 'pendente', true)
      RETURNING id INTO v_func_id;
    END IF;
  END IF;

  PERFORM movelaria_funcionario_garantir_jornada(v_func_id);
  RETURN NEW;
END;
$$;


--
-- Name: movelaria_sync_jornada_from_admissao_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_sync_jornada_from_admissao_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_jornada RECORD;
  v_semana JSONB;
BEGIN
  IF current_setting('movelaria.sync_horarios', true) = '1' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
    AND NEW.admissao_dados->'horarios_semana' IS NOT DISTINCT FROM OLD.admissao_dados->'horarios_semana'
    AND NEW.admissao_dados->'horarios_dias_ativos' IS NOT DISTINCT FROM OLD.admissao_dados->'horarios_dias_ativos'
  THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_jornada
  FROM movelaria_jornada_from_admissao_dados(NEW.admissao_dados);

  IF NOT FOUND OR v_jornada.hora_entrada IS NULL OR v_jornada.hora_saida IS NULL THEN
    RETURN NEW;
  END IF;

  v_semana := NEW.admissao_dados->'horarios_semana';

  PERFORM set_config('movelaria.sync_horarios', '1', true);

  INSERT INTO movelaria_funcionario_jornada (
    funcionario_id, hora_entrada, hora_saida_intervalo,
    hora_retorno_intervalo, hora_saida, tolerancia_minutos, dias_uteis, ativo,
    horarios_semana
  ) VALUES (
    NEW.id,
    v_jornada.hora_entrada,
    v_jornada.hora_saida_intervalo,
    v_jornada.hora_retorno_intervalo,
    v_jornada.hora_saida,
    COALESCE(
      (SELECT tolerancia_minutos FROM movelaria_funcionario_jornada WHERE funcionario_id = NEW.id),
      5
    ),
    v_jornada.dias_uteis,
    COALESCE(
      (SELECT ativo FROM movelaria_funcionario_jornada WHERE funcionario_id = NEW.id),
      true
    ),
    v_semana
  )
  ON CONFLICT (funcionario_id) DO UPDATE SET
    hora_entrada = EXCLUDED.hora_entrada,
    hora_saida_intervalo = EXCLUDED.hora_saida_intervalo,
    hora_retorno_intervalo = EXCLUDED.hora_retorno_intervalo,
    hora_saida = EXCLUDED.hora_saida,
    dias_uteis = EXCLUDED.dias_uteis,
    horarios_semana = COALESCE(EXCLUDED.horarios_semana, movelaria_funcionario_jornada.horarios_semana),
    atualizado_em = NOW();

  RETURN NEW;
END;
$$;


--
-- Name: movelaria_sync_pagamento_para_caixa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_sync_pagamento_para_caixa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_destinatario_id   UUID;
  v_mes               INTEGER;
  v_ano               INTEGER;
  v_descricao_reserva TEXT;
  v_descricao_old     TEXT;
  v_tipo_dest         TEXT;
  v_is_rateio           BOOLEAN;
  v_is_comissao       BOOLEAN;
  v_is_prestador_flow BOOLEAN;
  v_dest_nome         TEXT;
  v_valor_reserva     NUMERIC(12,2);
BEGIN
  v_descricao_reserva := 'Reserva automática via pagamento: ' || COALESCE(NEW.descricao, 'Sem descrição');
  v_descricao_old     := 'Reserva automática via pagamento: ' || COALESCE(OLD.descricao, 'Sem descrição');

  v_is_rateio :=
    COALESCE(NEW.descricao, '') LIKE 'Fixo montador:%'
    OR COALESCE(NEW.fornecedor_nome, '') LIKE 'Fixo montador:%';

  v_is_comissao :=
    NEW.prestador_id IS NOT NULL
    AND NOT v_is_rateio
    AND (
      NEW.obra_id IS NOT NULL
      OR COALESCE(NEW.fornecedor_nome, '') LIKE 'Comissão:%'
      OR COALESCE(NEW.descricao, '') LIKE 'Comissão:%'
    );

  IF (NEW.status = 'pendente' AND OLD.status IN ('pago', 'parcialmente_pago')) THEN
    IF movelaria_caixa_skip_cleanup() THEN
      RETURN NEW;
    END IF;

    DELETE FROM movelaria_caixa_movimentacoes
    WHERE tipo_movimentacao IN ('reserva', 'pagamento')
      AND (
        conta_pagar_id = OLD.id
        OR (
          conta_pagar_id IS NULL
          AND valor = OLD.valor_parcela
          AND descricao = v_descricao_old
          AND mes_referencia = EXTRACT(MONTH FROM OLD.data_vencimento)::INTEGER
          AND ano_referencia = EXTRACT(YEAR  FROM OLD.data_vencimento)::INTEGER
          AND destinatario_id IN (
            SELECT id FROM movelaria_caixa_destinatarios
            WHERE LOWER(TRIM(nome)) = LOWER(TRIM(COALESCE(OLD.fornecedor_nome, '')))
              AND ativo = true
          )
        )
      );
    RETURN NEW;
  END IF;

  IF (NEW.status = 'parcialmente_pago' AND COALESCE(NEW.valor_pago, 0) > 0) THEN
    IF movelaria_caixa_skip_cleanup() THEN
      RETURN NEW;
    END IF;

    IF v_is_comissao THEN
      v_dest_nome := movelaria_nome_destinatario_prestador(NEW.prestador_id, true);
      v_destinatario_id := movelaria_resolver_caixa_destinatario_prestador(v_dest_nome, NEW.prestador_id);
    ELSIF v_is_rateio OR NEW.prestador_id IS NOT NULL THEN
      v_dest_nome := movelaria_nome_destinatario_prestador(NEW.prestador_id, false);
      v_destinatario_id := movelaria_resolver_caixa_destinatario_prestador(
        COALESCE(v_dest_nome, NEW.fornecedor_nome),
        NEW.prestador_id
      );
    ELSE
      SELECT id INTO v_destinatario_id
      FROM movelaria_caixa_destinatarios
      WHERE LOWER(TRIM(nome)) = LOWER(TRIM(NEW.fornecedor_nome))
        AND ativo = true
      LIMIT 1;

      IF (v_destinatario_id IS NULL AND NEW.fornecedor_nome IS NOT NULL AND TRIM(NEW.fornecedor_nome) != '') THEN
        INSERT INTO movelaria_caixa_destinatarios (nome, tipo)
        VALUES (TRIM(NEW.fornecedor_nome), 'fornecedor')
        RETURNING id INTO v_destinatario_id;
      END IF;
    END IF;

    IF v_destinatario_id IS NOT NULL THEN
      v_mes := EXTRACT(MONTH FROM NEW.data_vencimento);
      v_ano := EXTRACT(YEAR  FROM NEW.data_vencimento);

      DELETE FROM movelaria_caixa_movimentacoes
      WHERE conta_pagar_id = NEW.id AND tipo_movimentacao = 'reserva';

      INSERT INTO movelaria_caixa_movimentacoes (
        destinatario_id, tipo_movimentacao, valor,
        data_movimentacao, mes_referencia, ano_referencia,
        descricao, conta_pagar_id
      ) VALUES (
        v_destinatario_id, 'reserva', NEW.valor_pago,
        CURRENT_DATE, v_mes, v_ano, v_descricao_reserva, NEW.id
      );
    END IF;

    RETURN NEW;
  END IF;

  IF (NEW.status = 'pago' AND (OLD.status IS NULL OR OLD.status != 'pago' OR COALESCE(OLD.valor_pago, 0) IS DISTINCT FROM COALESCE(NEW.valor_pago, 0))) THEN
    IF movelaria_caixa_skip_cleanup() THEN
      RETURN NEW;
    END IF;

    v_is_prestador_flow :=
      NEW.prestador_id IS NOT NULL
      AND (
        v_is_rateio
        OR v_is_comissao
        OR EXISTS (
          SELECT 1 FROM movelaria_caixa_movimentacoes
          WHERE conta_pagar_id = NEW.id AND tipo_movimentacao = 'reserva'
        )
      );

    IF v_is_comissao THEN
      v_dest_nome := movelaria_nome_destinatario_prestador(NEW.prestador_id, true);
      v_destinatario_id := movelaria_resolver_caixa_destinatario_prestador(v_dest_nome, NEW.prestador_id);
    ELSIF v_is_rateio OR v_is_prestador_flow THEN
      v_dest_nome := movelaria_nome_destinatario_prestador(NEW.prestador_id, false);
      v_destinatario_id := movelaria_resolver_caixa_destinatario_prestador(
        COALESCE(v_dest_nome, NEW.fornecedor_nome),
        NEW.prestador_id
      );
    ELSE
      v_tipo_dest := CASE WHEN NEW.prestador_id IS NOT NULL THEN 'marceneiro' ELSE 'fornecedor' END;
      SELECT id INTO v_destinatario_id
      FROM movelaria_caixa_destinatarios
      WHERE LOWER(TRIM(nome)) = LOWER(TRIM(NEW.fornecedor_nome))
        AND ativo = true
      LIMIT 1;

      IF (v_destinatario_id IS NULL AND NEW.fornecedor_nome IS NOT NULL AND TRIM(NEW.fornecedor_nome) != '') THEN
        INSERT INTO movelaria_caixa_destinatarios (nome, tipo)
        VALUES (TRIM(NEW.fornecedor_nome), v_tipo_dest)
        RETURNING id INTO v_destinatario_id;
      END IF;
    END IF;

    IF v_destinatario_id IS NOT NULL THEN
      v_mes := EXTRACT(MONTH FROM NEW.data_vencimento);
      v_ano := EXTRACT(YEAR  FROM NEW.data_vencimento);
      v_valor_reserva := COALESCE(NULLIF(NEW.valor_pago, 0), NEW.valor_parcela);

      DELETE FROM movelaria_caixa_movimentacoes
      WHERE conta_pagar_id = NEW.id AND tipo_movimentacao = 'reserva';

      IF v_is_prestador_flow OR v_is_rateio OR v_is_comissao THEN
        INSERT INTO movelaria_caixa_movimentacoes (
          destinatario_id, tipo_movimentacao, valor,
          data_movimentacao, data_vencimento, mes_referencia, ano_referencia,
          descricao, conta_pagar_id
        ) VALUES (
          v_destinatario_id, 'reserva', v_valor_reserva,
          COALESCE(NEW.data_pagamento, CURRENT_DATE), NEW.data_vencimento, v_mes, v_ano,
          CASE
            WHEN v_is_rateio
              THEN 'Reserva fixo montador: ' || COALESCE(NEW.descricao, NEW.fornecedor_nome, 'Sem descrição')
            WHEN v_is_comissao
              THEN 'Reserva comissão: ' || COALESCE(NEW.fornecedor_nome, NEW.descricao, 'Sem descrição')
            ELSE v_descricao_reserva
          END,
          NEW.id
        );
      ELSE
        INSERT INTO movelaria_caixa_movimentacoes (
          destinatario_id, tipo_movimentacao, valor,
          data_movimentacao, mes_referencia, ano_referencia,
          descricao, conta_pagar_id
        ) VALUES (
          v_destinatario_id, 'reserva', v_valor_reserva,
          COALESCE(NEW.data_pagamento, CURRENT_DATE), v_mes, v_ano,
          v_descricao_reserva, NEW.id
        );
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: movelaria_sync_usuario_de_funcionario_montador(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_sync_usuario_de_funcionario_montador() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_cargo TEXT;
  v_extras TEXT[];
  v_ja_vinculado UUID;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  IF NOT COALESCE(NEW.ativo, false) THEN
    RETURN NEW;
  END IF;

  IF NEW.tipo IS DISTINCT FROM 'montador'
     AND NEW.tipo IS DISTINCT FROM 'montador_admin' THEN
    RETURN NEW;
  END IF;

  v_cargo := NEW.tipo;
  v_uid := NEW.usuario_id;

  IF v_uid IS NULL AND NEW.email IS NOT NULL AND length(trim(NEW.email)) > 0 THEN
    SELECT u.id INTO v_uid
    FROM movelaria_usuarios u
    WHERE lower(u.email) = lower(trim(NEW.email))
      AND u.ativo = true
    ORDER BY u.criado_em DESC NULLS LAST
    LIMIT 1;

    -- Só vincula se o login ainda não tem outra pasta (índice único).
    IF v_uid IS NOT NULL AND NEW.usuario_id IS NULL THEN
      SELECT f.id INTO v_ja_vinculado
      FROM movelaria_funcionarios f
      WHERE f.usuario_id = v_uid
        AND f.id IS DISTINCT FROM NEW.id
      LIMIT 1;

      IF v_ja_vinculado IS NULL THEN
        NEW.usuario_id := v_uid;
      END IF;
    END IF;
  END IF;

  IF v_uid IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(u.perfis_extras, ARRAY[]::text[])
  INTO v_extras
  FROM movelaria_usuarios u
  WHERE u.id = v_uid;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  -- Já é montador/admin no perfil principal: nada a fazer.
  IF EXISTS (
    SELECT 1 FROM movelaria_usuarios u
    WHERE u.id = v_uid
      AND u.perfil IN ('montador', 'montador_admin')
  ) THEN
    RETURN NEW;
  END IF;

  -- Já tem o cargo nos extras.
  IF v_cargo = ANY (COALESCE(v_extras, ARRAY[]::text[])) THEN
    RETURN NEW;
  END IF;

  UPDATE movelaria_usuarios
  SET
    perfis_extras = (
      SELECT ARRAY(
        SELECT DISTINCT x
        FROM unnest(COALESCE(perfis_extras, ARRAY[]::text[]) || ARRAY[v_cargo]) AS t(x)
        WHERE x IS NOT NULL AND length(trim(x)) > 0
      )
    ),
    atualizado_em = NOW()
  WHERE id = v_uid;

  RETURN NEW;
END;
$$;


--
-- Name: movelaria_toggle_comissao_oculta_prestador(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_toggle_comissao_oculta_prestador(p_obra_id uuid, p_prestador_id uuid, p_oculto boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF NOT movelaria_usuario_tem_algum_perfil(
    ARRAY['administrador', 'financeiro', 'administrador_obras']
  ) THEN
    RAISE EXCEPTION 'Acesso negado: somente administradores ou financeiro podem ocultar comissões';
  END IF;

  UPDATE movelaria_obra_comissao_itens ci
  SET oculto_prestador = COALESCE(p_oculto, false),
      atualizado_em = NOW()
  WHERE ci.obra_id = p_obra_id
    AND ci.prestador_id = p_prestador_id
    AND ci.valor > 0;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Comissão não encontrada para esta obra e prestador';
  END IF;
END;
$$;


