--
-- Name: movelaria_upsert_cliente_from_lead(text, text, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_upsert_cliente_from_lead(p_nome text, p_telefone text, p_email text, p_origem text, p_data_cadastro date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NULLIF(trim(p_nome), '') IS NULL THEN
    RETURN;
  END IF;

  UPDATE movelaria_clientes c
  SET
    nome = COALESCE(NULLIF(trim(p_nome), ''), c.nome),
    telefone = COALESCE(NULLIF(trim(p_telefone), ''), c.telefone),
    email = COALESCE(NULLIF(trim(p_email), ''), c.email),
    origem = COALESCE(NULLIF(trim(p_origem), ''), c.origem),
    data_cadastro = COALESCE(p_data_cadastro, c.data_cadastro),
    atualizado_em = NOW()
  WHERE (
    (NULLIF(trim(p_telefone), '') IS NOT NULL AND c.telefone = NULLIF(trim(p_telefone), ''))
    OR (NULLIF(trim(p_email), '') IS NOT NULL AND c.email = NULLIF(trim(p_email), ''))
  );

  IF NOT FOUND THEN
    INSERT INTO movelaria_clientes (nome, telefone, email, origem, data_cadastro)
    VALUES (
      trim(p_nome),
      NULLIF(trim(p_telefone), ''),
      NULLIF(trim(p_email), ''),
      COALESCE(NULLIF(trim(p_origem), ''), 'Lead Garbo'),
      COALESCE(p_data_cadastro, CURRENT_DATE)
    );
  END IF;
END;
$$;


--
-- Name: movelaria_usuario_acessa_obra(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_usuario_acessa_obra(p_obra_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;

  IF movelaria_usuario_tem_algum_perfil(ARRAY['administrador', 'financeiro', 'administrador_obras', 'visualizador']) THEN
    RETURN EXISTS (SELECT 1 FROM movelaria_obras WHERE id = p_obra_id);
  END IF;

  IF movelaria_usuario_tem_perfil('montador_admin') THEN
    RETURN EXISTS (
      SELECT 1 FROM movelaria_obras o
      WHERE o.id = p_obra_id
        AND movelaria_montador_admin_pode_acessar_obra(o.montador_admin_id, o.grupo_obra_id, v_uid)
    );
  END IF;

  IF movelaria_usuario_tem_perfil('montador') THEN
    RETURN movelaria_montador_acessa_obra(p_obra_id, v_uid);
  END IF;

  RETURN false;
END;
$$;


