--
-- Name: movelaria_usuario_tem_algum_perfil(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_usuario_tem_algum_perfil(p_perfis text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM movelaria_usuarios u
    WHERE u.id = auth.uid()
      AND u.ativo = true
      AND (
        u.perfil = ANY(p_perfis)
        OR u.perfis_extras && p_perfis
      )
  );
$$;


--
-- Name: movelaria_usuario_tem_perfil(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_usuario_tem_perfil(p_perfil text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM movelaria_usuarios u
    WHERE u.id = auth.uid()
      AND u.ativo = true
      AND (u.perfil = p_perfil OR p_perfil = ANY(u.perfis_extras))
  );
$$;


--
-- Name: movelaria_usuario_tem_qualquer_perfil(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movelaria_usuario_tem_qualquer_perfil(p_perfis text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM movelaria_usuarios u
    WHERE u.id = auth.uid()
      AND u.ativo = true
      AND (
        u.perfil = ANY (p_perfis)
        OR EXISTS (
          SELECT 1
          FROM unnest(COALESCE(u.perfis_extras, '{}'::TEXT[])) AS extra(perfil)
          WHERE extra.perfil = ANY (p_perfis)
        )
      )
  );
$$;


