--
-- Name: normalize_projeto_stage_nome_sql(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_projeto_stage_nome_sql(p_nome text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT translate(
    lower(trim(both from coalesce(p_nome, ''))),
    'áàâãäéèêëíìîïóòôõöúùûüçñÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑ',
    'aaaaaeeeeiiiiooooouuuucnaaaaaeeeeiiiiooooouuuucn'
  );
$$;


--
-- Name: FUNCTION normalize_projeto_stage_nome_sql(p_nome text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.normalize_projeto_stage_nome_sql(p_nome text) IS 'Normaliza nome de coluna do ateliê/funil (minúsculas, sem acento) para match flexível.';


