--
-- Name: resolve_visita_em_obra_feita_status(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_visita_em_obra_feita_status(p_schema text, p_is_master boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_nome text;
BEGIN
  IF p_is_master THEN
    SELECT s.nome INTO v_nome
    FROM public."CRM-multi-empresas>pipeline_custom_stages<" s
    WHERE coalesce(s.ativo, true) = true
      AND public.normalize_projeto_stage_nome_sql(s.nome) LIKE '%visita%'
      AND public.normalize_projeto_stage_nome_sql(s.nome) LIKE '%obra%'
      AND public.normalize_projeto_stage_nome_sql(s.nome) LIKE '%feita%'
    ORDER BY s.ordem ASC NULLS LAST
    LIMIT 1;
  ELSE
    EXECUTE format(
      $q$
      SELECT s.nome
      FROM %I.pipeline_custom_stages s
      WHERE coalesce(s.ativo, true) = true
        AND public.normalize_projeto_stage_nome_sql(s.nome) LIKE '%%visita%%'
        AND public.normalize_projeto_stage_nome_sql(s.nome) LIKE '%%obra%%'
        AND public.normalize_projeto_stage_nome_sql(s.nome) LIKE '%%feita%%'
      ORDER BY s.ordem ASC NULLS LAST
      LIMIT 1
      $q$,
      p_schema
    ) INTO v_nome;
  END IF;

  RETURN NULLIF(btrim(coalesce(v_nome, '')), '');
END;
$_$;


--
-- Name: search_numeros_negativados(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_numeros_negativados(search_digits text DEFAULT ''::text, result_limit integer DEFAULT 100) RETURNS TABLE(id integer, "numeroTelefone" bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT n.id, n."numeroTelefone"
  FROM public."Negativacao-proforco-numeros" n
  WHERE
    COALESCE(search_digits, '') = ''
    OR length(search_digits) < 3
    OR n."numeroTelefone"::text LIKE '%' || search_digits || '%'
  ORDER BY n.id DESC
  LIMIT GREATEST(1, LEAST(COALESCE(result_limit, 100), 200));
$$;


--
-- Name: set_venda_realizada_em(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_venda_realizada_em() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'Venda Realizada (Matriculado)'
     AND NEW.venda_realizada_em IS NULL
     AND (
       TG_OP = 'INSERT'
       OR OLD.status IS DISTINCT FROM NEW.status
     ) THEN
    NEW.venda_realizada_em = now();
  END IF;

  RETURN NEW;
END;
$$;


