--
-- Name: submeter_form_inicio_orcamento(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submeter_form_inicio_orcamento(p_schema text, p_token text, p_valores jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_lead record;
  v_allowed text[];
  v_required text[];
  v_filtrado jsonb := '{}'::jsonb;
  v_key text;
  v_val text;
  v_cliente_nome text;
  v_identificador text;
  v_identificador_contrato text;
  v_orcamento_id uuid;
  v_contrato_id uuid;
  v_modelo_id uuid;
  v_campos_contrato jsonb;
  v_dados jsonb;
  v_req text;
BEGIN
  IF p_token IS NULL OR trim(p_token) = '' THEN
    RAISE EXCEPTION 'Token inválido';
  END IF;

  IF p_valores IS NULL OR jsonb_typeof(p_valores) <> 'object' THEN
    RAISE EXCEPTION 'Valores inválidos';
  END IF;

  IF public._form_orcamento_schema_ok(p_schema) THEN
    EXECUTE format(
      'SELECT id, nome, telefone, email
         FROM %I.leads
        WHERE token_form_orcamento = $1
        LIMIT 1',
      p_schema
    )
      INTO v_lead
      USING trim(p_token);

    IF v_lead IS NULL OR v_lead.id IS NULL THEN
      RAISE EXCEPTION 'Link inválido ou expirado';
    END IF;

    EXECUTE format(
      'SELECT coalesce(array_agg(nome ORDER BY ordem), ARRAY[]::text[]),
              coalesce(array_agg(nome) FILTER (WHERE obrigatorio), ARRAY[]::text[])
         FROM %I.contratos_variaveis
        WHERE mostrar_no_link_publico = true',
      p_schema
    )
      INTO v_allowed, v_required;

    BEGIN
      EXECUTE format(
        'SELECT id FROM %I.contratos_modelos
          WHERE ativo = true
          ORDER BY updated_at DESC NULLS LAST
          LIMIT 1',
        p_schema
      )
        INTO v_modelo_id;
    EXCEPTION WHEN undefined_table THEN
      v_modelo_id := NULL;
    END;

  ELSE
    SELECT id, nome, telefone, email
      INTO v_lead
      FROM public."CRM-multi-empresas>leads<"
     WHERE token_form_orcamento = trim(p_token)
     LIMIT 1;

    IF v_lead IS NULL OR v_lead.id IS NULL THEN
      RAISE EXCEPTION 'Link inválido ou expirado';
    END IF;

    SELECT coalesce(array_agg(nome ORDER BY ordem), ARRAY[]::text[]),
           coalesce(array_agg(nome) FILTER (WHERE obrigatorio), ARRAY[]::text[])
      INTO v_allowed, v_required
      FROM public."CRM-multi-empresas>contratos_variaveis<"
     WHERE mostrar_no_link_publico = true
       AND (schema_nome IS NULL OR schema_nome = coalesce(nullif(p_schema, ''), schema_nome));

    SELECT id INTO v_modelo_id
      FROM public."CRM-multi-empresas>contratos_modelos<"
     WHERE ativo = true
       AND (schema_nome IS NULL OR schema_nome = coalesce(nullif(p_schema, ''), schema_nome))
     ORDER BY updated_at DESC NULLS LAST
     LIMIT 1;
  END IF;

  IF v_allowed IS NULL OR cardinality(v_allowed) = 0 THEN
    RAISE EXCEPTION 'Nenhum campo configurado para o formulário público';
  END IF;

  FOREACH v_key IN ARRAY v_allowed
  LOOP
    v_val := nullif(trim(coalesce(p_valores->>v_key, '')), '');
    IF v_val IS NOT NULL THEN
      v_filtrado := v_filtrado || jsonb_build_object(v_key, v_val);
    END IF;
  END LOOP;

  IF v_required IS NOT NULL THEN
    FOREACH v_req IN ARRAY v_required
    LOOP
      IF nullif(trim(coalesce(v_filtrado->>v_req, '')), '') IS NULL THEN
        RAISE EXCEPTION 'Campo obrigatório não preenchido: %', v_req;
      END IF;
    END LOOP;
  END IF;

  v_cliente_nome := coalesce(
    nullif(trim(coalesce(
      v_filtrado->>'nome',
      v_filtrado->>'cliente_nome',
      v_filtrado->>'nome_cliente',
      v_filtrado->>'contratante',
      ''
    )), ''),
    nullif(trim(coalesce(v_lead.nome, '')), ''),
    'Cliente'
  );

  v_identificador := 'ORC-FORM-' || to_char(now() AT TIME ZONE 'America/Sao_Paulo', 'YYMMDD-HH24MI')
    || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 4);

  v_identificador_contrato := 'Rascunho — ' || v_cliente_nome || ' — '
    || to_char(now() AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI');

  v_campos_contrato := v_filtrado || jsonb_build_object('__etapa', '1');
  IF v_modelo_id IS NOT NULL THEN
    v_campos_contrato := v_campos_contrato || jsonb_build_object('__modelo_id', v_modelo_id::text);
  END IF;

  v_dados := jsonb_build_object(
    '_meta', jsonb_build_object(
      'origem', 'formulario_publico_lead',
      'campos_contrato_preenchidos', v_filtrado,
      'etapa', 0
    )
  );

  IF public._form_orcamento_schema_ok(p_schema) THEN
    EXECUTE format(
      'UPDATE %I.leads SET
         nome = CASE WHEN $1 <> '''' THEN $1 ELSE nome END,
         telefone = CASE WHEN $2 <> '''' THEN $2 ELSE telefone END,
         email = CASE WHEN $3 <> '''' THEN $3 ELSE email END,
         atualizado_em = now()
       WHERE id = $4',
      p_schema
    )
    USING
      coalesce(nullif(trim(coalesce(
        v_filtrado->>'nome', v_filtrado->>'cliente_nome', v_filtrado->>'nome_cliente', v_filtrado->>'contratante', ''
      )), ''), ''),
      coalesce(nullif(trim(coalesce(
        v_filtrado->>'telefone', v_filtrado->>'whatsapp', v_filtrado->>'celular', ''
      )), ''), ''),
      coalesce(nullif(trim(coalesce(v_filtrado->>'email', '')), ''), ''),
      v_lead.id;

    EXECUTE format(
      'INSERT INTO %I.orcamento_slides
         (identificador, lead_id, cliente_nome, status, dados)
       VALUES ($1, $2, $3, ''rascunho'', $4)
       RETURNING id',
      p_schema
    )
      INTO v_orcamento_id
      USING v_identificador, v_lead.id, v_cliente_nome, v_dados;

    EXECUTE format(
      'INSERT INTO %I.contratos
         (identificador, cliente_nome, status, campos_valores, conteudo_final, criado_por, lead_id)
       VALUES ($1, $2, ''rascunho'', $3, '''', NULL, $4)
       RETURNING id',
      p_schema
    )
      INTO v_contrato_id
      USING v_identificador_contrato, v_cliente_nome, v_campos_contrato, v_lead.id;
  ELSE
    UPDATE public."CRM-multi-empresas>leads<" SET
      nome = CASE
        WHEN nullif(trim(coalesce(
          v_filtrado->>'nome', v_filtrado->>'cliente_nome', v_filtrado->>'nome_cliente', v_filtrado->>'contratante', ''
        )), '') IS NOT NULL
        THEN trim(coalesce(
          v_filtrado->>'nome', v_filtrado->>'cliente_nome', v_filtrado->>'nome_cliente', v_filtrado->>'contratante', ''
        ))
        ELSE nome
      END,
      telefone = CASE
        WHEN nullif(trim(coalesce(
          v_filtrado->>'telefone', v_filtrado->>'whatsapp', v_filtrado->>'celular', ''
        )), '') IS NOT NULL
        THEN trim(coalesce(
          v_filtrado->>'telefone', v_filtrado->>'whatsapp', v_filtrado->>'celular', ''
        ))
        ELSE telefone
      END,
      email = CASE
        WHEN nullif(trim(coalesce(v_filtrado->>'email', '')), '') IS NOT NULL
        THEN trim(v_filtrado->>'email')
        ELSE email
      END,
      atualizado_em = now()
    WHERE id = v_lead.id;

    INSERT INTO public."CRM-multi-empresas>orcamento_slides<" (
      identificador, lead_id, cliente_nome, status, dados, schema_nome
    )
    VALUES (
      v_identificador, v_lead.id, v_cliente_nome, 'rascunho', v_dados, p_schema
    )
    RETURNING id INTO v_orcamento_id;

    INSERT INTO public."CRM-multi-empresas>contratos<" (
      schema_nome, identificador, cliente_nome, status, campos_valores, conteudo_final, criado_por, lead_id
    )
    VALUES (
      p_schema, v_identificador_contrato, v_cliente_nome, 'rascunho', v_campos_contrato, '', NULL, v_lead.id
    )
    RETURNING id INTO v_contrato_id;
  END IF;

  RETURN jsonb_build_object(
    'orcamento_id', v_orcamento_id,
    'contrato_id', v_contrato_id,
    'lead_id', v_lead.id,
    'identificador', v_identificador_contrato,
    'cliente_nome', v_cliente_nome
  );
END;
$_$;


--
-- Name: sync_lead_status_from_projeto_stage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_lead_status_from_projeto_stage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_schema text := TG_TABLE_SCHEMA;
  v_is_master boolean := (TG_TABLE_SCHEMA = 'public');
  v_stage_nome text;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.stage_id IS NOT DISTINCT FROM NEW.stage_id THEN
    RETURN NEW;
  END IF;

  IF NEW.stage_id IS NULL OR NEW.lead_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF v_is_master THEN
    SELECT s.nome INTO v_stage_nome
    FROM public."CRM-multi-empresas>projeto_stages<" s
    WHERE s.id = NEW.stage_id;
  ELSE
    EXECUTE format(
      'SELECT s.nome FROM %I.projeto_stages s WHERE s.id = $1',
      v_schema
    ) INTO v_stage_nome USING NEW.stage_id;
  END IF;

  IF NOT public.projeto_stage_triggers_visita_obra_feita(v_stage_nome) THEN
    RETURN NEW;
  END IF;

  PERFORM public.promote_lead_status_visita_obra_feita(v_schema, NEW.lead_id, v_is_master);
  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION sync_lead_status_from_projeto_stage(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_lead_status_from_projeto_stage() IS 'Ateliê → Pipeline: colunas a serem feitos / em andamento promovem lead para Visita em obra Feita (só avançar).';


--
-- Name: sync_lead_status_to_legacy_tables(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_lead_status_to_legacy_tables() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _telefone TEXT;
  _novo_status TEXT;
BEGIN
  -- Capturar telefone e novo status
  _telefone := NEW.telefone;
  _novo_status := NEW.status;

  -- Atualizar tabela usuarios (apenas se o registro existir)
  UPDATE public.usuarios
  SET status = _novo_status
  WHERE whatsapp = _telefone;

  -- Atualizar tabela usuarios_SaoPaulo_Proforco (apenas se o registro existir)
  UPDATE public."usuarios_SaoPaulo_Proforco"
  SET status = _novo_status
  WHERE whatsapp = _telefone;

  RETURN NEW;
END;
$$;


--
-- Name: sync_projeto_stage_from_lead_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_projeto_stage_from_lead_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_schema text := TG_TABLE_SCHEMA;
  v_is_master boolean := (TG_TABLE_SCHEMA = 'public');
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  IF NOT public.lead_status_is_enviou_orcamento(NEW.status) THEN
    RETURN NEW;
  END IF;

  IF v_is_master THEN
    UPDATE public."CRM-multi-empresas>lead_projetos<" lp
    SET stage_id = t.id
    FROM (
      SELECT s.id
      FROM public."CRM-multi-empresas>projeto_stages<" s
      WHERE coalesce(s.ativo, true) = true
        AND public.normalize_projeto_stage_nome_sql(s.nome) LIKE '%orcamento%'
        AND public.normalize_projeto_stage_nome_sql(s.nome) LIKE '%enviado%'
      ORDER BY s.ordem ASC NULLS LAST
      LIMIT 1
    ) t
    WHERE lp.lead_id = NEW.id AND lp.stage_id IS DISTINCT FROM t.id;
  ELSE
    EXECUTE format(
      $q$
      UPDATE %1$I.lead_projetos lp
      SET stage_id = t.id
      FROM (
        SELECT s.id
        FROM %1$I.projeto_stages s
        WHERE coalesce(s.ativo, true) = true
          AND public.normalize_projeto_stage_nome_sql(s.nome) LIKE '%%orcamento%%'
          AND public.normalize_projeto_stage_nome_sql(s.nome) LIKE '%%enviado%%'
        ORDER BY s.ordem ASC NULLS LAST
        LIMIT 1
      ) t
      WHERE lp.lead_id = $1 AND lp.stage_id IS DISTINCT FROM t.id
      $q$,
      v_schema
    ) USING NEW.id;
  END IF;

  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION sync_projeto_stage_from_lead_status(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_projeto_stage_from_lead_status() IS 'Pipeline → Ateliê: lead em Enviou orçamento move o projeto para a coluna Orçamento (Ja enviados).';


