--
-- Name: update_contato_on_new_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_contato_on_new_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.crm_selletos_chat_contatos
  SET 
    ultima_mensagem_em = NEW.criado_em,
    mensagens_nao_lidas = CASE 
      WHEN NEW.tipo_remetente = 'lead' THEN mensagens_nao_lidas + 1
      ELSE mensagens_nao_lidas
    END,
    atualizado_em = now()
  WHERE id = NEW.contato_id;
  
  RETURN NEW;
END;
$$;


