--
-- Name: whatsapp_mesclar_lid_para_telefone(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.whatsapp_mesclar_lid_para_telefone(p_telefone_real text, p_lid text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tel text := regexp_replace(coalesce(p_telefone_real, ''), '\D', '', 'g');
  v_lid text := regexp_replace(coalesce(p_lid, ''), '\D', '', 'g');
  v_lead_lid_id integer;
  v_lead_lid_tel text;
  v_lead_real_id integer;
  v_contato_real uuid;
  v_contato_lid uuid;
  v_msgs_movidas integer := 0;
BEGIN
  IF v_tel = '' OR v_lid = '' OR v_tel = v_lid THEN
    RETURN jsonb_build_object('status', 'noop', 'motivo', 'telefone_ou_lid_ausente');
  END IF;

  SELECT id, telefone INTO v_lead_lid_id, v_lead_lid_tel
  FROM "CRM-Selletos>leads<"
  WHERE regexp_replace(coalesce(telefone, ''), '\D', '', 'g') = v_lid
  LIMIT 1;

  IF v_lead_lid_id IS NULL THEN
    RETURN jsonb_build_object('status', 'noop', 'motivo', 'sem_lead_com_lid');
  END IF;

  SELECT id INTO v_lead_real_id
  FROM "CRM-Selletos>leads<"
  WHERE id <> v_lead_lid_id
    AND regexp_replace(coalesce(telefone, ''), '\D', '', 'g') IN (
      v_tel,
      CASE WHEN v_tel LIKE '55%' AND length(v_tel) >= 12 THEN substr(v_tel, 3) ELSE v_tel END,
      CASE WHEN v_tel NOT LIKE '55%' THEN '55' || v_tel ELSE v_tel END
    )
  LIMIT 1;

  IF v_lead_real_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'status', 'duplicado',
      'lead_lid_id', v_lead_lid_id,
      'lead_real_id', v_lead_real_id,
      'telefone_real', v_tel,
      'lid', v_lid
    );
  END IF;

  SELECT id INTO v_contato_real FROM crm_selletos_chat_contatos WHERE telefone = v_tel LIMIT 1;
  SELECT id INTO v_contato_lid FROM crm_selletos_chat_contatos WHERE telefone = v_lid OR lid = v_lid LIMIT 1;

  UPDATE "CRM-Selletos>leads<"
  SET telefone = v_tel
  WHERE id = v_lead_lid_id
    AND regexp_replace(coalesce(telefone, ''), '\D', '', 'g') = v_lid;

  IF v_contato_real IS NOT NULL AND v_contato_lid IS NOT NULL AND v_contato_real <> v_contato_lid THEN
    UPDATE crm_selletos_chat_mensagens
    SET contato_id = v_contato_real, telefone = v_tel
    WHERE contato_id = v_contato_lid;
    GET DIAGNOSTICS v_msgs_movidas = ROW_COUNT;

    UPDATE crm_selletos_chat_contatos
    SET lid = v_lid, lead_id = v_lead_lid_id, atualizado_em = now()
    WHERE id = v_contato_real;

    DELETE FROM crm_selletos_chat_contatos c
    WHERE c.id = v_contato_lid
      AND NOT EXISTS (SELECT 1 FROM crm_selletos_chat_mensagens m WHERE m.contato_id = c.id);
  ELSIF v_contato_real IS NOT NULL THEN
    UPDATE crm_selletos_chat_contatos
    SET lid = v_lid, lead_id = coalesce(lead_id, v_lead_lid_id), atualizado_em = now()
    WHERE id = v_contato_real;
  ELSIF v_contato_lid IS NOT NULL THEN
    UPDATE crm_selletos_chat_contatos
    SET telefone = v_tel, lid = v_lid, lead_id = coalesce(lead_id, v_lead_lid_id), atualizado_em = now()
    WHERE id = v_contato_lid
      AND NOT EXISTS (SELECT 1 FROM crm_selletos_chat_contatos x WHERE x.telefone = v_tel AND x.id <> v_contato_lid);

    UPDATE crm_selletos_chat_mensagens
    SET telefone = v_tel
    WHERE contato_id = v_contato_lid;
  END IF;

  INSERT INTO crm_selletos_chat_logs (telefone, evento, detalhes)
  VALUES (
    v_tel,
    'lid_mesclado',
    jsonb_build_object(
      'telefone_antigo', v_lid,
      'telefone_novo', v_tel,
      'lead_id', v_lead_lid_id,
      'msgs_movidas', v_msgs_movidas
    )
  );

  RETURN jsonb_build_object(
    'status', 'mesclado',
    'lead_id', v_lead_lid_id,
    'telefone_antigo', v_lid,
    'telefone_novo', v_tel,
    'msgs_movidas', v_msgs_movidas
  );
END;
$$;


