    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    imagem_url text,
    file_name text,
    mime_type text,
    destinatario_id uuid,
    CONSTRAINT lead_projeto_notas_conteudo_chk CHECK (((char_length(btrim(mensagem)) >= 1) OR (imagem_url IS NOT NULL))),
    CONSTRAINT lead_projeto_notas_tipo_chk CHECK ((tipo = ANY (ARRAY['envio'::text, 'reenvio'::text, 'conversa'::text])))
);

ALTER TABLE ONLY emp_garbo.lead_projeto_notas REPLICA IDENTITY FULL;

ALTER TABLE ONLY emp_garbo.lead_projeto_notas FORCE ROW LEVEL SECURITY;


