--
-- Name: CRM-Selletos>leads<; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."CRM-Selletos>leads<" (
    id bigint NOT NULL,
    nome text NOT NULL,
    empresa text,
    email text,
    telefone text,
    origem text,
    status text DEFAULT 'Novo Lead'::text NOT NULL,
    valor_negocio numeric DEFAULT 0 NOT NULL,
    data_chegada date DEFAULT CURRENT_DATE NOT NULL,
    vendedor_responsavel_id uuid,
    motivo_perda text,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    observacoes text,
    ordem_manual integer,
    regiao text,
    regiao_tabela text,
    venda_realizada_em timestamp with time zone,
    dar_atencao boolean DEFAULT false,
    valor_orcamento numeric DEFAULT 0 NOT NULL,
    arquivado_em timestamp with time zone,
    instancia_id uuid,
    instagram text,
    aula_experimental_marcada_por uuid,
    aula_experimental_marcada_em timestamp with time zone,
    aula_experimental_reuniao_id uuid,
    CONSTRAINT "CRM-Selletos>leads<_status_check" CHECK ((status = ANY (ARRAY['Novo Lead'::text, 'Aula Experimental Marcada'::text, 'Não Entraram para Aula Experimental'::text, 'Aula Realizada'::text, 'Negociação'::text, 'Venda Realizada (Matriculado)'::text, 'Interesse Futuro'::text, 'Venda Perdida (Não Matriculado)'::text, 'Clientes Já Cadastrados'::text])))
);

ALTER TABLE ONLY public."CRM-Selletos>leads<" REPLICA IDENTITY FULL;


--
-- Name: COLUMN "CRM-Selletos>leads<".venda_realizada_em; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."CRM-Selletos>leads<".venda_realizada_em IS 'Data em que o status foi alterado para Venda Realizada (Matriculado). Usada para KPIs de vendas por mês.';


--
-- Name: COLUMN "CRM-Selletos>leads<".instancia_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."CRM-Selletos>leads<".instancia_id IS 'Instância WhatsApp V2 do primeiro contato. Não sobrescrever depois de preenchido.';


--
-- Name: COLUMN "CRM-Selletos>leads<".aula_experimental_marcada_por; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."CRM-Selletos>leads<".aula_experimental_marcada_por IS 'Vendedor P2P (ou usuário) que agendou a aula experimental — selo no card.';


--
-- Name: COLUMN "CRM-Selletos>leads<".aula_experimental_marcada_em; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."CRM-Selletos>leads<".aula_experimental_marcada_em IS 'Quando a aula experimental foi agendada no fluxo P2P.';


--
-- Name: COLUMN "CRM-Selletos>leads<".aula_experimental_reuniao_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."CRM-Selletos>leads<".aula_experimental_reuniao_id IS 'Reunião em agenda_reunioes criada pelo agendamento P2P.';


--
-- Name: CRM-Selletos>leads<_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public."CRM-Selletos>leads<_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: CRM-Selletos>leads<_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public."CRM-Selletos>leads<_id_seq" OWNED BY public."CRM-Selletos>leads<".id;


