    model text DEFAULT 'gpt-4o-mini'::text NOT NULL,
    system_prompt text DEFAULT 'Analise as imagens enviadas e descreva o que observa de forma objetiva e útil para o atendimento comercial.'::text NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_por uuid,
    openai_api_key text,
    briefing_prompt text DEFAULT ''::text NOT NULL,
    render_ativo boolean DEFAULT true NOT NULL,
    render_vision_model text DEFAULT 'gpt-4o'::text NOT NULL,
    render_image_model text DEFAULT 'gpt-image-1.5'::text NOT NULL,
    render_analysis_prompt text DEFAULT ''::text NOT NULL,
    render_prompt text DEFAULT ''::text NOT NULL,
    iris_sky_ativo boolean DEFAULT true NOT NULL,
    iris_sky_model text DEFAULT 'gpt-4o-mini'::text NOT NULL,
    iris_sky_knowledge_ativo boolean DEFAULT true NOT NULL,
    iris_sky_embedding_model text DEFAULT 'text-embedding-3-small'::text NOT NULL,
    iris_sky_include_media_vision boolean DEFAULT true NOT NULL,
    iris_sky_include_whatsapp boolean DEFAULT true NOT NULL,
    iris_sky_match_count integer DEFAULT 12 NOT NULL,
    iris_sky_chat_prompt text DEFAULT ''::text NOT NULL,
    iris_sky_auto_index_ativo boolean DEFAULT true NOT NULL,
    iris_sky_knowledge_max_items integer DEFAULT 25 NOT NULL,
    iris_sky_knowledge_max_pages integer DEFAULT 40 NOT NULL,
    iris_sky_spot_prompt text,
    render_ambiente_ativo boolean DEFAULT true NOT NULL,
    render_ambiente_analysis_prompt text DEFAULT ''::text NOT NULL,
    render_ambiente_prompt text DEFAULT ''::text NOT NULL,
    contrato_openai_api_key text
);


--
-- Name: pipeline_lead_ai_config_public; Type: VIEW; Schema: emp_garbo; Owner: -
--

CREATE VIEW emp_garbo.pipeline_lead_ai_config_public AS
 SELECT pipeline_lead_ai_config.id,
    pipeline_lead_ai_config.singleton_key,
    pipeline_lead_ai_config.model,
    pipeline_lead_ai_config.system_prompt,
    pipeline_lead_ai_config.briefing_prompt,
    pipeline_lead_ai_config.render_ativo,
    pipeline_lead_ai_config.render_vision_model,
    pipeline_lead_ai_config.render_image_model,
    pipeline_lead_ai_config.render_analysis_prompt,
    pipeline_lead_ai_config.render_prompt,
    pipeline_lead_ai_config.render_ambiente_ativo,
    pipeline_lead_ai_config.render_ambiente_analysis_prompt,
    pipeline_lead_ai_config.render_ambiente_prompt,
    pipeline_lead_ai_config.iris_sky_ativo,
    pipeline_lead_ai_config.iris_sky_model,
    pipeline_lead_ai_config.iris_sky_knowledge_ativo,
    pipeline_lead_ai_config.iris_sky_embedding_model,
    pipeline_lead_ai_config.iris_sky_include_media_vision,
    pipeline_lead_ai_config.iris_sky_include_whatsapp,
    pipeline_lead_ai_config.iris_sky_match_count,
    pipeline_lead_ai_config.iris_sky_chat_prompt,
    pipeline_lead_ai_config.iris_sky_spot_prompt,
    pipeline_lead_ai_config.iris_sky_auto_index_ativo,
    pipeline_lead_ai_config.iris_sky_knowledge_max_items,
    pipeline_lead_ai_config.iris_sky_knowledge_max_pages,
    pipeline_lead_ai_config.ativo,
    pipeline_lead_ai_config.atualizado_em,
    pipeline_lead_ai_config.atualizado_por,
    ((pipeline_lead_ai_config.openai_api_key IS NOT NULL) AND (btrim(pipeline_lead_ai_config.openai_api_key) <> ''::text)) AS api_key_configured,
    ((pipeline_lead_ai_config.contrato_openai_api_key IS NOT NULL) AND (btrim(pipeline_lead_ai_config.contrato_openai_api_key) <> ''::text)) AS contrato_api_key_configured
   FROM emp_garbo.pipeline_lead_ai_config;


