--
-- Name: CRM-Selletos>lead_conversion_stats<; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public."CRM-Selletos>lead_conversion_stats<" AS
 SELECT count(*) AS total_leads,
    count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Aula Experimental Marcada'::text)) AS marcaram_aula,
    count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Não Entraram para Aula Experimental'::text)) AS nao_entraram_aula,
    count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Aula Realizada'::text)) AS realizaram_aula,
    count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Venda Realizada (Matriculado)'::text)) AS vendas_realizadas,
    count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Venda Perdida (Não Matriculado)'::text)) AS vendas_perdidas,
    round(((100.0 * (count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Aula Experimental Marcada'::text)))::numeric) / (NULLIF(count(*), 0))::numeric), 2) AS percentual_marcaram,
    round(((100.0 * (count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Não Entraram para Aula Experimental'::text)))::numeric) / (NULLIF(count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Aula Experimental Marcada'::text)), 0))::numeric), 2) AS percentual_nao_entraram,
    round(((100.0 * (count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Aula Realizada'::text)))::numeric) / (NULLIF(count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Aula Experimental Marcada'::text)), 0))::numeric), 2) AS percentual_realizaram,
    round(((100.0 * (count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Venda Realizada (Matriculado)'::text)))::numeric) / (NULLIF(count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Aula Realizada'::text)), 0))::numeric), 2) AS percentual_vendas
   FROM public."CRM-Selletos>leads<"
  WITH NO DATA;


--
-- Name: CRM-Selletos>lead_evolution_stats<; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public."CRM-Selletos>lead_evolution_stats<" AS
 SELECT date_trunc('day'::text, ("CRM-Selletos>leads<".data_chegada)::timestamp with time zone) AS data,
    count(*) AS total_leads,
    count(*) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Venda Realizada (Matriculado)'::text)) AS vendas,
    sum("CRM-Selletos>leads<".valor_negocio) FILTER (WHERE ("CRM-Selletos>leads<".status = 'Venda Realizada (Matriculado)'::text)) AS receita
   FROM public."CRM-Selletos>leads<"
  GROUP BY (date_trunc('day'::text, ("CRM-Selletos>leads<".data_chegada)::timestamp with time zone))
  ORDER BY (date_trunc('day'::text, ("CRM-Selletos>leads<".data_chegada)::timestamp with time zone))
  WITH NO DATA;


