--
-- Name: CRM-Selletos>vendor_performance_stats<; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public."CRM-Selletos>vendor_performance_stats<" AS
 SELECT u.id AS vendedor_id,
    u.nome AS vendedor_nome,
    u.avatar_url,
    count(l.id) AS total_leads,
    count(*) FILTER (WHERE (l.status = 'Venda Realizada (Matriculado)'::text)) AS vendas,
    sum(l.valor_negocio) FILTER (WHERE (l.status = 'Venda Realizada (Matriculado)'::text)) AS receita,
    round(((100.0 * (count(*) FILTER (WHERE (l.status = 'Venda Realizada (Matriculado)'::text)))::numeric) / (NULLIF(count(l.id), 0))::numeric), 2) AS taxa_conversao,
    round(avg(l.valor_negocio) FILTER (WHERE (l.status = 'Venda Realizada (Matriculado)'::text)), 2) AS ticket_medio
   FROM (public."CRM-Selletos>usuarios<" u
     LEFT JOIN public."CRM-Selletos>leads<" l ON ((l.vendedor_responsavel_id = u.id)))
  GROUP BY u.id, u.nome, u.avatar_url
  WITH NO DATA;


