-- Name: CRM-multi-empresas>pipeline_lead_ai_config<; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."CRM-multi-empresas>pipeline_lead_ai_config<" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    singleton_key text DEFAULT 'default'::text NOT NULL,
