    system_prompt text DEFAULT 'Analise as imagens enviadas e descreva o que observa de forma objetiva e útil para o atendimento comercial.'::text NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_por uuid,
    openai_api_key text,
    briefing_prompt text DEFAULT ''::text NOT NULL,
    render_ativo boolean DEFAULT true NOT NULL,
    render_vision_model text DEFAULT 'gpt-4o'::text NOT NULL,
    render_image_model text DEFAULT 'gpt-image-1.5'::text NOT NULL,
    render_analysis_prompt text DEFAULT ''::text NOT NULL,
    render_prompt text DEFAULT ''::text NOT NULL,
    iris_sky_ativo boolean DEFAULT true NOT NULL,
    iris_sky_model text DEFAULT 'gpt-4o-mini'::text NOT NULL,
    iris_sky_knowledge_ativo boolean DEFAULT true NOT NULL,
    iris_sky_embedding_model text DEFAULT 'text-embedding-3-small'::text NOT NULL,
    iris_sky_include_media_vision boolean DEFAULT true NOT NULL,
    iris_sky_include_whatsapp boolean DEFAULT true NOT NULL,
    iris_sky_match_count integer DEFAULT 12 NOT NULL,
    iris_sky_chat_prompt text DEFAULT ''::text NOT NULL,
    iris_sky_auto_index_ativo boolean DEFAULT true NOT NULL,
    iris_sky_knowledge_max_items integer DEFAULT 25 NOT NULL,
    iris_sky_knowledge_max_pages integer DEFAULT 40 NOT NULL,
    iris_sky_spot_prompt text,
    render_ambiente_ativo boolean DEFAULT true NOT NULL,
    render_ambiente_analysis_prompt text DEFAULT ''::text NOT NULL,
    render_ambiente_prompt text DEFAULT ''::text NOT NULL,
    contrato_openai_api_key text
);


--
-- Name: TABLE "CRM-multi-empresas>pipeline_lead_ai_config<"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."CRM-multi-empresas>pipeline_lead_ai_config<" IS 'Modelo e prompt da IA para análise de fotos no card do lead';


--
-- Name: COLUMN "CRM-multi-empresas>pipeline_lead_ai_config<".openai_api_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."CRM-multi-empresas>pipeline_lead_ai_config<".openai_api_key IS 'Chave da API OpenAI (somente admin grava; Edge Function lê com service_role)';


--
-- Name: COLUMN "CRM-multi-empresas>pipeline_lead_ai_config<".briefing_prompt; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."CRM-multi-empresas>pipeline_lead_ai_config<".briefing_prompt IS 'Prompt para gerar perguntas de briefing após a análise visual';


--
-- Name: CRM-multi-empresas>pipeline_lead_ai_config_public<; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public."CRM-multi-empresas>pipeline_lead_ai_config_public<" AS
 SELECT "CRM-multi-empresas>pipeline_lead_ai_config<".id,
    "CRM-multi-empresas>pipeline_lead_ai_config<".singleton_key,
    "CRM-multi-empresas>pipeline_lead_ai_config<".model,
    "CRM-multi-empresas>pipeline_lead_ai_config<".system_prompt,
    "CRM-multi-empresas>pipeline_lead_ai_config<".briefing_prompt,
    "CRM-multi-empresas>pipeline_lead_ai_config<".render_ativo,
    "CRM-multi-empresas>pipeline_lead_ai_config<".render_vision_model,
    "CRM-multi-empresas>pipeline_lead_ai_config<".render_image_model,
    "CRM-multi-empresas>pipeline_lead_ai_config<".render_analysis_prompt,
    "CRM-multi-empresas>pipeline_lead_ai_config<".render_prompt,
    "CRM-multi-empresas>pipeline_lead_ai_config<".render_ambiente_ativo,
    "CRM-multi-empresas>pipeline_lead_ai_config<".render_ambiente_analysis_prompt,
    "CRM-multi-empresas>pipeline_lead_ai_config<".render_ambiente_prompt,
    "CRM-multi-empresas>pipeline_lead_ai_config<".iris_sky_ativo,
    "CRM-multi-empresas>pipeline_lead_ai_config<".iris_sky_model,
    "CRM-multi-empresas>pipeline_lead_ai_config<".iris_sky_knowledge_ativo,
    "CRM-multi-empresas>pipeline_lead_ai_config<".iris_sky_embedding_model,
    "CRM-multi-empresas>pipeline_lead_ai_config<".iris_sky_include_media_vision,
    "CRM-multi-empresas>pipeline_lead_ai_config<".iris_sky_include_whatsapp,
    "CRM-multi-empresas>pipeline_lead_ai_config<".iris_sky_match_count,
    "CRM-multi-empresas>pipeline_lead_ai_config<".iris_sky_chat_prompt,
    "CRM-multi-empresas>pipeline_lead_ai_config<".iris_sky_spot_prompt,
    "CRM-multi-empresas>pipeline_lead_ai_config<".iris_sky_auto_index_ativo,
    "CRM-multi-empresas>pipeline_lead_ai_config<".iris_sky_knowledge_max_items,
    "CRM-multi-empresas>pipeline_lead_ai_config<".iris_sky_knowledge_max_pages,
    "CRM-multi-empresas>pipeline_lead_ai_config<".ativo,
    "CRM-multi-empresas>pipeline_lead_ai_config<".atualizado_em,
    "CRM-multi-empresas>pipeline_lead_ai_config<".atualizado_por,
    (("CRM-multi-empresas>pipeline_lead_ai_config<".openai_api_key IS NOT NULL) AND (btrim("CRM-multi-empresas>pipeline_lead_ai_config<".openai_api_key) <> ''::text)) AS api_key_configured,
    (("CRM-multi-empresas>pipeline_lead_ai_config<".contrato_openai_api_key IS NOT NULL) AND (btrim("CRM-multi-empresas>pipeline_lead_ai_config<".contrato_openai_api_key) <> ''::text)) AS contrato_api_key_configured
   FROM public."CRM-multi-empresas>pipeline_lead_ai_config<";


