-- Name: crm_multiempresas_n8n_chat_histories_proforco_saopaulo; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.crm_multiempresas_n8n_chat_histories_proforco_saopaulo WITH (security_invoker='true') AS
 SELECT n8n_chat_histories_proforco_saopaulo.id,
    n8n_chat_histories_proforco_saopaulo.session_id,
    n8n_chat_histories_proforco_saopaulo.message
   FROM public.n8n_chat_histories_proforco_saopaulo;


