--
-- Name: crm_multiempresas_ui_preferences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_multiempresas_ui_preferences (
    user_id uuid NOT NULL,
    disable_message_notifications_popup boolean DEFAULT false NOT NULL,
    hide_floating_popups boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pipeline_indicators jsonb DEFAULT '{"cards": {"orcamentos": false, "sales_stats": false, "vendor_ranking": false, "origin_by_month": false, "sales_by_origin": false}, "sectionOpen": false}'::jsonb NOT NULL,
    page_zoom smallint DEFAULT 100 NOT NULL,
    floating_agenda_side text DEFAULT 'right'::text NOT NULL,
    minimize_lead_sinalizacoes_popup boolean DEFAULT false NOT NULL,
    floating_agenda_zoom smallint DEFAULT 100 NOT NULL,
    minimize_lead_whatsapp_history boolean DEFAULT true NOT NULL,
    CONSTRAINT crm_multiempresas_ui_preferences_floating_agenda_side_check CHECK ((floating_agenda_side = ANY (ARRAY['left'::text, 'right'::text]))),
    CONSTRAINT crm_multiempresas_ui_preferences_floating_agenda_zoom_check CHECK (((floating_agenda_zoom >= 80) AND (floating_agenda_zoom <= 140))),
    CONSTRAINT crm_multiempresas_ui_preferences_page_zoom_check CHECK (((page_zoom >= 80) AND (page_zoom <= 140)))
);


--
-- Name: COLUMN crm_multiempresas_ui_preferences.pipeline_indicators; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_multiempresas_ui_preferences.pipeline_indicators IS 'Estado dos indicadores da Pipeline: sectionOpen e cards expandidos (true) ou recolhidos (false).';


--
-- Name: COLUMN crm_multiempresas_ui_preferences.page_zoom; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_multiempresas_ui_preferences.page_zoom IS 'Zoom da interface do Kanban em percentual (80–140). Persistido por usuário.';


--
-- Name: COLUMN crm_multiempresas_ui_preferences.floating_agenda_side; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_multiempresas_ui_preferences.floating_agenda_side IS 'Lado da tela onde o painel flutuante da Agenda Geral fica fixado (left ou right).';


--
-- Name: COLUMN crm_multiempresas_ui_preferences.minimize_lead_sinalizacoes_popup; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_multiempresas_ui_preferences.minimize_lead_sinalizacoes_popup IS 'Quando true, o painel de leads sinalizados permanece minimizado; exibe prévia transparente periódica.';


--
-- Name: COLUMN crm_multiempresas_ui_preferences.floating_agenda_zoom; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_multiempresas_ui_preferences.floating_agenda_zoom IS 'Zoom do painel flutuante da Agenda Geral (80–140%). Persistido por usuário.';


--
-- Name: COLUMN crm_multiempresas_ui_preferences.minimize_lead_whatsapp_history; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_multiempresas_ui_preferences.minimize_lead_whatsapp_history IS 'Quando true, o card de histórico WhatsApp no modal do lead permanece minimizado até o usuário expandir.';


