--

CREATE TABLE public.crm_selletos_chat_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contato_id uuid,
    telefone text,
    evento text NOT NULL,
    detalhes jsonb,
    criado_em timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: crm_selletos_chat_mensagens; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_selletos_chat_mensagens (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contato_id uuid,
    telefone text NOT NULL,
    tipo_remetente text NOT NULL,
    usuario_id uuid,
    tipo_mensagem text DEFAULT 'texto'::text NOT NULL,
    conteudo text,
    url_midia text,
    lida boolean DEFAULT false,
    enviada boolean DEFAULT true,
    origem text DEFAULT 'crm'::text NOT NULL,
    mensagem_n8n_id integer,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    file_name text,
    file_size integer,
    mime_type text,
    remote_jid text,
    message_id_external text,
    instancia_id uuid,
    timestamp_externo timestamp with time zone,
    transcricao text,
    CONSTRAINT crm_selletos_chat_mensagens_origem_check CHECK ((origem = ANY (ARRAY['crm'::text, 'webhook'::text, 'n8n'::text]))),
    CONSTRAINT crm_selletos_chat_mensagens_tipo_mensagem_check CHECK ((tipo_mensagem = ANY (ARRAY['texto'::text, 'audio'::text, 'imagem'::text, 'pdf'::text, 'video'::text]))),
    CONSTRAINT crm_selletos_chat_mensagens_tipo_remetente_check CHECK ((tipo_remetente = ANY (ARRAY['lead'::text, 'atendente'::text, 'ia'::text])))
);


--
-- Name: COLUMN crm_selletos_chat_mensagens.timestamp_externo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_selletos_chat_mensagens.timestamp_externo IS 'Horário real da mensagem (Mega messageTimestamp); ordenação do histórico';


--
-- Name: COLUMN crm_selletos_chat_mensagens.transcricao; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_selletos_chat_mensagens.transcricao IS 'Texto derivado de áudio/imagem/documento quando não há bolha de texto';


--
-- Name: crm_selletos_ui_preferences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_selletos_ui_preferences (
    user_id uuid NOT NULL,
    disable_message_notifications_popup boolean DEFAULT false NOT NULL,
    hide_floating_popups boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    floating_agenda_side text DEFAULT 'right'::text NOT NULL,
    floating_agenda_zoom integer DEFAULT 100 NOT NULL,
    page_zoom integer DEFAULT 100 NOT NULL,
    marketing_topics_board_expanded boolean DEFAULT true NOT NULL,
    marketing_kanban_zoom integer DEFAULT 100 NOT NULL,
    marketing_p2p_zoom integer DEFAULT 100 NOT NULL,
    CONSTRAINT crm_selletos_ui_preferences_floating_agenda_side_check CHECK ((floating_agenda_side = ANY (ARRAY['left'::text, 'right'::text]))),
    CONSTRAINT crm_selletos_ui_preferences_floating_agenda_zoom_check CHECK (((floating_agenda_zoom >= 80) AND (floating_agenda_zoom <= 140))),
    CONSTRAINT crm_selletos_ui_preferences_marketing_kanban_zoom_check CHECK (((marketing_kanban_zoom >= 50) AND (marketing_kanban_zoom <= 140))),
    CONSTRAINT crm_selletos_ui_preferences_marketing_p2p_zoom_check CHECK (((marketing_p2p_zoom >= 50) AND (marketing_p2p_zoom <= 140))),
    CONSTRAINT crm_selletos_ui_preferences_page_zoom_check CHECK (((page_zoom >= 80) AND (page_zoom <= 140)))
);


--
-- Name: COLUMN crm_selletos_ui_preferences.page_zoom; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_selletos_ui_preferences.page_zoom IS 'Zoom do quadro Kanban (80–140, passo 10). Aplica CSS zoom no quadro inteiro, não em cada card.';


--
-- Name: COLUMN crm_selletos_ui_preferences.marketing_topics_board_expanded; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_selletos_ui_preferences.marketing_topics_board_expanded IS 'Se true, a lousa de tópicos do Marketing Conteúdo fica expandida; se false, minimizada.';


--
-- Name: COLUMN crm_selletos_ui_preferences.marketing_kanban_zoom; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_selletos_ui_preferences.marketing_kanban_zoom IS 'Zoom do Kanban de Marketing Conteúdo (50–140, passo 10). Menor = mais colunas na tela.';


--
-- Name: COLUMN crm_selletos_ui_preferences.marketing_p2p_zoom; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_selletos_ui_preferences.marketing_p2p_zoom IS 'Zoom do quadro Marketing Peer-to-Peer (50–140, passo 10). Menor = mais colunas na tela.';


