    company_id uuid,
    category text NOT NULL,
    name text NOT NULL,
    sku text,
    unit text DEFAULT 'un'::text NOT NULL,
    unit_price numeric(10,2),
    price_per_m2 numeric(10,2),
    price_per_sheet numeric(10,2),
    sheet_area_m2 numeric(8,3),
    thickness_mm numeric(6,2),
    width_mm numeric(8,2),
    length_mm numeric(8,2),
    loss_pct numeric(5,2) DEFAULT 0,
    active boolean DEFAULT true NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT inventory_items_category_check CHECK ((category = ANY (ARRAY['chapa'::text, 'fita_borda'::text, 'ferragem'::text, 'puxador'::text, 'consumivel'::text, 'servico'::text, 'mao_obra'::text, 'outro'::text])))
);


