    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    foto_perfil_path text,
    dispensado_em timestamp with time zone,
    dispensado_por uuid,
    categoria text DEFAULT 'montador'::text,
    valor_fixo_mensal numeric(12,2) DEFAULT 0 NOT NULL,
    fixo_primeiro_vencimento date,
    fixo_recorrencia_id uuid,
    CONSTRAINT movelaria_funcionarios_admissao_status_check CHECK ((admissao_status = ANY (ARRAY['pendente'::text, 'preenchido_funcionario'::text, 'completo'::text]))),
    CONSTRAINT movelaria_funcionarios_categoria_check CHECK ((categoria = ANY (ARRAY['design'::text, 'projetista'::text, 'montador'::text, 'financeiro'::text, 'administrativo'::text, 'outro'::text]))),
    CONSTRAINT movelaria_funcionarios_tipo_check CHECK ((tipo = ANY (ARRAY['montador'::text, 'montador_admin'::text, 'administrador_obras'::text, 'marceneiro'::text, 'financeiro'::text, 'design'::text, 'projetista'::text, 'administrativo'::text, 'outro'::text]))),
