);


--
-- Name: movelaria_funcionario_ponto_resumo; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.movelaria_funcionario_ponto_resumo AS
 SELECT f.id AS funcionario_id,
    j.hora_entrada,
    j.hora_saida,
    j.ativo AS jornada_ativa,
    (public.movelaria_ponto_status_dia(f.id, public.movelaria_ponto_data_local()) ->> 'status_dia'::text) AS status_hoje,
    ( SELECT (count(*))::integer AS count
           FROM public.movelaria_funcionario_ponto_marcacoes m
          WHERE ((m.funcionario_id = f.id) AND (public.movelaria_ponto_data_local(m.registrado_em) >= (date_trunc('month'::text, (public.movelaria_ponto_data_local())::timestamp with time zone))::date))) AS batidas_mes
   FROM (public.movelaria_funcionarios f
     LEFT JOIN public.movelaria_funcionario_jornada j ON (((j.funcionario_id = f.id) AND (j.ativo = true))))
  WHERE (f.ativo = true);


