--
-- Name: movelaria_obras; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.movelaria_obras (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    origem_orcamento_id uuid,
    origem_lead_id text,
    cliente_id uuid,
    cliente_nome text NOT NULL,
    lousa text,
    endereco_obra text,
    tipo_obra_id uuid,
    grupo_obra_id uuid,
    montador_admin_id uuid,
    montador_id uuid,
    data_prevista_inicio date,
    data_prevista_fim date,
    tempo_maximo_horas numeric(8,2),
    status_kanban text DEFAULT 'datas_em_aberto'::text NOT NULL,
    iniciado_em timestamp with time zone,
    finalizado_em timestamp with time zone,
    concluido_em_atraso boolean GENERATED ALWAYS AS (
CASE
    WHEN ((finalizado_em IS NOT NULL) AND (iniciado_em IS NOT NULL) AND (tempo_maximo_horas IS NOT NULL)) THEN ((EXTRACT(epoch FROM (finalizado_em - iniciado_em)) / 3600.0) > tempo_maximo_horas)
    ELSE NULL::boolean
END) STORED,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    pedido_material_feito boolean DEFAULT false NOT NULL,
    descricao text,
    comissao_habilitada boolean DEFAULT false NOT NULL,
    comissao_total numeric(12,2) DEFAULT 0 NOT NULL,
    comissao_gerada boolean DEFAULT false NOT NULL,
    dias_trabalho integer[],
    horario_inicio text,
    horario_fim text,
    duracao_real_horas numeric(10,4),
    data_entrega_pedido date,
    numero_pedido_cort_claud text,
    atraso_permanente boolean DEFAULT false NOT NULL,
    atraso_marcado_em timestamp with time zone,
    data_prevista_inicio_original date,
    data_prevista_fim_original date,
    CONSTRAINT movelaria_obras_status_kanban_check CHECK ((status_kanban = ANY (ARRAY['datas_em_aberto'::text, 'datas_em_atraso'::text, 'datas_definidas'::text, 'em_andamento'::text, 'concluida'::text, 'cancelada'::text])))
);


