--
-- Name: orcamentos_ia_ai_secrets_public; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.orcamentos_ia_ai_secrets_public AS
 SELECT orcamentos_ia_ai_secrets.id,
    orcamentos_ia_ai_secrets.company_id,
    orcamentos_ia_ai_secrets.atualizado_em,
    orcamentos_ia_ai_secrets.atualizado_por,
    ((orcamentos_ia_ai_secrets.openai_api_key IS NOT NULL) AND (btrim(orcamentos_ia_ai_secrets.openai_api_key) <> ''::text)) AS openai_configured,
    ((orcamentos_ia_ai_secrets.anthropic_api_key IS NOT NULL) AND (btrim(orcamentos_ia_ai_secrets.anthropic_api_key) <> ''::text)) AS anthropic_configured
   FROM public.orcamentos_ia_ai_secrets;


