--
-- Name: system_preferences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.system_preferences (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    base_assembly character varying(50) DEFAULT 'under_sides'::character varying NOT NULL,
    top_assembly character varying(50) DEFAULT 'over_sides'::character varying NOT NULL,
    mounting_device character varying(50) DEFAULT 'minifix_dowel'::character varying NOT NULL,
    back_panel_type character varying(50) DEFAULT 'grooved'::character varying NOT NULL,
    back_panel_thickness integer DEFAULT 6 NOT NULL,
    drawer_slide_type character varying(50) DEFAULT 'hidden_soft_close'::character varying NOT NULL,
    front_gap_mm numeric(4,1) DEFAULT 2.0 NOT NULL,
    box_thickness_mm integer DEFAULT 15 NOT NULL,
    shelf_recess_mm numeric(5,1) DEFAULT 10.0 NOT NULL,
    edgeband_policy character varying(50) DEFAULT 'visible_edges'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    front_thickness_mm integer DEFAULT 18 NOT NULL,
    drawer_construction character varying(50) DEFAULT 'kit_fabril_5_pecas'::character varying NOT NULL,
    mixed_edge_banding boolean DEFAULT true NOT NULL,
    CONSTRAINT system_preferences_back_panel_type_check CHECK (((back_panel_type)::text = ANY ((ARRAY['grooved'::character varying, 'rebated'::character varying, 'screwed'::character varying, 'reinforced'::character varying])::text[]))),
    CONSTRAINT system_preferences_base_assembly_check CHECK (((base_assembly)::text = ANY ((ARRAY['under_sides'::character varying, 'between_sides'::character varying])::text[]))),
    CONSTRAINT system_preferences_drawer_construction_check CHECK (((drawer_construction)::text = ANY ((ARRAY['kit_fabril_5_pecas'::character varying, 'frente_only'::character varying, 'custom'::character varying])::text[]))),
    CONSTRAINT system_preferences_drawer_slide_type_check CHECK (((drawer_slide_type)::text = ANY ((ARRAY['telescopic'::character varying, 'telescopic_light'::character varying, 'hidden_soft_close'::character varying, 'touch'::character varying])::text[]))),
    CONSTRAINT system_preferences_front_thickness_mm_check CHECK ((front_thickness_mm = ANY (ARRAY[15, 18, 25]))),
    CONSTRAINT system_preferences_mounting_device_check CHECK (((mounting_device)::text = ANY ((ARRAY['screw'::character varying, 'minifix_dowel'::character varying, 'dowel_only'::character varying])::text[]))),
    CONSTRAINT system_preferences_top_assembly_check CHECK (((top_assembly)::text = ANY ((ARRAY['over_sides'::character varying, 'between_sides'::character varying, 'inside'::character varying])::text[])))
);


--
-- Name: COLUMN system_preferences.front_thickness_mm; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_preferences.front_thickness_mm IS 'Espessura padrão de frentes/portas (MDF cor do projeto). Default Cortecloud: 18.';


--
-- Name: COLUMN system_preferences.drawer_construction; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_preferences.drawer_construction IS 'kit_fabril_5_pecas = laterais+contras 15mm branco, fundo 6mm + corrediça oculta.';


--
-- Name: COLUMN system_preferences.mixed_edge_banding; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_preferences.mixed_edge_banding IS 'true = fita da frente (cor) na borda frontal da caixa branca (padrão Cortecloud).';


