--

COMMENT ON TABLE public.whatsapp_ia_status IS 'IA ativa/desativada por telefone (WhatsApp V2). Sem policies — só Edge/n8n service role.';


--
-- Name: whatsapp_instancias; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.whatsapp_instancias (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nome text NOT NULL,
    instance_key text NOT NULL,
    host text DEFAULT 'apinocode01.megaapi.com.br'::text NOT NULL,
    token text NOT NULL,
    regiao text,
    webhook_secret text DEFAULT encode(extensions.gen_random_bytes(24), 'hex'::text) NOT NULL,
    telefone_conectado text,
    status text DEFAULT 'desconhecido'::text NOT NULL,
    ultimo_status_em timestamp with time zone,
    ativo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    ia_ativa boolean DEFAULT true NOT NULL,
    codigo text,
    CONSTRAINT whatsapp_instancias_codigo_format CHECK (((codigo IS NULL) OR (codigo ~ '^[A-Za-z0-9]{1,10}$'::text))),
    CONSTRAINT whatsapp_instancias_host_mega CHECK ((host ~* '^[a-z0-9.-]+\.megaapi\.com\.br$'::text)),
    CONSTRAINT whatsapp_instancias_status_check CHECK ((status = ANY (ARRAY['desconhecido'::text, 'conectado'::text, 'desconectado'::text, 'aguardando_qr'::text, 'erro'::text])))
);


--
-- Name: TABLE whatsapp_instancias; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.whatsapp_instancias IS 'Conexão WhatsApp V2 — tokens só via service role / Edge Function whatsapp-instancias';


--
-- Name: COLUMN whatsapp_instancias.ia_ativa; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.whatsapp_instancias.ia_ativa IS 'Chave geral: se false, IA não responde nenhum contato desta instância.';


--
-- Name: COLUMN whatsapp_instancias.codigo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.whatsapp_instancias.codigo IS 'Código curto da linha (ex.: 0090). Rótulo UI = região legível + código.';


--
-- Name: whatsapp_instancias_publico; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.whatsapp_instancias_publico WITH (security_invoker='false') AS
 SELECT whatsapp_instancias.id,
    whatsapp_instancias.nome,
    whatsapp_instancias.instance_key,
    whatsapp_instancias.host,
    whatsapp_instancias.regiao,
    whatsapp_instancias.codigo,
    whatsapp_instancias.telefone_conectado,
    whatsapp_instancias.status,
    whatsapp_instancias.ultimo_status_em,
    whatsapp_instancias.ativo,
    whatsapp_instancias.ia_ativa,
    whatsapp_instancias.created_at,
    whatsapp_instancias.updated_at
   FROM public.whatsapp_instancias;


--
-- Name: VIEW whatsapp_instancias_publico; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.whatsapp_instancias_publico IS 'Campos públicos de whatsapp_instancias (sem token/webhook_secret), incl. codigo e ia_ativa';


--
-- Name: whatsapp_v2_config; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.whatsapp_v2_config (
    chave text NOT NULL,
    valor text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE whatsapp_v2_config; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.whatsapp_v2_config IS 'Config WhatsApp V2 (ex.: webhook_mestre_url). Sem policies — só Edge/service role.';


--
-- Name: whatsapp_v2_flags_publico; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.whatsapp_v2_flags_publico WITH (security_invoker='false') AS
 SELECT whatsapp_v2_config.chave,
    whatsapp_v2_config.valor
   FROM public.whatsapp_v2_config
  WHERE (whatsapp_v2_config.chave = 'historico_somente_crm'::text);


--
-- Name: VIEW whatsapp_v2_flags_publico; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.whatsapp_v2_flags_publico IS 'Flags públicas V2 (ex. historico_somente_crm) para rollback do histórico só CRM';


