CREATE POLICY emp_leads_select_unificada ON emp_garbo.leads FOR SELECT TO authenticated USING ((public.me_is_super_admin(( SELECT auth.uid() AS uid)) OR (public.me_get_empresa_role('emp_garbo'::text, ( SELECT auth.uid() AS uid)) = 'admin'::text) OR ((public.me_get_empresa_role('emp_garbo'::text, ( SELECT auth.uid() AS uid)) = 'vendedor'::text) AND (public.me_role_has_permission('vendedor'::text, 'all_leads'::text, 'view'::text) OR (vendedor_responsavel_id = ( SELECT auth.uid() AS uid)) OR (vendedor_responsavel_id IS NULL))) OR public.me_lead_linked_to_prestador('emp_garbo'::text, id, ( SELECT auth.uid() AS uid))));


