   FROM public."CRM-multi-empresas>usuario_empresa<"
  WHERE ("CRM-multi-empresas>usuario_empresa<".user_id = auth.uid()))) AND (EXISTS ( SELECT 1
   FROM public."CRM-multi-empresas>user_roles<"
  WHERE (("CRM-multi-empresas>user_roles<".user_id = auth.uid()) AND ("CRM-multi-empresas>user_roles<".role = 'admin'::public.selletos_crm_app_role)))))));


